vector<int> ans;
int cnt = 0;
ll n;
const int K = 2;
class kDTree{
    shared_ptr<kDTree> left,right;
  public:
    int depth;
    datas location;
    kDTree(){
      left = nullptr;
      right =nullptr;
    }
    shared_ptr<kDTree> constructTree(int l,int r,int _depth){
      if(r - l <= 0 || l < 0 || r > n) return nullptr;
      int axis = _depth % K;
      if(axis == 0){
        sort(d.begin() + l,d.begin() + r,sortx);
      }
      else{
        sort(d.begin() + l,d.begin() + r,sorty);
      }
      auto med = d[(l+r)/2];
      /* cout << (l+r)/2 << ' ' << d[(l+r)/2].i << endl; */
      auto node = make_shared<kDTree>(kDTree());
      node->location = med;
      node->left = (constructTree(l,(l+r)/2,_depth+1));
      node->right = (constructTree((l+r)/2+1,r,_depth+1));
      return node;
    }
    void find(int x,int y,int x2,int y2,int d){
      int axis = d % K;
      /* cout << location.i << ' ' << axis << endl; */
      if(x <= location.x && location.x <= x2 && y <= location.y && location.y <= y2){
        ans[cnt] = location.i;
        cnt++;
      }
      if(axis == 0){
        if(x <= location.x && location.x <= x2){
          if(left != nullptr)
            left->find(x,y,x2,y2,d+1);
          if(right != nullptr)
            right->find(x,y,x2,y2,d+1);
        }
        else if(location.x <= x){
          if(right != nullptr)
            right->find(x,y,x2,y2,d+1);
        }
        else if(location.x >= x2){
          if(left != nullptr)
            left->find(x,y,x2,y2,d+1);
        }
        else
          return ;
      }
      else{
        if(y <= location.y && location.y <= y2){
          if(left != nullptr)
            left->find(x,y,x2,y2,d+1);
          if(right != nullptr)
            right->find(x,y,x2,y2,d+1);
        }
        else if(location.y <= y){
          if(right != nullptr)
            right->find(x,y,x2,y2,d+1);
        }
        else if(location.y >= y2){
          if(left != nullptr)
            left->find(x,y,x2,y2,d+1);
        }
        else{
          return ;
        }
      }
    }
    void insert(int x,int y,int i){
      int axis = depth % K;
      if(axis == 0){
        if(location.x < x){
          if(right == nullptr){
            auto node = make_shared<kDTree>(kDTree());
            node->depth = depth+1;
            node->location = {x,y,i};
            right = node;
          }
          else
            right->insert(x,y,i);
        }
        else{
          if(left == nullptr){
            auto node = make_shared<kDTree>(kDTree());
            node->depth = depth+1;
            node->location = {x,y,i};
            left = node;
          }
          else
            left->insert(x,y,i);
        }
      }
      else{
        if(location.y < y){
          if(right == nullptr){
            auto node = make_shared<kDTree>(kDTree());
            node->depth = depth+1;
            node->location = {x,y,i};
            right = node;
          }
          else
            right->insert(x,y,i);
        }
        else{
          if(left == nullptr){
            auto node = make_shared<kDTree>(kDTree());
            node->depth = depth+1;
            node->location = {x,y,i};
            left = node;
          }
          else
            left->insert(x,y,i);
        }
      }
    }
    void show(int k){
      rep(i,k){
        cout << "  ";
      }
      cout << location.x << ' ' << location.y << ' ' << location.i << endl;
      if(left != nullptr){
        left->show(k+1);
      }
      if(right != nullptr){
        right->show(k+1);
      }
    }
};

