void solve()
{
	READ(int, n);

	KDTree<int, 2> tree(n);
	REP(i, n)
	{
		READ(int, x, y);
		tree[i] = { x, y };
	}
	tree.build();
	READ(int, q);
	REP(i, q)
	{
		READ(int, sx, tx, sy, ty);
		auto v = tree.range({ sx, sy }, { tx + 1,ty + 1 });
		sort(allof(v));
		for (auto val : v) { WRITE(val); }
		WRITE("");
	}
}

