using namespace std;

struct QuadTree{

private:

  struct node_t{
    int cnt;
    vector<int>vals;
    node_t *tl,*tr,*bl,*br;

    node_t(){
      cnt=0;
    }
  };

  node_t *root;

  node_t *insert(node_t *node,int ax,int ay,int bx,int by,int x,int y){
    if(ax>x || x>bx || ay>y || y>by)return node;
    if(!node)node=new node_t();
    node->cnt++;
    if(ax==bx && ay==by)return node;

    int mx=(ax+bx)>>1,my=(ay+by)>>1;

    node->bl=insert(node->bl,ax,ay,mx,my,x,y);
    node->tl=insert(node->tl,ax,my+1,mx,by,x,y);
    node->br=insert(node->br,mx+1,ay,bx,my,x,y);
    node->tr=insert(node->tr,mx+1,my+1,bx,by,x,y);

    return node;
  }

  node_t *insert(node_t *node,int ax,int ay,int bx,int by,int x,int y,int val){
    if(ax>x || x>bx || ay>y || y>by)return node;
    if(!node)node=new node_t();

    node->cnt++;
    node->vals.push_back(val);

    if(ax==bx && ay==by)return node;

    int mx=(ax+bx)>>1,my=(ay+by)>>1;

    node->bl=insert(node->bl,ax,ay,mx,my,x,y,val);
    node->tl=insert(node->tl,ax,my+1,mx,by,x,y,val);
    node->br=insert(node->br,mx+1,ay,bx,my,x,y,val);
    node->tr=insert(node->tr,mx+1,my+1,bx,by,x,y,val);

    return node;
  }

  int count(node_t *node,int ax,int ay,int bx,int by,
	    int x1,int y1,int x2,int y2) {
    if(!node || ax>x2 || x1>bx || ay>y2 || y1>by)return 0;
    if(x1<=ax && bx<=x2 && y1<=ay && by<=y2)return node->cnt;

    int mx=(ax+bx)>>1,my=(ay+by)>>1;

    int res=0;
    res+=count(node->bl,ax,ay,mx,my,x1,y1,x2,y2);
    res+=count(node->tl,ax,my+1,mx,by,x1,y1,x2,y2);
    res+=count(node->br,mx+1,ay,bx,my,x1,y1,x2,y2);
    res+=count(node->tr,mx+1,my+1,bx,by,x1,y1,x2,y2);
    return res;
  }


  vector<int> getList(node_t *node,int ax,int ay,int bx,int by,
	    int x1,int y1,int x2,int y2) {
    if(!node || ax>x2 || x1>bx || ay>y2 || y1>by)return vector<int>();
    if(x1<=ax && bx<=x2 && y1<=ay && by<=y2)return node->vals;

    int mx=(ax+bx)>>1,my=(ay+by)>>1;

    vector<int>res1,res2,res3,res4,res12,res34,res;
    res1=getList(node->bl,ax,ay,mx,my,x1,y1,x2,y2);
    res2=getList(node->tl,ax,my+1,mx,by,x1,y1,x2,y2);
    res3=getList(node->br,mx+1,ay,bx,my,x1,y1,x2,y2);
    res4=getList(node->tr,mx+1,my+1,bx,by,x1,y1,x2,y2);

    res1.insert(res1.end(),all(res2));
    res3.insert(res3.end(),all(res4));
    res1.insert(res1.end(),all(res3));
    //merge(all(res1),all(res2),res12.begin());
    //merge(all(res3),all(res4),res34.begin());
    //merge(all(res12),all(res34),res.begin());

    return res1;
  }

public:

  void insert(int x,int y){
    root=insert(root,0,0,max_x-1,max_y-1,x,y);
  }

  void insert(int x,int y,int val){
    root=insert(root,0,0,max_x-1,max_y-1,x,y,val);
  }


  int count(int x1, int y1, int x2, int y2) {
    return count(root,0,0,max_x-1,max_y-1,x1,y1,x2,y2);
  }

  vector<int> getList(int x1, int y1, int x2, int y2) {
    vector<int>res=getList(root,0,0,max_x-1,max_y-1,x1,y1,x2,y2);
    sort(all(res));
    res.erase(unique(all(res)),res.end());
