int makeKdTreeNode(int left, int right, int depth) {
    if (left >= right) {
        return -1;
    }

    int curNodeIndex = tindex++;

    bool (*c)(const Point &p1, const Point &p2) =  depth % 2 == 0 ? lessX : lessY;
    sort(pts + left, pts + right, c);

    int mid = (left + right) / 2;
    ns[curNodeIndex].p_id = mid;

    ns[curNodeIndex].ld_id = makeKdTreeNode(left, mid, depth + 1);
    ns[curNodeIndex].ru_id = makeKdTreeNode(mid + 1, right, depth + 1);

    return curNodeIndex;
}

void queryRect(int sx, int sy, int tx, int ty, int nodeId, int depth, vector<Point> &inPts){

    Point &p = pts[ns[nodeId].p_id];
    int x = p.x, y = p.y;

    if ((sx <= x && tx >= x && sy <= y && ty >= y)) {
        inPts.push_back(p);
    }

    if (depth % 2 == 0) {
        if (ns[nodeId].ru_id > 0 && tx >= x)
            queryRect(sx, sy, tx, ty, ns[nodeId].ru_id, depth + 1, inPts);
        if (ns[nodeId].ld_id > 0 && sx <= x)
            queryRect(sx, sy, tx, ty, ns[nodeId].ld_id, depth + 1, inPts);
    }
    else{
        if (ns[nodeId].ru_id > 0 && ty >= y)
            queryRect(sx, sy, tx, ty, ns[nodeId].ru_id, depth + 1, inPts);
        if (ns[nodeId].ld_id > 0 && sy <= y)
            queryRect(sx, sy, tx, ty, ns[nodeId].ld_id, depth + 1, inPts);
    }
}

#include <iostream>
#include <algorithm>
#include <numeric>
#include <vector>

struct Point {
    int x, y;
};

std::vector<Point> points;

struct Node {
    int id;
    Node *l, *r;
    Node(int id) : id(id), l(nullptr), r(nullptr){};
};

Node* buildkD(std::vector<int>& ids, int l, int r, int depth) {
    if (l == r) return nullptr;

    if (depth & 1) {
        std::sort(ids.begin() + l, ids.begin() + r,
                  [&](int i, int j) { return (points[i].x != points[j].x ? points[i].x < points[j].x : points[i].y < points[j].y); });
    } else {
        std::sort(ids.begin() + l, ids.begin() + r,
                  [&](int i, int j) { return (points[i].y != points[j].y ? points[i].y < points[j].y : points[i].x < points[j].x); });
    }

    int mid = (l + r) / 2;
    Node* node = new Node(ids[mid]);
    node->l = buildkD(ids, l, mid, depth + 1);
    node->r = buildkD(ids, mid + 1, r, depth + 1);
    return node;
}

std::vector<int> find(int lx, int rx, int ly, int ry, int depth, Node* node) {
    std::vector<int> ret;
    if (node == nullptr || lx > rx || ly > ry) return ret;

    int x = points[node->id].x, y = points[node->id].y;
    if (lx <= x && x <= rx && ly <= y && y <= ry) ret.push_back(node->id);

    if (depth & 1) {  // xでソートされている
        std::vector<int> res = find(lx, std::min(rx, x), ly, ry, depth + 1, node->l);
        std::copy(res.begin(), res.end(), back_inserter(ret));

        res = find(std::max(lx, x), rx, ly, ry, depth + 1, node->r);
        std::copy(res.begin(), res.end(), back_inserter(ret));

    } else {  // yでソートされている
        std::vector<int> res = find(lx, rx, ly, std::min(ry, y), depth + 1, node->l);
        std::copy(res.begin(), res.end(), back_inserter(ret));

        res = find(lx, rx, std::max(ly, y), ry, depth + 1, node->r);
        std::copy(res.begin(), res.end(), back_inserter(ret));
    }
    return ret;
}

int main() {
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    int N;
    std::cin >> N;

    points.resize(N);
    for (auto& p : points) std::cin >> p.x >> p.y;

    std::vector<int> ids(N);
    std::iota(ids.begin(), ids.end(), 0);
    Node* root = buildkD(ids, 0, N, 0);

    int Q;
    std::cin >> Q;
    for (int q = 0; q < Q; ++q) {
        int lx, rx, ly, ry;
        std::cin >> lx >> rx >> ly >> ry;

        auto ret = find(lx, rx, ly, ry, 0, root);
        std::sort(ret.begin(), ret.end());

        for (auto i : ret) std::cout << i << '\n';
        std::cout << '\n';
    }
    return 0;
}

