template<typename T>
class kdtree {
    struct node { int pos, l, r; };
    int np;
    T vec;
    vector<node> tree;
public:
    kdtree(auto& P): np(0)
    {
        vec=P;
        int n=vec.size();
        tree=vector<node>(n);
        build(0, n);
    }
    int build(int l, int r, int depth=0)
    {
        if (l>=r) return -1;
        int mid=(l+r)/2;
        int t=np++;
        if (depth%2==0)
            sort(begin(vec)+l, begin(vec)+r, [](auto& a, auto& b) { return a.x<b.x; });
        else
            sort(begin(vec)+l, begin(vec)+r, [](auto& a, auto& b) { return a.y<b.y; });
        tree[t].pos=mid;
        tree[t].l=build(l, mid, depth+1);
        tree[t].r=build(mid+1, r, depth+1);
        return t;
    }
    void get(T& res, int sx, int tx, int sy, int ty, int v=0, int depth=0)
    {
        int x=vec[tree[v].pos].x;
        int y=vec[tree[v].pos].y;
        if (sx<=x && x<=tx && sy<=y && y<=ty)
            res.push_back(vec[tree[v].pos]);
        if (depth%2==0) {
            if (tree[v].l!=-1 && sx<=x) get(res, sx, tx, sy, ty, tree[v].l, depth+1);
            if (tree[v].r!=-1 && x<=tx) get(res, sx, tx, sy, ty, tree[v].r, depth+1);
        }
        else {
            if (tree[v].l!=-1 && sy<=y) get(res, sx, tx, sy, ty, tree[v].l, depth+1);
            if (tree[v].r!=-1 && y<=ty) get(res, sx, tx, sy, ty, tree[v].r, depth+1);
        }
    }
};

int main()
{
    int n; __builtin_scanf("%d", &n);

    struct point { int x, y, id; };
    vector<point> p(n);
    for(int i=0; i<n; ++i) {
        int x, y; __builtin_scanf("%d%d", &x, &y);
        p[i]={x, y, i};
    }
    kdtree<decltype(p)> t(p);

    int q; __builtin_scanf("%d", &q);
    while (q--) {
        int sx, tx, sy, ty; __builtin_scanf("%d%d%d%d", &sx, &tx, &sy, &ty);
        decltype(p) res;
        t.get(res, sx, tx, sy, ty);
        sort(begin(res), end(res), [](auto& a, auto& b){ return a.id<b.id; });
        for(auto& e: res) printf("%d\n", e.id);
        puts("");
    }
}

