#include <bits/stdc++.h>
using namespace std;
using lint = long long;
template<class T = int> using V = vector<T>;
template<class T = int> using VV = V< V<T> >;

#pragma GCC target ("avx")
struct Bitvector {
  using T = uint32_t;
  static constexpr int W = 32;
  static int popcnt(T x) { return __builtin_popcount(x); }

  const int n;
  V<T> b;
  V<> c;
  Bitvector(int n) : n(n), b(n / W + 1), c(n / W + 1) {}
  void set(int i) { b[i / W] |= (T)1 << i % W; }
  void build() { for (int i = 0; i < n / W; ++i) c[i + 1] = c[i] + popcnt(b[i]); }
  bool operator[](int i) const { return b[i / W] >> i % W & 1; }
  int rank(int i) const { return c[i / W] + popcnt(b[i / W] & ~(~(T)0 << i % W)); }
  int rank(bool v, int i) const { return v ? rank(i) : i - rank(i); }
};
struct WeightedSegmentTree {
  using T = V<>;
  static T op(const T& x, const T& y) {
    if (x.size() + y.size() > 100) return {};
    auto res = x;
    res.insert(end(res), begin(y), end(y));
    return res;
  }
  static T e() { return {}; }

  struct SegmentTree {
    const int n;
    V<T> t;
    SegmentTree(int n) : n(n), t(2 * n, e()) {}
    T& operator[](int i) { return t[i + n]; }
    void build() { for (int i = n - 1; i; --i) t[i] = op(t[2 * i], t[2 * i + 1]); }
    T acc(int l, int r) const {
      T resl = e(), resr = e();
      for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
        if (l & 1) resl = op(resl, t[l++]);
        if (r & 1) resr = op(t[--r], resr);
      }
      return op(resl, resr);
    }
    void set(int i, const T& x) {
      t[i += n] = x;
      while (i >>= 1) t[i] = op(t[2 * i], t[2 * i + 1]);
    }
  };
  const int n, h;
  V<Bitvector> b;
  V<> z;
  V<SegmentTree> st;
  template<class Itr> WeightedSegmentTree(Itr first, Itr last) :
    n(distance(first, last)), h(__lg(2 * *max_element(first, last) + 1)), b(h, Bitvector(n)), z(h), st(h + 1, SegmentTree(n)) {
    assert(*min_element(first, last) >= 0);
    V<> w(first, last), nw(n);
    for (int j = 0; j < h; ++j) {
      for (int i = 0; i < n; ++i) {
        if (w[i] >> h + ~j & 1) b[j].set(i);
        else ++z[j];
      }
      b[j].build();
      int p = 0, q = z[j];
      for (int i = 0; i < n; ++i) (b[j][i] ? nw[q++] : nw[p++]) = w[i];
      swap(w, nw);
    }
  }
  T operator[](int i) const {return {st[0].t[i + n]}; }
  T acc(int l, int r, int x, int y, int j, int s, int t) const {
    if (y <= s or t <= x) return e();
    if (x <= s and t <= y) return st[j].acc(l, r);
    int m = s + t >> 1, p = b[j].rank(0, l), q = b[j].rank(0, r);
    return op(acc(p, q, x, y, j + 1, s, m), acc(z[j] + l - p, z[j] + r - q, x, y, j + 1, m, t));
  }
  T acc(int l, int r, int x, int y) const { return acc(l, r, x, y, 0, 0, 1 << h); }
  void set(int i, T x) {
    for (int j = 0; j < h; ++j) {
      st[j].set(i, x);
      int v = b[j][i];
      i = v * z[j] + b[j].rank(v, i);
    }
    st[h].set(i, x);
  }
};

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);
  int n; cin >> n;
  V<> x(n), y(n); for (int i = 0; i < n; ++i) cin >> x[i] >> y[i];
  auto xs = x, ys = y;
  sort(begin(xs), end(xs));
  sort(begin(ys), end(ys));
  ys.erase(unique(begin(ys), end(ys)), end(ys));
  V<> id(n);
  iota(begin(id), end(id), 0);
  sort(begin(id), end(id), [&](int i, int j) { return x[i] < x[j]; });
  V<> w(n);
  for (int i = 0; i < n; ++i) {
    w[i] = lower_bound(begin(ys), end(ys), y[id[i]]) - begin(ys);
  }
  WeightedSegmentTree wst(begin(w), end(w));
  for (int i = 0; i < n; ++i) {
    wst.set(i, {id[i]});
  }
  int q; cin >> q;
  while (q--) {
    int x0, x1, y0, y1; cin >> x0 >> x1 >> y0 >> y1, ++x1, ++y1;
    x0 = lower_bound(begin(xs), end(xs), x0) - begin(xs);
    x1 = lower_bound(begin(xs), end(xs), x1) - begin(xs);
    y0 = lower_bound(begin(ys), end(ys), y0) - begin(ys);
    y1 = lower_bound(begin(ys), end(ys), y1) - begin(ys);
    auto res = wst.acc(x0, x1, y0, y1);
    sort(begin(res), end(res));
    for (int e : res) cout << e << '\n';
    cout << '\n';
  }
}

