int make_tree(int l,int r,int depth) {
	if (r == l)return -1;
	int k = c;
	c++;
	if (depth & 1) {
		sort(p.begin() + l, p.begin() + r, ordery);
		tree[k].p = p[(l + r) / 2];
		tree[k].l = make_tree(l, (l + r) / 2, depth + 1);
		tree[k].r = make_tree((l + r) / 2 + 1, r, depth + 1);
	}
	else {
		sort(p.begin() + l, p.begin() + r, orderx);
		tree[k].p = p[(l + r) / 2];
		tree[k].l = make_tree(l, (l + r) / 2, depth + 1);
		tree[k].r = make_tree((l + r) / 2 + 1, r, depth + 1);
	}
	return k;
}

void solve(int t,int depth) {
	if (t == -1)return;
	int X = tree[t].p.x;
	int Y = tree[t].p.y;
	if (sx <= X&&X <= tx&&sy <= Y&&Y <= ty)res.push_back(tree[t].p.id);
	if (depth & 1) {
		if (sy <= Y)solve(tree[t].l, depth + 1);
		if (Y <= ty)solve(tree[t].r, depth + 1);
	}
	else {
		if (sx <= X)solve(tree[t].l, depth + 1);
		if (X <= tx)solve(tree[t].r, depth + 1);
	}
}

