bool cmp2(Node a, Node b) {
	return a.y < b.y;
}

bool cmp3(Node a, Node b) {
	return a.node < b.node;
}

int make2DTree(int l, int r, int depth)
{
	if (l >= r)
		return NIL;
	int mid = (l + r) / 2;
	int t = np++;

	if (depth % 2 == 0)
		sort(p + l, p + r, cmp1);
	else
		sort(p + l, p + r, cmp2);

	T[t].location = p[mid].node;
	T[t].l = make2DTree(l, mid, depth + 1);
	T[t].r = make2DTree(mid + 1, r, depth + 1);

	return t;
}

void find(int v, int sx, int tx, int sy, int ty, int depth)
{
	int x, y;
	x = p[T[v].location].x;
	y = p[T[v].location].y;
	if (sx <= x && x <= tx && sy <= y && y <= ty) {
		f.push_back(T[v].location);
	}
	if (depth % 2 == 0) {
		if (T[v].l != NIL && sx <= x)
			find(T[v].l, sx, tx, sy, ty, depth + 1);
		if (T[v].r != NIL && x <= tx)
			find(T[v].r, sx, tx, sy, ty, depth + 1);
	}
	else {
		if (T[v].l != NIL && sy <= y)
			find(T[v].l, sx, tx, sy, ty, depth + 1);
		if (T[v].r != NIL && y <= ty)
			find(T[v].r, sx, tx, sy, ty, depth + 1);
	}
}

