using namespace std;

const int INF = INT_MAX/3;

typedef complex<double> Point;

struct P{
    Point point;
    int id;
    P (const Point &point, int id)
        : point(point), id(id) {}
    bool operator<(const P &p)const{
        return id < p.id;
    }
};


struct node{
    P p;
    node *l, *r;
    node (const P &p)
        : p(p), l(NULL), r(NULL) {}
};

struct kDTree{
    node *root;
    kDTree() :root(NULL){}

    void insert(const P &p){
        root = insert(root, 0, p);
    }

    node *insert(node *t, int d, const P &p){
        if(t==NULL) return new node(p);
        if(compare(d, p, t->p)) t->l = insert(t->l, !d, p);
        else t->r = insert(t->r, !d, p);
        return t;
    }

    void find(const P &ld, const P &ru, vector<P> &out){
        find(root, 0, ld, ru, out);
    }

    void find(node *t, int d, const P &ld, const P &ru, vector<P> &out){
        if(t==NULL) return;
        const P &p = t->p;
        if(real(ld.point) <= real(p.point) && real(p.point) <= real(ru.point) && imag(ld.point) <= imag(p.point) && imag(p.point) <= imag(ru.point)){
            out.push_back(p);
        }
        if(!compare(d, p, ld)) find(t->l, !d, ld, ru, out);
        if(!compare(d, ru, p)) find(t->r, !d, ld, ru, out);
    }
};

