struct OwnNode
{
	int x, y;
	int index;
	OwnNode* right;
	OwnNode* left;

	OwnNode(int x, int y,int index) :x(x), y(y),index(index), right(nullptr), left(nullptr) {}

	void insert(int x, int y, int d, int index)
	{
		if (d % 2 == 0)
		{
			if (this->x < x)
			{
				if (right == nullptr)
				{
					right = new OwnNode(x, y, index);
				}
				else
				{
					right->insert(x, y, d + 1, index);
				}
			}
			else
			{
				if (left == nullptr)
				{
					left = new OwnNode(x, y, index);
				}
				else
				{
					left->insert(x, y, d + 1, index);
				}
			}
		}
		else
		{
			if (this->y < y)
			{
				if (right == nullptr)
				{
					right = new OwnNode(x, y, index);
				}
				else
				{
					right->insert(x, y, d + 1, index);
				}
			}
			else
			{
				if (left == nullptr)
				{
					left = new OwnNode(x, y, index);
				}
				else
				{
					left->insert(x, y, d + 1, index);
				}
			}
		}
	}

	void find(OwnNode& ld, OwnNode& ru, int d, priority_queue<int, vector<int>, greater<int>>& pq)
	{
		if (ld.x <= x&&x <= ru.x&&ld.y <= y&&y <= ru.y)
		{
			pq.push(index);
		}

		if (d % 2 == 0)
		{
			if (ld.x <= x)
			{
				if (left != nullptr)
				{
					left->find(ld, ru, d + 1, pq);
				}
			}
			if(x<=ru.x)
			{
				if (right != nullptr)
				{
					right->find(ld, ru, d + 1, pq);
				}
			}
		}
		else
		{
			if (ld.y <= y)
			{
				if (left != nullptr)
				{
					left->find(ld, ru, d + 1, pq);
				}
			}
			if (y <= ru.y)
			{
				if (right != nullptr)
				{
					right->find(ld, ru, d + 1, pq);
				}
			}
		}
	}
};

int main()
{
	OwnNode* top = nullptr;
	int n, q;
	scanf("%d", &n);

	for (int i = 0; i < n; i++)
	{
		int x, y;
		scanf("%d %d", &x, &y);
		if (top == nullptr)
		{
			top = new OwnNode(x, y, i);
		}
		else
		{
			top->insert(x, y, 0, i);
		}
	}

	scanf("%d", &q);

	for (int i = 0; i < q; i++)
	{
		int x1, y1, x2, y2;
		scanf("%d %d %d %d", &x1, &x2, &y1, &y2);
		OwnNode n1(x1, y1, -1), n2(x2, y2, -1);
		priority_queue<int, vector<int>, greater<int>> pq;
		top->find(n1, n2, 0, pq);
		while (!pq.empty())
		{
			cout << pq.top() << endl;
			pq.pop();
		}
		cout << endl;
	}

	return 0;
}

