bool lessY(const point &p1, const point &p2) { return p1.y < p2.y; }

int
makeKDTree(int l, int r, int depth)
{
	if (l >= r)
		return nil;

	int mid = (l + r) / 2;
	if (depth % 2 == 0)
		sort(p + l, p + r, lessX);
	else
		sort(p + l, p + r, lessY);

	int s = np++;
	t[s].location = mid;
	t[s].l = makeKDTree(l, mid, depth + 1);
	t[s].r = makeKDTree(mid + 1, r, depth + 1);
	return s;
}

void
find(int v, int sx, int tx, int sy, int ty, int depth, vector<point> &ans)
{
	int x = p[t[v].location].x;
	int y = p[t[v].location].y;

	if (sx <= x && x <= tx && sy <= y && y <= ty)
		ans.push_back(p[t[v].location]);

	if (depth % 2 == 0)
	{
		if (t[v].l != nil)
		{
			if (sx <= x)
				find(t[v].l, sx, tx, sy, ty, depth + 1, ans);
		}

		if (t[v].r != nil)
		{
			if (x <= tx)
				find(t[v].r, sx, tx, sy, ty, depth + 1, ans);
		}
	}
	else
	{
		if (t[v].l != nil)
		{
			if (sy <= y)
				find(t[v].l, sx, tx, sy, ty, depth + 1, ans);
		}

		if (t[v].r != nil)
		{
			if (y <= ty)
				find(t[v].r, sx, tx, sy, ty, depth + 1, ans);
		}
	}
}

