        vector<int> res, ans;
        orr.query(a,b+1,c,d+1,res);
        each(it,res){
            ans.pb(it);
        }
        sort(all(ans));
        each(j,ans){
            cout << j << "\n";
        }
        cout << "\n";
    }
    return 0;
}

