const int MAX_N = 500010;

const int D = 2;
using value_t = int;
using dat_t = std::array<value_t, D>;

struct node {
    const dat_t *key;
    dat_t min, max;
    int size;

    node *left, *right;

    void *operator new(std::size_t){
        static node pool[MAX_N];
        static int p = 0;
        return pool + p++;
    }
};

using np = node*;
using cnp = const node *;
using dp = dat_t*;
using cdp = const dat_t*;

np make_tree(cdp *left, cdp *right, int d){
    d %= D;

    int sz = right - left;
    if(sz <= 0) return nullptr;

    node *res = new node;
    for(int d = 0; d < D; ++d){
        res->min[d] = std::numeric_limits<int>::max();
        res->max[d] = std::numeric_limits<int>::min();
        for(auto i = left; i != right; ++i){
            res->min[d] = std::min(res->min[d], (**i)[d]);
            res->max[d] = std::max(res->max[d], (**i)[d]);
        }
    }

    sort(left, right, [d](cdp a, cdp b){
            return (*a)[d] < (*b)[d];
        });
    res->key = left[sz/2];

    if(sz > 1){
        res->left = make_tree(left, left + sz/2, d + 1);
        res->right = make_tree(left + sz/2 + 1, right, d + 1);
    } else {
        res->left = nullptr;
        res->right = nullptr;
    }
    res->size = sz;
    return res;
}

cnp make_tree(cdp left, cdp right){
    static const dat_t *ptr[MAX_N];
    int sz = right - left;
    for(auto i = left; i != right; ++i) ptr[i - left] = i;
    return make_tree(ptr, ptr + sz, 0);
}

void range_query(cnp n, const dat_t &min, const dat_t &max,
                 std::vector<std::pair<cdp, cnp>> &ans){
    if(n == nullptr) return;

    int overwrap = 2;

    for(int d = 0; d < D; ++d){
        if(n->max[d] < min[d] || max[d] < n->min[d]){
            overwrap = 0;
            break;
        } else if(!(min[d] <= n->min[d] && n->max[d] <= max[d])){
            overwrap = 1;
        }
    }

    if(overwrap == 0){
        ;
    } else if(overwrap == 1){
        bool inner = true;
        for(int d = 0; d < D; ++d){
            if(!(min[d] <= (*n->key)[d] && (*n->key)[d] <= max[d])){
                inner = false;
                break;
            }
        }
        if(inner) ans.emplace_back(n->key, nullptr);
        range_query(n->left, min, max, ans);
        range_query(n->right, min, max, ans);
    } else {
        ans.emplace_back(nullptr, n);
    }
}

