    int make_tree(int l,int r,int depth = 0){
        if(!(l<r))return -1;
        if(depth % 2 == 0){
            sort(P.begin()+l,P.begin()+r,lessx);
        }else{
            sort(P.begin()+l,P.begin()+r,lessy);
        }
        int t = np++;
        int mid = (l+r)/2;
        Tree[t].loc = mid;
        Tree[t].l = make_tree(l,mid,depth+1);
        Tree[t].r = make_tree(mid+1,r,depth+1);
