                stk.push(p.second);
                while(stk.size()){
                    auto c = stk.top();
                    stk.pop();
                    if(c == nullptr) continue;
                    ans.push_back(c->key);
                    stk.push(c->left);
                    stk.push(c->right);
                }
            }
        }
