        tree[i].pos[1] = next();
    }
    root = build(1, n, 0);
}

int st[2], ed[2], ans[500005], tot = 0;

inline bool judge(const node &t) {
    return t.pos[0] >= st[0]
        && t.pos[0] <= ed[0]
        && t.pos[1] >= st[1]
        && t.pos[1] <= ed[1];
}

inline bool check(const node &t) {
    return t.min[0] <= ed[0]
        && t.max[0] >= st[0]
        && t.min[1] <= ed[1]
        && t.max[1] >= st[1];
}

void query(int t) {
    if (judge(tree[t]))ans[tot++] = tree[t].id;
    if (tree[t].son[0] && check(tree[tree[t].son[0]]))query(tree[t].son[0]);
    if (tree[t].son[1] && check(tree[tree[t].son[1]]))query(tree[t].son[1]);
}

inline void query(void) {
    for (int i = 0; i < m; ++i, tot = 0) {
        st[0] = next();
        ed[0] = next();
        st[1] = next();
        ed[1] = next();
        tot = 0;
        query(root);
        sort(ans, ans + tot);
        for (int j = 0; j < tot; ++j)
            printf("%d\n", ans[j]);
        puts("");
    }
}

signed main(void) {
    n = next(); build();
    m = next(); query();
    //system("pause");
}

