#include<iostream>
using namespace std;
#include<cstdio>       // k-D_tree. (k = 2)
#include<algorithm>

class Point
{
public:
    int id, x, y;
    Point(){};
    Point(int no, int pos_x, int pos_y) : id(no), x(pos_x), y(pos_y) {};
    void print(){ printf("%d\n", id); }
};

bool cmp_x(const Point &P1, const Point &P2){ return P1.x < P2.x; }
bool cmp_y(const Point &P1, const Point &P2){ return P1.y < P2.y; }
bool cmp_id(const Point &P1, const Point &P2){ return P1.id < P2.id; }

class node // nodes of 2-D_tree.
{
public:
    Point *mark;
    node *less, *more;
    int depth;   // parity of depth is important.
    node() : mark(NULL), less(NULL), more(NULL), depth(0) {};
    node(Point* pos, node* l, node* m, int d) : mark(pos), less(l), more(m), depth(d) {};
};

node* make_tree(Point S[], int left, int right, int d) // recursive construction of 2-D_tree.
{
    if(left > right){ return NULL; }
    if(left == right){
        node* leaf = new node;
        *leaf = node(&S[left], NULL, NULL, d);    // arrived at leaf.
        return leaf;
    }

	if(d & 1){
        sort(S + left, S + right + 1, cmp_x);
	}else{
        sort(S + left, S + right + 1, cmp_y);
	}

    int mid = (left + right) / 2;

    node* n = new node;   // make a new node.
    n->mark = &S[mid];
    n->depth = d;
    n->less = make_tree(S, left, mid - 1, d + 1);
    n->more = make_tree(S, mid + 1, right, d + 1);

    return n;
}

int cnt;

void find(Point S[], int sx, int tx, int sy, int ty, node* kd_n)
{
    if(kd_n == NULL) return;

    if(sx <= kd_n->mark->x && kd_n->mark->x <= tx && sy <= kd_n->mark->y && kd_n->mark->y <= ty){
        S[cnt] = *(kd_n->mark);
        cnt++;
    }
    int ax = kd_n->mark->x, ay = kd_n->mark->y, d = kd_n->depth;

    if(d & 1){
        if(sx <= ax) find(S, sx, tx, sy, ty, kd_n->less);
        if(ax <= tx) find(S, sx, tx, sy, ty, kd_n->more);
    }else{
        if(sy <= ay) find(S, sx, tx, sy, ty, kd_n->less);
        if(ay <= ty) find(S, sx, tx, sy, ty, kd_n->more);
    }
}

int main()
{
    int i, pos_x, pos_y, n;
    Point P[500000], Q[100];

    scanf("%d", &n);
    for(i = 0; i < n; i++){ scanf("%d %d", &pos_x, &pos_y); P[i] = Point(i, pos_x, pos_y); }

    node* root;
    root = make_tree(P, 0, n - 1, 0);  // make a 2-D_tree.

    int q, sx, tx, sy, ty;
    scanf("%d", &q);
    while(q){
        cnt = 0;
        scanf("%d %d %d %d", &sx, &tx, &sy, &ty);      // input data.
        find(Q, sx, tx, sy, ty, root);   // counting.
        sort(Q, Q + cnt, cmp_id);
        for(i = 0; i < cnt; i++){ Q[i].print(); }  // print out.
        cout << endl;
        q--;
    };

    return 0;
}

#include<bits/stdc++.h>
using namespace std;
const int sz = 1 << 20;
typedef pair< int, int > Pi;
vector< Pi > seg[2 * sz + 1];
int x[500000], y[500000];
vector< int > nums;
vector< int > ret;
void InitRange(int k, int l, int r) {
  if(l + 1 >= r) {
    return;
  } else {
    InitRange(2 * k + 1, l, (l + r) >> 1);
    InitRange(2 * k + 2, (l + r) >> 1, r);
    seg[k].resize(seg[2 * k + 1].size() + seg[2 * k + 2].size());
    merge(seg[2 * k + 1].begin(), seg[2 * k + 1].end(), seg[2 * k + 2].begin(), seg[2 * k + 2].end(), seg[k].begin());
  }
}

void PrintRange(int a, int b, int low, int high, int k, int l, int r) {
  if(a >= r || b <= l) {
    return;
  } else if(a <= l && r <= b) {
    for(vector< Pi >::iterator it = lower_bound(seg[k].begin(), seg[k].end(), Pi(low, -1)); it != seg[k].end() && it -> first <= high; it++) { 
      ret.push_back(it -> second);
    }
  } else {
    PrintRange(a, b, low, high, 2 * k + 1, l, (l + r) >> 1);
    PrintRange(a, b, low, high, 2 * k + 2, (l + r) >> 1, r);
  }
}

int main() {
  int n;
  scanf("%d", &n);
  for(int i = 0; i < n; i++) {
    scanf("%d %d", &x[i], &y[i]);
    nums.push_back(x[i]);
  }
  sort(nums.begin(), nums.end());
  nums.erase(unique(nums.begin(), nums.end()), nums.end());
  for(int i = 0; i < n; i++) {
    x[i] = lower_bound(nums.begin(), nums.end(), x[i]) - nums.begin();
  }

  for(int i = 0; i < n; i++) {
    seg[x[i] + sz - 1].push_back(make_pair(y[i], i));
  }
  InitRange(0, 0, sz);

  int q;
  scanf("%d", &q);
  while(q--){ 
    ret.clear();
    int sx, tx, sy, ty;
    scanf("%d %d %d %d", &sx, &tx, &sy, &ty);
    sx = lower_bound(nums.begin(), nums.end(), sx) - nums.begin();
    tx = upper_bound(nums.begin(), nums.end(), tx) - nums.begin();

    PrintRange(sx, tx, sy, ty, 0, 0, sz);
    sort(ret.begin(), ret.end());
    for(vector< int >::const_iterator it = ret.begin(); it != ret.end(); it++) {
      printf("%d\n", *it);
    }
    printf("\n");
  }

}

#include <algorithm>
#include <cstdio>
#include <vector>
using namespace std;

class Node {
public:
    int location; // 位置
    int p, l, r; // ポイントの親，左の子，右の子
    Node() {}
};

class Point {
public:
    int id, x, y;
    Point() {}
    // 点の中身を定める
    Point(int id, int x, int y)
        : id(id) // 値
        , x(x) // x座標
        , y(y) // y座標
    {
    }
    bool operator<(const Point& p) const // 比較演算子をオーバーロード
    {
        return id < p.id;
    }

    void print()
    {
        printf("%d\n", id); // coutより高速なprintf関数を使用
    }
};

static const int MAX = 1000000;
static const int NIL = -1;

int N;
Point P[MAX]; // 入力のポイントを入れるもの
Node T[MAX]; // ポイントの位置情報を格納
int np;

// p1とp2のx座標の大きさを比較
bool lessX(const Point& p1, const Point& p2)
{
    return p1.x < p2.x;
}
// p1とp2のy座標の大きさを比較
bool lessY(const Point& p1, const Point& p2)
{
    return p1.y < p2.y;
}

int makeKDTree(int l, int r, int depth)
{
    // 2次元の木構造を作る
    if (!(l < r)) { // 左端が右端以上に右にあるときは終了
        return NIL;
    }
    int mid = (l + r) / 2;
    int t = np++; // 二分木のノード番号を設定
    if (depth % 2 == 0) { // 木の深さが偶数の時(xの層)
        sort(P + l, P + r, lessX); // lからrまでxについて昇順で整列
    } else { // 木の深さが奇数の時(yの層)
        sort(P + l, P + r, lessY); // lからrまでyについて昇順で整列
    }
    // 以上の処理をすべての入力ポイントに関して行う
    T[t].location = mid;
    T[t].l = makeKDTree(l, mid, depth + 1);
    T[t].r = makeKDTree(mid + 1, r, depth + 1);

    return t;
}

/*
    v:ノードの値
    sx, tx, sy, ty:指定された座標
    depth:木の深さ(初期値は0)
    ans:答えを格納するvector
*/
void find(int v,
    int sx,
    int tx,
    int sy,
    int ty,
    int depth,
    vector<Point>& ans)
{
    // x, yはノードの座標
    int x = P[T[v].location].x;
    int y = P[T[v].location].y;
    // ノードの座標が指定された座標に収まるときはansに加える
    if (sx <= x && x <= tx && sy <= y && y <= ty) {
        ans.push_back(P[T[v].location]);
    }

    // ノードの座標が指定された座標に収まらない時
    // 根から葉に行くにつれて大きく(or小さく)なるのでもし左端，右端にも入らなかった場合は
    // それより葉側のノードも範囲外->探索する必要はない
    if (depth % 2 == 0) { // 深さが偶数の時x軸に関して探索
        if (T[v].l != NIL) {
            if (sx <= x) {
                find(T[v].l, sx, tx, sy, ty, depth + 1, ans);
            }
        }
        if (T[v].r != NIL) {
            if (x <= tx) {
                find(T[v].r, sx, tx, sy, ty, depth + 1, ans);
            }
        }
    } else { // 深さが偶数の時y軸に関して探索
        if (T[v].l != NIL) {
            if (sy <= y) {
                find(T[v].l, sx, tx, sy, ty, depth + 1, ans);
            }
        }
        if (T[v].r != NIL) {
            if (y <= ty) {
                find(T[v].r, sx, tx, sy, ty, depth + 1, ans);
            }
        }
    }
}

int main()
{
    int x, y;
    scanf("%d", &N);
    for (int i = 0; i < N; i++) {
        scanf("%d %d", &x, &y); // cinより高速なscanf関数を使用
        P[i] = Point(i, x, y);
        T[i].l = T[i].r = T[i].p = NIL; // Tには親，子を設定しない
    }

    np = 0;

    int root = makeKDTree(0, N, 0);

    int q;
    scanf("%d", &q);
    int sx, tx, sy, ty;
    vector<Point> ans;
    for (int i = 0; i < q; i++) {
        scanf("%d %d %d %d", &sx, &tx, &sy, &ty);
        ans.clear();
        find(root, sx, tx, sy, ty, 0, ans);
        sort(ans.begin(), ans.end()); // 答えを昇順にソート
        for (int j = 0; j < ans.size(); j++) {
            ans[j].print(); // 昇順で出力
        }
        printf("\n");
    }

    return 0;
}

