  for (int i = 0; i < n; ++i) ps[i].x = distance(begin(xs), lower_bound(begin(xs), end(xs), ps[i].x));
  VV<P> init(xs.size());
  for (int i = 0; i < n; ++i) init[ps[i].x].push_back(ps[i]);
  for (auto&& v : init) sort(begin(v), end(v), comp_y);
  SegmentTree<Monoid> st(begin(init), end(init));
  int q; cin >> q;
  for (int i = 0; i < q; ++i) {
    int xl, xr, yl, yr; cin >> xl >> xr >> yl >> yr, ++xr, ++yr;
    xl = distance(begin(xs), lower_bound(begin(xs), end(xs), xl));
    xr = distance(begin(xs), lower_bound(begin(xs), end(xs), xr));
    auto res = st.get(xl, xr, yl, yr);
    sort(begin(res), end(res), comp_id);
    for (const auto& e : res) cout << e.id << '\n';
    cout << '\n';
  }
}

#include<stdio.h>
#include<vector>
#include<algorithm>
using namespace std;

struct Point {
	long long x, y;
	int i;
};

struct Node {
	Point p;
	int left;
	int right;
};

bool cmp_x(const Point& p1, const Point& p2) {
	return p1.x < p2.x;
}

bool cmp_y(const Point& p1, const Point& p2) {
	return p1.y < p2.y;
}

int makeTree(Node kDTree[],int& i, vector<Point>& points, int begin, int end,int depth) {
	if (begin >= end)return -1;
	if (depth & 1)sort(points.begin() + begin, points.begin() + end, cmp_x);
	else sort(points.begin() + begin, points.begin() + end, cmp_y);

	depth++;

	int mid = (begin + end) / 2;
	int j = i; i++;

	kDTree[j].p = points[mid];

	kDTree[j].left = makeTree(kDTree, i, points, begin, mid, depth);
	kDTree[j].right = makeTree(kDTree, i, points, mid + 1, end, depth);

	return j;
}

void searchTree(Node kDTree[], int i, Point p1, Point p2, int depth,vector<int>& ans) {
	Point p = kDTree[i].p;
	if (p.x >= p1.x && p.x <= p2.x && p.y >= p1.y && p.y <= p2.y) {
		ans.push_back(p.i);
	}

	if (depth & 1) {
		if (kDTree[i].left != -1 && p.x >= p1.x) {
			searchTree(kDTree, kDTree[i].left, p1, p2, depth + 1, ans);
		}
		if (kDTree[i].right != -1 && p.x <= p2.x) {
			searchTree(kDTree, kDTree[i].right, p1, p2, depth + 1, ans);
		}
	}
	else {
		if (kDTree[i].left != -1 && p.y >= p1.y) {
			searchTree(kDTree, kDTree[i].left, p1, p2, depth + 1, ans);
		}
		if (kDTree[i].right != -1 && p.y <= p2.y) {
			searchTree(kDTree, kDTree[i].right, p1, p2, depth + 1, ans);
		}
	}
}

const int MAX = 500000;

int main() {
	int n, q;
	vector<Point> points;
