struct Point {

	int x, y, id;

	Point(void){};
	Point(int a, int b, int c):x(a), y(b), id(c){};

}; 

int cmpX(const void *a, const void *b) {

	Point *pa = (Point *)a;
	Point *pb = (Point *)b;

	return pa->x - pb->x; 

}

int cmpY(const void *a, const void *b) {

	Point *pa = (Point *)a;
	Point *pb = (Point *)b;

	return pa->y - pb->y; 

}

bool cmpx(Point a, Point b) {
	return a.x < b.x;
}

bool cmpy(Point a, Point b) {
	return a.y < b.y;
}

int cmpInt(const void *a, const void *b) {

	int *x = (int *)a;
	int *y = (int *)b;

	return *x - *y;

}

