class PrioritySearchTree{
	struct P{
		int idx,x,y;
		P(int idx,int x,int y):idx(idx),x(x),y(y){}
		bool operator<(const P& p)const{return x<p.x;}
	};
	struct Node{
		int idx,x,y;
		Node *l,*r;
		Node(const P &p):idx(p.idx),x(p.x),y(p.y){}
		~Node(){
			if(l)delete l;
			if(r)delete r;
		}
		void search(bool odd,int x1,int y1,int x2,int y2,std::vector<int> &result)const{
			if(!this||odd&&y2<y)return;
			if(x<x1)r->search(!odd,x1,y1,x2,y2,result);
			else if(x2<x)l->search(!odd,x1,y1,x2,y2,result);
			else {
				if(y1<=y&&y<=y2)result.push_back(idx);
				l->search(!odd,x1,y1,x2,y2,result);
				r->search(!odd,x1,y1,x2,y2,result);
			}
		}
	} *root;
	Node* build(bool odd,std::vector<P> &ps,int a,int b){
		if(a>b)return NULL;
		int m;
		if(odd){
			int miny=ps[a].y;
			m=a;
			for(int i=a+1;i<=b;i++){
				if(ps[i].y < miny){
					miny=ps[i].y;
					m=i;
				}
			}
		}else{
			m=(a+b)/2;
		}
		Node *res=new Node(ps[m]);
		res->l=build(!odd,ps,a,m-1);
		res->r=build(!odd,ps,m+1,b);
		return res;
	}
public:
	PrioritySearchTree(const std::vector<std::pair<int,int> > &xy){
		std::vector<P> ps;
		for(int i=0;i<(int)xy.size();i++)ps.push_back(P(i,xy[i].first,xy[i].second));
		std::sort(ps.begin(),ps.end());
		root=build(true,ps,0,ps.size()-1);
	}
	PrioritySearchTree(){delete root;}
	std::vector<int> search(int x1,int y1,int x2,int y2)const{
		std::vector<int> result;
		root->search(true,x1,y1,x2,y2,result);
		std::sort(result.begin(),result.end());
		return result;
	}
};

