#define MAXN 500005
using namespace std;
inline long long sq(long long x){return x*x;}
namespace KDTree {
    struct Point {
        int x, y;
        int index;
        long long distance(const Point &b) const {
            return sq(x-b.x) + sq(y-b.y);
        }
        bool in(const Point& a, const Point& b) const {
            return a.x <= x && x <= b.x && a.y <= y && y <= b.y;
        }
    };
    inline bool cmpX(const Point &a, const Point &b){
        return a.x < b.x || (a.x == b.x && a.y < b.y) || (a.x == b.x && a.y == b.y && a.index < b.index);
    }
    inline bool cmpY(const Point &a, const Point &b){
        return a.y < b.y || (a.y == b.y && a.x < b.x) || (a.y == b.y && a.x == b.x && a.index < b.index);
    }
    bool cmp(const Point &a, const Point &b, bool div){
        return div?cmpY(a,b):cmpX(a,b);
    }
    struct Node {
        Point e;
        Node *lc, *rc;
        bool div;
    } pool[MAXN], *tail, *root;
    void init(){
        tail = pool;
    }
    Node *build(Point *a, int l, int r, bool div){
        if(l >= r) return NULL;
        Node *p = tail++;
        p->div = div;
        int mid = (l+r)/2;
        nth_element(a+l,a+mid,a+r,div?cmpY:cmpX);
        p->e = a[mid];
        p->lc = build(a,l,mid,!div);
        p->rc = build(a,mid+1,r,!div);
        return p;
    }
    int ans[105], ans_cnt = 0;
    void RangeQuery(Node *node, Point& L, Point& R)
    {
        if(node == NULL) return;
        if(node->e.in(L, R)) ans[ans_cnt++] = node->e.index;
        if(!node->div){
            if(node->e.x >= L.x){
                RangeQuery(node->lc, L, R);
            }
            if(node->e.x <= R.x){
                RangeQuery(node->rc, L, R);
            }
        } else {
            if(node->e.y >= L.y){
                RangeQuery(node->lc, L, R);
            }
            if(node->e.y <= R.y){
                RangeQuery(node->rc, L, R);
            }
        }
    }
};

KDTree::Point r[MAXN];

