    for(lli i = 0;i < n;i++) k[i] = i;
}

void make(vitr from,vitr to,int d){
    if(from == to) return;
    sort(from,to,[d](lli a,lli b){
        return p[a][d] < p[b][d];
    });
    make(from,from+(to-from)/2,(d+1)%2);
    make(from+(to-from)/2+1,to,(d+1)%2);
}

bool contain(vll& a,vll& b,vll& s){
    for(lli i = 0;i < 2;i++){
        if(a[i] > s[i]) return false;
        if(b[i] < s[i]) return false;
    }
    return true;
}

void search(vll& s,vll& t,vll& a,vll& b,lli d,vitr from,vitr to){
    if(from == to) return;
    if(contain(s,t,a) && contain(s,t,b)){
        for(vitr itr = from;itr < to;itr++){
            ans.push_back(*itr);
        }
        return;
    }
    for(lli i = 0;i < 2;i++){
        if(a[i] > t[i]) return;
        if(b[i] < s[i]) return;
    }
    lli l = p[*(from+(to-from)/2)][d];
    if(contain(s,t,p[*(from+(to-from)/2)])) ans.push_back(*(from+(to-from)/2));
    swap(b[d],l);
    search(s,t,a,b,(d+1)%2,from,from+(to-from)/2);
    swap(b[d],l);
    swap(a[d],l);
    search(s,t,a,b,(d+1)%2,from+(to-from)/2+1,to);
    swap(a[d],l);
}


