struct Node {
    int location;
    int p, l, r;
    Node() {}
};

struct Point {
    int id, x, y;
    Point() {}
    Point (int id, int x, int y) :id(id), x(x), y(y)  {}
    bool operator<(const Point& p) const {
        return id < p.id;
    }

    void print() {
        printf("%d\n", id);
    }
};

static const int MAX = 1000000;
static const int NIL = -1;

int N;
Point P[MAX];
Node T[MAX];
int np;

bool lessX(const Point &p1, const Point &p2) {
    return p1.x < p2.x;
}

bool lessY(const Point &p1, const Point &p2) {
    return p1.y < p2.y;
}

int makekDTree(int l, int r, int depth) {
    if (!(l<r)) return NIL;
    int mid = (l + r) / 2;
    int t = np++;
    if (depth%2 == 0) {
        sort(P + l, P + r, lessX);
    }
    else {
        sort(P + l, P + r, lessY);
    }
    T[t].location = mid;
    T[t].l = makekDTree(l, mid, depth + 1);
    T[t].r = makekDTree(mid+1, r, depth + 1);

    return t;
}

void find(int v, int sx, int tx, int sy, int ty, int depth, vector<Point> & ans) {
    int x = P[T[v].location].x;
    int y = P[T[v].location].y;

    if (sx <= x and x <= tx and sy <= y and y <= ty) {
        ans.push_back(P[T[v].location]);
    }

    if (depth%2 == 0) {
        if (T[v].l != NIL) {
            if (sx <= x) find(T[v].l, sx, tx, sy, ty, depth + 1, ans);
        }
        if (T[v].r != NIL) {
            if (x <= tx) find(T[v].r, sx, tx, sy, ty, depth + 1, ans);
        }
    }
    else {
        if (T[v].l != NIL) {
            if (sy <= y) find(T[v].l, sx, tx, sy, ty, depth + 1, ans);
        }
        if (T[v].r != NIL) {
            if (y <= ty) find(T[v].r, sx, tx, sy, ty, depth + 1, ans);
        }
    }
}

int main() {
    int x, y;
    scanf("%d", &N);
    rep(i, N) {
        scanf("%d %d", &x, &y);
        P[i] = Point(i, x, y);
        T[i].l = T[i].r = T[i].p = NIL;
    }

    np = 0;

    int root = makekDTree(0, N, 0);

    int q;
    scanf("%d", &q);
    int sx, tx, sy, ty;
    vector<Point> ans;
    rep(i, q) {
        scanf("%d %d %d %d", &sx, &tx, &sy, &ty);
        ans.clear();
        find(root, sx, tx, sy, ty, 0, ans);
        sort(ans.begin(), ans.end());
        rep(j, ans.size()) {
            ans[j].print();
        }
        printf("\n");
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <memory>
#include <algorithm>


struct Point {
    int id;
    int x;
    int y;

    Point(int id, int x, int y) : id(id), x(x), y(y) {}
};

using PointList = std::vector<Point>;


class KdTree {
    struct Node {
        using Ptr = std::unique_ptr<Node>;

        Point location;
        Ptr left;
        Ptr right;

        Node(const Point& loc, Ptr l, Ptr r)
            : location(loc), left(std::move(l)), right(std::move(r)) {}

        Node(const Point& loc) : Node(loc, nullptr, nullptr) {}
    };

    Node::Ptr build(PointList::iterator first, PointList::iterator last, int depth) {
        auto k = std::distance(first, last);
        if (k < 1)
            return nullptr;

        if (k == 1) {
            return std::make_unique<Node>(*first);
        }

        if (depth % 2 == 0) {
            // horizontal
            std::sort(first, last, [](const Point& p1, const Point& p2) { return p1.x < p2.x; });
        } else {
            // vertical
            std::sort(first, last, [](const Point& p1, const Point& p2) { return p1.y < p2.y; });
        }
        auto mid = first + std::distance(first, last) / 2;
        return std::make_unique<Node>(
            *mid,
            build(first, mid, depth+1),
            build(mid+1, last, depth+1)
        );;
    }

public:
    explicit KdTree(PointList points) : _root(nullptr) {
        _root = build(points.begin(), points.end(), 0);
    }

    PointList find(int sx, int sy, int tx, int ty) {
        PointList points;
        find(*_root, sx, sy, tx, ty, 0, points);
        std::sort(points.begin(), points.end(), [](const Point& p1, const Point& p2) { return p1.id < p2.id; });
        return points;
    }

    void find(const Node& node, int sx, int sy, int tx, int ty, int depth, PointList& ans) {
        auto p = node.location;
        if (sx <= p.x && p.x <= tx && sy <= p.y && p.y <= ty) {
            ans.push_back(p);
        }

        if (depth % 2 == 0) {
            // horizontal
            if (node.left != nullptr && sx <= p.x) {
                find(*node.left, sx, sy, tx, ty, depth+1, ans);
            }
            if (node.right != nullptr && p.x <= tx) {
                find(*node.right, sx, sy, tx, ty, depth+1, ans);
            }
        } else {
            // vertical
            if (node.left != nullptr && sy <= p.y) {
                find(*node.left, sx, sy, tx, ty, depth+1, ans);
            }
            if (node.right != nullptr && p.y <= ty) {
                find(*node.right, sx, sy, tx, ty, depth+1, ans);
            }
        }
    }

private:
    Node::Ptr _root;
};


int main() {
    using namespace std;
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    PointList points;
    for (int i = 0; i < n; ++i) {
        int x, y;
        cin >> x >> y;
        points.emplace_back(i, x, y);
    }
    KdTree kdtree(std::move(points));

    int q;
    cin >> q;
    for (int i = 0; i < q; ++i) {
        int sx, sy, tx, ty;
        cin >> sx >> tx >> sy >> ty;
        auto found = kdtree.find(sx, sy, tx, ty);
        for (auto& p : found) {
            cout << p.id << "\n";
        }
        cout << "\n";
    }

    return 0;
}

