const int MAX_N = 5e5 + 5;
const int MAX_LG = 14;
pair<int , int> x[MAX_N] ; int y[MAX_N];
pair<int , int> st[MAX_LG][MAX_N];
void build(int dep , int l , int r)
{
    if (l == r)
    {
        st[dep][l] = {y[x[l].second],x[l].second};
        return ;
    }
    int mid = (l + r) >> 1;
    build(dep + 1 , l , mid);
    build(dep + 1 , mid + 1 , r);
    merge(st[dep + 1] + l , st[dep + 1] + mid + 1 , st[dep + 1] + mid + 1 , st[dep + 1] + r + 1 , st[dep] + l);
}
vector<int> result;
inline void query(int dep , int l , int r , int x1 , int y1 , int x2 , int y2)
{

    if (x[r].first < x1 || x[l].first > x2)
        return ;
    if (st[dep][l].first > max(y1 , y2) || st[dep][r].first < min(y1 , y2))
        return ;
    if (x[l].first >= x1 && x[r].first <= x2)
    {
        if (st[dep][l].first >= min(y1 , y2) && st[dep][r].first <= max(y1 , y2))
        {
            for (int j = l ; j <= r ; j ++)
                result.push_back(st[dep][j].second);
            return ;
        }
    }
    int mid = (l + r) >> 1;
    query(dep + 1 , l ,     mid , x1 , y1 , x2 , y2);
    query(dep + 1 , mid + 1 , r , x1 , y1 , x2 , y2);
    return ;
}
int32_t main()
{
    int n = in();
    for (int i = 0 ; i < n ; i ++)
    {
        x[i] = {in() , i};
        y[i] = in();
    }
    sort(x , x + n);
    build(0 , 0 , n - 1);
    int q = in();
    while (q --)
    {
        int x1 = in() , x2 = in() , y1 = in() , y2 = in();
        if (x2 < x1) {swap(x1 , x2); swap(y1 , y2) ;}
        result.clear();
        query(0 , 0 , n - 1 , x1 , y1 , x2 , y2);
        sort(result.begin(),result.end());
        for (int j = 0 ; j < result.size() ; j ++)
            cout << result[j] << "\n";
        cout << "\n";
    }
}

