void query(Node *v,int L,int R,int D,int U,int a,int b,int c,int d){
	if(L>R||D>U)return;
	if(v==NULL)return;
	//printf("query %d %d %d %d %d %d %d %d\n",L,R,D,U,a,b,c,d);
	if(v->lp==NULL&&v->rp==NULL){
		int x = (v->val).fi, y = (v->val).sec;
		if(a<=x&&x<=b&&c<=y&&y<=d)print(v);
	}else{
		int nL=L,nR=R,nD=D,nU=U;
		if((v->depth)%2==0)nR = min(nR,(v->val).fi-1);
		else nU = min(nU,(v->val).sec-1);
		if(nL>nR||nD>nU){}
		else if(a<=nL&&nR<=b&&c<=nD&&nU<=d)report_subtree(v->lp);
		else if(nR<a||b<nL||nU<c||d<nD){}
		else query(v->lp,nL,nR,nD,nU,a,b,c,d);
		nL=L,nR=R,nD=D,nU=U;
		if((v->depth)%2==0)nL = max(nL,(v->val).fi);
		else nD = max(nD,(v->val).sec);
		if(nL>nR||nD>nU){}
		else if(a<=nL&&nR<=b&&c<=nD&&nU<=d)report_subtree(v->rp);
		else if(nR<a||b<nL||nU<c||d<nD){}
		else query(v->rp,nL,nR,nD,nU,a,b,c,d);
	}
}
