using namespace std;

struct point{
	int x, y, id;
};

struct _node{
	struct point p;
	struct _node *left;
	struct _node *right;
};

struct rect{
	int x1, y1, x2, y2;
};

typedef struct _node * node;

const int MAX_N = 500005;

struct point p[MAX_N];

int ptr;
int a[MAX_N];
int temp[MAX_N];

node head, z;

void tree2Dinsert (struct point p ){

	node f, t;
	int d, td;

	for (d = 0, t = head; t != z; d = !d ){
		td = (d ? (p.x < t->p.x ) : (p.y < t->p.y ) );
		f = t;
		t = (td ? t->left : t->right );
	} // end for

	t = new (_node );
	t->p = p; t->left = z; t->right = z;

	if (td )
		f->left = t;
	else
		f->right = t;
}

void preprocess (int n ){

	int i;
	p[0].x = 0; p[0].y = 0; p[0].id = -1;

	z = new (_node );
	z->left = z; z->right = z; z->p = p[0];

	head = new (_node );
	head->left = z; head->right = z; head->p = p[0];

	for (i = 1; i <= n; i++ ) tree2Dinsert (p[i] );
}

int insiderect (struct point p, struct rect range ){

	return ((range.x1 <= p.x && p.x <= range.x2 )
		&& (range.y1 <= p.y && p.y <= range.y2 ) );
}

int handle (struct point p ){
	a[ptr] = p.id;
	ptr++;
}

void tree2drange (node t, struct rect range, int d ){
	int t1, t2, tx1, tx2, ty1, ty2;
	if (t == z ) return;
	tx1 = (range.x1 < t->p.x );
	tx2 = (t->p.x <= range.x2 );
	ty1 = (range.y1 < t->p.y );
	ty2 = (t->p.y <= range.y2 );
	t1  = (d ? tx1 : ty1 );
	t2  = (d ? tx2 : ty2 );
	if (t1 ) tree2drange (t->left, range, !d );
	if (insiderect (t->p, range ) )
		if (t != head ) handle (t->p );
	if (t2 ) tree2drange (t->right, range, !d );
}

void bucket_sort (int radix ){

	memset (temp, 0, sizeof (temp ) );
	vector<int> b[10];
	rep (i, 10 ) b[i].clear();

	rep (i, ptr ){
		b[a[i]/(int)pow(10, radix )].push_back (a[i] );
	} // end rep

	int k = 0;
	rep (i, 10 ){
		rep (j, b[i].size() ){
			temp[k] = b[i][j];
			k++;
		} // end rep
	} // end rep

	rep (i, ptr ) a[i] = temp[i];		
}

void radix_sort (void ){
	int maxn = 0;
	rep (i, ptr ){
		if (a[i] > maxn ) maxn = a[i];
	} // end rep

	for (int i = 0; maxn > 0; i++, maxn /= 10 ){
		bucket_sort (i);
	} // end for
}

int main()
{
