std::unique_ptr<KDTree::Node> KDTree::build(std::vector<Vertex>::iterator low, std::vector<Vertex>::iterator high, int depth) {
  if(!(low < high)) return nullptr;
  int index = (low - begin(vertex_) + high - begin(vertex_)) / 2;
  std::sort(low, high, Compare(depth));
  auto middle = begin(vertex_) + index;
  auto result = std::unique_ptr<Node>(new Node(index));
  result->left_child = build(low, middle, (depth + 1) % dimension_);
  result->right_child = build(middle + 1, high, (depth + 1) % dimension_);
  return result;
}
