    }
    void init()
    {
        for(int i=0;i<2;i++)
        {
            for(int j=0;j<2;j++)
            {
                scanf("%d",&border[i][j]);
            }
        }
    }
};

int dimension=0;
int Size=2;

class Node
{
public:
    int idx;
    vec pos;

    Node()
    {
        pos.resize(2);
    }
    bool operator < (const Node & node) const
    {
        int d=dimension;
        return pos[d]<node.pos[d];
    }
};

priority_queue<int,vector<int>,greater<int> > ans;

class KDTree
{
public:
    vector<Node> nodes;
    int n;

    KDTree(int _n)
    {
        n=_n;
        nodes.resize(n);
        init();
        build(0,n,0);
    }

    void init()
    {
        for(int i=0;i<n;i++)
        {
            scanf("%d %d",&nodes[i].pos[0],&nodes[i].pos[1]);
            nodes[i].idx=i;
        }
    }

    void build(int l,int r,int d)
    {
        if(l+1>=r) return;
        int mid=(l+r)/2;
        dimension=d;
        nth_element(nodes.begin()+l,nodes.begin()+mid,nodes.begin()+r);
        build(l,mid,d^1);
        build(mid+1,r,d^1);
    }

    void query(int l,int r,Rect & rect,int d)
    {
        if(l>=r) return;
        int mid=(l+r)/2;
        if(rect.in(nodes[mid].pos[0],0)&&rect.in(nodes[mid].pos[1],1))
        {
            ans.push(nodes[mid].idx);
        }
        if(nodes[mid].pos[d]<=rect.border[d][1])
        {
            query(mid+1,r,rect,d^1);
        }
        if(nodes[mid].pos[d]>=rect.border[d][0])
        {
            query(l,mid,rect,d^1);
        }
    }
};

int main()
{
    int n,q;

    while(scanf("%d",&n)!=EOF)
    {
        KDTree kd(n);
        scanf("%d",&q);

        while(q--)
        {
            Rect rect;
            rect.init();
            kd.query(0,n,rect,0);
            while(!ans.empty())
            {
                int top=ans.top();ans.pop();
                printf("%d\n",top);
            }
            puts("");
        }
    }

    return 0;
}

