		pair<vi, vi> range = { vi(2), vi(2) };
		Loop(j, 2) {
			cin >> range.first[j] >> range.second[j];
		}
		vi ans = kdtree.find_in_range(range);
		Loop(j, ans.size()) printf("%d\n", ans[j]);
		printf("\n");
	}
}

