bool cmp_x(point a, point b)
{
	return a.x < b.x;
}
bool cmp_y(point a, point b)
{
	return a.y < b.y;
}
struct treeNode
{
	int loc;
	treeNode* left;
	treeNode* right;
	treeNode()
	{
		left = NULL;
		right = NULL;
		loc = 0;
	}
};
class kdtree
{
private:
	treeNode* root;
	treeNode* mktree(treeNode*& v, int lo, int hi, int depth, point* s)
	{
		if (!(lo < hi)) return NULL;
		v = new treeNode;
		if (depth % 2 == 0)
		{
			sort(s + lo, s + hi, cmp_x);
		}
		else {
			sort(s + lo, s + hi, cmp_y);
		}
		int mid = (lo + hi) / 2;
		v->loc = mid;
		v->left = mktree(v->left, lo, mid, depth + 1, s);
		v->right = mktree(v->right, mid + 1, hi, depth + 1, s);
		return v;
	}
	void search(treeNode* v, int sx, int tx, int sy, int ty, int depth)
	{
		int x = s[v->loc].x;
		int y = s[v->loc].y;
		int id = s[v->loc].id;
		if (sx <= x && sy <= y && y <= ty && x <= tx)
		{
			ans.push_back(id);
		}
		if (depth % 2 == 0)
		{
			if (v->left != NULL)
			{
				if (sx <= x)
				{
					search(v->left, sx, tx, sy, ty, depth + 1);
				}
			}
			if (v->right != NULL)
			{
				if (tx >= x)
				{
					search(v->right, sx, tx, sy, ty, depth + 1);
				}
			}
		}
		else
		{
			if (v->left != NULL)
			{
				if (sy <= y)
				{
					search(v->left, sx, tx, sy, ty, depth + 1);
				}
			}
			if (v->right != NULL)
			{
				if (ty >= y)
				{
					search(v->right, sx, tx, sy, ty, depth + 1);
				}
			}
		}

	}
public:
	kdtree()
	{
		root = NULL;
	}
	void query(int sx, int tx, int sy, int ty)
	{
		ans.clear();
		search(root, sx, tx, sy, ty, 0);
	}
	void init(point* s, int size)
	{
		mktree(root, 0, size, 0, s);
	}
};
