set<data> t[(1<<20)];

void Set(int x,int y,int id){
  x=x+(1<<19)-1;
  while(1){
    if(t[x].size()<100)t[x].insert((data){y,id});
    if(x==0)break;
    x=(x-1)/2;
  }
}

void find(int ax,int ay,int bx,int by,vector<int> &v,int k=0,int l=0,int r=(1<<19)){

  if(bx<=l || r<=ax)return;

  if(ax<=l&&r<=bx){
    set<data> :: iterator it = t[k].lower_bound((data){ay,-1});
    while(1){
      if(it==t[k].end() || by < it->y)break;
      v.push_back(it->id);
      it++;
    }
  }else{
    find(ax,ay,bx,by,v,k*2+1,l,(l+r)/2);
    find(ax,ay,bx,by,v,k*2+2,(l+r)/2,r);
  }
}

