using namespace std;

#define NIL -1

struct Point{
    int location;
    int x;
    int y;
};

bool asc_x(const Point& l, const Point& r) {
    return l.x < r.x;
}

bool asc_y(const Point& l, const Point& r) {
    return l.y < r.y;
}

struct Node{
    Point p;
    Node* left;
    Node* right;
};

class Tree{
private:
    Node* top;
    Node* AddNode(vector<Point>& P, int l, int r, int depth){
        if (l > r) return NULL;
        Node* N = new Node;
        int m = (l + r) / 2;
        if (depth % 2) {
            sort(P.begin() + l, P.begin() + r + 1, asc_y);
        } else {
            sort(P.begin() + l, P.begin() + r + 1, asc_x);
        }
        N->p = P[m];
        N->left  = AddNode(P, l    , m - 1, depth + 1);
        N->right = AddNode(P, m + 1, r    , depth + 1);
        return N;
    }
    void findNode(int s_x, int t_x, int s_y, int t_y,
                  Node* N, int depth, vector<int>& ans){
        if (N == NULL) return;
        if (s_x <= N->p.x && N->p.x <= t_x &&
            s_y <= N->p.y && N->p.y <= t_y) {
                ans.push_back(N->p.location);
            }
        if (depth % 2) {
            if (N->p.y <= t_y) {
                findNode(s_x, t_x, s_y, t_y, N->right, depth + 1, ans);
            }
            if (N->p.y >= s_y) {
                findNode(s_x, t_x, s_y, t_y, N->left , depth + 1, ans);
            }
        } else {
            if (N->p.x <= t_x) {
                findNode(s_x, t_x, s_y, t_y, N->right, depth + 1, ans);
            }
            if (N->p.x >= s_x) {
                findNode(s_x, t_x, s_y, t_y, N->left , depth + 1, ans);
            }
        }
    }
public:

    int MakeTree(vector<Point>& P){
        top = AddNode(P, 0, P.size() - 1, 0);
    }

    void find(int s_x, int t_x, int s_y, int t_y, vector<int>& ans){
        findNode(s_x, t_x, s_y, t_y, top, 0, ans);
    }
};

