#include<iostream>
using namespace std;
#include<cstdio>
#include<algorithm>

struct point{ int x, y, id; };

point init(int pos_x, int pos_y, int index)
{
    point p; 
    p.x = pos_x, p.y = pos_y, p.id = index; 
    return p; 
}

bool cmp_x(const point &P1, const point &P2){ if(P1.x != P2.x){ return P1.x < P2.x; } return P1.y < P2.y; }
bool cmp_y(const point &P1, const point &P2){ if(P1.y != P2.y){ return P1.y < P2.y; } return P1.x < P2.x; }

void cycle_x(point *S, point *T, point *U, int left, int right)
{
    int mid = ((left + right) >> 1);
    int a = left, b = mid + 1;

    for(int i = left; i < right; i++){
        if(cmp_x(T[i], S[mid])){
            U[a++] = T[i];
        }else if(S[mid].id == T[i].id){
            U[mid] = T[i];
        }else{
            U[b++] = T[i];
        }
    }
    T[mid] = U[mid];
    if(right - left < 5){
		for(int i = left; i < right; i++){ T[i] = U[i]; }
	}
}

void cycle_y(point *S, point *T, point *U, int left, int right)
{
    int mid = ((left + right) >> 1);
    int a = left, b = mid + 1;

    for(int i = left; i < right; i++){
        if(cmp_y(T[i], S[mid])){
            U[a++] = T[i];
        }else if(S[mid].id == T[i].id){
            U[mid] = T[i];
        }else{
            U[b++] = T[i];
        }
    }
	T[mid] = U[mid];
	if(right - left < 5){
		for(int i = left; i < right; i++){ T[i] = U[i]; }
	}
}

void kd_tree(point *S, point *T, point *U, int left, int right, int d)
{
    if(right - left < 2) return;

	int f = d % 6;

	if(f == 0){ cycle_x(S, T, U, left, right); }
	if(f == 1){ cycle_y(U, S, T, left, right); }
	if(f == 2){ cycle_x(T, U, S, left, right); }
	if(f == 3){ cycle_y(S, T, U, left, right); }
	if(f == 4){ cycle_x(U, S, T, left, right); }
	if(f == 5){ cycle_y(T, U, S, left, right); }

	int mid = ((left + right) >> 1);

    kd_tree(S, T, U, left, mid, d + 1);
    kd_tree(S, T, U, mid + 1, right, d + 1);
}

int cnt;

void find_pt(int *Q, point *S, int sx, int tx, int sy, int ty, int left, int right, int d)
{
    if(left >= right) return;

    int mid = ((left + right) >> 1);
    point p = S[mid];
    int a = p.x, b = p.y;

    if(sx <= a && a <= tx && sy <= b && b <= ty){
        Q[cnt++] = p.id;
    }

    if((d & 1) == 0){
        if((left < mid) && (sx < a || (sx == a && sy <= b))){ find_pt(Q, S, sx, tx, sy, ty, left, mid, d + 1); }
        if((mid + 1 < right) && (a < tx || (a == tx && b <= ty))){ find_pt(Q, S, sx, tx, sy, ty, mid + 1, right, d + 1); }
    }else{
        if((left < mid) && (sy < b || (sy == b && sx <= a))){ find_pt(Q, S, sx, tx, sy, ty, left, mid, d + 1); }
        if((mid + 1 < right) && (b < ty || (b == ty && a <= tx))){ find_pt(Q, S, sx, tx, sy, ty, mid + 1, right, d + 1); }
    }
    return;
}

int main()
{
    point *S, *T, *U;
    int Q[100];
    int i, pos_x, pos_y, n;
    scanf("%d", &n);

    S = new point [n], T = new point [n], U = new point [n];

    for(i = 0; i < n; i++){
        scanf("%d %d", &pos_x, &pos_y);
        S[i] = init(pos_x, pos_y, i);
        T[i] = S[i];
    }
    sort(S, S + n, cmp_x);
    sort(T, T + n, cmp_y);

    kd_tree(S, T, U, 0, n, 0);

    int sx, tx, sy, ty, q;
    scanf("%d", &q);
    while(q){
        cnt = 0;
        scanf("%d %d %d %d", &sx, &tx, &sy, &ty);
        find_pt(Q, S, sx, tx, sy, ty, 0, n, 0);
        sort(Q, Q + cnt);
        for(int i = 0; i < cnt; i++){ printf("%d\n", Q[i]); }
        printf("\n");
        q--;
    }

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

static const int MAX = 1000000;
static const int NIL = -1;

int n;

struct Node{
  int location, p, l, r;
};

struct Point{
  int id,x,y;
  bool operator < (const Point &p) const {
    return id < p.id;
  }
};

Point P[MAX];
Node T[MAX];


bool lessX(const Point &p1, const Point &p2){ return p1.x < p2.x; }
bool lessY(const Point &p1, const Point &p2){ return p1.y < p2.y; }

int treeIndex = 0;

int makeTree(int l, int r, int depth){
  if(l >= r) return NIL;
  int mid = (l + r) / 2;
  int index = treeIndex++;
  if(depth % 2 == 0){
    sort(P+l, P+r, lessX);
    T[index].location = mid;
  }else{
    sort(P+l, P+r, lessY);
    T[index].location = mid;
  }
  T[index].r = makeTree(mid+1, r, depth + 1);
  T[index].l = makeTree(l, mid, depth + 1);
  return index;
}

void find(int v, int sx, int tx, int sy, int ty, int depth, vector<int> &ans){
  int x = P[T[v].location].x, y = P[T[v].location].y;
  if(sx <= x && x <= tx && sy <= y && y <= ty){
    ans.push_back(P[T[v].location].id);
  }
  if(T[v].l != NIL){
    if(depth % 2 == 0){
      if(sx <= x) find(T[v].l, sx, tx, sy, ty, depth+1, ans);
    }else{
      if(sy <= y) find(T[v].l ,sx, tx, sy, ty, depth+1, ans);
    }
  }
  if(T[v].r != NIL){
    if(depth % 2 == 0){
      if(x <= tx) find(T[v].r, sx, tx, sy, ty, depth+1, ans);
    }else{
      if(y <= ty) find(T[v].r, sx, tx, sy, ty, depth+1, ans);
    }
  }
}

int main(){
  scanf("%d" ,&n);
  for(int i = 0; i < n; i++){
    scanf("%d %d", &P[i].x, &P[i].y);
    P[i].id = i;
  }
  int root = makeTree(0, n, 0);

  int q;
  scanf("%d", &q);
  int sx, tx, sy, ty;
  vector<int> ans;
  for(int i = 0; i < q; i++){
    scanf("%d %d %d %d", &sx, &tx, &sy, &ty);
    ans.clear();
    find(root, sx, tx, sy, ty, 0, ans);
    sort(ans.begin(), ans.end());
    for(int i = 0; i < ans.size(); i++){
      printf("%d\n", ans[i]);
    }
    printf("\n");
  }
}

