    int sx,tx,sy,ty;
    vector<Point> ans;
    for(int i=0;i<q;i++){
        scanf("%d %d %d %d", &sx,&sy, &tx,&ty);
        ans.clear();
        find(root,sx,tx,sy,ty,0,ans);
        sort(ans.begin(),ans.end());
        for(int j=0;j<ans.size();j++){
            ans[j].print();
        }
        printf("\n");
    }
    return 0;

}

#include<bits/stdc++.h>

using namespace std;

class kDTree{
public:
  vector< vector<int> > vec; // points (all points should be unique.)
  vector< pair<int,int> > children; // children of a point
  int root; // root of the tree

  kDTree(vector< vector<int> > v):vec(v){
    children = vector< pair<int,int> >(v.size(), pair<int,int>(-1,-1));
    root = make_tree(0,vec.size(),0);
  }

  int make_tree(int l, int r, int d){
    if(r-l == 1) return l;
    if(r-l <= 0) return -1;

    vector<int> v(r-l);
    for(int i = 0; i < (int)v.size(); i++) v[i] = l+i;

    vector<int> p = choose(v, d, (r-l)/2);

    vector< vector<int> > L,R;
    for(int i = l; i < r; i++){
      if(p == vec[i]) continue;
      if(p[d] < vec[i][d]) R.push_back(vec[i]);
      if(p[d] >= vec[i][d]) L.push_back(vec[i]);
    }

    int c = l+L.size();
    for(int i = 0; i < (int)L.size(); i++) vec[l+i] = L[i];
    vec[c] = p;
    for(int i = 0; i < (int)R.size(); i++) vec[c+1+i] = R[i];
    children[c].first = make_tree(l,c,(d+1)%p.size());
    children[c].second = make_tree(c+1,r,(d+1)%p.size());
    return c;
  }

  /*
    find k-th position of element in a given array.
    assume currrent dimension is d.
    algorithm is quick select

    O(N)
    N: number of element
  */
  vector<int> choose(const vector<int>& v, const int d, const int k) const {
    if(v.size() == 1) return vec[v[0]];

    int p = rand()%v.size();
    vector<int> L,R;
    for(int i = 0; i < (int)v.size(); i++){
      if(p == i) continue;
      if(vec[v[i]][d] <= vec[v[p]][d]) L.push_back(v[i]);
      if(vec[v[i]][d] > vec[v[p]][d]) R.push_back(v[i]);
    }

    if((int)L.size() == k-1) return vec[v[p]];
    if((int)L.size() >= k) return choose(L,d,k);
    if((int)L.size() < k) return choose(R,d,k-(int)L.size()-1);
  }

  /*
    return set of points P_i that hold lower[x] <= P_i[x] <= upper[x] in all possible x.
   */
  vector< vector<int> > area_search(const vector<int>& lower, const vector<int>& upper,
                                     vector<int> c_lower, vector<int> c_upper,
                                    int l, int r, int d, int idx){

    if(l >= r || idx == -1 || include(lower, c_upper) || include(c_lower, upper)) return vector< vector<int> >();

    vector< vector<int> > res;
    if(include(c_lower, lower) && include(upper, c_upper)){
      for(int i = l; i < r; i++) res.push_back(vec[i]);
    }else{
      if(include(vec[idx], lower) && include(upper, vec[idx])) res.push_back(vec[idx]);
      vector<int> n_cl = c_lower, n_cu = c_upper;
      n_cl[d] = n_cu[d] = vec[idx][d];
      vector< vector<int> > v1 = area_search(lower, upper, c_lower, n_cu, l, idx, (d+1)%vec[idx].size(), children[idx].first); 
      vector< vector<int> > v2 = area_search(lower, upper, n_cl, c_upper, idx+1, r, (d+1)%vec[idx].size(), children[idx].second);
      res.insert(res.end(), v1.begin(), v1.end());
      res.insert(res.end(), v2.begin(), v2.end());
    }
    return res;
  }

  /*
    Are all elements of B less than all corresponding elements of A?
  */
  bool include(const vector<int>& A, const vector<int>& B){
    for(int i = 0; i < (int)A.size(); i++) if(A[i] < B[i]) return false;
    return true;
  }
};


