using namespace std;

struct KDimTree {
    using Point=pair<int, int>;
    struct Node {
        size_t index;
        Point p;
        Node *l, *r;
        Node(const Point &p, size_t i=0): index(i), p(p), l(NULL), r(NULL) {}
    } *root;
    struct Comp {
        bool operator()(int d, const Point &p, const Point &q) {
            return d? p.first<q.first : p.second<q.second;
        }
    } comp;
    KDimTree(): root(NULL) {}
    void insert(const Point &p, size_t i=0) {
        root = insert(root, 0, p, i);
    }
    Node *insert(Node *t, int d, const Point &p, size_t i=0) {
        if (t == NULL) return new Node(p, i);
        if (comp(d, p, t->p)) {
            t->l = insert(t->l, !d, p, i);
        } else {
            t->r = insert(t->r, !d, p, i);
        };
        return t;
    }
    template <class Output>
    bool search(const Point &ld, const Point &ru, Output &out) {
        search(root, 0, ld, ru, out);
        return !out.empty();
    }
    template <class Output>
    void search(
        Node *t, int d, const Point &ld, const Point &ru, Output &out
    ) {
        if (t == NULL) return;

        const Point &p=t->p;
        if (ld.first<=p.first && p.first<=ru.first)
            if (ld.second<=p.second && p.second<=ru.second)
                out.insert(*t);

        if (!comp(d, p, ld)) search(t->l, !d, ld, ru, out);
        if (!comp(d, ru, p)) search(t->r, !d, ld, ru, out);
    }
};

int main() {
    size_t n;
    scanf("%zu", &n);

    KDimTree tree;
    for (size_t i=0; i<n; ++i) {
        KDimTree::Point p;
        scanf("%d %d", &p.first, &p.second);

        tree.insert(p, i);
    }

    size_t q;
    scanf("%zu", &q);

    for (size_t i=0; i<q; ++i) {
        KDimTree::Point ld, ru;
        scanf("%d %d %d %d", &ld.first, &ru.first, &ld.second, &ru.second);

        struct IndexCompare {
            bool operator()(const KDimTree::Node &x, const KDimTree::Node &y) {
                return x.index < y.index;
            }
        };

        set<KDimTree::Node, IndexCompare> out;
        tree.search(ld, ru, out);

        for (const KDimTree::Node &x: out)
            printf("%zd\n", x.index);

        printf("\n");
    }

    return 0;
}

