    Point P[1000], Q[100];

    cin >> n;
    for(i = 0; i < n; i++){ cin >> pos_x >> pos_y; P[i] = Point(i, pos_x, pos_y); }

    node* root;
    root = make_tree(P, 0, n - 1, 0);  // make a 2-D_tree.

