	vector<int> ans;
	for(int i=0;i<q;i++)
	{
			scanf("%d%d%d%d",&sx,&tx,&sy,&ty);
			ans.clear();
			find(root,sx,tx,sy,ty,0,ans);
			sort(ans.begin(),ans.end());
			for(int j=0;j<ans.size();j++)printf("%d\n",ans[j]);
			printf("\n");
	}
	return 0;
}

