class KDTree {
private:
  typedef std::vector<double> Point;
  struct Node {
    int label;
    Point point;
    Node* left_child;
    Node* right_child;
    Node(int id, const Point& p) : label(id), point(p), left_child(nullptr), right_child(nullptr) {}
  };
public:
  KDTree(int d);
  void insert(int id, const Point& p);
  void search(const Point& low, const Point& high) const;
private:
  int dimension_;
  Node* root_;
  void insert(int id, const Point& p, Node* node, int depth);
  void search(const Point& low, const Point& high, Node* node, int depth) const;
};
//
KDTree::KDTree(int d) : dimension_(d), root_(new Node(-1, Point(d, 1e9+1))) {};
//
void KDTree::insert(int id, const Point& p) {insert(id, p, root_, 0);}
void KDTree::insert(int id, const Point& p, Node* node, int depth) {
  auto& child = p[depth] < node->point[depth] ? node->left_child : node->right_child;
  if(child) insert(id, p, child, (depth + 1) % dimension_);
  else      child = (new Node(id, p));
}
//
void KDTree::search(const Point& low, const Point& high) const {search(low, high, root_, 0);}
void KDTree::search(const Point& low, const Point& high, Node* node, int depth) const {
  if(!node) return;
  bool ok = true;
  for(int d = 0; d < dimension_; ++d) ok &= (low[d] <= node->point[d] && node->point[d] <= high[d]);
  if(ok) answer.push_back(node->label);
  if(low[depth] <= node->point[depth]) search(low, high, node->left_child, (depth + 1) % dimension_);
  if(node->point[depth] <= high[depth]) search(low, high, node->right_child, (depth + 1) % dimension_);
}
