class DisjointSet {
public:
    vector<int> rank, p;

    DisjointSet() {};
    DisjointSet(int s) {
        rank.resize(s, 0);
        p.resize(s, 0);
        for (int i = 0; i < s; i++) makeSet(i);
    }

    void makeSet(int x) {
        p[x] = x;
        rank[x] = 0;
    }

    bool same(int x, int y) {
        return findSet(x) == findSet(y);
    }

    void unite(int x, int y) {
        link(findSet(x), findSet(y));
    }

    void link(int x, int y) {
        if (rank[x] > rank[y]) {
            p[y] = x;
        } else {
            p[x] = y;
            if (rank[x] == rank[y]) {
                rank[y]++;
            }
        }
    }

    int findSet(int x) {
        while (x != p[x]) {
            x = p[x];
        }
        return x;
    }
};

int main(void) {
    int n, q; cin >> n >> q;
    DisjointSet ds = DisjointSet(n);

    for (int i = 0; i < q; i++) {
        int com, x, y; cin >> com >> x >> y;
        if (com == 0) {
            ds.unite(x, y);
        } else {
            if (ds.same(x, y)) {
                cout << 1 << endl;
            } else {
                cout << 0 << endl;
            }
        }
    }

    return 0;
}

