struct tree{
	int x,y;
	int num;
}tree[500000];
vector<int>ans;
bool cmpx(struct tree a , struct tree b){
	return a.x < b.x;
}

bool cmpy(struct tree a, struct tree b){
	return a.y < b.y;
}

void build(int begin,int end,int level){
	if(begin<end){
		if(!level)
			sort(tree+begin,tree+end,cmpx);
		else
			sort(tree+begin,tree+end,cmpy);
		int mid=(end+begin)/2;
		build(begin,mid,level^1);
		build(mid+1,end,level^1);
	}
}

void search(int begin ,int end, int sx , int tx ,int sy ,int ty ,int level ){
	if(begin<end){
		int mid=(end+begin)/2;
		if(!level){
			if(tree[mid].x>=sx&&tree[mid].x<=tx){
				if(tree[mid].y>=sy&&tree[mid].y<=ty)
					ans.push_back(tree[mid].num);
				search(begin,mid,sx,tx,sy,ty,level^1);
				search(mid+1,end,sx,tx,sy,ty,level^1);
			}
			else if(tx<tree[mid].x) search(begin,mid,sx,tx,sy,ty,level^1);
			else if(sx>tree[mid].x)	search(mid+1,end,sx,tx,sy,ty,level^1);
		}
		else{
			if(tree[mid].y>=sy&&tree[mid].y<=ty){
				if(tree[mid].x>=sx&&tree[mid].x<=tx)
					ans.push_back(tree[mid].num);
				search(begin,mid,sx,tx,sy,ty,level^1);
				search(mid+1,end,sx,tx,sy,ty,level^1);
			}
			else if(ty<tree[mid].y) search(begin,mid,sx,tx,sy,ty,level^1);
			else if(sy>tree[mid].y)	search(mid+1,end,sx,tx,sy,ty,level^1);
		}
	}
}

