using namespace std;

template<typename T>
using point = pair<T, T>;

template<typename T>
class KdTree {
private:
    struct node {
        uint32_t id;
        point<T> p;
        node *left, *right;
        node(uint32_t id, const point<T> &p) : id(id), p(p), left(NULL), right(NULL) {}
    };

    node *root;

    node *insert(node *nd, uint32_t id, const point<T> &p, bool x) {
        if (nd == NULL) return new node(id, p);

        if (x ? p.first < nd->p.first : p.second < nd->p.second) {
            nd->left = insert(nd->left, id, p, !x);
        } else {
            nd->right = insert(nd->right, id, p, !x);
        }

        return nd;
    }

    void search(node *nd, const point<T> &s, const point<T> &t, bool x, vector<uint32_t> &vec) {
        if (nd == NULL) return;

        if (s.first <= nd->p.first && nd->p.first <= t.first &&
            s.second <= nd->p.second && nd->p.second <= t.second) {
            vec.push_back(nd->id);
        }

        if (x ? s.first <= nd->p.first : s.second <= nd->p.second) search(nd->left, s, t, !x, vec);
        if (x ? nd->p.first <= t.first : nd->p.second <= t.second) search(nd->right, s, t, !x, vec);

        return;
    }

public:
    KdTree() : root(NULL) {}

    void insert(uint32_t id, const point<T> &p) {
        root = insert(root, id, p, true);
        return;
    }

    void search(const point<T> &s, const point<T> &t, vector<uint32_t> &vec) {
        search(root, s, t, true, vec);
        return;
    }

};

int main() {
    int32_t n;
    scanf("%d", &n);

    KdTree<int32_t> kdt;

    for (int32_t i = 0; i < n; i++) {
