    for (int32_t i = 0; i < q; i++) {
        int32_t sx, tx, sy, ty;
        scanf("%d %d %d %d", &sx, &tx, &sy, &ty);

        vector<uint32_t> res;
        kdt.search(make_pair(sx, sy), make_pair(tx, ty), res);

        sort(res.begin(), res.end());

        for (uint32_t id : res) printf("%u\n", id);
        printf("\n");
    }

