#include<bits/stdc++.h>

using namespace std;

typedef long long int64;

set< int > ans;

struct SegmentTreeFractionalCascading
{
  vector< vector< pair< int, int > > > seg;
  vector< vector< int > > LL, RR;
  int sz;

  SegmentTreeFractionalCascading(vector< vector< pair< int, int > > > &array)
  {
    sz = 1;
    while(sz < array.size()) sz <<= 1;
    seg.resize(2 * sz - 1);
    LL.resize(2 * sz - 1);
    RR.resize(2 * sz - 1);
    for(int k = 0; k < array.size(); k++) {
      for(auto &p : array[k]) seg[k + sz - 1].emplace_back(p);
      sort(begin(seg[k + sz - 1]), end(seg[k + sz - 1]));
    }
    for(int k = sz - 2; k >= 0; k--) {
      seg[k].resize(seg[2 * k + 1].size() + seg[2 * k + 2].size());
      LL[k].resize(seg[k].size() + 1);
      RR[k].resize(seg[k].size() + 1);
      merge(begin(seg[2 * k + 1]), end(seg[2 * k + 1]), begin(seg[2 * k + 2]), end(seg[2 * k + 2]), begin(seg[k]));
      int tail1 = 0, tail2 = 0;
      for(int i = 0; i < seg[k].size(); i++) {
        while(tail1 < seg[2 * k + 1].size() && seg[2 * k + 1][tail1] < seg[k][i]) ++tail1;
        while(tail2 < seg[2 * k + 2].size() && seg[2 * k + 2][tail2] < seg[k][i]) ++tail2;
        LL[k][i] = tail1, RR[k][i] = tail2;
      }
      LL[k][seg[k].size()] = (int) seg[2 * k + 1].size();
      RR[k][seg[k].size()] = (int) seg[2 * k + 2].size();
    }
  }

  int query(int a, int b, int lower, int upper, int k, int l, int r)
  {
    if(a >= r || b <= l) {
      return (0);
    } else if(a <= l && r <= b) {
      for(int i = lower; i < upper; i++) ans.emplace(seg[k][i].second);
      return (upper - lower);
    } else {
      return (query(a, b, LL[k][lower], LL[k][upper], 2 * k + 1, l, (l + r) >> 1) + query(a, b, RR[k][lower], RR[k][upper], 2 * k + 2, (l + r) >> 1, r));
    }
  }

  int query(int a, int b, int l, int r)
  {
    return (query(a, b, l, r, 0, 0, sz));
  }
};


int main()
{
  int N, X[500000], Y[500000];
  scanf("%d", &N);
  vector< int > nums(N);
  for(int i = 0; i < N; i++) {
    scanf("%d %d", &X[i], &Y[i]);
    nums[i] = X[i];
  }
  sort(begin(nums), end(nums));
  nums.erase(unique(begin(nums), end(nums)), end(nums));
  vector< vector< pair< int, int > > > g(nums.size());
  for(int i = 0; i < N; i++) {
    X[i] = lower_bound(begin(nums), end(nums), X[i]) - begin(nums);
    g[X[i]].emplace_back(Y[i], i);
  }
  SegmentTreeFractionalCascading seg(g);
  int Q;
  scanf("%d", &Q);
  while(Q--) {
    int a, b, c, d;
    scanf("%d %d %d %d", &a, &b, &c, &d);
    a = lower_bound(begin(nums), end(nums), a) - begin(nums);
    ++b;
    b = lower_bound(begin(nums), end(nums), b) - begin(nums);
    seg.query(a, b, c, d + 1);
    for(auto &s : ans) printf("%d\n", s);
    puts("");
    ans.clear();
  }
}

