};

class Point {
public:
  int id, x, y;

  Point() {}
  Point(int id, int x, int y) {
    this->id = id;
    this->x = x;
    this->y = y;
  }

  bool operator < (const Point &another) const {
    return id < another.id;
  }
};

const int MAX_N = 500000;

Node T[MAX_N];
Point P[MAX_N];

int N, NP = 0;
vector<Point> ANS;

bool compX(const Point &a, const Point &b) {
  return a.x < b.x;
}

bool compY(const Point &a, const Point &b) {
  return a.y < b.y;
}

int make1DTree(int l, int r, int d) {
  if (l >= r) return -1;

  int m = (l + r)/2;
  int t = NP++;

  if (d % 2 == 0) sort(P+l, P+r, compX);
  else sort(P+l, P+r, compY);

  T[t].location = m;
  T[t].l = make1DTree(l, m, d+1);
  T[t].r = make1DTree(m+1, r, d+1);

  return t;
}

void find(int v, int sx, int tx, int sy, int ty, int d) {
  int x = P[T[v].location].x;
  int y = P[T[v].location].y;

  if (sx <= x && x <= tx && sy <= y && y <= ty)
    ANS.push_back(P[T[v].location]);

  if (d % 2 == 0) {
    if (T[v].l != -1 && sx <= x) find(T[v].l, sx, tx, sy, ty, d+1);

    if (T[v].r != -1 && x <= tx) find(T[v].r, sx, tx, sy, ty, d+1);
  } else {
    if (T[v].l != -1 && sy <= y) find(T[v].l, sx, tx, sy, ty, d+1);

    if (T[v].r != -1 && y <= ty) find(T[v].r, sx, tx, sy, ty, d+1);
  }
}

