    if(x>=sx&&x<=tx&&y>=sy&&y<=ty) ans.push_back(P[T[v].location]);
    // 子はxで分割されている
    if(depth % 2 == 0) {
      if(T[v].l != NIL) {
        if(x>=sx) find(T[v].l,sx,tx,sy,ty,depth+1,ans);
      }
      if(T[v].r != NIL) {
        if(x<=tx) find(T[v].r,sx,tx,sy,ty,depth+1,ans);
      }
    } else {
      if(T[v].l != NIL) {
        if(y>=sy) find(T[v].l,sx,tx,sy,ty,depth+1,ans);
      }
      if(T[v].r != NIL) {
        if(y<=ty) find(T[v].r,sx,tx,sy,ty,depth+1,ans);
      }
    }
  }
};
int main()
{
  int x,y;
