            if (li >= l.ys.length && ri >= r.ys.length) break;
            if (li >= l.ys.length) n.ys ~= r.ys[ri++];
            else if (ri >= r.ys.length) n.ys ~= l.ys[li++];
            else {
                n.ys ~= (P[l.ys[li]].y < P[r.ys[ri]].y ? l.ys[li++] : r.ys[ri++]);
            }
        }
        return n;
    }
    this(Point[] ps) {
        this.P = ps.dup;
        auto ys = iota(0, ps.size, 1).array.sort!((i, j) => P[i].x < P[j].x).array;
        this.root = construct(ys);
    }

    /* (sx <= x <= gx && sy <= y <= gy)????????§??????(x, y)??§?±?esult???????????\??§??????. ??¢????????¢?????????????±???¨??¢???*/
    int[] query(int sx, int sy, int gx, int gy) {
        int[] result;
        void f(Node cur_root) {
            if (gx < cur_root.left_x || cur_root.right_x < sx) {
                // do nothing
            } else if (sx <= cur_root.left_x && cur_root.right_x <= gx) {
                int[] ys = cur_root.ys;
                result ~= ys.map!((i)=>tuple(P[i].y, i)).assumeSorted.upperBound(tuple(sy, 0)).lowerBound(tuple(gy + 1, 0)).map!((x)=>x[1]).array;
                //result ~= ys.assumeSorted!((i, j) => (P[i].y < P[j].y)).upperBound(sy).lowerBound(gy + 1).array;
            } else {
                if(cur_root.left is null || cur_root.right is null) {
                    foreach (i; cur_root.ys.map!((i)=>tuple(P[i].y, i)).assumeSorted.upperBound(tuple(sy, 0)).lowerBound(tuple(gy + 1, 0)).map!((x)=>x[1])) {
                        auto p = P[i];
                        if (sx <= p.x && p.x <= gx && sy <= p.y && p.y <= gy) {
                            result ~= i;
                        }
                    }
                } else {
                    f(cur_root.left);
                    f(cur_root.right);
                }
            }
        }
        f(root);
        return result;
    }
}

