template<int K, typename T>
class kDTree {
public:
    struct Point {
        int id;
        vector<T> xs;
        template<typename... Args>
        Point(int id, Args&& ...args):id(id), xs{forward<Args>(args)...}{}
    };
    kDTree(vector<Point>& ps):data(ps.size(), -1){
        build(ps, 0, (int)ps.size(), 0, 0);
    }
    vector<Point> rangeQuery(const Point& lo, const Point& hi, int k, int depth){
        vector<Point> res;
        if((int)data.size() <= k)return res;
        if(lo.xs <= data[k].xs && data[k].xs <= hi.xs)res.push_back(data[k]);
        int d = depth % K;
        if(lo.xs[d] <= data[k].xs[d]){
            vector<Point> tmp = rangeQuery(lo, hi, (k << 1) + 1, depth + 1);
            res.insert(res.end(), tmp.begin(), tmp.end());
        }
        if(data[k].xs[d] <= hi.xs[d]){
            vector<Point> tmp = rangeQuery(lo, hi, (k << 1) + 2, depth + 1);
            res.insert(res.end(), tmp.begin(), tmp.end());
        }
        return res;
    }
private:
    vector<Point> data;
    void build(vector<Point>& ps, int l, int r, int k, int depth){
        if(r <= l)return;
        if(l + 1 == r)data[k] = ps[l];
        else{
            int d = depth % K;
            sort(ps.begin() + l, ps.begin() + r, [&](const Point& a, const Point& b){return a.xs[d] < b.xs[d];});
            int mid = (l + r) >> 1;
            data[k] = ps[mid];
            build(ps, l, mid, (k << 1) + 1, depth + 1);
            build(ps, mid + 1, r, (k << 1) + 2, depth + 1);
        }
    }
};

int main(){
    int n;
    cin >> n;
    vector<kDTree<2, int>::Point> ps; ps.reserve(n << 1);
    rep(i, n){
        int x, y;
        cin >> x >> y;
        ps.emplace_back(i, x, y);
    }
    kDTree<2, int> kdtree(ps);
    int q;
    cin >> q;
    for(; q--; cout << '\n'){
        int sx, tx, sy, ty;
        cin >> sx >> tx >> sy >> ty;
        ps = kdtree.rangeQuery(kDTree<2, int>::Point(-1, sx, sy), kDTree<2, int>::Point(-1, tx, ty), 0, 0);
        sort(all(ps), [](const kDTree<2, int>::Point& a, const kDTree<2, int>::Point& b){return a.id < b.id;});
        for(const auto& p: ps)cout << p.id << '\n';
    }
    return 0;
}

