int make2Dtree(int l,int r,int d){
    if (r-l <= 0) return NIL;
    int mid = (l+r)/2;
    sort_ck(l,r,d);
    int t = np++;
    T[t].id = A[mid][2];
    T[t].x = A[mid][0];
    T[t].y = A[mid][1];
    int d_ = (d+1)%2;
    T[t].l = make2Dtree(l,mid,d_);
    T[t].r = make2Dtree(mid+1,r,d_);

    return t;
}

