	int i;
};

struct Node {
	Point point;
	int left;
	int	right;
};

template<class T>
void q_sort(T ary[], int begin, int end, bool (*cmp)(const T&, const T&)) {
	if (begin >= end)return;
	int left = begin;
	int right = end;
	T piv = ary[(begin + end) / 2];

	while (true) {
		while (cmp(ary[left], piv))left++;
		while (cmp(piv,ary[right]))right--;
		if (left >= right)break;
		swap(ary[left], ary[right]);
		left++;
		right--;
	}
	q_sort(ary, begin, left - 1, cmp);
	q_sort(ary, right + 1, end, cmp);
}

bool cmp_x(const Point& p1, const Point& p2) {
	return p1.x < p2.x;
}
bool cmp_y(const Point& p1, const Point& p2) {
	return p1.y < p2.y;
}

int makeTree(Node kDTree[], Point points[], int begin, int end, int depth, int& i) {
	if (begin >= end)return -1;

	if (depth % 2)q_sort(points, begin, end - 1, cmp_y);
	else q_sort(points, begin, end - 1, cmp_x);

	int mid = (begin + end) / 2;
	kDTree[i].point = points[mid];

	int j = i;
	i++;

	kDTree[j].left = makeTree(kDTree, points, begin, mid, depth + 1, i);
	kDTree[j].right = makeTree(kDTree, points, mid + 1, end, depth + 1, i);

	return j; 
}

void search(Node kDTree[],int i, Point& p1, Point& p2, int depth,set<int>& ans) {
	Point p = kDTree[i].point;
	if (p.x >= p1.x && p.y >= p1.y && p.x <= p2.x && p.y <= p2.y) {
		ans.insert(p.i);
	}

	if (depth % 2) {
		if (kDTree[i].left != -1 && kDTree[i].point.y >= p1.y) {
			search(kDTree, kDTree[i].left, p1, p2, depth + 1, ans);
		}
		if (kDTree[i].right != -1 && kDTree[i].point.y <= p2.y) {
			search(kDTree, kDTree[i].right, p1, p2, depth + 1, ans);
		}
	}
	else {
		if (kDTree[i].left != -1 && kDTree[i].point.x >= p1.x) {
			search(kDTree, kDTree[i].left, p1, p2, depth + 1, ans);
		}
		if (kDTree[i].right != -1 && kDTree[i].point.x <= p2.x) {
			search(kDTree, kDTree[i].right, p1, p2, depth + 1, ans);
		}
	}
}
int main() {
	int n, q;
	Point points[MAX];
	Node kDTree[MAX];


	cin >> n;
	for (int i = 0; i < n; i++) {
		cin >> points[i].x >> points[i].y;
		points[i].i = i;
	}

	int index = 0;
	makeTree(kDTree, points, 0, n, 0, index);

	cin >> q;
	for (int i = 0; i < q; i++) {
		Point p1, p2;
		set<int> ans;

		cin >> p1.x >> p2.x >> p1.y >> p2.y;
		search(kDTree, 0, p1, p2, 0, ans);

		for (set<int>::iterator it = ans.begin(); it != ans.end(); it++) {
			cout << *it << endl;
		}
		cout << endl;
	}
	return 0;
}

