struct Point{
    int id,x,y;

    void assign(int id_,int x_,int y_){
      id=id_,x=x_,y=y_;
    }

    bool operator <(const Point &p) const{
      return id<p.id;
    }
  };

  bool compX(const Point &a,const Point &b){
    return a.x<b.x;
  }
  bool compY(const Point &a,const Point &b){
    return a.y<b.y;
  }

struct Node{
  int l,r,index;

  Node(){
    l=r=-1;
  }
};

struct KDTree{
  vector<Node> node;
  vector<Point> point;

  int n,np;

  void init(int n_){
    n=n_;
    np=0;
    node.clear();
    point.clear();
    node.resize(n*2);
    point.resize(n);
  }

  int makeTree(int l,int r,int depth){
    if(l>=r)return -1;
    int v=np++;
    int m=(l+r)/2;

    if(depth%2==0){
      sort(point.begin()+l,point.begin()+r,compX);
    }
    else{
      sort(point.begin()+l,point.begin()+r,compY);
    }

    node[v].index=m;
    node[v].l=makeTree(l,m,depth+1);
    node[v].r=makeTree(m+1,r,depth+1);

    return v;
  }

  void find(int v,int sx,int sy,int tx,int ty,int depth,vector<int> *ans){
    int x=point[node[v].index].x;
    int y=point[node[v].index].y;

    if(sx<=x&&x<=tx&&sy<=y&&y<=ty){
      ans->push_back(point[node[v].index].id);
    }

    if(depth%2==0){
      if(node[v].l!=-1&&sx<=x)find(node[v].l,sx,sy,tx,ty,depth+1,ans);
      if(node[v].r!=-1&&x<=tx)find(node[v].r,sx,sy,tx,ty,depth+1,ans);
    }
    else{
      if(node[v].l!=-1&&sy<=y)find(node[v].l,sx,sy,tx,ty,depth+1,ans);
      if(node[v].r!=-1&&y<=ty)find(node[v].r,sx,sy,tx,ty,depth+1,ans);
    }
  }
};

int main(void){
  int n,q,i,j;
  int x,y,sx,sy,tx,ty;

  cin>>n;

  KDTree tree;
  tree.init(n);

  for(i=0;i<n;i++){
    scanf("%d %d",&x,&y);
    tree.point[i].assign(i,x,y);
  }

  tree.makeTree(0,n,0);

  vector<int> ans;

  cin>>q;
  for(i=0;i<q;i++){
    ans.clear();
    scanf("%d %d %d %d",&sx,&tx,&sy,&ty);
    tree.find(0,sx,sy,tx,ty,0,&ans);
    sort(ans.begin(),ans.end());

    for(j=0;j<ans.size();j++){
      printf("%d\n",ans[j]);
    }
    printf("\n");
  }

  return 0;
}

