void KDTree::insert(int id, const Point& p) {insert(id, p, root_, 0);}
void KDTree::insert(int id, const Point& p, const std::unique_ptr<Node>& node, int depth) {
  auto& child = p[depth] < node->point[depth] ? node->left_child : node->right_child;
  if(child) insert(id, p, child, (depth + 1) % dimension_);
  else      child = std::unique_ptr<Node>(new Node(id, p));
}
