void KDTree::search(const Point& low, const Point& high) const {search(low, high, root_, 0);}
void KDTree::search(const Point& low, const Point& high, const std::unique_ptr<Node>& node, int depth) const {
  if(!node) return;
  bool ok = true;
  for(int d = 0; d < dimension_; ++d) ok &= (low[d] <= node->point[d] && node->point[d] <= high[d]);
  if(ok) answer.push_back(node->label);
  if(high[depth] < node->point[depth]) {
    search(low, high, node->left_child, (depth + 1) % dimension_);
  } else if(node->point[depth] < low[depth]) {
    search(low, high, node->right_child, (depth + 1) % dimension_);
  } else {
    search(low, high, node->left_child, (depth + 1) % dimension_);
    search(low, high, node->right_child, (depth + 1) % dimension_);
  }
}

