using namespace std;

struct XY
{
    int x;
    int y;
    int index;
};

struct Node
{
    XY xy;
    Node *right;
    Node *left;
};

Node* kdTree(vector<XY> v, int first, int last, int depth) {
    int size = last - first;
    if (size < 0) {
        return nullptr;
    }

    int axis = depth % 2;
    if (axis == 0) {
        sort(v.begin() + first, v.begin() + last, [](const XY& first, const XY& second) {
            return first.x < second.x;
        });
    }
    else {
        sort(v.begin() + first, v.begin() + last, [](const XY& first, const XY& second) {
            return first.y < second.y;
        });
    }
    Node *node = new Node;
    node->xy = v[first + size / 2];
    node->right = kdTree(v, first + size / 2 + 1, last, depth + 1);
    node->left = kdTree(v, first, first + size / 2 - 1, depth + 1);

    return node;
}

void search(Node *p, int sx, int tx, int sy, int ty, int depth, vector<int>* result) {
    if (p == nullptr) {
        return;
    }

    int axis = depth % 2;

    if (axis == 0) {
        if (p->xy.x < sx) {
            search(p->right, sx, tx, sy, ty, depth + 1, result);
        }
        else if (p->xy.x > tx) {
            search(p->left, sx, tx, sy, ty, depth + 1, result);
        }
        else {
            search(p->left, sx, tx, sy, ty, depth + 1, result);
            if (p->xy.y >= sy && p->xy.y <= ty) {
                result->push_back(p->xy.index);
            }
            search(p->right, sx, tx, sy, ty, depth + 1, result);
        }
    }
    else {
        if (p->xy.y < sy) {
            search(p->right, sx, tx, sy, ty, depth + 1, result);
        }
        else if (p->xy.y > ty) {
            search(p->left, sx, tx, sy, ty, depth + 1, result);
        }
        else {
            search(p->left, sx, tx, sy, ty, depth + 1, result);
            if (p->xy.x >= sx && p->xy.x <= tx) {
                result->push_back(p->xy.index);
            }
            search(p->right, sx, tx, sy, ty, depth + 1, result);
        }
    }
}

void freeKdTree(Node *p) {
    if (p == nullptr) {
        return;
    }
    freeKdTree(p->left);
    freeKdTree(p->right);
    free(p);
}

int main()
{

    int n;
    cin >> n;
    vector<XY> xys;
    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        xys.push_back(XY{ x, y, i });
    }

    Node *pkdTree = kdTree(xys, 0, n - 1, 0);

    int q;
    cin >> q;
    for (int i = 0; i < q; i++) {
        int sx, tx, sy, ty;
        cin >> sx >> tx >> sy >> ty;
        vector<int> result;
        search(pkdTree, sx, tx, sy, ty, 0, &result);
        sort(result.begin(), result.end());
        for (auto index : result) {
            cout << index << endl;
        }
    }

    freeKdTree(pkdTree);
    return 0;
}

