class PrioritySearchTree{
	struct P{
		int idx,x,y;
		P(int idx,int x,int y):idx(idx),x(x),y(y){}
		bool operator<(const P& p)const{return x<p.x;}
	};
	struct Node{
		int idx,x,y;
		Node *l,*r;
		Node(const P &p):idx(p.idx),x(p.x),y(p.y){}
		~Node(){
			if(l)delete l;
			if(r)delete r;
		}
		void search(int x1,int y1,int x2,int y2,std::vector<int> &result)const{
			if(!this||y2<y)return;
			if(x<x1)r->search(x1,y1,x2,y2,result);
			else if(x2<x)l->search(x1,y1,x2,y2,result);
			else {
				if(y1<=y)result.push_back(idx);
				l->search(x1,y1,x2,y2,result);
				r->search(x1,y1,x2,y2,result);
			}
		}
	} *root;
	Node* build(std::vector<P> &ps,int a,int b){
		if(a>b)return NULL;
		int miny=ps[a].y,mini=a;
		for(int i=a+1;i<=b;i++){
			if(ps[i].y < miny){
				miny=ps[i].y;
				mini=i;
			}
		}
		Node *res=new Node(ps[mini]);
		if(a==mini)res->l=NULL;
		else{
			int m=(a+mini-1)/2;
			Node *lt=new Node(ps[m]);
			lt->l=build(ps,a,m-1);
			lt->r=build(ps,m+1,mini-1);
			res->l=lt;
		}
		if(b==mini)res->r=NULL;
		else{
			int m=(mini+1+b)/2;
			Node *rt=new Node(ps[m]);
			rt->l=build(ps,mini+1,m-1);
			rt->r=build(ps,m+1,b);
			res->r=rt;
		}
		return res;
	}
public:
	PrioritySearchTree(const std::vector<std::pair<int,int> > &xy){
		std::vector<P> ps;
		for(int i=0;i<xy.size();i++)ps.push_back(P(i,xy[i].first,xy[i].second));
		std::sort(ps.begin(),ps.end());
		root=build(ps,0,ps.size()-1);
	}
	PrioritySearchTree(){delete root;}
	std::vector<int> search(int x1,int y1,int x2,int y2)const{
		std::vector<int> result;
		root->search(x1,y1,x2,y2,result);
		std::sort(result.begin(),result.end());
		return result;
	}
};

