	if (depth % 2) {
		if (T[v].l != NIL) {
			if (sx <= x) {
				find(T[v].l, sx, tx, sy, ty, depth + 1, ans);
			}
		}
		if (T[v].r != NIL) {
			if (x <= tx) {
				find(T[v].r, sx, tx, sy, ty, depth + 1, ans);
			}
		}
	}
	else {
		if (T[v].l != NIL) {
			if (sy <= y) {
