bool cmp(int &a , int &b)
{
    return y[a] < y[b];
}
void build(int dep , int l , int r)
{
    if (l == r)
    {
        st[dep][l] = x[l].second;
        return ;
    }
    int mid = (l + r) >> 1;
    build(dep + 1 , l , mid);
    build(dep + 1 , mid + 1 , r);
    merge(st[dep + 1] + l , st[dep + 1] + mid + 1 , st[dep + 1] + mid + 1 , st[dep + 1] + r + 1 , st[dep] + l , cmp);
}
int j;
vector<int> result;
inline void query(int dep , int l , int r , int x1 , int y1 , int x2 , int y2)
{
    if (x[r].first < x1 || x[l].first > x2)
        return ;
    if (y[st[dep][l]] > y2 || y[st[dep][r]] < y1)
        return ;
    if (x[l].first >= x1 && x[r].first <= x2)
    {
        if (y[st[dep][l]] >= y1 && y[st[dep][r]] <= y2)
        {
            for (j = l ; j <= r ; j ++)
                result.push_back(st[dep][j]);
            return ;
        }
    }
    int mid = (l + r) >> 1;
    query(dep + 1 , l  , mid , x1 , y1 , x2 , y2);
    query(dep + 1 , mid + 1 , r , x1 , y1 , x2 , y2);
    return ;
}
