int make2DTree(vector<Point> &p, vector<Node> &t, int l, int r, int depth = 0) {
  if (r <= l) return NIL;

  int mid = (l + r) / 2;
  if (depth % 2 == 0) sort(p.begin() + l, p.begin() + r, lessX);
  else sort(p.begin() + l, p.begin() + r, lessY);

  int nt = np++;
  t[nt].location = mid;
  t[nt].l = make2DTree(p, t, l,  mid, depth + 1);
  t[nt].r = make2DTree(p, t, mid + 1, r, depth + 1);

  return nt;
}

