  if (sx <= x && x <= tx && sy <= y && y <= ty) ans.push_back(cp);

  if (depth % 2 == 0) {
    if (t[v].l != NIL && sx <= x) find(p, t, t[v].l, sx, tx, sy, ty, ans, depth + 1);
    if (t[v].r != NIL && x <= tx) find(p, t, t[v].r, sx, tx, sy, ty, ans, depth + 1);
