    if (t[v].l != NIL && sy <= y) find(p, t, t[v].l, sx, tx, sy, ty, ans, depth + 1);
    if (t[v].r != NIL && y <= ty) find(p, t, t[v].r, sx, tx, sy, ty, ans, depth + 1);
  }
}

