	T[mid] = U[mid];
	if(right - left < 5){
		for(int i = left; i < right; i++){ T[i] = U[i]; }
	}
}

void kd_tree(point *S, point *T, point *U, int left, int right, int d)
{
    if(right - left < 2) return;

	if((d % 6) == 0){ cycle_x(S, T, U, left, right); }
	if((d % 6) == 1){ cycle_y(U, S, T, left, right); }
	if((d % 6) == 2){ cycle_x(T, U, S, left, right); }
	if((d % 6) == 3){ cycle_y(S, T, U, left, right); }
	if((d % 6) == 4){ cycle_x(U, S, T, left, right); }
	if((d % 6) == 5){ cycle_y(T, U, S, left, right); }

	int mid = ((left + right) >> 1);

    kd_tree(S, T, U, left, mid, d + 1);
    kd_tree(S, T, U, mid + 1, right, d + 1);
}

int cnt;

void find_pt(int *Q, point *S, int sx, int tx, int sy, int ty, int left, int right, int d)
{
    if(left >= right) return;

    int mid = ((left + right) >> 1);
    point p = S[mid];
    int a = p.x, b = p.y;

    if(sx <= a && a <= tx && sy <= b && b <= ty){
        Q[cnt++] = p.id;
    }

    if((d & 1) == 0){
        if((left < mid) && (sx < a || (sx == a && sy <= b))){ find_pt(Q, S, sx, tx, sy, ty, left, mid, d + 1); }
        if((mid + 1 < right) && (a < tx || (a == tx && b <= ty))){ find_pt(Q, S, sx, tx, sy, ty, mid + 1, right, d + 1); }
    }else{
        if((left < mid) && (sy < b || (sy == b && sx <= a))){ find_pt(Q, S, sx, tx, sy, ty, left, mid, d + 1); }
        if((mid + 1 < right) && (b < ty || (b == ty && a <= tx))){ find_pt(Q, S, sx, tx, sy, ty, mid + 1, right, d + 1); }
    }
    return;
}

