struct KDtree {
	struct Node {
		int index, l, r;
		Node() {};
		Node(int index, int l = NIL, int r = NIL) :index(index), l(l), r(r) {};
	};

	vector<Point>points; vector<Node>nodes; int n, np, root;
	KDtree(vector<Point>&p) :n(p.size()), points(p), np(0) {
		nodes.resize(n);
		root = makeKDtree(0, n, true);
	}
	int makeKDtree(int l, int r, bool is_x_base) {
		if (!(l < r))return NIL;
		int mid = (l + r) / 2, t = np++;
		vector<Point>::iterator first = points.begin() + l,
			nth = points.begin() + mid, last = points.begin() + r;
		if (is_x_base)nth_element(first, nth, last, lessX);
		else nth_element(first, nth, last, lessY);
		nodes[t] = Node(mid, makeKDtree(l, mid, !is_x_base), makeKDtree(mid + 1, r, !is_x_base));
		return t;
	}
	bool inrange(const Point &p, const Point &s, const Point &t) {
		return s.x <= p.x&&p.x <= t.x&&s.y <= p.y&&p.y <= t.y;
	}
	vector<Point>ret;
	vector<Point>find(const Point &s, const Point &t) {
		ret.clear();
		return find(root, true, s, t);
	}
	vector<Point> find(int v, bool is_x_base, const Point &s, const Point &t) {
		auto p = points[nodes[v].index];
		if (inrange(p, s, t))ret.emplace_back(p);
		if (is_x_base) {
			if (nodes[v].l != NIL && s.x <= p.x)find(nodes[v].l, !is_x_base, s, t);
			if (nodes[v].r != NIL && p.x <= t.x)find(nodes[v].r, !is_x_base, s, t);
		}
		else {
			if (nodes[v].l != NIL && s.y <= p.y)find(nodes[v].l, !is_x_base, s, t);
			if (nodes[v].r != NIL && p.y <= t.y)find(nodes[v].r, !is_x_base, s, t);
		}
		return ret;
	}
};
