}

int n, q, sx[20000], tx[20000], sy[20000], ty[20000], np = 0;

int make2dtree(int l, int r, int d){
  if(l >= r) return -1;
  int x = np++;
  if(d % 2 == 0) sort(p + l, p + r, compx);
  else sort(p + l, p + r, compy);
  int mid = (l + r) / 2;
  t[x].key = mid;
  t[x].l = make2dtree(l, mid, d + 1);
  t[x].r = make2dtree(mid + 1, r, d + 1);
  return x;
}

void findx(int v, int sx, int tx, int sy, int ty, int d){
  int x = p[t[v].key].x, y = p[t[v].key].y;
  if(sx <= x && x <= tx && sy <= y && y <= ty) ans.push_back(p[t[v].key].id);
  if(d % 2 == 0){
    if(t[v].l != -1 && sx <= x) findx(t[v].l, sx, tx, sy, ty, d + 1);
    if(t[v].r != -1 && tx >= x) findx(t[v].r, sx, tx, sy, ty, d + 1);
  }
  else{
    if(t[v].l != -1 && sy <= y) findx(t[v].l, sx, tx, sy, ty, d + 1);
    if(t[v].r != -1 && ty >= y) findx(t[v].r, sx, tx, sy, ty, d + 1);
  }
  return;
}

