    v.erase(unique(v.begin(), v.end()), v.end());
    return v;
}

vector<int> bound_list(vector<int> v, int b){
    vector<int> res;
    for(int i = 0; i < v.size(); i += b){
        res.push_back(v[i]);
    }
    return res;
}

int index(const vector<int>& v, int x){
    return lower_bound(v.begin(), v.end(), x) - v.begin();
}

