#include <iostream>
#include <vector>

#define POINT_MAX 500001

using namespace std;

int n, q;
int xs[POINT_MAX], ys[POINT_MAX];

class Point {
public:
    Point(int id, int x, int y)
    : id(id), x(x), y(y) {
    }
    int id, x, y;
};

class Node {
public:
    Node()
    : l(), r(), location(-1) {
    }
    Node* l;
    Node* r;
    int location;
};

bool ascX(const Point& x, const Point& y) {
    return x.x < y.x;
}

bool ascY(const Point& x, const Point& y) {
    return x.y < y.y;
}

class KdTree {
public:
    KdTree(vector<Point>& ps)
    : ps(ps) {
        root = buildKdTree(ps, 0, (int)ps.size(), 0);
    }

    void find(int x1, int x2, int y1, int y2, vector<int>& res) {
        _find(x1, x2, y1, y2, 0, root, res);
        sort(res.begin(), res.end());
    }
private:
    vector<Point>& ps;
    Node* root;

    void _find(int x1, int x2, int y1, int y2, int depth, Node* n, vector<int>& res) {
        Point& p(ps[n->location]);
        if(x1 <= p.x && p.x <= x2 &&
           y1 <= p.y && p.y <= y2) {
            res.push_back(p.id);
        }

        if(depth % 2 == 0) {
            if(n->l != nullptr && p.x >= x1) {
                _find(x1, x2, y1, y2, depth+1, n->l, res);
            }
            if(n->r != nullptr && p.x <= x2) {
                _find(x1, x2, y1, y2, depth+1, n->r, res);
            }
        } else {
            if(n->l != nullptr && p.y >= y1) {
                _find(x1, x2, y1, y2, depth+1, n->l, res);
            }
            if(n->r != nullptr && p.y <= y2) {
                _find(x1, x2, y1, y2, depth+1, n->r, res);
            }
        }
    }

    static Node* buildKdTree(vector<Point>& ps, int l, int r,
                            int depth) {
        if(l > r){
            return nullptr;
        }

        if(depth % 2 == 0) {
            sort(ps.begin()+l, ps.begin()+r, ascX);
        } else {
            sort(ps.begin()+l, ps.begin()+r, ascY);
        }

        int mid = (l+r)/2;

        Node* n = new Node();
        n->location = mid;
        n->l = buildKdTree(ps, l, mid-1, depth+1);
        n->r = buildKdTree(ps, mid+1, r, depth+1);

        return n;
    }

};

int main() {
    vector<Point> ps;

    cin >> n;

    int x, y;
    for(int i=0; i<n; i++) {
        cin >> x >> y;
        ps.push_back(Point(i, x, y));
    }

    KdTree kd(ps);

    cin >> q;

    int x1, x2, y1, y2;
    for(int i=0; i<q; i++) {
        vector<int> ans;
        cin >> x1 >> x2 >> y1 >> y2;
        kd.find(x1, x2, y1, y2, ans);
        for(auto it = ans.begin(); it != ans.end(); it++) {
            cout << *it << endl;
        }
        cout << endl;
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
#define P pair<int,int>
#define FOR(I,A,B) for(int I = int(A); I < int(B); ++I)

const int MN = 1000000;

P tree[MN];//tree[頂点番号]={子左,子右};
P value[MN];//value[頂点番号]={xの値,yの値};
int ind=1,root=1;

int n;
auto fx = [](P &a,P &b){return (a.first<b.first);};//x小さい順
auto fy = [](P &a,P &b){return (a.second<b.second);};//y小さい順

void make_tree(int p,vector<P> data,int depth,bool leftc){
	sort(data.begin(), data.end(),(depth%2?fy:fx));//0x 1y
	int mid = data.size();mid/=2;
	if(leftc){
		tree[p].first = ind;
		value[ind] = data[mid];
	}else{
		tree[p].second = ind;
		value[ind] = data[mid];
	}
	int pp = ind;
	ind++;
	vector<P> datal,datar;
	FOR(i,0,mid)datal.push_back(data[i]);
	FOR(i,mid+1,data.size())datar.push_back(data[i]);
	data.clear();
	if(datal.size())make_tree(pp,datal,depth+1,true);
	if(datar.size())make_tree(pp,datar,depth+1,false);
}

vector<P> ans;
int sx,tx,sy,ty;
void calc(int ind,int dep){
	int x = value[ind].first;
	int y = value[ind].second;
	if(sx<=x&&x<=tx && sy<=y&&y<=ty){
		ans.push_back({x,y});
		if(~tree[ind].first)calc(tree[ind].first,dep+1);
		if(~tree[ind].second)calc(tree[ind].second,dep+1);
		return;
	}
	if(dep&1){//y
		if(~tree[ind].first){
			if(value[ind].second>=sy)calc(tree[ind].first,dep+1);
		}
		if(~tree[ind].second){
			if(value[ind].second<=ty)calc(tree[ind].second,dep+1);
		}
	}else{//x
		if(~tree[ind].first){//-1じゃない
			if(value[ind].first>=sx)calc(tree[ind].first,dep+1);
		}
		if(~tree[ind].second){
			if(value[ind].first<=tx)calc(tree[ind].second,dep+1);
		}
	}
}


int main(){

	FOR(i,0,MN)tree[i]=value[i]={-1,-1};
	cin >> n;
	vector<P> xy(n);
	FOR(i,0,n)cin>>xy[i].first>>xy[i].second;
	map<P,int> ma;
	FOR(i,0,n)ma[xy[i]] = i;
	make_tree(0,xy,0,true);
	/*FOR(i,0,7){
		cout << "i:" << i << " " << tree[i].first << " " << tree[i].second << " : " << value[i].first << " " << value[i].second << endl;
	}*/
	int q;
	cin >> q;
	FOR(i,0,q){
		ans.clear();
		cin >> sx >> tx >> sy >> ty;
		if(n)calc(1,0);
		vector<int> ansi;
		for(P x:ans)ansi.push_back(ma[x]);
		sort(ansi.begin(), ansi.end());
		for(int i:ansi) cout << i << '\n';
		cout << '\n';
	}
}

