#define NIL -1

int kd_index = 0;

struct point {
	int id;
	int x;
	int y;
};

bool compare_x(const point& p, const point& q) { return p.x < q.x; }
bool compare_y(const point& p, const point& q) { return p.y < q.y; }

struct Node {
	int index;
	int x;
	int y;
	int left_child;
	int right_child;
};

int construct_kdtree(Node* kdtree, point* P, int left, int right, int depth)
{
	if (left>=right) return NIL;

	Node v;

	int mid = (left + right) / 2;

	if (left+1<right) {
		if ((depth&1)==0) {
			std::sort(P + left, P + right, compare_x);
		}
		else {
			std::sort(P + left, P + right, compare_y);
		}
		v.x = P[mid].x; v.y = P[mid].y;
		v.index = mid;
		v.left_child = construct_kdtree(kdtree, P, left, mid, depth+1);
		v.right_child = construct_kdtree(kdtree, P, mid+1, right, depth+1);
	}
	else {
		v.x= P[left].x; v.y= P[left].y;
		v.index = left;
		v.left_child = v.right_child = NIL;
	}

	kdtree[kd_index++] = v;
	return kd_index - 1;
}

void tab(int n)
{
	for (int i=0; i<n; i++) std::cout << " ";
}

void show_kdtree(Node* kdtree, int v_index, int depth)
{
	Node v = kdtree[v_index];
	tab(2*depth);
	std::cout << "x = " << v.x << ", y = " << v.y << ", index = " << v.index << std::endl;
	if (v.left_child != NIL) show_kdtree(kdtree, v.left_child, depth+1);
	if (v.right_child != NIL) show_kdtree(kdtree, v.right_child, depth+1);
}

void rsq(Node* kdtree, std::vector<int>& points, point* P, int v_index, int sx, int tx, int sy, int ty, int depth)
{
	Node v = kdtree[v_index];
	if (sx <= v.x && v.x <= tx && sy <= v.y && v.y <= ty) { // point is contained
		points.push_back(P[v.index].id);
		// std::cout << "index = " << v->index << ", ID = " << points.back() << std::endl;
	}
	if ((depth&1)==0) {
		if (v.x >= sx) if (v.left_child != NIL) rsq(kdtree, points, P, v.left_child, sx, tx, sy, ty, depth+1);
		if (v.x <= tx) if (v.right_child != NIL) rsq(kdtree, points, P, v.right_child, sx, tx, sy, ty, depth+1);
	} else {
		if (v.y >= sy) if (v.left_child != NIL) rsq(kdtree, points, P, v.left_child, sx, tx, sy, ty, depth+1);
		if (v.y <= ty) if (v.right_child != NIL) rsq(kdtree, points, P, v.right_child, sx, tx, sy, ty, depth+1);
	}
}

int main ()
{
	int n; //std::cin >> n;
	scanf("%d", &n);

	point* P = new point[n];
	for (int i=0; i<n; i++) {
		P[i].id = i;
		//std::cin >> P[i].x >> P[i].y;
		scanf("%d %d", &(P[i].x), &(P[i].y));
	}
	Node* kdtree = new Node[n];

	int root = construct_kdtree(kdtree, P, 0, n, 0);

	// show_kdtree(root, 0);

	int q; std::cin >> q;
	for (int i=0; i<q; i++) {
		int sx, tx, sy, ty;
		//std::cin >> sx >> tx >> sy >> ty;
		scanf("%d %d %d %d", &sx, &tx, &sy, &ty);
		std::vector<int> ans;
		rsq(kdtree, ans, P, root, sx, tx, sy, ty, 0);
		std::sort(ans.begin(), ans.end());
		for (std::vector<int>::iterator it = ans.begin(); it != ans.end(); ++it) {
			//std::cout << *it << std::endl;
			printf("%d\n", *it);
		}
		//std::cout << std::endl;
		printf("\n");
	}

	delete[] kdtree;
	delete[] P;

	return 0;
}

