			}
		}
		if (aok) {
			ans.emplace_back(val);
		}
		axisSorter<T> as(depth%Dim);
		if (as(val, amax)||val.coors[depth%Dim]==amax.coors[depth%Dim]) {
			if (rtree != nullptr) {
				vector<T>tans(rtree->query(amin, amax));
				ans.insert(ans.end(), tans.begin(), tans.end());
			}
		}
		if (as(amin, val) || val.coors[depth%Dim] == amax.coors[depth%Dim]) {
			if (ltree != nullptr) {
				vector<T>tans(ltree->query(amin, amax));
				ans.insert(ans.end(), tans.begin(), tans.end());
			}
		}
		return ans;
	}
private :
	void init(vector<T>&ps,const int l,const int r) {
		if (l >= r) {
			return;
		}
		sort(ps.begin()+l, ps.begin()+r, axisSorter<T>(depth%Dim));
		const int mid = (l + r) / 2;
		val = ps[mid];
		ltree = make_kdtree(ps, l, mid, depth + 1);
		rtree = make_kdtree(ps,mid+1,r, depth + 1);
	}

};
template<class T>
kdtree<T> *make_kdtree(vector<T>&ps_, const int l, const int r, const int depth = 0) {
	if (l >= r)return nullptr;
	else {
		return new kdtree<T>(ps_, l, r, depth);
	}
}
