int makeKDTree(int l, int r, int d) {
    if (!(l < r)) return NIL;

    int mid = (l+r)/2;
    int t = np++;
    if (d % 2 == 0) {
        sort(P+l, P+r, lessX);
    } else {
        sort(P+l, P+r, lessY);
    }

    T[t].location = mid;
    T[t].l = makeKDTree(l, mid, d+1);
    T[t].r = makeKDTree(mid+1, r, d+1);

    return t;
}

void find(int v, int sx, int tx, int sy, int ty, int d, vector<Point> &ans) {
    int x = P[T[v].location].x;
