template <class val_t>
class kdTree {
private:
	struct node {
		int id;
		val_t val;
		int deg;
		node *parent;
		node *left, *right;
	};
	int dimension; // dimension
	int n; // the number of nodes
	node *root; // the root of the tree
	node *nil; // the node for leaves of the tree
	pair<val_t, val_t> bounding_box; // save min_val and max_val
	bool bounding_box_enabled; // enable bounding_box
	struct idval_t {
		int id;
		val_t val;
	};
	typedef typename vector<idval_t>::iterator vidval_iterator;
	node* build_kdTree_rec(node *parent, pair<vidval_iterator, vidval_iterator> range, int depth) {
		if (distance(range.first, range.second) == 0) return nil;
		else {
			node *ret = new node;
			int axis = depth % dimension;
			sort(range.first, range.second, [=](const idval_t& l, const idval_t& r) { return l.val[axis] < r.val[axis]; });
			vidval_iterator mid = range.first + distance(range.first, range.second) / 2;
			idval_t target = { -1, bounding_box.first };
			target.val[axis] = mid->val[axis];
			mid = lower_bound(range.first, range.second, target, [=](const idval_t &l, const idval_t & r) {return l.val[axis] < r.val[axis]; });
			*ret = { mid->id, mid->val, depth, nil, nil, nil };
			ret->left = build_kdTree_rec(ret, { range.first, mid }, depth + 1);
			ret->right = build_kdTree_rec(ret, { mid + 1,range.second }, depth + 1);
			return ret;
		}
	}
	vi find_in_range_rec(node *focus, pair<val_t, val_t> &range, int depth) {
		if (focus == nil) return {};
		else {
			vi ret;
			int axis = depth % dimension;
			bool judge = true;
			Loop(i, dimension) {
				if (range.first[i] <= focus->val[i] && focus->val[i] <= range.second[i]) continue;
				else { judge = false; break; }
			}
			if (judge) ret.push_back(focus->id);
			if (range.first[axis] < focus->val[axis]) {
				vi left_result = find_in_range_rec(focus->left, range, depth + 1);
				ret.insert(ret.end(), left_result.begin(), left_result.end());
			}
			if (focus->val[axis] <= range.second[axis]) {
				vi right_result = find_in_range_rec(focus->right, range, depth + 1);
				ret.insert(ret.end(), right_result.begin(), right_result.end());
			}
			return ret;
		}
	}
	inline void update_bounding_box(val_t &a) {
		if (!bounding_box_enabled) {
			bounding_box = { a,a };
		}
		else {
			Loop(i, a.size()) {
				bounding_box.first[i] = min(bounding_box.first[i], a[i]);
				bounding_box.second[i] = max(bounding_box.second[i], a[i]);
			}
		}
	}
public:
	kdTree(vector<val_t> A, int dimension) {
		n = (int)A.size();
		this->dimension = dimension;
		bounding_box_enabled = false;
		vector<idval_t> ary(n);
		Loop(i, n) {
			ary[i] = { i, A[i] };
			update_bounding_box(A[i]);
		}
		nil = new node;
		root = build_kdTree_rec(nil, { ary.begin(), ary.end() }, 0);
		return;
	}
	// return id of vals in [range.first, range.second]
	vi find_in_range(pair<val_t, val_t> range) {
		vi ret = find_in_range_rec(root, range, 0);
		sort(ret.begin(), ret.end());
		return ret;
	}
};

