using namespace std;

struct point {
	int x;
	int y;
	int index;
	point(int x, int y, int index) :x(x), y(y), index(index) {}

	bool operator < (const point& o) const {
		if (x != o.x) return x < o.x;
		if (y != o.y)return y < o.y;
		return false;
	}
};

vector<point> P;

void kd_search(int l,int r,int sx, int tx, int sy, int ty,vector<int>& ans) {
	int mid = l + (r - l) / 2;
	if (l != 0 && mid == l) return;
	if (sx <= P[mid].x && P[mid].x <= tx && sy <= P[mid].y && P[mid].y <= ty) {
		ans.emplace_back(P[mid].index);
	}

	if (l == 0 && mid == l) return;
	if (sx <= P[mid].x && P[mid].x <= tx) {
		kd_search(l, mid, sx, tx, sy, ty, ans);
		kd_search(mid, r, sx, tx, sy, ty, ans);
		return;
	}
	if (P[mid].x < sx) {
		kd_search(mid, r, sx, tx, sy, ty, ans);
		return;
	}
	if (tx < P[mid].x) {
		kd_search(l, mid, sx, tx, sy, ty, ans);
		return;
	}
}

