	rep(i, 0, q)
	{
		int sx, tx, sy, ty;
		cin >> sx >> tx >> sy >> ty;

		vector<P> out;
		kt.search(P(sx, sy), P(tx, ty), out);
		vector<int> ans;
		for (P j : out) ans.push_back(_map[make_pair(real(j), imag(j))]);
		sort(ans.begin(), ans.end());
		for (int j : ans) cout << j << endl;
		cout << endl;
	}
}

#include <cstdio>
