class Point{
    public:
        int id,x,y;
        Point(){}
        //メンバ変数の初期化
        Point(int id,int x,int y):id(id),x(x),y(y){}
        //比較演算子のオーバーロード
        bool operator<(const Point &p){
            return id<p.id;
        }

        void print(){
            printf("%d\n",id);
        }
};

int N,np;
Point P[500001];
Node T[500001];

bool lessX(const Point &left,const Point &right){
    return left.x<right.x;
}
bool lessY(const Point &left,const Point &right){
    return left.y<right.y;
}

int make2Dtree(int l,int r,int depth){
    if(!(l<r)) return NIL;
    int mid=(l+r)/2;
    int t=np++;
    if(depth%2==0){
        sort(P+l,P+r,lessX);
    }
    else{
        sort(P+l,P+r,lessY);
    }
    T[t].location=mid;
    T[t].l=make2Dtree(l,mid,depth+1);
    T[t].r=make2Dtree(mid+1,r,depth+1);
    return t;
}

void find(int v,int sx,int tx,int sy,int ty,int depth,vector<Point> &ans){
    int x=P[T[v].location].x;
    int y=P[T[v].location].y;
    if(sx<=x&&x<=tx&&sy<=y&&y<=ty){
        ans.push_back(P[T[v].location]);
    }

    if(depth%2==0){
        if(T[v].l!=NIL&&sx<=x){
            find(T[v].l,sx,tx,sy,ty,depth+1,ans);
        }
        if(T[v].r!=NIL&&x<=tx){
            find(T[v].r,sx,tx,sy,ty,depth+1,ans);
        }
    }
    else{
        if(T[v].l!=NIL&&sy<=y){
            find(T[v].l,sx,tx,sy,ty,depth+1,ans);
        }
        if(T[v].r!=NIL&&y<=ty){
            find(T[v].r,sx,tx,sy,ty,depth+1,ans);
        }
    }
}

int main(){
    int x,y;
    scanf("%d",&N);
    for(int i=0;i<N;i++){
        scanf("%d%d",&x,&y);
        P[i]=Point(i,x,y);
        T[i].p=T[i].l=T[i].r=NIL;
    }

    np=0;
    int root=make2Dtree(0,N,0);

    int q;
    scanf("%d",&q);
    int sx,tx,sy,ty;
    vector<Point> ans;
    for(int i=0;i<q;i++){
        scanf("%d%d%d%d",&sx,&tx,&sy,&ty);
        ans.clear();
        find(root,sx,tx,sy,ty,0,ans);
        sort(ans.begin(),ans.end());
        for(int j=0;j<ans.size();j++){
            ans[j].print();
        }
        printf("\n");
    }
}

