    point() : id(-1), x(0), y(0) {}
    point(int id, int x, int y) : id(id), x(x), y(y) {}
    point(int id, pair<int,int> xy) : id(id), x(xy.first), y(xy.second) {}
    bool operator < (const point &p) const {
        return id < p.id;
    }
};
class kdtree {
private:
    struct node {
        // int p;
        int location;
        node *left;
        node *right;
        node() : left(nullptr), right(nullptr) {}
    };

    static bool lessX(const point &a, const point &b) { return a.x < b.x; }
    static bool lessY(const point &a, const point &b) { return a.y < b.y; }

    node *root;
    int np;
    int N;
    vector<point> &P;

    node *make_kd_tree(int l, int r, int depth) {
        if (!(l < r)) return nullptr;
        int mid = (l + r) / 2;

        if (depth) sort(begin(P) + l, begin(P) + r, lessY);
        else       sort(begin(P) + l, begin(P) + r, lessX);

        node *t = new node();
        t->location = mid;
        t->left = make_kd_tree(l, mid, !depth);
        t->right = make_kd_tree(mid+1, r, !depth);
        return t;
    }
    void find(node *v, int sx, int sy, int tx, int ty, int depth, vector<point> &ans) {
        int x = P[v->location].x;
        int y = P[v->location].y;

        if (sx <= x && x <= tx && sy <= y && y <= ty) {
            ans.push_back(P[v->location]);
        }

        if (depth) {
            if(v->left != nullptr && sy <= y)  find(v->left, sx, sy, tx, ty, !depth, ans);
            if(v->right != nullptr && y <= ty) find(v->right, sx, sy, tx, ty, !depth, ans);
        } else {
            if(v->left != nullptr && sx <= x)  find(v->left, sx, sy, tx, ty, !depth, ans);
            if(v->right != nullptr && x <= tx) find(v->right, sx, sy, tx, ty, !depth, ans);
        }
    }

public:
    kdtree(vector<point> &p) : P(p) {
        np = 0;
        N = p.size();
        root = make_kd_tree(0, N, 0);
    }
    void query(int sx,int sy,int tx,int ty, vector<point> &p) {
        find(root, sx, sy, tx, ty, 0, p);
    }
};

