    // 奇数がy
    }else{
        if(tree[v].l != NIL){
            if(sy <= y){
                find(tree[v].l,sx,tx,sy,ty,depth + 1,ans);
            }

        }
        if(tree[v].r != NIL){
            if(y <= ty){
                find(tree[v].r,sx,tx,sy,ty,depth + 1,ans);
            }
        }
    }

}

