/// 2分セグメント木。RMQとかが解ける。
template<class T, class TParentFunc>
struct SegTreeT
{
	int size;
	vector<T> tree;
	TParentFunc parent;
	T initialValue;
	static constexpr unsigned int msb(unsigned int v) { REP(i, 5) v |= v >> (1 << i); return (v >> 1) + 1; }

	SegTreeT(int count, TParentFunc parentBuilder, T initialFill)
		: size(msb(count - 1) << 1)
		, tree(size * 2)
		, parent(parentBuilder)
		, initialValue(initialFill)
	{
		fill(partof(tree, size, size), initialFill);
		rebuild();
	}

	// []を使うと更新されないのでrebuildすること。数が少なければupdateの方がよい。
	T& operator[](int i) { return tree[i + size]; }
	void rebuild() { RREP(i, size) { tree[i] = parent(tree[i * 2], tree[i * 2 + 1]); } }

	void update(int index, T value)
	{
		tree[index + size] = value;
		for (int i = (index + size) / 2; i > 0; i /= 2)
			tree[i] = parent(tree[i * 2], tree[i * 2 + 1]);
	}

	T query(int s, int e, int i, int l, int r, T value)
	{
		if (r <= s || e <= l) return value;
		if (s <= l && r <= e) return parent(value, tree[i]);
		value = query(s, e, i * 2, l, (l + r) / 2, value);
		value = query(s, e, i * 2 + 1, (l + r) / 2, r, value);
		return value;
	}

	T query(int begin, int end, T initialValue) { return query(begin, end, 1, 0, size, initialValue); }
	T query(int begin, int end) { return query(begin, end, initialValue); }
};
template<class T = int, class TParentFunc = const T& (*)(const T&, const T&)>
SegTreeT<T, TParentFunc> SegTree(int N, TParentFunc f = min, int initialValue = INF)
{
	return SegTreeT<T, TParentFunc>(N, f, initialValue);
}


template <class T, size_t K>
struct KDTree {
	static constexpr unsigned int msb(unsigned int v) { REP(i, 5) v |= v >> (1 << i); return (v >> 1) + 1; }

	using PT = array<T, K>;
	vector<PT> p_{ };
	vector<int> tree{};

	void add(PT p)
	{
		p_.push_back(p);
	}

	void build()
	{
		int treesize = 1 << msb(p_.size() + 1);
		tree.assign(treesize, -1);

		vector<int> work(p_.size());
		iota(allof(work), 0);
		build_internal(work, 0, 1, 0, work.size());
	}

	void build_internal(vector<int> &w, int depth, int i, int l, int r)
	{
		if (r - l == 0) { return; }

		int d = depth % K;
		int m = (r - l - 1) / 2 + l;
		nth_element(w.begin() + l, w.begin() + m, w.begin() + r, COMP(a, b, p_[a][d] < p_[b][d]));
		tree[i] = w[m];
		build_internal(w, depth + 1, i * 2, l, m);
		build_internal(w, depth + 1, i * 2 + 1, m + 1, r);
	}

	vector<int> range(PT s, PT e)
	{
		vector<int> ret;
		range_internal(ret, s, e, 0, 1, 0, p_.size());
		return ret;
	}

	void range_internal(vector<int> &ret, PT s, PT e, int depth, int i, int l, int r)
	{
		if (r - l == 0) { return; }

		PT p = p_[tree[i]];
		bool inRange = true;
		REP(i, K) { inRange &= p[i] >= s[i] && p[i] <= e[i]; }
		if (inRange) { ret.push_back(tree[i]); }

		int d = depth % K;
		int m = (r - l - 1) / 2 + l;
		if (p[d] >= s[d]) { range_internal(ret, s, e, depth + 1, i * 2, l, m); }
		if (p[d] <= e[d]) { range_internal(ret, s, e, depth + 1, i * 2 + 1, m + 1, r); }
	}
};

////////////////////
/// template end ///
////////////////////

void solve()
{
	READ(int, n);

	KDTree<int, 2> tree;
	REP(i, n)
	{
		READ(int, x, y);
		tree.add({ x, y });
	}
	tree.build();
	READ(int, q);
	REP(i, q)
	{
		READ(int, sx, tx, sy, ty);
		auto v = tree.range({ sx,sy }, { tx,ty });
		sort(allof(v));
		for (auto val : v) { WRITE(val); }
		WRITE();
	}
}

#include<bits/stdc++.h>
using namespace std;
using UL = unsigned int;
using ULL = unsigned long long;
using LL = long long;
#define rep(i,n) for(UL i=0; i<(n); i++)

UL N;
pair<int,int> P[524288];

struct RT{
 UL N;
 UL D;
 tuple<int,int,UL> V[20][524288];
 void init(UL n){
  N=1; D=0; while(N<n){ D++; N<<=1; }
  rep(i,n) V[0][i] = make_tuple(P[i].first,P[i].second,i);
  for(UL i=n; i<N; i++) V[0][i] = make_tuple(INT_MAX,INT_MAX,0);
  sort(V[0],V[0]+N);
  for(UL d=0; d<D; d++){
   UL L=(1<<d);
   for(UL l=0; l<N; l+=(L+L)){
    UL p=0, q=0;
    while(p+q<L+L){
     bool choose_p = false;
     if(q==L) choose_p=true;
     else if(p<L) if(get<1>(V[d][l+p]) <= get<1>(V[d][l+L+q])) choose_p=true;
     if(choose_p) { V[d+1][l+p+q]=V[d][l+p]; p++; }
     else { V[d+1][l+p+q]=V[d][l+L+q]; q++; }
    }
   }
  }
 }
 const vector<UL>& query(int xl,int xr,int yl,int yr,UL a=~0u,UL b=~0u,UL d=~0u){
  static vector<UL> ans;
  if(!~d){ a=0; b=N; d=D; ans.clear(); }
  if(xr<=get<0>(V[0][a]) || get<0>(V[0][b-1])<xl) return ans;
  if(xl<=get<0>(V[0][a]) && get<0>(V[0][b-1])<xr) {
   UL pl,pr;
   UL l,r;
   l=a; r=b+1;
   while(l+1<r){ UL m=(l+r)>>1;
    if(get<1>(V[d][m-1])<yl) l=m; else r=m;
   } pl=l;
   l=a; r=b+1;
   while(l+1<r){ UL m=(l+r)>>1;
    if(get<1>(V[d][m-1])<yr) l=m; else r=m;
   } pr=l;
   for(UL p=pl; p<pr; p++) ans.push_back(get<2>(V[d][p]));
   return ans;
  }
  query(xl,xr,yl,yr,a,(a+b)>>1,d-1);
  query(xl,xr,yl,yr,(a+b)>>1,b,d-1);
  return ans;
 }
} G;

int main() {
 scanf("%u",&N);
 rep(i,N) scanf("%d%d",&P[i].first,&P[i].second);
 G.init(N);
 UL Q; scanf("%u",&Q);
 rep(q,Q){
  int xl,xr,yl,yr; scanf("%d%d%d%d",&xl,&xr,&yl,&yr);
  auto ans=G.query(xl,xr+1,yl,yr+1);
  sort(ans.begin(),ans.end());
  for(UL a:ans) printf("%u\n",a);
  printf("\n");
 }
 return 0;
}

#include<iostream>
#include<set>
using namespace std;

struct Node{
    Node* left  = NULL;
    Node* right = NULL;
    int x;
    int y;
    int location;
    Node(int x, int y, int location) : x(x), y(y), location(location){}
    Node(){}
};
class Tree{
private:
    Node* root = NULL;
    void add_Node(Node* n, Node*& pos, int depth){
        if (pos == NULL) {
            pos = n;
            return;
        }
        if (depth % 2 == 0) {
            if (n->y < pos->y) {
                add_Node(n, pos->left , depth + 1);
            } else {
                add_Node(n, pos->right, depth + 1);
            }
        } else {
            if (n->x < pos->x) {
                add_Node(n, pos->left , depth + 1);
            } else {
                add_Node(n, pos->right, depth + 1);
            }
        }
    }
    void find_Node(int sx, int tx, int sy,
                   int ty, set<int>& ans, Node* pos, int depth){
        if (pos == NULL) return;
        if (sx <= pos->x && pos->x <= tx && sy <= pos->y && pos->y <= ty) {
            ans.insert(pos->location);
        }
        if (depth % 2 == 0){
            if (sy <= pos->y) {
                find_Node(sx, tx, sy, ty, ans, pos->left, depth + 1);
            }
            if (pos->y <= ty) {
                find_Node(sx, tx, sy, ty, ans, pos->right, depth + 1);
            }
        } else {
            if (sx <= pos->x) {
                find_Node(sx, tx, sy, ty, ans, pos->left, depth + 1);
            }
            if (pos->x <= tx) {
                find_Node(sx, tx, sy, ty, ans, pos->right, depth + 1);
            }
        }
    }
public:
    void add_data(int x_in, int y_in, int loc_in){
        Node* n = new Node(x_in, y_in, loc_in);
        add_Node(n, root, 0);
    }
    void find_data(int sx, int tx, int sy, int ty, set<int>& ans){
        find_Node(sx, tx, sy, ty, ans, root, 0);
    }
};

int main(){
    int n;
    cin >> n;
    Tree T;
    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        T.add_data(x, y, i);
    }
    int q;
    cin >> q;
    for (int i = 0; i < q; i++) {
        set<int> ans;
        int sx, tx, sy, ty;
        cin >> sx >> tx >> sy >> ty;
        T.find_data(sx, tx, sy, ty, ans);
        for (auto it = ans.begin(); it != ans.end(); it++) {
            cout << *it << endl;
        }
        cout << endl;
    }
    return 0;
}

#include <cstdio>
#include <vector>
