using namespace std;

typedef struct{
    int key;
    int x;
    int y;
}point;

bool compkey(point p1, point p2){ return p1.key < p2.key; }
bool compx(point p1, point p2){ return p1.x < p2.x; }
bool compy(point p1, point p2){ return p1.y < p2.y; }

vector<point> points;

int binarySearchx(int x, int left, int right){
    while(left<right){
        int mid = (left+right)/2;
        int tmp = points[mid].x;
        if(tmp<x){
            if(left<mid)left=mid;
            else left++;
        }
        else right=mid;
    }
    return left;
}

int binarySearchy(int y, int left, int right){
    while(left<right){
        int mid = (left+right)/2;
        int tmp = points[mid].y;
        if(tmp<y){
            if(left<mid)left=mid;
            else left++;
        }
        else right=mid;
    }
    return left;
}

void printPoints(int sx, int tx, int sy, int ty){
    int leftx = binarySearchx(sx,0,points.size());
    int rightx = binarySearchy(tx,0,points.size());

    sort(points.begin()+leftx,points.begin()+rightx,compy);

    int lefty = binarySearchy(sy,leftx,rightx);
    int righty = binarySearchy(ty,leftx,rightx);

    sort(points.begin()+lefty,points.begin()+righty,compkey);
    for(int i = lefty;i<righty;i++)printf("%d\n",points[i].key);

    sort(points.begin()+leftx,points.begin()+rightx,compx);

    printf("\n");
}

int main(){
    int i,n,x,y,q,sx,tx,sy,ty;
    point tmp;

    scanf("%d",&n);
    for(i=0;i<n;i++){
        scanf("%d %d",&x,&y);
        tmp.key = i;
        tmp.x = x;
        tmp.y = y;
        points.push_back(tmp);
    }

    sort(points.begin(), points.end(), compx);

    int j;

    scanf("%d",&q);
    for(i=0;i<q;i++){
        scanf("%d %d %d %d",&sx,&tx,&sy,&ty);
        printPoints(sx,tx,sy,ty);
    }

    return 0;
}

