bool X(const Point& a, const Point& b) { return a.x < b.x; }
bool Y(const Point& a, const Point& b) { return a.y < b.y; }

int make2DTree(int l, int r, int d) {
	if (l >= r) return -1;

	if (d % 2 == 0) sort(P + l, P + r, X);
	else sort(P + l, P + r, Y);

	int mid = (l + r) / 2, t = np++;
	T[t].location = mid; T[t].d = d;
	T[t].l = make2DTree(l, mid, d+1);
	T[t].r = make2DTree(mid + 1, r, d+1);

	return t;
}

void Find(int v, int sx, int tx, int sy, int ty) {
	int x = P[T[v].location].x, y = P[T[v].location].y;

	if (sx <= x && x <= tx && sy <= y && y <= ty) { A[c] = P[T[v].location].id; c++; }

	if (T[v].d%2 == 0) {
		if (T[v].l != -1 && sx <= x) Find(T[v].l, sx, tx, sy, ty);
		if (T[v].r != -1 && x <= tx) Find(T[v].r, sx, tx, sy, ty);
	}
	else {
		if (T[v].l != -1 && sy <= y) Find(T[v].l, sx, tx, sy, ty);
		if (T[v].r != -1 && y <= ty) Find(T[v].r, sx, tx, sy, ty);
	}
}

