		int x, y; cin >> x >> y;
		P[i] = Point(x, y, i);
		T[i].l = T[i].r = T[i].p = NIL;
	}
	np = 0;
	int root = makekDTree(0, N, 0);
	int q; cin >> q;
	vector<Point> ans;
	for (int i = 0; i < q; i++) {
		int sx, tx, sy, ty; cin >> sx >> tx >> sy >> ty;
