		kd.search(point(sx, sy, -1), point(tx, ty, -1), oit);
		vector<int> idxes;
		for (auto it = out.begin(); it != oit; it++) {
			idxes.push_back(it->idx);
		}
		sort(idxes.begin(), idxes.end());
