#include<iostream>
using namespace std;
#include<cstdio>
#include<algorithm>

struct point{ int x, y, id; };

point init(int pos_x, int pos_y, int index)
{
	point p; 
	p.x = pos_x, p.y = pos_y, p.id = index; 
	return p; 
}

bool cmp_x(const point &P1, const point &P2){ if(P1.x != P2.x){ return P1.x < P2.x; } return P1.y < P2.y; }
bool cmp_y(const point &P1, const point &P2){ if(P1.y != P2.y){ return P1.y < P2.y; } return P1.x < P2.x; }
bool cmp_id(const point &P1, const point &P2){ return P1.id < P2.id; }

void kd_tree(point *P, int *S, int *T, int *U, int left, int right, int d)
{
	if(right - left < 2) return;

	int mid = ((left + right) >> 1);
	int a = left, b = mid + 1;

	if((d & 1) == 0){
		for(int i = left; i < right; i++){
			if(cmp_x(P[T[i]], P[S[mid]])){
				U[a++] = T[i];
			}else if(P[S[mid]].id == P[T[i]].id){
				U[mid] = T[i];
			}else{
				U[b++] = T[i];
			}
		}
		for(int i = left; i < right; i++){ T[i] = U[i]; }

	}else{
		for(int i = left; i < right; i++){
			if(cmp_y(P[S[i]], P[T[mid]])){
				U[a++] = S[i];
			}else if(P[T[mid]].id == P[S[i]].id){
				U[mid] = S[i];
			}else{
				U[b++] = S[i];
			}
		}
		for(int i = left; i < right; i++){ S[i] = U[i]; }
	}
	kd_tree(P, S, T, U, left, mid, d + 1);
	kd_tree(P, S, T, U, mid + 1, right, d + 1);
}

int cnt;

void find_pt(point *P, int *Q, int *S,  int sx, int tx, int sy, int ty, int left, int right, int d)
{
	if(left >= right) return;

	int mid = ((left + right) >> 1);
	point p = P[S[mid]];
	int a = p.x, b = p.y;

	if(sx <= a && a <= tx && sy <= b && b <= ty){
		Q[cnt] = p.id, cnt++;
	}

	if((d & 1) == 0){
		if((left < mid) && (sx < a || (sx == a && sy <= b))){ find_pt(P, Q, S, sx, tx, sy, ty, left, mid, d + 1); }
		if((mid + 1 < right) && (a < tx || (a == tx && b <= ty))){ find_pt(P, Q, S, sx, tx, sy, ty, mid + 1, right, d + 1); }
	}else{
		if((left < mid) && (sy < b || (sy == b && sx <= a))){ find_pt(P, Q, S, sx, tx, sy, ty, left, mid, d + 1); }
		if((mid + 1 < right) && (b < ty || (b == ty && a <= tx))){ find_pt(P, Q, S, sx, tx, sy, ty, mid + 1, right, d + 1); }
	}
	return;
}

int main()
{
	point *P;
	int *S, *T, *U;
	int Q[100];
	int i, pos_x, pos_y, n;
	scanf("%d", &n);

	P = new point [n];
	S = new int [n], T = new int [n], U = new int [n];

	for(i = 0; i < n; i++){
		scanf("%d %d", &pos_x, &pos_y);
		P[i] = init(pos_x, pos_y, i);
	}
	sort(P, P + n, cmp_x);
	for(i = 0; i < n; i++){ S[i] = P[i].id; }
	sort(P, P + n, cmp_y);
	for(i = 0; i < n; i++){ T[i] = P[i].id; }
	sort(P, P + n, cmp_id);

	kd_tree(P, S, T, U, 0, n, 0);

	int sx, tx, sy, ty, q;
	scanf("%d", &q);
	while(q){
		cnt = 0;
		scanf("%d %d %d %d", &sx, &tx, &sy, &ty);
		find_pt(P, Q, S, sx, tx, sy, ty, 0, n, 0);
		sort(Q, Q + cnt);
		for(int i = 0; i < cnt; i++){ printf("%d\n", Q[i]); }
		printf("\n");
		q--;
	}
	delete [] P;
	delete [] S, delete [] T, delete [] U;

	return 0;
}

#include<stdio.h>
#include<vector>
#include<algorithm>
using namespace std;

struct Point {
	long long x, y;
	int i;
};

struct Node {
	Point p;
	int left;
	int right;
};

bool cmp_x(const Point& p1, const Point& p2) {
	return p1.x < p2.x;
}

bool cmp_y(const Point& p1, const Point& p2) {
	return p1.y < p2.y;
}

int makeTree(Node kDTree[],int& i, vector<Point>& points, int begin, int end,int depth) {
	if (begin >= end)return -1;
	if (depth & 1)sort(points.begin() + begin, points.begin() + end, cmp_x);
	else sort(points.begin() + begin, points.begin() + end, cmp_y);

	depth++;

	int mid = (begin + end) / 2;
	int j = i; i++;

	kDTree[j].p = points[mid];

	kDTree[j].left = makeTree(kDTree, i, points, begin, mid, depth);
	kDTree[j].right = makeTree(kDTree, i, points, mid + 1, end, depth);

	return j;
}

void searchTree(Node kDTree[], int i, Point p1, Point p2, int depth,vector<int>& ans) {
	Point p = kDTree[i].p;
	if (p.x >= p1.x && p.x <= p2.x && p.y >= p1.y && p.y <= p2.y) {
		ans.push_back(p.i);
	}

	if (depth & 1) {
		if (kDTree[i].left != -1 && p.x >= p1.x) {
			searchTree(kDTree, kDTree[i].left, p1, p2, depth + 1, ans);
		}
		if (kDTree[i].right != -1 && p.x <= p2.x) {
			searchTree(kDTree, kDTree[i].right, p1, p2, depth + 1, ans);
		}
