const int axis_num = 2;

struct Point {
  int id;
  array<int,axis_num> pos;
  Point() : id(-1), pos{0} {}
};

struct Node {
  Point point;
  Node* left;
  Node* right;
  Node(Point p, Node* l, Node* r) : point(p), left(l), right(r) {}
};

Node* makeTree(vector<Point>& ps, int l, int r, int depth) {
  if (l>=r) return NULL;
  int k = depth%axis_num;
  sort(ps.begin()+l, ps.begin()+r, [&](Point a, Point b) { return a.pos[k] < b.pos[k]; });
  int mid = (l+r)/2;
  return new Node(ps[mid], makeTree(ps,l,mid,depth+1), makeTree(ps,mid+1,r,depth+1));
}

void find(Node* nd, Point s, Point t, int depth, vector<int>& ans) {
  Point p = nd->point;
  bool inRange = true;
  rep(k,axis_num) {
    if (p.pos[k] < s.pos[k] || t.pos[k] < p.pos[k]) inRange = false;
  }
  if (inRange) ans.push_back(p.id);

  int k = depth%axis_num;
  if (nd->left != NULL && s.pos[k] <= p.pos[k]) find(nd->left, s, t, depth+1, ans);
  if (nd->right != NULL && t.pos[k] >= p.pos[k]) find(nd->right, s, t, depth+1, ans);
}

