struct Node {
    int location;
    int left;
    int right;
};

int node_num = 0;
Point P[N];
Node T[N];

int make2DTree(int range_l, int range_r, int depth)
{
    if (!(range_l < range_r))
        return NIL;

    int mid = (range_l + range_r) / 2;
    int t = node_num++;

    if (depth % 2 == 0)
        sort(P + range_l, P + range_r,
             [](const Point &p1, const Point &p2) { return p1.x < p2.x; });
    else
        sort(P + range_l, P + range_r,
             [](const Point &p1, const Point &p2) { return p1.y < p2.y; });

    T[t].location = mid;
    T[t].left = make2DTree(range_l, mid, depth + 1);
    T[t].right = make2DTree(mid + 1, range_r, depth + 1);

    return t;
}

void find(int root, int sx, int tx, int sy, int ty, int depth, vector<Point> &ans)
{
    int x = P[T[root].location].x;
    int y = P[T[root].location].y;

    if (sx <= x && x <= tx && sy <= y && y <= ty)
        ans.push_back(P[T[root].location]);

    if (depth % 2 == 0)
    {
        if (T[root].left != NIL && sx <= x)
            find(T[root].left, sx, tx, sy, ty, depth + 1, ans);
        if (T[root].right != NIL && x <= tx)
            find(T[root].right, sx, tx, sy, ty, depth + 1, ans);
    } else
    {
        if (T[root].left != NIL && sy <= y)
            find(T[root].left, sx, tx, sy, ty, depth + 1, ans);
        if (T[root].right != NIL && y <= ty)
            find(T[root].right, sx, tx, sy, ty, depth + 1, ans);
    }
}

