typedef struct node{
	int x;
	int y;
	int depth;
	int id;
	node *right;
	node *left;
} node;


bool compX(node &n1, node &n2){
	return n1.x < n2.x;
}

bool compY(node &n1, node &n2){
	return n1.y < n2.y;
}

node *nil;
std::vector<int> ans;
std::vector<node> nodes;

node* make_tree(int l, int r, int depth){
	if (l>=r){
		return nil;
	}

	if (depth % 2 == 0){
		std::sort(&nodes[l], &nodes[r], compX);
	}
	else{
		std::sort(&nodes[l], &nodes[r], compY);
	}

	int mid = (l+r)/2;
	nodes[mid].depth = depth;
	nodes[mid].left = make_tree(l, mid, depth+1);
	nodes[mid].right = make_tree(mid+1, r, depth+1);

	return &nodes[mid];
}

void search(node *n, int x_l, int x_h, int y_l, int y_h){
	int x = n->x;
	int y = n->y;

	if (x_l <= x && x <= x_h && y_l <= y && y <= y_h) ans.push_back(n->id);

	if (n->depth % 2 == 0){
		if (n->left != nil && x_l <= x) search(n->left, x_l, x_h, y_l, y_h);
		if (n->right != nil && x <= x_h) search(n->right, x_l, x_h, y_l, y_h);
	}

	else{
		if (n->left != nil && y_l <= y) search(n->left, x_l, x_h, y_l, y_h);
		if (n->right != nil && y <= y_h) search(n->right, x_l, x_h, y_l, y_h);
	}

}

void search_from_root(node *root, int x_l, int x_h, int y_l, int y_h){
	search(root, x_l, x_h, y_l, y_h);
	sort(ans.begin(), ans.end());
	for (int i=0; i<ans.size(); i++) printf("%d\n", ans[i]);
	printf("\n");
	ans.clear();
}

