	node *root;
	scanf("%d", &n);
	nodes.resize(n);

	for(int i=0; i<n;i++){
		scanf("%d %d", &x, &y);
		nodes[i].x = x;
		nodes[i].y = y;
		nodes[i].id = i;
	}

	root = make_tree(0, n, 0);
