template <typename T>
class SegmentTree {
	const int n;
	vector<vector<T>> data;
	int size(int n) {
		int res;
		for (res = 1; res < n; res <<= 1);
		return res;
	}
public:
	SegmentTree(const vector<T>& data_) : n(size(data_.size())), data(n * 2)
	{
		for (int i = 0; i < (int)data_.size(); i++) {
			data[i + n].push_back(data_[i]);
		}
		for (int i = n - 1; i >= 0; i--) {
			merge(data[i * 2].begin(), data[i * 2].end(), data[i * 2 + 1].begin(), data[i * 2 + 1].end(), back_inserter(data[i]));
		}
	}
	void for_each(int l, int r, function<void(vector<T>&)> que) {
		l += n; r += n + 1;
		while (l < r) {
			if (l & 1) que(data[l++]);
			if (r & 1) que(data[--r]);
			l >>= 1; r >>= 1;
		}
	}
};

