OwnNode nodes[500000];


void find(int index,OwnNode& ld, OwnNode& ru, int d, vector<int>& v)
{
	if (ld.x <= nodes[index].x&&nodes[index].x <= ru.x&&ld.y <= nodes[index].y&&nodes[index].y <= ru.y)
	{
		v.push_back(nodes[index].index);
	}

	if (d % 2 == 0)
	{
		if (ld.x <= nodes[index].x)
		{
			if (nodes[index].left != -1)
			{
				find(nodes[index].left, ld, ru, d + 1, v);
			}
		}
		if (nodes[index].x <= ru.x)
		{
			if (nodes[index].right != -1)
			{
				find(nodes[index].right, ld, ru, d + 1, v);
			}
		}
	}
	else
	{
		if (ld.y <= nodes[index].y)
		{
			if (nodes[index].left != -1)
			{
				find(nodes[index].left, ld, ru, d + 1, v);
			}
		}
		if (nodes[index].y <= ru.y)
		{
			if (nodes[index].right != -1)
			{
				find(nodes[index].right, ld, ru, d + 1, v);
			}
		}
	}
}

int BuildKDTree(int s, int e, int d)
{
	int m = (s + e) / 2;
	D = d;
	nth_element(nodes + s, nodes + m, nodes + e + 1);
	nodes[m].left = m == s ? -1 : BuildKDTree(s, m - 1, d + 1);
	nodes[m].right = m == e ? -1 : BuildKDTree(m + 1, e, d + 1);
	return m;
}

