using namespace std;

struct XY
{
    int x;
    int y;
    int index;
};

struct Node
{
    XY xy;
    Node *right;
    Node *left;
};

void InsertNode(Node *root, XY xy) {
    int depth = 0;
    Node *parent = root;
    Node *child = root;
    bool is_right;
    while (true)
    {
        if (child == nullptr) {
            Node *node = new Node;
            node->xy = xy;
            node->right = nullptr;
            node->left = nullptr;
            if (is_right) {
                parent->right = node;
            }
            else {
                parent->left = node;
            }
            break;
        }

        parent = child;
        int axis = depth % 2;
        if (axis == 0) {
            if (child->xy.x < xy.x) {
                child = child->right;
                is_right = true;
            }
            else {
                child = child->left;
                is_right = false;
            }
        }
        else {
            if (child->xy.y < xy.y) {
                child = child->right;
                is_right = true;
            }
            else {
                child = child->left;
                is_right = false;
            }
        }
        depth++;
    }
}

Node* kdTree(vector<XY> v, int first, int last, int depth) {
    int size = last - first;
    if (size < 0) {
        return nullptr;
    }

    int axis = depth % 2;
    if (axis == 0) {
        sort(v.begin() + first, v.begin() + last + 1, [](const XY& first, const XY& second) {
            return first.x < second.x;
        });
    }
    else {
        sort(v.begin() + first, v.begin() + last + 1, [](const XY& first, const XY& second) {
            return first.y < second.y;
        });
    }
    Node *node = new Node;
    node->xy = v[first + size / 2];
    node->right = kdTree(v, first + size / 2 + 1, last, depth + 1);
    node->left = kdTree(v, first, first + size / 2 - 1, depth + 1);

    return node;
}

void search(Node *p, int sx, int tx, int sy, int ty, int depth, vector<int>* result) {
    if (p == nullptr) {
        return;
    }

    int axis = depth % 2;

    if (axis == 0) {
        if (p->xy.x < sx) {
            search(p->right, sx, tx, sy, ty, depth + 1, result);
        }
        else if (p->xy.x > tx) {
            search(p->left, sx, tx, sy, ty, depth + 1, result);
        }
        else {
            search(p->left, sx, tx, sy, ty, depth + 1, result);
            search(p->right, sx, tx, sy, ty, depth + 1, result);
            if (p->xy.y >= sy && p->xy.y <= ty) {
                result->push_back(p->xy.index);
            }
        }
    }
    else {
        if (p->xy.y < sy) {
            search(p->right, sx, tx, sy, ty, depth + 1, result);
        }
        else if (p->xy.y > ty) {
            search(p->left, sx, tx, sy, ty, depth + 1, result);
        }
        else {
            search(p->left, sx, tx, sy, ty, depth + 1, result);
            search(p->right, sx, tx, sy, ty, depth + 1, result);
            if (p->xy.x >= sx && p->xy.x <= tx) {
                result->push_back(p->xy.index);
            }
        }
    }
}

void freeKdTree(Node *p) {
    if (p == nullptr) {
        return;
    }
    freeKdTree(p->left);
    freeKdTree(p->right);
    free(p);
}

