using tree = node*;
using vector = std::vector<point>;
using iterator = std::vector<point>::iterator;

tree make2Dtree(iterator l, iterator r, int depth)
{
  if (l>=r)
    return nullptr;

  if (depth % 2 == 0)
    {
      std::sort(l, r, [](point a, point b){return a.x < b.x;});
    }
  else
    {
      std::sort(l, r, [](point a, point b){return a.y < b.y;});
    }

  auto mid = l + std::distance(l, r)/2;
  auto new_node = new node;
  new_node->p = *mid;
  new_node->left = make2Dtree(l, mid, depth+1);
  new_node->right = make2Dtree(mid+1, r, depth+1);

  return new_node;
}

void find(tree T, int sx, int tx, int sy, int ty, int depth, vector& ans)
{
  if (T == nullptr) return;


  auto p = T->p;
  if (sx<=p.x && p.x<=tx && sy<=p.y && p.y<=ty)
    {
      ans.push_back(p);
    }

  if (depth%2==0)
    {
      if (p.x>=sx)
        find(T->left, sx, tx, sy, ty, depth+1, ans);
      if (p.x<=tx)
        find(T->right, sx, tx, sy, ty, depth+1, ans);
    }
  else
    {
      if (p.y>=sy)
        find(T->left, sx, tx, sy, ty, depth+1, ans);
      if (p.y<=ty)
        find(T->right, sx, tx, sy, ty, depth+1, ans);
    }
}

