mat ans;

template <int N>
class kd_tree {
private:
    mat node;
public:
    kd_tree(){}
    kd_tree(lli n,mat& x){
        node = mat(n,vll(N));
        for(lli i = 0;i < n;i++) node[i] = x[i];
        make(node.begin(),node.end(),0);
    }
    void make(mat::iterator from,mat::iterator to,int d){
        if(from == to) return;
        sort(from,to,[d](vll a,vll b){
            return a[d] < b[d];
        });
        make(from,from+(to-from)/2,(d+1)%N);
        make(from+(to-from)/2+1,to,(d+1)%N);
    }
    lli search(vll s,vll t,vll a,vll b,lli d){
        return search(s,t,a,b,d,node.begin(),node.end());
    }
    lli search(vll s,vll t,vll a,vll b,lli d,mat::iterator from,mat::iterator to){
        if(from == to) return 0;
        //if(contain(s,t,a) && contain(s,t,b)) return to - from;
        for(lli i = 0;i < N;i++){
            if(a[i] > t[i]) return 0;
            if(b[i] < s[i]) return 0;
        }
        vll p = *(from+(to-from)/2);
        vll a_ = a;
        vll b_ = b;
        a_[d] = p[d];b_[d] = p[d];
        return (contain(s,t,p) ? 1 : 0) + search(s,t,a,b_,(d+1)%N,from,from+(to-from)/2) + search(s,t,a_,b,(d+1)%N,from+(to-from)/2+1,to);

    }
    bool contain(vll& a,vll& b,vll& s){
        for(lli i = 0;i < N;i++){
            if(a[i] > s[i]) return false;
            if(b[i] < s[i]) return false;
        }
        ans.push_back(s);
        return true;
    }

};

