void build(Node* &v,vector<T> vx,vector<T> vy,int d){
	int size = vx.size();
	int half = size/2;
	if(size==0)return;
	v = new Node(vx,vy,d);
	if(d%2==0){
		v->val = vx[half].fi;
		if(size==1)return;
		for(int i=0;i<size;i++){
			tmp[vx[i].sec]=i;
			vx[i].sec = i;
		}
		for(int i=0;i<size;i++)vy[i].sec=tmp[vy[i].sec];
		int border = vx[half].fi.fi;
		vector<T> lx,ly,rx,ry;
		for(int i=0;i<size;i++){
			if(vx[i].fi.fi<border)lx.pb(vx[i]);
			else rx.pb(vx[i]);
			if(vy[i].fi.fi<border)ly.pb(vy[i]);
			else ry.pb(vy[i]);
		}
		build(v->lp,lx,ly,d+1);
		build(v->rp,rx,ry,d+1);
	}else{
		v->val = vy[half].fi;
		if(size==1)return;
		for(int i=0;i<size;i++){
			tmp[vy[i].sec]=i;
			vy[i].sec = i;
		}
		for(int i=0;i<size;i++)vx[i].sec=tmp[vx[i].sec];
		int border = vy[half].fi.sec;
		vector<T> lx,ly,rx,ry;
		for(int i=0;i<size;i++){
			if(vx[i].fi.sec<border)lx.pb(vx[i]);
			else rx.pb(vx[i]);
			if(vy[i].fi.sec<border)ly.pb(vy[i]);
			else ry.pb(vy[i]);
		}
		build(v->lp,lx,ly,d+1);
		build(v->rp,rx,ry,d+1);
	}
	return;
}
