bool operator<(const Point &p1, const Point &p2) {
  return p1.x < p2.x or (p1.x == p2.x and p1.y < p2.y);
}
bool operator==(const Point &p1, const Point &p2) {
  return !(p1 < p2) and !(p2 < p1);
}
bool operator<=(const Point &p1, const Point &p2) {
  return p1 < p2 or p1 == p2;
}
auto CompareY = [](const Point &p1, const Point &p2) {
  return p1.y < p2.y or (p1.y == p2.y and p1.x < p2.x);
};

struct Node {
  Point p;
  Node *left;
  Node *right;
  Node(Point p, Node *left, Node *right) : p{p}, left{left}, right{right} {}
};

Node *Build(vector<Point> &sx, vector<Point> &sy, int depth) {
  if (sx.size() == 1)
    return new Node(sx[0], nullptr, nullptr);
  vector<Point> sxlow;
  vector<Point> sxhigh;
  vector<Point> sylow;
  vector<Point> syhigh;
  int midx = sx.size() / 2 + (sx.size() % 2) - 1;
  Point thresh;
  if (depth % 2 == 0) {
    thresh = sx[midx];
  } else {
    thresh = sy[midx];
  }
  //  cout << "depth " << depth << "thresh: " << thresh.x << " " << thresh.y
  //       << endl;
  for (auto &p : sx) {
    if ((depth % 2 == 0 and
         ((p.x < thresh.x) or (p.x == thresh.x and p.y <= thresh.y))) or
        (depth % 2 == 1 and
         ((p.y < thresh.y) or (p.y == thresh.y and p.x <= thresh.x)))) {
      sxlow.push_back(p);
    } else {
      sxhigh.push_back(p);
    }
  }
  for (auto &p : sy) {
    if ((depth % 2 == 0 and
         (p.x < thresh.x or p.x == thresh.x and p.y <= thresh.y)) or
        (depth % 2 == 1 and
         (p.y < thresh.y or p.y == thresh.y and p.x <= thresh.x))) {
      sylow.push_back(p);
    } else {
      syhigh.push_back(p);
    }
  }
  //  cout << "Threshold ";
  //  if (depth % 2 == 0)
  //    cout << "x=";
  //  else
  //    cout << "y=";
  //  cout << "(" << thresh.x << ", " << thresh.y << ")" << endl;
  //  cout << "xlow: ";
  //  for (int i = 0; i < sxlow.size(); ++i)
  //    cout << "(" << sxlow[i].x << ",  " << sxlow[i].y << ") ";
  //  cout << endl;
  //  cout << "xhigh: ";
  //  for (int i = 0; i < sxhigh.size(); ++i)
  //    cout << "(" << sxhigh[i].x << ", " << sxhigh[i].y << ") ";
  //  cout << "ylow: ";
  //  for (int i = 0; i < sylow.size(); ++i)
  //    cout << "(" << sylow[i].x << ", " << sylow[i].y << ") ";
  //  cout << endl;
  //  cout << "yhigh: ";
  //  for (int i = 0; i < syhigh.size(); ++i)
  //    cout << "(" << syhigh[i].x << ", " << syhigh[i].y << ") ";
  return new Node(thresh, Build(sxlow, sylow, depth + 1),
                  Build(sxhigh, syhigh, depth + 1));
}

void Print(Node *curr, int depth) {
  if (!curr->left) // leaf
    cout << "(" << curr->p.x << ", " << curr->p.y << ")\n";
  if (curr->left) {
    if (depth % 2 == 0)
      cout << "x=";
    else
      cout << "y=";
    cout << "(" << curr->p.x << ", " << curr->p.y << ")" << endl;
  }
  if (curr->left)
    Print(curr->left, depth + 1);
  if (curr->right)
    Print(curr->right, depth + 1);
}

void Query(Node *curr, int depth, const Point &p1, const Point &p2,
           set<int> &res) {
  //  cout << "Query at ";
  //  cout << ((curr->left) ? "internal " : "leaf ");
  //  cout << curr->p.x << " " << curr->p.y << endl;
  if (curr->left == nullptr) { // leaf; tree is full
    if (curr->p.x >= p1.x and curr->p.x <= p2.x and curr->p.y >= p1.y and
        curr->p.y <= p2.y)
      res.insert(curr->p.id);
    return;
  }
  if ((p1 <= curr->p and depth % 2 == 0) or
      ((CompareY(p1, curr->p) or (p1 == curr->p)) and depth % 2 == 1))
    Query(curr->left, depth + 1, p1, p2, res);
  if ((curr->p < p2 and depth % 2 == 0) or
      (CompareY(curr->p, p2) and depth % 2 == 1))
    Query(curr->right, depth + 1, p1, p2, res);
}

