class KDTree {
public:
  explicit KDTree(std::vector<Vertex> vertex);
  void search(int sx, int sy, int tx, int ty) const;
private:
  static const int NIL = -1;
  class Compare {
  public:
    Compare(int d) : d(d) {}
    bool operator()(const Vertex& lhs, const Vertex& rhs) const {return d & 1 ? lhs.y < rhs.y : lhs.x < rhs.x;}
  private:
    int d;
  };
  struct Node {
    Vertex vertex;
    int left_child, right_child;
    Node(const Vertex& v = Vertex(), int l = NIL, int r = NIL) : vertex(v), left_child(l), right_child(r) {}
  };
  int build(std::vector<Vertex>& vertex, int low, int high, int depth);
  void search(int index, int sx, int sy, int tx, int ty, int depth) const;
  std::vector<Node> node_;
  int root_;
};
// ?????????????????????
KDTree::KDTree(std::vector<Vertex> vertex) : node_(vertex.size()) {root_ = build(vertex, 0, vertex.size(), 0);}
// ?§????
int KDTree::build(std::vector<Vertex>& vertex, int low, int high, int depth) {
  if(!(low < high)) return NIL;
  std::sort(begin(vertex) + low, begin(vertex) + high, Compare(depth));
  int middle = (low + high) / 2;
  node_[middle].vertex = vertex[middle];
  node_[middle].left_child = build(vertex, low, middle, depth ^ 1);
  node_[middle].right_child = build(vertex, middle + 1, high, depth ^ 1);
  return middle;
}
// ?????¢?????????????????°?????????????????°??¨???????????¢???????????§?¨????????????§?¨??????????
void KDTree::search(int sx, int sy, int tx, int ty) const {search(root_, sx, sy, tx, ty, 0);}
void KDTree::search(int index, int sx, int sy, int tx, int ty, int depth) const {
  if(index == NIL) return;
  if(sx <= node_[index].vertex.x && node_[index].vertex.x <= tx && sy <= node_[index].vertex.y && node_[index].vertex.y <= ty) answer.insert(node_[index].vertex.label);
  if(depth & 1) {
    if(sy <= node_[index].vertex.y) search(node_[index].left_child, sx, sy, tx, ty, depth ^ 1);
    if(node_[index].vertex.y <= ty) search(node_[index].right_child, sx, sy, tx, ty, depth ^ 1);
  } else {
    if(sx <= node_[index].vertex.x) search(node_[index].left_child, sx, sy, tx, ty, depth ^ 1);
    if(node_[index].vertex.x <= tx) search(node_[index].right_child, sx, sy, tx, ty, depth ^ 1);
  }
}

