    cin >> q;
    for (int i = 0; i < q; i++) {
        set<int> ans;
        int sx, tx, sy, ty;
        cin >> sx >> tx >> sy >> ty;
        T.find_data(sx, tx, sy, ty, ans);
        for (auto it = ans.begin(); it != ans.end(); it++) {
            cout << *it << endl;
        }
        cout << endl;
    }
    return 0;
}

