bool lessY(const Point &p1, const Point &p2){return p1.y < p2.y;};

/* 0-indexed only */
class kDTree{
private:
  Point *P;
  Node *Tree;
  int n;
  int np;
  int root;
public:
  kDTree(int x[], int y[], int id[], int N);
  ~kDTree();
  int make_tree(int l, int r, int depth);
  void find_func(int sx, int tx, int sy, int ty, vector<Point> &ans);
  void find(int v, int sx, int tx, int sy, int ty, int depth, vector<Point> &ans);
};

kDTree::kDTree(int x[], int y[], int id[], int N){
  n = N;
  P = new Point[n];
  Tree = new Node[n];
  for(int i=0;i<n;i++){
    P[i].x = x[i];
    P[i].y = y[i];
    P[i].id = id[i];
  }
  np = 0;
  root = make_tree(0, n, 0);
}

kDTree::~kDTree(){
  delete [] P;
  delete [] Tree;
}

int kDTree::make_tree(int l, int r, int depth){
  if(!(l<r)) return NIL;
  int mid = (l+r)/2;
  int t = np++;

  if(depth%2 == 0){
    sort(P+l, P+r, lessX);
  }
  else{
    sort(P+l, P+r, lessY);
  }
  Tree[t].location = mid;
  Tree[t].l = make_tree(l, mid, depth+1);
  Tree[t].r = make_tree(mid+1, r, depth+1);

  return t;
}

void kDTree::find_func(int sx, int tx, int sy, int ty, vector<Point> &ans){
  find(root, sx, tx, sy, ty, 0, ans);
}

void kDTree::find(int v, int sx, int tx, int sy, int ty, int depth, vector<Point> &ans){
  int x = P[Tree[v].location].x;
  int y = P[Tree[v].location].y;

  if(sx<=x && x<=tx && sy<=y && y<=ty){
    ans.push_back(P[Tree[v].location]);
  }

  if(depth%2 == 0){
    if(Tree[v].l != NIL){
      if(sx<=x) find(Tree[v].l, sx, tx, sy, ty, depth+1, ans);
    }
    if(Tree[v].r != NIL){
      if(x<=tx) find(Tree[v].r, sx, tx, sy, ty, depth+1, ans);
    }
  }
  else{
    if(Tree[v].l != NIL){
      if(sy<=y) find(Tree[v].l, sx, tx, sy, ty, depth+1, ans);
    }
    if(Tree[v].r != NIL){
      if(y<=ty) find(Tree[v].r, sx, tx, sy, ty, depth+1, ans);
    }
  }
}

