}

bool contain(vll& a,vll& b,vll& s){
    for(lli i = 0;i < 2;i++){
        if(a[i] > s[i]) return false;
        if(b[i] < s[i]) return false;
    }
    return true;
}

void search(vll& s,vll& t,vll& a,vll& b,lli d,vitr from,vitr to){
    if(from == to) return;
    if(contain(s,t,a) && contain(s,t,b)){
        for(vitr itr = from;itr < to;itr++){
            ans.push_back(*itr);
        }
        return;
    }
    for(lli i = 0;i < 2;i++){
        if(a[i] > t[i]) return;
        if(b[i] < s[i]) return;
    }
    vll p_ = p[*(from+(to-from)/2)];
    vll a_ = a;
    vll b_ = b;
    a_[d] = p_[d];b_[d] = p_[d];
    if(contain(s,t,p_)) ans.push_back(*(from+(to-from)/2));
    search(s,t,a,b_,(d+1)%2,from,from+(to-from)/2);
    search(s,t,a_,b,(d+1)%2,from+(to-from)/2+1,to);
}


