#include<iostream>
using namespace std;
#include<cstdio>       // k-D_tree. (k = 2)
#include<algorithm>

class Point
{
public:
    int id, x, y;
    Point(){};
    Point(int no, int pos_x, int pos_y) : id(no), x(pos_x), y(pos_y) {};
    void print(){ printf("%d\n", id); }
};

bool cmp_x(const Point &P1, const Point &P2){ return P1.x < P2.x; }
bool cmp_y(const Point &P1, const Point &P2){ return P1.y < P2.y; }
bool cmp_id(const Point &P1, const Point &P2){ return P1.id < P2.id; }

class node // nodes of 2-D_tree.
{
public:
    Point *mark;
    node *less, *more;
    int depth;   // parity of depth is important.
    node() : mark(NULL), less(NULL), more(NULL), depth(0) {};
    node(Point* pos, node* l, node* m, int d) : mark(pos), less(l), more(m), depth(d) {};
};

node* make_tree(Point S[], int left, int right, int d) // recursive construction of 2-D_tree.
{
    if(left > right){ return NULL; }
    if(left == right){
        node* leaf = new node;
        *leaf = node(&S[left], NULL, NULL, d);    // arrived at leaf.
        return leaf;
    }

	if(d & 1){
		sort(S + left, S + right + 1, cmp_x);
	}else{
        sort(S + left, S + right + 1, cmp_y);
	}

    int mid = (left + right) / 2;

    node* n = new node;   // make a new node.
    n->mark = &S[mid];
    n->depth = d;
    n->less = make_tree(S, left, mid - 1, d + 1);
    n->more = make_tree(S, mid + 1, right, d + 1);

    return n;
}

int cnt;

void find(Point S[], int sx, int tx, int sy, int ty, node* kd_n)
{
    if(kd_n == NULL) return;
    int a = kd_n->mark->x, b = kd_n->mark->y;

    if(sx <= a && a <= tx && sy <= b && b <= ty){
        S[cnt] = *(kd_n->mark);
        cnt++;
    }
    int d = kd_n->depth;

    if(d & 1){
        if(sx <= a) find(S, sx, tx, sy, ty, kd_n->less);
        if(a <= tx) find(S, sx, tx, sy, ty, kd_n->more);
    }else{
        if(sy <= b) find(S, sx, tx, sy, ty, kd_n->less);
        if(b <= ty) find(S, sx, tx, sy, ty, kd_n->more);
    }
}

int main()
{
    int i, pos_x, pos_y, n;
    Point P[500000], Q[100];

    scanf("%d", &n);
