struct segTreeRangeFreq {
    int n;
    vector<vector<PII>> dat;
    // 初期化 O(NlogN)
    segTreeRangeFreq() {}
    segTreeRangeFreq(vector<vector<PII>> v) {
        n = 1; while(n < (ll)v.size()) n *= 2;
        dat.resize(2*n-1);
        REP(i, v.size()) dat[i+n-1] = v[i];
        for(int i=n-2; i>=0; --i) {
            dat[i].resize(dat[i*2+1].size() + dat[i*2+2].size());
            merge(ALL(dat[i*2+1]), ALL(dat[i*2+2]), dat[i].begin());
        }
    }
    // [a, b) のx以上y以下の個数を返す O(log^2N)
    vector<int> query(int a, int b, ll x, ll y, int k, int l, int r) {
        if(b <= l || r <= a) return {};
        if(a <= l && r <= b) {
            vector<int> ret;
            ll itr1 = lower_bound(ALL(dat[k]), PII(x, -LLINF)) - dat[k].begin();
            ll itr2 = upper_bound(ALL(dat[k]), PII(y, LLINF)) - dat[k].begin();
            // cout << "itr1=" << itr1 << " itr2=" << itr2 << endl;
            FOR(i, itr1, itr2) ret.push_back(dat[k][i].second);
            // cout << "l=" << l << " r=" << r << " dat=" << dat[k] << " ret=" << ret << endl;
            return ret;
        }
        vector<int> vl = query(a, b, x, y, k*2+1, l, (l+r)/2);
        vector<int> vr = query(a, b, x, y, k*2+2, (l+r)/2, r);
        for(auto i: vr) vl.push_back(i);
        return vl;
    }
    vector<int> query(int a, int b, ll x, ll y) { return query(a, b, x, y, 0, 0, n); }
};

