  };
  struct Node {
    Vertex vertex;
    int left_child, right_child;
    Node(const Vertex& v = Vertex(), int l = NIL, int r = NIL) : vertex(v), left_child(l), right_child(r) {}
  };
  int build(std::vector<Vertex>& vertex, int low, int high, int depth);
  void search(int index, int sx, int sy, int tx, int ty, int depth) const;
  std::vector<Node> node_;
