  if(index == NIL) return;
  if(sx <= node_[index].vertex.x && node_[index].vertex.x <= tx && sy <= node_[index].vertex.y && node_[index].vertex.y <= ty) answer[node_[index].vertex.label] = true;
  if(depth & 1) {
    if(sy <= node_[index].vertex.y) search(node_[index].left_child, sx, sy, tx, ty, depth ^ 1);
    if(node_[index].vertex.y <= ty) search(node_[index].right_child, sx, sy, tx, ty, depth ^ 1);
  } else {
    if(sx <= node_[index].vertex.x) search(node_[index].left_child, sx, sy, tx, ty, depth ^ 1);
    if(node_[index].vertex.x <= tx) search(node_[index].right_child, sx, sy, tx, ty, depth ^ 1);
  }
}

