template<class T = int> using V = vector<T>;
template<class T = int> using VV = V< V<T> >;
template<class T> void assign(V<T>& v, int n, const T& a = T()) { v.assign(n, a); }
template<class T, class... Args> void assign(V<T>& v, int n, const Args&... args) { v.resize(n); for (auto&& e : v) assign(e, args...); }


constexpr int inf = 1e9;

struct P { int id, x, y; };
auto comp_id = [](const P& lhs, const P& rhs) { return lhs.id < rhs.id; };
auto comp_x = [](const P& lhs, const P& rhs) { return lhs.x < rhs.x; };
auto comp_y = [](const P& lhs, const P& rhs) { return lhs.y < rhs.y; };

struct Monoid {
  using T = V<P>;
  static T op(const T& lhs, const T& rhs) {
    T res;
    merge(begin(lhs), end(lhs), begin(rhs), end(rhs), back_inserter(res), comp_y);
    return move(res);
  }
  static T e() { return T(); }
};

template<class Monoid> struct SegmentTree {
  using T = typename Monoid::T;
  struct Node {
    lint l, r, m;
    T val;
    unique_ptr<Node> cl, cr;
    Node(lint l, lint r) : l(l), r(r), m(l + r >> 1), val(Monoid::e()), cl(nullptr), cr(nullptr) {}
  };

  unique_ptr<Node> root;

  SegmentTree() : root(make_unique<Node>(-inf, inf + 1)) {}

  T get(lint l, lint r) { return _get(l, r, root); }

  void set(lint i, const T& a) { _set(i, a, root); }

  T _get(lint l , lint r, const unique_ptr<Node>& v) {
    if (l <= v->l and v->r <= r) return v->val;
    T resl = Monoid::e(), resr = Monoid::e();
    if (l < v->m) {
      if (v->cl == nullptr) v->cl = make_unique<Node>(v->l, v->m);
      resl = _get(l, r, v->cl);
    }
    if (v->m < r) {
      if (v->cr == nullptr) v->cr = make_unique<Node>(v->m, v->r);
      resr = _get(l, r, v->cr);
    }
    return Monoid::op(resl, resr);
  }

  void _set(lint i, const T& a, const unique_ptr<Node>& v) {
    if (v->r - v->l == 1) {
      v->val = a;
      return;
    }
    if (i < v->m) {
      if (v->cl == nullptr) v->cl = make_unique<Node>(v->l, v->m);
      _set(i, a, v->cl);
      v->val = Monoid::op(v->cl->val, v->cr != nullptr ? v->cr->val : Monoid::e());
    } else {
      if (v->cr == nullptr) v->cr = make_unique<Node>(v->m, v->r);
      _set(i, a, v->cr);
      v->val = Monoid::op(v->cl != nullptr ? v->cl->val : Monoid::e(), v->cr->val);
    }
  }
};

