inline bool lessX(const Point &p1, const Point &p2) { return p1.x < p2.x; }
inline bool lessY(const Point &p1, const Point &p2) { return p1.y < p2.y; }

int makeKDTree(int l, int r, int depth) {
	if (!(l < r)) return NIL;
	int mid = (l + r) / 2;
	int t = np++;

	if (depth % 2 == 0) {
		sort(P + l, P + r, lessX);
	}
	else {
		sort(P + l, P + r, lessY);
	}
	T[t].location = mid;
	T[t].l = makeKDTree(l, mid, depth + 1);
	T[t].r = makeKDTree(mid + 1, r, depth + 1);

	return t;
}

void find(int v, int sx, int tx, int sy, int ty, int depth, vector<Point> &ans) {
	int loc = T[v].location;
	int a = P[loc].x;
	int b = P[loc].y;

	if (sx <= a && a <= tx &&sy <= b && b <= ty) {
		ans.push_back(P[loc]);
	}
	if (depth % 2 == 0) {
		if (T[v].l != NIL && sx <= a) find(T[v].l, sx, tx, sy, ty, depth + 1, ans);
		if (T[v].r != NIL && a <= tx) find(T[v].r, sx, tx, sy, ty, depth + 1, ans);
	}
	else {
		if (T[v].l != NIL && sy <= b) find(T[v].l, sx, tx, sy, ty, depth + 1, ans);
		if (T[v].r != NIL && b <= ty) find(T[v].r, sx, tx, sy, ty, depth + 1, ans);
	}
}

int main() {
	int n, x, y, sx, tx, sy, ty, q;
	scanf("%d", &n);
	for (int i = 0; i < n; i++) {
		scanf("%d%d", &x, &y);
		P[i] = Point(i, x, y);
	}
	np = 0;
	int root = makeKDTree(0, n, 0);
	vector<Point> ans;
	scanf("%d", &q);
	for (int i = 0; i < q; i++) {
		scanf("%d%d%d%d", &sx, &tx, &sy, &ty);
		ans.clear();
		find(root, sx, tx, sy, ty, 0, ans);
		sort(ans.begin(), ans.end());
		for (int j = 0; j < ans.size(); j++) {
			ans[j].print();
		}
		printf("\n");

	}
}

