void build(int d , int b , int e )
{
    if (b == e) {
        st[d][b] = x[b].second;
        return;
    }
    int m = (b + e) >> 1;
    build(d + 1, b, m);
    build(d + 1, m + 1, e);
    int l = b, r = m + 1;
    for (int pt = b; pt <= e; ++pt) // p = point ha
        if (l != m + 1 && (r == e + 1 || y[st[d + 1][l]] < y[st[d + 1][r]]))
            st[d][pt] = st[d + 1][l++];
        else
            st[d][pt] = st[d + 1][r++];
}
int j;
int result[105];
int L = 0;
inline void query(int dep , int l , int r , int x1 , int y1 , int x2 , int y2 , int p = 0)
{
    if (x[r].first < x1 || x[l].first > x2)
        return ;
    if (y[st[dep][l]] > y2 || y[st[dep][r]] < y1)
        return ;
    if (x[l].first >= x1 && x[r].first <= x2)
    {

        if (ptr[p] < l)
            ptr[p] = l;
        while (ptr[p] <= r && (y[st[dep][ptr[p]]] < y1 || y[st[dep][ptr[p]]] ) > y2)
            ptr[p] ++;
        for (int j = ptr[p] ; j <= r ; j ++)
        {
            if (!(y[st[dep][j]] >= y1 && y[st[dep][j]] <= y2))break;
            L ++;
            result[L] = st[dep][j];
        }
        return ;
    }
    int mid = (l + r) >> 1;
    query(dep + 1 , l  , mid , x1 , y1 , x2 , y2);
    query(dep + 1 , mid + 1 , r , x1 , y1 , x2 , y2);
    return ;
}
