/// 2分セグメント木。RMQとかが解ける。
template<class T, class TParentFunc>
struct SegTreeT
{
	int size;
	vector<T> tree;
	TParentFunc parent;
	T initialValue;
	static constexpr unsigned int msb(unsigned int v) { REP(i, 5) v |= v >> (1 << i); return (v >> 1) + 1; }

	SegTreeT(int count, TParentFunc parentBuilder, T initialFill)
		: size(msb(count - 1) << 1)
		, tree(size * 2)
		, parent(parentBuilder)
		, initialValue(initialFill)
	{
		fill(partof(tree, size, size), initialFill);
		rebuild();
	}

	// []を使うと更新されないのでrebuildすること。数が少なければupdateの方がよい。
	T& operator[](int i) { return tree[i + size]; }
	void rebuild() { RREP(i, size) { tree[i] = parent(tree[i * 2], tree[i * 2 + 1]); } }

	void update(int index, T value)
	{
		tree[index + size] = value;
		for (int i = (index + size) / 2; i > 0; i /= 2)
			tree[i] = parent(tree[i * 2], tree[i * 2 + 1]);
	}

	T query(int s, int e, int i, int l, int r, T value)
	{
		if (r <= s || e <= l) return value;
		if (s <= l && r <= e) return parent(value, tree[i]);
		value = query(s, e, i * 2, l, (l + r) / 2, value);
		value = query(s, e, i * 2 + 1, (l + r) / 2, r, value);
		return value;
	}

	T query(int begin, int end, T initialValue) { return query(begin, end, 1, 0, size, initialValue); }
	T query(int begin, int end) { return query(begin, end, initialValue); }
};
template<class T = int, class TParentFunc = const T& (*)(const T&, const T&)>
SegTreeT<T, TParentFunc> SegTree(int N, TParentFunc f = min, int initialValue = INF)
{
	return SegTreeT<T, TParentFunc>(N, f, initialValue);
}


template <class T, size_t K>
struct KDTree {
	static constexpr unsigned int msb(unsigned int v) { REP(i, 5) v |= v >> (1 << i); return (v >> 1) + 1; }

	using PT = array<T, K>;
	vector<PT> p_{ };
	vector<int> tree{};

	void add(PT p)
	{
		p_.push_back(p);
	}

	void build()
	{
		int treesize = 1 << msb(p_.size() + 1);
		tree.assign(treesize, -1);

		vector<int> work(p_.size());
		iota(allof(work), 0);
		build_internal(work, 0, 1, 0, work.size());
	}

	void build_internal(vector<int> &w, int depth, int i, int l, int r)
	{
		if (r - l == 0) { return; }

		int d = depth % K;
		int m = (r - l - 1) / 2 + l;
		nth_element(w.begin() + l, w.begin() + m, w.begin() + r, COMP(a, b, p_[a][d] < p_[b][d]));
		tree[i] = w[m];
		build_internal(w, depth + 1, i * 2, l, m);
		build_internal(w, depth + 1, i * 2 + 1, m + 1, r);
	}

	vector<int> range(PT s, PT e)
	{
		vector<int> ret;
		range_internal(ret, s, e, 0, 1, 0, p_.size());
		return ret;
	}

	void range_internal(vector<int> &ret, PT s, PT e, int depth, int i, int l, int r)
	{
		if (r - l == 0) { return; }

		PT p = p_[tree[i]];
		bool inRange = true;
		REP(i, K) { inRange &= p[i] >= s[i] && p[i] <= e[i]; }
		if (inRange) { ret.push_back(tree[i]); }

		int d = depth % K;
		int m = (r - l - 1) / 2 + l;
		if (p[d] >= s[d]) { range_internal(ret, s, e, depth + 1, i * 2, l, m); }
		if (p[d] <= e[d]) { range_internal(ret, s, e, depth + 1, i * 2 + 1, m + 1, r); }
	}
};

