struct Xorshift {
  uint64_t x = 88172645463325252LL;
  unsigned next_int() {
    x = x ^ (x << 7);
    return x = x ^ (x >> 9);
  }
  unsigned next_int(unsigned mod) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % mod;
  }
  unsigned next_int(unsigned l, unsigned r) {
    x = x ^ (x << 7);
    x = x ^ (x >> 9);
    return x % (r - l + 1) + l;
  }
  double next_double() {
    return double(next_int()) / UINT_MAX;
  }
} rnd;

template<typename T>
void shuffle_vector(vector<T>& v, Xorshift& rnd) {
  int n = v.size();
  for (int i = n - 1; i >= 1; i--) {
    int r = rnd.next_int(i);
    swap(v[i], v[r]);
  }
}



template <class T, size_t K>
struct KDTree {
  using P = array<T, K>;
  vector<P> points;
  vector<int> tree;

  KDTree() {}
  KDTree(int n) : points(n) {
    int sz = 1;
    while (sz < n) sz <<= 1;
    tree.resize(sz, -1);
  }
  KDTree(const vector<P>& points) : points(points) {
    int n = (int)points.size(), sz = 1;
    while (sz < n) sz <<= 1;
    tree.resize(sz, -1);
  }

  P& operator [] (int i) { return points[i]; }

  void build() {
    vector<int> w(points.size());
    iota(w.begin(), w.end(), 0);
    build_internal(w, 0, 1, 0, w.size());
  }

  vector<int> range(const P& s, const P& e) {
    vector<int> ret;
    ret.reserve(points.size());
    range_internal(ret, s, e, 0, 1, 0, points.size());
    return ret;
  }

private:
  void build_internal(vector<int>& w, int depth, int i, int l, int r) {
    if (l == r) return;
    int d = depth % K;
    int m = (r - l - 1) / 2 + l;
    nth_element(
      w.begin() + l, w.begin() + m, w.begin() + r, 
      [&](const auto& a, const auto& b) { return points[a][d] < points[b][d]; }
    );
    tree[i] = w[m];
    build_internal(w, depth + 1, i * 2, l, m);
    build_internal(w, depth + 1, i * 2 + 1, m + 1, r);
  }

  void range_internal(vector<int>& ret, const P& s, const P& e, int depth, int i, int l, int r) {
    if (l == r) return;
    const P& p = points[tree[i]];
    bool in_range = true;
    for(int i = 0; i < K; i++) in_range &= p[i] >= s[i] && p[i] < e[i];
    if (in_range) ret.push_back(tree[i]);
    int d = depth % K;
    int m = (r - l - 1) / 2 + l;
    if (p[d] >= s[d]) range_internal(ret, s, e, depth + 1, i * 2, l, m);
    if (p[d] < e[d]) range_internal(ret, s, e, depth + 1, i * 2 + 1, m + 1, r);
  }
};

