	inline friend bool operator <
		(const node &a, const node &b) {
		if (a.pos[cmpk] != b.pos[cmpk])
			return a.pos[cmpk] < b.pos[cmpk];
		else
			return a.pos[cmpk ^ 1] < b.pos[cmpk ^ 1];
	}
}tree[500005];

int build(int l, int r, int k) {
	int d = (l + r) / 2; cmpk = k;
	nth_element(
		tree + l + 1,
		tree + d + 1,
		tree + r + 1);
	tree[d].son[0] = tree[d].son[1] = 0;
	if (l != d)tree[d].son[0] = build(l, d - 1, k ^ 1);
	if (r != d)tree[d].son[1] = build(d + 1, r, k ^ 1);	
	return d;
}

inline void build(void) {
	for (int i = 1; i <= n; ++i)tree[i].id = i - 1,
		cin >> tree[i].pos[0] >> tree[i].pos[1];
	root = build(1, n, 0);
}

