void dfs(vector<int> vec, int k, bool xaxis){
    vector<pair<int, int>> cvec;
    if(xaxis){
        for(auto v: vec)
            cvec.push_back({X[v], v});
    }else{
        for(auto v: vec)
            cvec.push_back({Y[v], v});
    }
    sort(cvec.begin(), cvec.end());

    int m = cvec.size();
    data[k] = cvec[m/2].second;

    vector<int> lvec;
    for(int i=0; i<m/2; i++){
        lvec.push_back(cvec[i].second);
    }
    if(lvec.size() > 0){
        dfs(lvec, 2*k+1, xaxis^true);
    }
    vector<int> rvec;
    for(int i=m/2+1; i<m; i++){
        rvec.push_back(cvec[i].second);
    }
    if(rvec.size() > 0){
        dfs(rvec, 2*k+2, xaxis^true);
    }
}

void buildtree(){
    int N_ = X.size();
    int N = 1;
    while(N <= N_)
        N <<= 1;
    data.assign(2*N-1, -1);

    vector<int> vec;
    for(int i=0; i<N_; i++)
        vec.push_back(i);

    dfs(vec, 0, true);
}

void query(int k, int sx, int tx, int sy, int ty, bool xaxis, vector<int> &ans){
    if(data[k] == -1) return;

    if(xaxis){
        if(sx <= X[data[k]] && X[data[k]] <= tx && sy <= Y[data[k]] && Y[data[k]] <= ty)
            ans.push_back(data[k]);

        if(sx <= X[data[k]])
            query(2*k+1, sx, tx, sy, ty, xaxis^true, ans);
        if(X[data[k]] <= tx)
            query(2*k+2, sx, tx, sy, ty, xaxis^true, ans);
    }else{
        if(sx <= X[data[k]] && X[data[k]] <= tx && sy <= Y[data[k]] && Y[data[k]] <= ty)
            ans.push_back(data[k]);

        if(sy <= Y[data[k]])
            query(2*k+1, sx, tx, sy, ty, xaxis^true, ans);
        if(Y[data[k]] <= ty)
            query(2*k+2, sx, tx, sy, ty, xaxis^true, ans);
    }
}

