struct Vertex {
    int label;
    double x, y;
    Vertex(int label = -1, double x = 0.0, double y = 0.0) :label(label), x(x), y(y) {}
};

bool compare_x(const Vertex& v1, const Vertex& v2) {return v1.x < v2.x;}
bool compare_y(const Vertex& v1, const Vertex& v2) {return v1.y < v2.y;}

class KDTree {
public:
    KDTree(std::vector<Vertex> list) {
        make_tree(root_, list, 0, list.size() - 1, false);
    }
    void search(const Vertex& initial, const Vertex& terminal) const {search(root_, initial, terminal, false);}
//     void print() const {traverse(root_, 0);}
private:
    struct Node {
        Vertex vertex;
        std::unique_ptr<Node> left_child;
        std::unique_ptr<Node> right_child;
        Node(const Vertex& vertex = Vertex()) :vertex(vertex), left_child(nullptr), right_child(nullptr) {}
    };
//     void traverse(const std::unique_ptr<Node>& node, int depth) const {
//         if(!node) return;
//         traverse(node->left_child, depth + 1);
//         traverse(node->right_child, depth + 1);
//     };
    void make_tree(std::unique_ptr<Node>& node, std::vector<Vertex>& list, int l, int r, bool parity) {
        if(r < l) return;
//         if(parity)  std::sort(list.begin() + l, list.begin() + r + 1, compare_y);
//         else        std::sort(list.begin() + l, list.begin() + r + 1, compare_x);
        int mid = (l + r) / 2;
        if(parity)  std::nth_element(list.begin() + l, list.begin() + mid, list.begin() + r + 1, compare_y);
        else        std::nth_element(list.begin() + l, list.begin() + mid, list.begin() + r + 1, compare_x);
        node = std::unique_ptr<Node>(new Node(list[mid]));
        make_tree(node->left_child, list, l, mid - 1, !parity);
        make_tree(node->right_child, list, mid + 1, r, !parity);
    }
    bool compare(const Vertex& v1, const Vertex& v2, bool y_first) const {
        return y_first ? v1.y < v2.y : v1.x < v2.x;
    }
    void search(const std::unique_ptr<Node>& node, const Vertex& initial, const Vertex& terminal, bool parity) const {
        if(!node) return;
        if(initial.x <= node->vertex.x && node->vertex.x <= terminal.x && initial.y <= node->vertex.y && node->vertex.y <= terminal.y) {
//             answer.insert(node->vertex.label);
            answer.push_back(node->vertex.label);
        }
        if(!compare(node->vertex, initial, parity)) search(node->left_child, initial, terminal, !parity);
        if(!compare(terminal, node->vertex, parity)) search(node->right_child, initial, terminal, !parity);
    }
    std::unique_ptr<Node> root_;
};

