{

    int n;
    cin >> n;
    vector<XY> xys;
    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        xys.push_back(XY{ x, y, i });
    }

    Node *pkdTree = kdTree(xys, 0, n - 1, 0);

    int q;
    cin >> q;
    for (int i = 0; i < q; i++) {
        int sx, tx, sy, ty;
        cin >> sx >> tx >> sy >> ty;
        vector<int> result;
        search(pkdTree, sx, tx, sy, ty, 0, &result);
        sort(result.begin(), result.end());
        for (auto index : result) {
            cout << index << endl;
        }
        cout << endl;
    }

    freeKdTree(pkdTree);
    return 0;
}

