  for(int i=0;i<q;i++){
    int x1,y1,x2,y2;
    cin >> x1 >> x2 >> y1 >> y2;
    vector<int>res;
    kdtree_search(x1,y1,x2,y2,0,0,res);
    sort(all(res));
    for(int j=0;j<res.size();j++){
      cout << res[j] << endl;
    }
    cout << endl;
  }

  return 0;
}

