	if (a >= b) return;
	if (turn % 2 == 0) sort(V.begin() + a, V.begin() + b, xComp);
	else sort(V.begin() + a, V.begin() + b, yComp);
	int mid = (a + b) / 2;
	node* buf = (node*)malloc(sizeof(node));
	buf->innum = mid;
	buf->left = NIL;
	buf->right = NIL;
	*focus = buf;
	makeT(a, mid, &((*focus)->left), turn + 1);
	makeT(mid + 1, b, &((*focus)->right), turn + 1);
}

