struct point{ int x, y, id; };

point init(int pos_x, int pos_y, int index)
{
    point p; 
    p.x = pos_x, p.y = pos_y, p.id = index; 
    return p; 
}

bool cmp_x(const point &P1, const point &P2){ if(P1.x != P2.x){ return P1.x < P2.x; } return P1.y < P2.y; }
bool cmp_y(const point &P1, const point &P2){ if(P1.y != P2.y){ return P1.y < P2.y; } return P1.x < P2.x; }

typedef struct node{ point mark; node *less, *more; } kd_node;

kd_node* init(point pos, node* l, node* m)
{
    kd_node* node = new kd_node;
    node->mark = pos, node->less = l, node->more = m;
    return node;
}

kd_node* kd_tree(point *S, point *T, point *U, int left, int right, int d)
{
    if(left == right) return NULL;
    if(left + 1 == right){
        kd_node* leaf = new kd_node;
        leaf->less = NULL, leaf->more = NULL;
        if((d & 1) == 0){
            leaf->mark = S[left];
        }else{
            leaf->mark = T[left];
        }
        return leaf;
    }

    kd_node* node = new kd_node;
    int mid = (left + right) / 2;
    int a = left, b = mid;

    if((d & 1) == 0){
        node->mark = S[mid];
        for(int i = left; i < right; i++){  // sort.
            if(cmp_x(T[i], S[mid])){
                U[a] = T[i], a++;
            }else{
                U[b] = T[i], b++;
            }
        }
        for(int i = left; i < right; i++){ T[i] = U[i]; }

    }else{
        node->mark = T[mid];
        for(int i = left; i < right; i++){  // sort.
            if(cmp_y(S[i], T[mid])){
                U[a] = S[i], a++;
            }else{
                U[b] = S[i], b++;
            }
        }
        for(int i = left; i < right; i++){ S[i] = U[i]; }
    }
    node->less = kd_tree(S, T, U, left, mid, d + 1);
    node->more = kd_tree(S, T, U, mid, right, d + 1);

    return node;
}

int cnt;

void find_pt(int *Q, int sx, int tx, int sy, int ty, kd_node* node, int d)
{
    point p = node->mark;
    int a = p.x, b = p.y;

    if(node->less == NULL && node->more == NULL){
        if(sx <= a && a <= tx && sy <= b && b <= ty){
            Q[cnt] = p.id, cnt++;
        }
        return;
    }
    if((d & 1) == 0){
        if(sx <= a){ find_pt(Q, sx, tx, sy, ty, node->less, d + 1); }
        if(a <= tx){ find_pt(Q, sx, tx, sy, ty, node->more, d + 1); }
    }else{
        if(sy <= b){ find_pt(Q, sx, tx, sy, ty, node->less, d + 1); }
        if(b <= ty){ find_pt(Q, sx, tx, sy, ty, node->more, d + 1); }
    }
    return;
}

int main()
{
    point S[50000], T[50000], U[50000];
    int Q[100];
    int i, pos_x, pos_y, n;
    scanf("%d", &n);
    for(i = 0; i < n; i++){
        scanf("%d %d", &pos_x, &pos_y);
        S[i] = init(pos_x, pos_y, i);
        T[i] = S[i];
    }
    sort(S, S + n, cmp_x);
    sort(T, T + n, cmp_y);

    kd_node* root = kd_tree(S, T, U, 0, n, 0);

    int sx, tx, sy, ty, q;
    scanf("%d", &q);
    while(q){
        cnt = 0;
        scanf("%d %d %d %d", &sx, &tx, &sy, &ty);
        find_pt(Q, sx, tx, sy, ty, root, 0);
        sort(Q, Q + cnt);
        for(int i = 0; i < cnt; i++){ printf("%d\n", Q[i]); }
        printf("\n");
        q--;
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
vector<int> val[1048588], id[1048588], ret; int d;
void query(int a, int b, int vl, int vr, int k, int l, int r) {
	if(a <= l && r <= b) {
		int ptl = lower_bound(val[k].begin(), val[k].end(), vl) - val[k].begin();
		int ptr = lower_bound(val[k].begin(), val[k].end(), vr) - val[k].begin();
		for(int i = ptl; i < ptr; i++) ret.push_back(id[k][i]);
		return;
	}
	if(r <= a || b <= l) return;
	query(a, b, vl, vr, k * 2, l, (l + r) >> 1);
	query(a, b, vl, vr, k * 2 + 1, (l + r) >> 1, r);
}
int n, q, x[500009], y[500009], p[500009], tmp[500009], xa, ya, xb, yb;
bool compare(int i, int j) {
	return x[i] < x[j];
}
int main() {
	scanf("%d", &n);
	d = 32 - __builtin_clz(n);
	for(int i = 0; i < n; i++) scanf("%d%d", &x[i], &y[i]), p[i] = i;
	sort(p, p + n, compare);
	vector<int> xs(n), ys(n);
	for(int i = 0; i < n; i++) tmp[i] = x[p[i]];
	for(int i = 0; i < n; i++) x[i] = tmp[i];
	for(int i = 0; i < n; i++) tmp[i] = y[p[i]];
	for(int i = 0; i < n; i++) y[i] = tmp[i];
	for(int i = 0; i < n; i++) {
		val[(1 << d) + i] = vector<int>({ y[i] });
		id[(1 << d) + i] = vector<int>({ p[i] });
	}
	for(int i = (1 << d) - 1; i >= 1; i--) {
		int pl = val[i * 2].size(), pr = val[i * 2 + 1].size();
		val[i].resize(pl + pr);
		id[i].resize(pl + pr);
		int lc = 0, rc = 0;
		while(lc + rc < pl + pr) {
			bool left = true;
			if(lc == pl) left = false;
			else if(rc != pr && val[i * 2][lc] > val[i * 2 + 1][rc]) left = false;
			if(left) {
				val[i][lc + rc] = val[i * 2][lc];
				id[i][lc + rc] = id[i * 2][lc];
				lc++;
			}
			else {
				val[i][lc + rc] = val[i * 2 + 1][rc];
				id[i][lc + rc] = id[i * 2 + 1][rc];
				rc++;
			}
		}
	}
	scanf("%d", &q);
	while(q--) {
		scanf("%d%d%d%d", &xa, &xb, &ya, &yb);
		int ptl = lower_bound(x, x + n, xa) - x;
		int ptr = lower_bound(x, x + n, xb + 1) - x;
		ret.clear();
		query(ptl, ptr, ya, yb + 1, 1, 0, 1 << d);
		sort(ret.begin(), ret.end());
		for(int i : ret) printf("%d\n", i);
		printf("\n");
	}
	return 0;
}

