template<class T_>
class kdtree{
private:
    struct plane{
        i64 idx;
        plane *l;
        plane *r;
    };
    i64 n;
    i64 k;
    i64 *id;
    T_ *c;
    i64 hoge1=0LL;
    plane *s;
    plane *r=nullptr;
    i64 hoge2=0LL;
public:
    void make(i64 N,i64 K){
        n=N;
        k=K;
        id=new i64[n]{};
        for(i64 i=0;i<n;i++) id[i]=i;
        c=new T_[n*k]{};
        s=new plane[n]{};
    }
    void add(T_ *&C){
        for(i64 i=0LL;i<k;i++) c[n*i+hoge1]=C[i];
        hoge1++;
    }
    void calc(void){
        r=calc_inter(0LL,0LL,n);
    }
    vector<i64> search(T_ *&S,T_ *&T){
        vector<i64> lst;
        search_inter(0,r,S,T,lst);
        return lst;
    }
    void refr(void){
        delete[] id;
        delete[] c;
        delete[] s;
    }
private:
    plane *calc_inter(i64 K,i64 L,i64 R){
        if(L>=R) return nullptr;
        nth_element(id+L,id+(L+R)/2,id+R,[=](const i64 &p1,const i64 &p2){return c[n*K+p1]<c[n*K+p2];});
        i64 t=hoge2;
        hoge2++;
        s[t].idx=id[(L+R)/2];
        s[t].l=calc_inter((K+1)%k,L,(L+R)/2);
        s[t].r=calc_inter((K+1)%k,(L+R)/2+1,R);
        return &(s[t]);
    }
    void search_inter(i64 K,plane *R,T_ *&S,T_ *&T,vector<i64> &LST){
        if(R==nullptr) return;
        bool f=1;
        for(i64 i=0;i<k;i++){
            f&=(S[i]<=c[n*i+R->idx]&&c[n*i+R->idx]<=T[i]);
            if(!f) break;
        }
        if(f) LST.emplace_back(R->idx);
        if(S[K]<=c[n*K+R->idx]) search_inter((K+1)%k,R->l,S,T,LST);
        if(c[n*K+R->idx]<=T[K]) search_inter((K+1)%k,R->r,S,T,LST);
    }
};

int main(void){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    i64 n;
    scanf("%lli",&n);
    kdtree<i64> kd;
    kd.make(n,2LL);
    i64 *c=new i64[2]{};
    for(i64 i=0LL;i<n;i++){
        scanf("%lli%lli",&c[0],&c[1]);
        kd.add(c);
    }
    kd.calc();
    i64 q;
    scanf("%lli",&q);
    i64 *s=new i64[2]{},*t=new i64[2]{};
    for(i64 i=0LL;i<q;i++){
        scanf("%lli%lli%lli%lli",&s[0],&t[0],&s[1],&t[1]);
        vector<i64> lst=kd.search(s,t);
        sort(lst.begin(),lst.end());
        for(const i64 &i:lst) printf("%lli\n",i);
        printf("\n");
    }
    return 0;
}

#include <iostream>
#define MAX_DOTS_NUM    500000      /* 設定可能な点の最大数 */
#define MAX_QUERY_NUM   20000       /* 要求可能なクエリの最大数 */
#define MAX_POSIRION    1000000000  /* 2次元平面の最大値 */
#define MIN_POSIRION    -1000000000 /* 2次元平面の最小値 */

int main(void){

    int  dotsNum = 0;                       /* 点の数 */
    long dotsPositionX[MAX_DOTS_NUM] = {0}; /* 点のx座標 */
    long dotsPositionY[MAX_DOTS_NUM] = {0}; /* 点のy座標 */

    std::cin >> dotsNum;
    if((dotsNum > MAX_DOTS_NUM)||(dotsNum<0))
    {
        return 0;   /* エラーケース：設定可能な点の最大数を超えたか、負の値が入力された */
    }
    for(int index=0; index<dotsNum; ++index)
    {
        std::cin >> dotsPositionX[index] >> dotsPositionY[index];
        if( (dotsPositionX[index] > MAX_POSIRION) || (dotsPositionX[index] < MIN_POSIRION)
         || (dotsPositionY[index] > MAX_POSIRION) || (dotsPositionY[index] < MIN_POSIRION) )
        {
            return 0;  /* エラーケース：二次元平面範囲外の点が設定された */
        }
    }

    int  queryNum = 0;                      /* クエリ数 */

    std::cin >> queryNum;
    if((queryNum > MAX_QUERY_NUM)||(queryNum<0))
    {
        return 0;   /* エラーケース：設定可能なクエリの最大数を超えたか、負の値が入力された */
    }

    long bottomOfPositionX  = 0;    /* x座標の最小値 */
    long topOfPositionX     = 0;    /* x座標の最大値 */
    long bottomOfPositionY  = 0;    /* x座標の最小値 */
    long topOfPositionY     = 0;    /* y座標の最大値 */

    /* 各クエリごとに対応する点を出力 */
    for(int index=0; index<queryNum; ++index)
    {

        std::cin >> bottomOfPositionX >> topOfPositionX >> bottomOfPositionY >> topOfPositionY;

        /* エラーチェック */
        if( (bottomOfPositionX > MAX_POSIRION) || (bottomOfPositionX < MIN_POSIRION)        /* 二次元平面範囲外のクエリが設定された */
         || (topOfPositionX > MAX_POSIRION)    || (topOfPositionX < MIN_POSIRION)
         || (bottomOfPositionY > MAX_POSIRION) || (bottomOfPositionY < MIN_POSIRION)
         || (topOfPositionY > MAX_POSIRION)    || (topOfPositionY < MIN_POSIRION)
         || (bottomOfPositionX > topOfPositionX) || (bottomOfPositionY > topOfPositionY) )  /* 大小関係が逆 */
        {
            return 0;  /* エラーケース：二次元平面範囲外のクエリが設定されたか、大小関係が逆 */
        }

        /* 範囲内の点を表示 */
        for(int index=0; index<dotsNum; ++index)
        {
            if( (dotsPositionX[index] >= bottomOfPositionX) && (dotsPositionX[index] <= topOfPositionX)
             && (dotsPositionY[index] >= bottomOfPositionY) && (dotsPositionY[index] <= topOfPositionY) )
            {
                std::cout << index << std::endl;
            }
        }
        /* クエリ1個分の出力が終わったら1行空ける */
        std::cout << std::endl;
    }
    return 0;
}

