  struct Node{
    int idx, axis;
    Node *LN, *RN;
  };
  Node* p;
  vector<Point> pl;
  vector<int> idxs;
  Node* _build(const int il, const int ir, const int d){
    if(ir <= il) return nullptr;
    int m = (il+ir)/2;
    nth_element(idxs.begin()+il, idxs.begin()+m, idxs.begin()+ir, [&](int l, int r){return pl[l][d] < pl[r][d];});
    Node* node = new Node();
    node->idx = idxs[m];
    node->axis = d;
    node->LN = _build(il, m, (d+1)%D);
    node->RN = _build(m+1, ir, (d+1)%D);
    return node;
  }
  void build(vector<Point> &v){
    pl = v;
    D = sz(v[0]);
    FOR(i, 0, sz(pl)) idxs.pb(i);
    p = _build(0, sz(pl), 0);
  }
  void _query(const Node *node, const Point &L, const Point &R, vector<int> &v){
    if (node == nullptr) return;
    int idx = node->idx, axis = node->axis;
    FOR(i, 0, D) if(pl[idx][i] < L[i] || R[i] < pl[idx][i]) goto no;
    v.pb(idx);
no: ;
    if(L[axis] <= pl[idx][axis]) _query(node->LN, L, R, v);
    if(pl[idx][axis] <= R[axis]) _query(node->RN, L, R, v);
  }
  void query(const Point &L, const Point &R, vector<int> &v){
    _query(p, L, R, v);
  }
} kdt;
