	Point(int n = -1, int m = 0, int l = 0):id(n), x(m), y(l){};
	int get_x() const {return x;}
	int get_y() const {return y;}
	int get(bool flag) const {if (flag){return get_x();}else{return get_y();};}
	int get_id() const {return id;}
private:
	int id;
	int x, y;
};
void sort(std::vector<Point> &array, bool flag, int left, int right){
	if (right > left){
		int mid = left + (right - left) / 2;
		int pivot = array.at(mid).get(flag);
		int l = left; int r = right;
		while (r > l){
			while (array.at(l).get(flag) < pivot)++l;
			while (array.at(r).get(flag) > pivot)--r;
			if (r > l){
				Point temp = array.at(l);
				array.at(l) = array.at(r);
				array.at(r) = temp;
				++l; --r;
			}
		}
		sort(array, flag, left, --l); sort(array, flag, ++r, right);
	}
}
void sort(std::vector<int> &array, int left, int right){
	if (right > left){
		int mid = left + (right - left) / 2;
		int pivot = array.at(mid);
		int l = left; int r = right;
		while (r > l){
			while (array.at(l) < pivot)++l;
			while (array.at(r) > pivot)--r;
			if (r > l){
				int temp = array.at(l);
				array.at(l) = array.at(r);
				array.at(r) = temp;
				++l; --r;
			}
		}
		sort(array, left, --l); sort(array, ++r, right);
	}
}
template <class T>
void make_kDtree(std::vector<T> &array, bool flag, int left, int right){
	if (right > left){
		sort(array, flag, left, right);
		int mid = left + (right - left) / 2;
		make_kDtree(array, !flag, left, mid);make_kDtree(array, !flag, mid + 1, right);
	}
}
void search_point(std::vector<Point> &array, bool flag, int left, int right, const Point &max, const Point &min, std::vector<int> &result){
	if (right >= left){
		int mid = left + (right - left) / 2;
		if (max.get(flag) >= array.at(mid).get(flag) and array.at(mid).get(flag) >= min.get(flag)){
      if (max.get(!flag) >= array.at(mid).get(!flag) and array.at(mid).get(!flag) >= min.get(!flag)){
			   result.push_back(array.at(mid).get_id());
       }
			search_point(array, !flag, left, mid - 1, max, min, result); search_point(array, !flag, mid + 1, right, max, min, result);
		}else if (array.at(mid).get(flag) > max.get(flag)){
			search_point(array, !flag, left, mid - 1, max, min, result);
		}else{
			search_point(array, !flag, mid + 1, right, max, min, result);
		}
	}
}
int main(){
	std::vector<Point> array;
	int n;
	std::scanf("%d", &n);
	for (auto i = 0; i < n; ++i){
		int x, y;
		std::scanf("%d %d", &x, &y);
		array.push_back(Point(i, x, y));
	}
	make_kDtree(array, true, 0, array.size() - 1);
	int q;
	std::scanf("%d", &q);
	for (auto i = 0; i < q; ++i){
		int xmin, xmax, ymin, ymax;
		std::scanf("%d %d %d %d", &xmin, &xmax, &ymin, &ymax);
		std::vector<int> result;
		Point max(-1, xmax, ymax);
		Point min(-1, xmin, ymin);
		search_point(array, true, 0, array.size() - 1, max, min, result);
		sort(result, 0, result.size() - 1);
		for (auto j : result){
			std::printf("%d\n", j);
		}
		std::printf("\n");
	}
}

