#define GENERIC(f) ([](auto&&... args) -> decltype(auto) { return (f)(forward<decltype(args)>(args)...); })

template<typename BF, typename UF>
auto ON(BF bf, UF uf) {
    return [bf,uf](const auto& x, const auto& y) {
        return bf(uf(x), uf(y));
    };
}

struct Point {
    i64 id;
    i64 x;
    i64 y;
};

ostream& operator<<(ostream& out, const Point& p) {
    return out << p.id;
}

struct XYTree {
    static constexpr i64 NIL = -1;

    struct Node {
        Point p;
        i64 l;
        i64 r;
    };

    vector<Node> nodes_;
    i64 root_;

    explicit XYTree(vector<Point>& ps) {
        nodes_.reserve(ps.size());
        root_ = init(begin(ps), end(ps), 0);
    }

    template<typename RandomIt>
    i64 init(RandomIt first, RandomIt last, i64 depth) {
        if(first >= last) return NIL;

        auto f = [depth](const Point& p) {
            return is_even(depth) ? p.x : p.y;
        };
        sort(first, last, ON(less<>(),f));

        auto mid = first + (last-first)/2;  // mid < last が成立
        i64 l = init(first, mid, depth+1);
        i64 r = init(mid+1, last, depth+1);
        nodes_.emplace_back(Node { *mid, l, r });
        return nodes_.size() - 1;
    }

    vector<Point> find(i64 sx, i64 tx, i64 sy, i64 ty) {
        vector<Point> res;
        search(res, root_, sx, tx, sy, ty, 0);
        return res;
    }

    void search(vector<Point>& res, i64 v, i64 sx, i64 tx, i64 sy, i64 ty, i64 depth) {
        const Node& node = nodes_[v];
        i64 x = node.p.x;
        i64 y = node.p.y;

        if(sx <= x && x <= tx && sy <= y && y <= ty)
            res.emplace_back(node.p);

        if(is_even(depth)) {
            if(node.l != NIL && sx <= x) search(res, node.l, sx, tx, sy, ty, depth+1);
            if(node.r != NIL && x <= tx) search(res, node.r, sx, tx, sy, ty, depth+1);
        }
        else {
            if(node.l != NIL && sy <= y) search(res, node.l, sx, tx, sy, ty, depth+1);
            if(node.r != NIL && y <= ty) search(res, node.r, sx, tx, sy, ty, depth+1);
        }
    }
};

i64 N;
vector<Point> PS;

void solve() {
    XYTree tree(PS);

    i64 Q; RD(Q);
    REP(_, Q) {
        i64 sx,tx; RD(sx); RD(tx);
        i64 sy,ty; RD(sy); RD(ty);
        vector<Point> ans = tree.find(sx,tx,sy,ty);
        ALL(sort, ans, ON(less<>(), [](const Point& p) { return p.id; }));
        ALL(for_each, ans, GENERIC(PRINTLN));
        PRINTLN();
    }
}

signed main() {
    RD(N);
    PS.reserve(N);

    REP(i, N) {
        i64 x,y; RD(x); RD(y);
        PS.emplace_back(Point { i, x, y });
    }

    solve();

    return 0;
}

#include <bits/stdc++.h>
