    if (T[v].r != NIL)
        r = P[T[v].r];
    else
        r = Point(INT_MAX, INT_MAX, INT_MAX);

    if (d % 2 == 0) {
        if (T[v].l != NIL && sx <= l.x)
            find(T[v].l, sx, tx, sy, ty, d + 1, ans);
        if (T[v].r != NIL && r.x <= tx)
            find(T[v].r, sx, tx, sy, ty, d + 1, ans);
    } else {
        if (T[v].l != NIL && sy <= l.y)
            find(T[v].l, sx, tx, sy, ty, d + 1, ans);
        if (T[v].r != NIL && r.y <= ty)
            find(T[v].r, sx, tx, sy, ty, d + 1, ans);
    }
}


