        nodes[i].IOid = i;
    }
    int root = buildTree(0, n, 0);//构建二叉树
    //test();
    scanf("%d", &q);
    while (q--) {
        scanf("%d%d%d%d", &xMin, &xMax, &yMin, &yMax);
        findNodes(root, xMin, xMax, yMin, yMax, 0);//从二叉树的根节点执行查询
        sort(result.begin(), result.end());//对结果集进行排序
        int length = result.size();
        for(int i=0;i<length;i++){
            printf("%d\n", result[i]);
        }
