struct data{
  int y,id;
  bool operator < (const data &p)const{
    return (y==p.y?id<p.id:y<p.y);
  }
};

int n;
int px[MAX_N],py[MAX_N];
int ax[MAX_Q],ay[MAX_Q];
int bx[MAX_Q],by[MAX_Q];

set<data> t[MAX_L+1];

void Set(int x,int y,int id){

  while(x<=MAX_L){
    t[x].insert((data){y,id});
    x+=x&-x;
  }
}

set<int> ans;
void find(int bx,int ay,int by,bool f){

  while(bx>0){
    set<data> :: iterator it = t[bx].lower_bound((data){ay,-1});
    set<int> :: iterator it2;
    while(it!=t[bx].end() && it->y <=by){
      if(f){
	ans.insert(it->id);
      }else{
	it2=ans.find(it->id);
	if(it2!=ans.end())ans.erase(it2);
      }
      it++;
    }
    bx -= bx & -bx;
  }
}


int tx[MAX_L];
int ux[MAX_L];
int size=0;

int main(){
  scanf("%d",&n);
  for(int i=0;i<n;i++)scanf("%d %d",&px[i],&py[i]);

  int q;
  scanf("%d",&q);
  for(int i=0;i<q;i++){
    scanf("%d %d %d %d",&ax[i],&bx[i],&ay[i],&by[i]);
    ax[i]--;
    tx[size++]=ax[i];
    tx[size++]=bx[i];
  }
  tx[size++]=1e9+1;
  sort(tx,tx+size);
  ux[0]=1;
  for(int i=1;i<size;i++){
    if(tx[i]==tx[i-1])ux[i]=ux[i-1];
    else ux[i]=ux[i-1]+1;
  }

  for(int i=0;i<n;i++){
    px[i]=ux[ lower_bound(tx,tx+size,px[i])-tx ];
    Set(px[i],py[i],i);
  }

  for(int i=0;i<q;i++){
    ans.clear();
    find( ux[ lower_bound(tx,tx+size,bx[i])-tx ]    ,ay[i],by[i],1);
