template<typename T> struct SegmentTree {
  size_t n;
  vector<vector<T>> data;

  SegmentTree(size_t n_, vector<T> v) {
    n = 1;
    while(n < n_) n *= 2;
    data.resize(2 * n - 1);
    build(v);
  }
  void build(vector<T> v) {
    for (int i = 0; i < v.size(); ++i) data[i + n - 1].push_back(v[i]);
    for (int i = n - 2; i >= 0; --i) {
      int lch = i * 2 + 1;
      int rch = i * 2 + 2;
      data[i].resize(data[lch].size() + data[rch].size());
      merge(begin(data[lch]), end(data[lch]), begin(data[rch]), end(data[rch]),
          begin(data[i]));
    }
  }
  void query(int a, int b, int x0, int x1, vector<int>& res, int k = 0, int l = 0, int r = -1) {
    if (r < 0) r = n;
    if (b <= l || r <= a) return;
    if (a <= l && r <= b) {
      auto lb = lower_bound(begin(data[k]), end(data[k]), P{x0, -1});
      auto ub = upper_bound(begin(data[k]), end(data[k]), P{x1, n});
      for (auto itr = lb; itr != ub; ++itr) {
        res.push_back(itr->second);
      }
      return;
    }
    query(a, b, x0, x1, res, k * 2 + 1, l, (l + r) / 2);
    query(a, b, x0, x1, res, k * 2 + 2, (l + r) / 2, r);
  }
};

int main() {
  int n; scanf("%d", &n);

  vector<int> xs(n);
  vector<P> ys(n);
  vector<pair<int, P>> ps(n);
  for (int i = 0; i < n; ++i) {
    int x, y; scanf("%d%d", &x, &y);
    ps[i] = {x, {y, i}};
  }
  sort(begin(ps), end(ps));
  for (int i = 0; i < n; ++i) tie(xs[i], ys[i]) = ps[i];

  SegmentTree<P> seg(n, ys);
  int q; cin >> q;
  while (q--) {
    vector<int> ans;
    int sx, tx, sy, ty; scanf("%d%d%d%d", &sx, &tx, &sy, &ty);
    int l = lower_bound(begin(xs), end(xs), sx) - begin(xs);
    int r = upper_bound(begin(xs), end(xs), tx) - begin(xs);
    seg.query(l, r, sy, ty, ans);
    sort(begin(ans), end(ans));
    for (auto&& x : ans) printf("%d\n", x);
    printf("\n");
  }
  return 0;
}

