node *kdTree::insert(node *t,int d, int x, int y, int n)
{
	if (t == NULL) return new node(x, y, n);
	if (!d)
	{
		if (x < t->mx)
			t->left = insert(t->left, !d, x, y, n);
		else
			t->right = insert(t->right, !d, x, y, n);
	}
	else
	{
		if (y < t->my)
			t->left = insert(t->left, !d, x, y, n);
		else
			t->right = insert(t->right, !d, x, y, n);
	}
	return t;
}

void kdTree::query(int sx, int tx, int sy, int ty)
 {
	 query(root, 0, sx, tx, sy, ty);
 }

void kdTree::query(node *t, int d, int sx, int tx, int sy, int ty)
{
	 if (t == NULL) return;
	 if (sx <= t->mx && t->mx <= tx && sy <= t->my && t->my <= ty)
		 vout.push_back(t->no);
	 if (!d)
	 {
		 if (!(sx > t->mx))
			 query(t->left, !d, sx, tx, sy, ty);
		 if (!(tx < t->mx))
			 query(t->right, !d, sx, tx, sy, ty);
	 }
	 else
	 {
		 if (!(sy > t->my))
			 query(t->left, !d, sx, tx, sy, ty);
		 if (!(ty < t->my))
			 query(t->right, !d, sx, tx, sy, ty);
	 }
}

