};
class Point {
public:
	int x, y;
	int id;
	Point(int x, int y, int id) :id(id), x(x), y(y) {};
	Point() {};
};
bool lessX(Point& a, Point& b) {
	return a.x < b.x;
}
bool lessY(Point& a, Point& b) {
	return a.y < b.y;
}
bool lessID(Point& a, Point& b) {
	return a.id < b.id;
}
static int NIL = -1;
const int MAX = 1000000;
Point p[MAX];
Tree t[MAX];
int sit = 0;
int n;
int makeTree(int left, int right, int depth) {
	if ( !(left < right)) {
		return NIL;
	}
	if (depth % 2 == 1 ) {
		sort(p + left, p + right, lessX);
	}
	else {
		sort(p + left, p + right, lessY);
	}
	int midle = (left + right) / 2;
	int k = sit;
	sit++;
	t[k].position = midle;
	t[k].left = makeTree(left, midle,depth+1);
	t[k].right = makeTree(midle + 1, right,depth+1);
	return k;
} 
void find(int k, int sx, int tx, int sy, int ty, int depth,vector<Point>&v) {
	int x = p[t[k].position].x;
	int y = p[t[k].position].y;
	if (x <= tx && sx <= x && y <= ty && sy <= y) {
		v.push_back(p[t[k].position]);
	}
	if (depth % 2 == 1) {
		if (t[k].left != NIL && x >= sx)  find(t[k].left, sx, tx, sy, ty, depth+1, v);
		if(t[k].right != NIL && x <= tx)  find(t[k].right, sx, tx, sy, ty, depth+1, v);
	}
	else {
		if (t[k].left != NIL && y >= sy)  find(t[k].left, sx, tx, sy, ty, depth+1, v);
		if (t[k].right != NIL && y <= ty)  find(t[k].right, sx, tx, sy, ty, depth+1, v);
	}
}
