struct KDtree {
	struct Node {
		int index, l, r;
		Node() :index(NIL), l(NIL), r(NIL) {}
	};
	int n, np, root; vector<Point>points; vector<Node>nodes;
	KDtree(const vector<Point> &ps) :n(ps.size()), np(0), points(ps), nodes(n) {
		root = makeKDtree(0, n, true);
	}
	int makeKDtree(int l, int r, bool is_x_base = true) {
		if (!(l < r))return NIL;
		int t = np++, mid = (l + r) / 2;
		vector<Point>::iterator first = points.begin()+l,
			nth = points.begin() + mid, last = points.begin() + r;
		if (is_x_base)nth_element(first, nth, last, lessX);
		else nth_element(first, nth, last, lessY);
		nodes[t].index = mid;
		nodes[t].l = makeKDtree(l, mid, !is_x_base);
		nodes[t].r = makeKDtree(mid + 1, r, !is_x_base);
		return t;
	}
	vector<Point>ret;
	bool inrange(Point &p, Point &s, Point &t) {
		return (s.x <= p.x&&p.x <= t.x) && (s.y <= p.y&&p.y <= t.y);
	}
	vector<Point> find(Point s, Point t) {
		ret.clear();
		return find(root, s, t, true);
	}
	vector<Point> find(int v, Point s, Point t, bool is_x_base = true) {
		auto p = points[nodes[v].index];
		if (inrange(p, s, t))ret.emplace_back(p);
		if (is_x_base) {
			if (nodes[v].l != NIL && s.x <= p.x)find(nodes[v].l, s, t, !is_x_base);
			if (nodes[v].r != NIL && p.x <= t.x)find(nodes[v].r, s, t, !is_x_base);
		}
		else {
			if (nodes[v].l != NIL && s.y <= p.y)find(nodes[v].l, s, t, !is_x_base);
			if (nodes[v].r != NIL && p.y <= t.y)find(nodes[v].r, s, t, !is_x_base);
		}
		return ret;
	}
};
