		sort(P + l, P + r, lessX);
	} else {
		sort(P + l, P + r, lessY);
	}
	int mid = (l + r) / 2;
	int t = np++;
	T[t].location = mid;
	T[t].l = makeKdTree(l, mid, depth + 1);
	T[t].r = makeKdTree(mid + 1, r, depth + 1);

	return t;
}

