using namespace std;

enum VAL{ODD, EVEN};
struct Pos{
    int x;
    int y;
    int order;
};
bool asc_x(const Pos& l, const Pos& r) {
    return l.x < r.x;
}
bool asc_y(const Pos& l, const Pos& r) {
    return l.y < r.y;
}

struct Node{
    int x;
    int y;
    int order;
    Node* left;
    Node* right;
};

class Tree{
    Node* root;
    Node* makeTree(vector<Pos>& A, int l, int r, VAL V){
        if (l > r) return nullptr;
        if (V == ODD) {
            sort(A.begin() + l, A.begin() + r + 1, asc_y);
            V = EVEN;
        } else {
            sort(A.begin() + l, A.begin() + r + 1, asc_x);
            V = ODD;
        }
        int mid = (l + r) / 2;
        Node* p = new Node;
        p->x     = A[mid].x;
        p->y     = A[mid].y;
        p->order = A[mid].order;
        p->left  = makeTree(A,       l, mid - 1, V);
        p->right = makeTree(A, mid + 1,       r, V);
        return p;
    }
    void find_(Node* n, int sx, int tx, int sy, int ty, VAL V, vector<int>& ans){
        if (n == nullptr) return;
        int n_, s, t;
        if (V == ODD) {
            n_ = n->y;
            s  = sy;
            t  = ty;
            V = EVEN;
        } else {
            n_ = n->x;
            s  = sx;
            t  = tx;
            V = ODD;
        }
        if (n_ >= s) find_(n->left, sx, tx, sy, ty, V, ans);
        if (n->x >= sx && n->x <= tx && n->y >= sy && n->y <= ty) {
            ans.push_back(n->order);
        }
        if (n_ <= t) find_(n->right, sx, tx, sy, ty, V, ans);
    }
public:
    Tree(vector<Pos>& A){
        root = makeTree(A, 0, A.size() - 1, ODD);
    }
    void find(int sx, int tx, int sy, int ty){
        vector<int> ans;
        find_(root, sx, tx, sy, ty, ODD, ans);
        sort(ans.begin(), ans.end());
        for (int i = 0, s = ans.size(); i < s; i++) {
            printf("%d\n", ans[i]);
        }
        printf("\n");
    }
};

