void InitRange(int k, int l, int r) {
  if(l + 1 >= r) {
    return;
  } else {
    InitRange(2 * k + 1, l, (l + r) >> 1);
    InitRange(2 * k + 2, (l + r) >> 1, r);
    seg[k].resize(seg[2 * k + 1].size() + seg[2 * k + 2].size());
    merge(seg[2 * k + 1].begin(), seg[2 * k + 1].end(), seg[2 * k + 2].begin(), seg[2 * k + 2].end(), seg[k].begin());
  }
}

vector< int >* PrintRange(int a, int b, int low, int high, int k, int l, int r) {
  itr[k].clear();
  if(a >= r || b <= l) {
    return(&itr[k]);
  } else if(a <= l && r <= b) {
    itr[k].clear();
    for(vector< Pi >::iterator it = lower_bound(seg[k].begin(), seg[k].end(), Pi(low, -1)); it != seg[k].end() && it -> first <= high; it++) { 
      itr[k].push_back(it -> second);
    }
    sort(itr[k].begin(), itr[k].end());
    return(&itr[k]);
  } else {
    vector< int >* ret1 = PrintRange(a, b, low, high, 2 * k + 1, l, (l + r) >> 1);
    vector< int >* ret2 = PrintRange(a, b, low, high, 2 * k + 2, (l + r) >> 1, r);
    itr[k].resize(ret1 -> size() + ret2 -> size());
    merge(ret1 -> begin(), ret1 -> end(), ret2 -> begin(), ret2 -> end(), itr[k].begin());
    return(&itr[k]);
  }
}

