    Node() {}
    Node(int _p, int _l, int _r) : p(_p), l(_l), r(_r) {}
    Node(const Node& n) : p(n.p), l(n.l), r(n.r) {}
};

struct Point {
    int id, x, y;
    Point() {}
    Point(int _id, int _x, int _y) : id(_id), x(_x), y(_y) {}
    Point(const Point& p) : id(p.id), x(p.x), y(p.y) {}
    bool operator<(const Point& p) const { return id < p.id; }
};

bool less_id(const Point& l, const Point& r) { return l.id < r.id; };
bool less_x(const Point& l, const Point& r) { return l.x < r.x; };
bool less_y(const Point& l, const Point& r) { return l.y < r.y; };

class KdTree {
private:
    vector<Point> points;
    vector<Node> nodes;
    int n;

public:
    KdTree() : points(), nodes(), n(0) {}
    KdTree(const vector<Point>& points) : points(points), nodes(points.size()), n(0) { make_tree(0, points.size(), 0); }

    int make_tree(int l, int r, int depth) {
        if (!(l < r)) { return -1; }

        int mid = (l + r) / 2;
        int t = n++;

        if (depth % 2 == 0) {
            sort(next(points.begin(), l), next(points.begin(), r), less_x);
        } else {
            sort(next(points.begin(), l), next(points.begin(), r), less_y);
        }

        nodes[t].location = mid;
        nodes[t].l = make_tree(l, mid, depth + 1);
        nodes[t].r = make_tree(mid + 1, r, depth + 1);

        return t;
    }

    void find(int v, int sx, int tx, int sy, int ty, int depth, vector<Point>& ans) {
        int x = points[nodes[v].location].x;
        int y = points[nodes[v].location].y;

        if (sx <= x && x <= tx && sy <= y && y <= ty) { ans.push_back(points[nodes[v].location]); }
        if (depth % 2 == 0) {
            if (nodes[v].l != -1 && sx <= x) { find(nodes[v].l, sx, tx, sy, ty, depth + 1, ans); }
            if (nodes[v].r != -1 && x <= tx) { find(nodes[v].r, sx, tx, sy, ty, depth + 1, ans); }
        } else {
            if (nodes[v].l != -1 && sy <= y) { find(nodes[v].l, sx, tx, sy, ty, depth + 1, ans); }
            if (nodes[v].r != -1 && y <= ty) { find(nodes[v].r, sx, tx, sy, ty, depth + 1, ans); }
        }
    }
};

void print(vector<Point>& ans) {
    sort(ans.begin(), ans.end());
    for (auto p : ans) { printf("%d\n", p.id); }
    printf("\n");
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n;
    scanf("%d", &n);

    vector<Point> points(n);
    rep(i, 0, n) {
        points[i].id = i;
        scanf("%d %d", &(points[i].x), &(points[i].y));
    }

    KdTree tree(points);
    int q;
    scanf("%d", &q);
    rep(i, 0, q) {
        int sx, tx, sy, ty;
        scanf("%d %d %d %d", &sx, &tx, &sy, &ty);
        vector<Point> ans;
        tree.find(0, sx, tx, sy, ty, 0, ans);
        print(ans);
    }

    return 0;
}

