using namespace std;
using lint = long long int;
template<class T = int> using V = vector<T>;
template<class T = int> using VV = V< V<T> >;
template<class T> void assign(V<T>& v, int n, const T& a = T()) { v.assign(n, a); }
template<class T, class... Args> void assign(V<T>& v, int n, const Args&... args) { v.resize(n); for (auto&& e : v) assign(e, args...); }


struct P { int id, x, y; };
auto comp_id = [](const P& lhs, const P& rhs) { return lhs.id < rhs.id; };
auto comp_x = [](const P& lhs, const P& rhs) { return lhs.x < rhs.x; };
auto comp_y = [](const P& lhs, const P& rhs) { return lhs.y < rhs.y; };

struct Monoid {
  using T = V<P>;
  static T op(const T& lhs, const T& rhs) {
    T res;
    merge(begin(lhs), end(lhs), begin(rhs), end(rhs), back_inserter(res), comp_y);
    return move(res);
  }
  static T e() { return T(); }
};

template<class Monoid> struct SegmentTree {
  using T = typename Monoid::T;

  const int n;
  V<T> val;

  SegmentTree(int n) : n(n), val(2 * n, Monoid::e()) {}
  template<class Itr> SegmentTree(Itr first, Itr last) : n(distance(first, last)), val(2 * n, Monoid::e()) {
    copy(first, last, next(begin(val), n));
    build();
  }

  T& at(int i) { return val[i + n]; }

  void build() {
    for (int i = n - 1; i > 0; --i) val[i] = Monoid::op(val[2 * i], val[2 * i + 1]);
  }

  T get(int l, int r) const {
    T resl = Monoid::e(), resr = Monoid::e();
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) { 
      if (l & 1) resl = Monoid::op(resl, val[l++]); 
      if (r & 1) resr = Monoid::op(val[--r], resr);
    }
    return Monoid::op(resl, resr);
  }

  void set(int i, const T& a) {
    for (val[i += n] = a, i >>= 1; i > 0; i >>= 1) val[i] = Monoid::op(val[2 * i], val[2 * i + 1]);
  }
};

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);
  int n; cin >> n;
  V<P> ps(n);
  V<> xs(n);
  for (int i = 0; i < n; ++i) {
    int x, y; cin >> x >> y;
    ps[i] = {i, x, y};
    xs[i] = x;
  }
  sort(begin(xs), end(xs));
  xs.erase(unique(begin(xs), end(xs)), end(xs));
  for (int i = 0; i < n; ++i) ps[i].x = distance(begin(xs), lower_bound(begin(xs), end(xs), ps[i].x));
  VV<P> init(xs.size());
  for (int i = 0; i < n; ++i) init[ps[i].x].push_back(ps[i]);
  for (auto&& v : init) sort(begin(v), end(v), comp_y);
  SegmentTree<Monoid> st(begin(init), end(init));
  int q; cin >> q;
  for (int i = 0; i < q; ++i) {
    int xl, xr, yl, yr; cin >> xl >> xr >> yl >> yr, ++xr, ++yr;
    xl = distance(begin(xs), lower_bound(begin(xs), end(xs), xl));
    xr = distance(begin(xs), lower_bound(begin(xs), end(xs), xr));
    auto res = st.get(xl, xr);
    auto first = lower_bound(begin(res), end(res), P{-1, 0, yl}, comp_y);
    auto last = lower_bound(begin(res), end(res), P{-1, 0, yr}, comp_y);
    sort(first, last, comp_id);
    while (first != last) {
      cout << first->id << '\n';
      ++first;
    }
    cout << '\n';
  }
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;
class Point {
public:
    Point(){};
    Point(int i, int x, int y) : id {i}, x {x}, y {y} {};
    int id;
    int x;
    int y;
};

class TwoDTree {
public:
    TwoDTree(){};
    TwoDTree(Point* p, TwoDTree* l, TwoDTree* r) : root {p}, left {l}, right {r} {};
    TwoDTree(vector<Point>& ps) {
        auto tree = const2DTree(ps.begin(), ps.end(), 0);
        root = tree->root;
        left = tree->left;
        right = tree->right;
    };
    typedef vector<Point>::iterator pIter;

    TwoDTree* const2DTree(pIter a, pIter b, int d){
        if(a >= b){
            return nullptr;
        }
        if(d%2){
            sort(a, b, [](Point p, Point q){ return p.y < q.y; });
        } else {
            sort(a, b, [](Point p, Point q){ return p.x < q.x; });
        }
        pIter mid = a + (b-a)/2;
        auto l = const2DTree(a, mid, d+1);
        auto r = const2DTree(mid+1, b, d+1);
        return new TwoDTree(&(*mid), l, r);
    };
    vector<Point> find(int x1, int x2, int y1, int y2){
        auto ps = new vector<Point>();
        find(x1, x2, y1, y2, 0, *ps);
        return *ps;
    };
    Point* root;
    TwoDTree* left;
    TwoDTree* right;
private:
    void find(int x1, int x2, int y1, int y2, int d, vector<Point>& vec){
        if(!root){
            return;
        }
        int rx = root->x;
        int ry = root->y;
        if(x1 <= rx && rx <= x2 && y1 <= ry && ry <= y2){
            vec.push_back(*root);
        }

        if(left){
            if(d%2 == 0 && rx >= x1){
                left->find(x1, x2, y1, y2, d+1, vec);
            } else if(d%2 == 1 && ry >= y1){
                left->find(x1, x2, y1, y2, d+1, vec);
            }
        }
        if(right){
            if(d%2 == 0 && rx <= x2){
                right->find(x1, x2, y1, y2, d+1, vec);
            } else if(d%2 == 1 && ry <= y2){
                right->find(x1, x2, y1, y2, d+1, vec);
            }
        }
    }
};

int main(){
    ios_base::sync_with_stdio(false);
    int n;
    cin >> n;
    auto ps = vector<Point>();
    int x, y;
    for(int i = 0; i < n; ++i){
        cin >> x >> y;
        ps.push_back(Point(i, x, y));
    }
    auto kdTree = TwoDTree(ps);
    int q;
    cin >> q;
    int sx, tx, sy, ty;
    for(int i = 0; i < q; ++i){
