#include<vector>
using namespace std;

enum Collision {
	INSIDE,
	OUTSIDE,
	CROSS
};

const int  MAX_POINT = 5;

struct Point {
	Point():x(-1),y(-1),id(-1) {};
	Point(long long x, long long y) :x(x), y(y) {};
	bool operator == (const Point& p)const {
		return x == p.x && y == p.y;
	}
	long long x;
	long long y;
	int id;
};

struct Rect {
	Rect() :t(0), l(0), b(0), r(0) {};
	Rect(long long t, long long l, long long b, long long r) :t(t), l(l), b(b), r(r) {};
	long long t;
	long long l;
	long long b;
	long long r;
};

class Block {
public:
	Block(Rect rect) {
		this->rect = rect;
		for (int i = 0; i < 4; i++) {
			child[i] = NULL;
		}
	}

	void insert(Point p) {
		if (child[0] != NULL) {
			insertChild(p);
		}
		else if (points.size() >= MAX_POINT) {
			long long wid = (rect.b - rect.t) / 2;
			Point pos[4] = {
				{rect.l,rect.t},
				{rect.l + wid,rect.t},
				{rect.l,rect.t + wid},
				{rect.l + wid,rect.t + wid}
			};

			for (int i = 0; i < 4; i++) {
				Rect r(pos[i].y, pos[i].x, pos[i].y + wid, pos[i].x + wid);
				child[i] = new Block(r);
			}

			for (int i = 0; i < points.size(); i++) {
				insertChild(points[i]);
			}
			insertChild(p);
		}
		points.push_back(p);

	}

	void insertChild(Point p) {
		for (int i = 0; i < 4; i++) {
			if (child[i]->insidePoint(p)) {
				child[i]->insert(p);
				return;
			}
		}
	}

	void pointCheck(const Rect& r, set<int>& s) {
		switch (collision(r)) {

		case INSIDE:
			for (int i = 0; i < points.size(); i++) {
				s.insert(points[i].id);
			}
			break;

		case OUTSIDE:
			break;

		case CROSS:
			if (child[0] != NULL) {
				for (int i = 0; i < 4; i++) {
					child[i]->pointCheck(r,s);
				}
			}
			else {
				for (int i = 0; i < points.size(); i++) {
					if (insideRect(r, points[i])) {
						s.insert(points[i].id);
					}
				}
			}
			break;
		}
	}

	bool insideRect(const Rect& r, const Point& p) {
		if (r.t <= p.y && r.b >= p.y && r.l <= p.x && r.r >= p.x) {
			return true;
		}
		return false;
	}

	bool insidePoint(const Point& p) {
		if (rect.t <= p.y && rect.b > p.y && rect.l <= p.x && rect.r > p.x) {
			return true;
		}
		return false;
	}

	Collision collision(const Rect& r) {
		if (rect.t >= r.t && rect.b <= r.b && rect.l >= r.l && rect.r <= r.r) {
			return INSIDE;
		}
		else if (rect.t <= r.b && rect.b >= r.t && rect.l <= r.r && rect.r >= r.l) {
			return CROSS;
		}
		else {
			return OUTSIDE;
		}
	}

private:
	vector<Point> points;
	Block* child[4];
	Rect rect;
};

const long long MAX = 2147483648;
const long long HALF = MAX / 2;

int main() {
	int n, q;
	Rect rect(0, 0, MAX, MAX);
	Block block(rect);
	set<int> s;

	cin >> n;
	for (int i = 0; i < n; i++) {
		Point p;
		cin >> p.x >> p.y;
		p.x += HALF;
		p.y += HALF;
		p.id = i;
		block.insert(p);
	}

	cin >> q;
	for (int i = 0; i < q; i++) {
		Rect rect;
		cin >> rect.l >> rect.r >> rect.t >> rect.b;
		rect.l += HALF;
		rect.r += HALF;
		rect.t += HALF;
		rect.b += HALF;

		block.pointCheck(rect, s);
		for (set<int>::iterator it = s.begin(); it != s.end(); it++) {
			cout << *it << endl;
		}
		s.clear();

		cout << endl;
	}
}

