struct kDTree {
  struct node {
    int location;
    int p, l, r;
    node(int location=-1, int p=-1, int l=-1, int r=-1)
      :location(location), p(p), l(l), r(r){}
  };
  struct data {
    int id;
    vector<int> attr;
    data(){}
    data(int id, vector<int> attr):id(id), attr(attr){}
    bool operator < (const data& d) const {
      return id < d.id;
    }
  };
  static const int MAX = 1000000;
  static const int NIL = -1;
  int k, n, np, root;
  vector<data> d;
  vector<node> tr;
  kDTree(int k, int n)
    :k(k), n(n), np(0), d(n, data(-1, vector<int>(k))), tr(n, node(NIL, NIL, NIL, NIL)){}
  void setData(int id, vector<int> attr) {
    assert(attr.size() == k);
    d[id] = data(id, attr);
  }
  int build(int l, int r, int depth) {
    if(!(l < r)) return NIL;
    int mid = (l + r) / 2;
    int id = np++;
    sort(d.begin() + l, d.begin() + r, [&](data x, data y) {
	return x.attr[depth%k] < y.attr[depth%k];
      });
    tr[id].location = mid;
    tr[id].l = build(l, mid, depth+1);
    tr[id].r = build(mid+1, r, depth+1);

    return id;
  }
  void build() {
    root = build(0, n, 0);
  }
  void find(int v, vector<int> s, vector<int> t, int depth, vector<data>& res) {
    vector<int> attr = d[tr[v].location].attr;
    bool flag = true;
    for(int i = 0; i < k; i++) if(attr[i] < s[i] || t[i] < attr[i]) flag = false;
    if(flag) {
      res.push_back(d[tr[v].location]);
    }
    if(tr[v].l != NIL) {
      if(s[depth%k] <= attr[depth%k]) find(tr[v].l, s, t, depth+1, res);
    }
    if(tr[v].r != NIL) {
      if(attr[depth%k] <= t[depth%k]) find(tr[v].r, s, t, depth+1, res);
    }
  }
  vector<data> find(vector<int> s, vector<int> t) {
    vector<data> res;
    find(root, s, t, 0, res);
    return res;
  }
};

