  void construct(ll l,ll r,ll d){
    if(l+1>=r) return;
    if(d%2==0) sort(tree.begin()+l,tree.begin()+r,[](pii a,pii b){return a.first<b.first;});
    else sort(tree.begin()+l,tree.begin()+r,[](pii a,pii b){return a.second<b.second;});
    ll mid=(l+r)/2;
    construct(l,mid,d+1);
    construct(mid+1,r,d+1);
  }
  vector<pii> get(ll sx,ll tx,ll sy,ll ty){return get(sx,tx,sy,ty,0,tree.size(),0);}
  vector<pii> get(ll sx,ll tx,ll sy,ll ty,ll l,ll r,ll d){
    if(l>=r) return vector<pii>();
    ll mid=(l+r)/2; pii p=tree[mid];
    vector<pii> ret;
    if(sx<=p.first&&p.first<=tx&&sy<=p.second&&p.second<=ty) ret.PB(p);
    if(l+1==r) return ret;
    if(d%2==0){
      if(tx<=p.first){for(pii i:get(sx,tx,sy,ty,l,mid,d+1)) ret.PB(i); return ret;}
      if(p.first<=sx){for(pii i:get(sx,tx,sy,ty,mid+1,r,d+1)) ret.PB(i); return ret;}
      for(pii i:get(sx,tx,sy,ty,l,mid,d+1)) ret.PB(i);
      for(pii i:get(sx,tx,sy,ty,mid+1,r,d+1)) ret.PB(i);
      return ret;
    }else{
      if(ty<=p.second){for(pii i:get(sx,tx,sy,ty,l,mid,d+1)) ret.PB(i); return ret;}
      if(p.second<=sy){for(pii i:get(sx,tx,sy,ty,mid+1,r,d+1)) ret.PB(i); return ret;}
      for(pii i:get(sx,tx,sy,ty,l,mid,d+1)) ret.PB(i);
      for(pii i:get(sx,tx,sy,ty,mid+1,r,d+1)) ret.PB(i);
      return ret;
    }
  }
};

int main(){
  ll n; cin>>n;
  vi x(n),y(n); REP(i,n) cin>>x[i]>>y[i];
  KDTree tree;
  REP(i,n) tree.add(x[i],y[i]);
  tree.construct();
  unordered_map<string,vector<ll>> ptoi;
  REP(i,n) ptoi[to_string(x[i])+"/"+to_string(y[i])].push_back(i);
  ll q; cin>>q;
