    vi ans;
    for(pii p:tree.get(sx,tx,sy,ty)){
      for(ll j:ptoi[to_string(p.first)+"/"+to_string(p.second)]) ans.PB(j);
    }
    sort(ans.begin(),ans.end());
    for(ll j:ans) cout<<j<<endl;
    cout<<endl;
  }
}

