        S[i].first = T[i].second = x;
        S[i].second = T[i].first = y;
        S[i].index = T[i].index = i;
    }

    sort(S.begin(), S.end());
    sort(T.begin(), T.end());

    size_t q;
    scanf("%zu", &q);

    for (size_t i=0; i<q; ++i) {
        int sx, tx, sy, ty;
        scanf("%d %d %d %d", &sx, &tx, &sy, &ty);

        lp_queue<size_t> q;
        size_t x_lb=lower_bound(S.begin(), S.end(), Point(sx, sy))-S.begin();
        size_t x_ub=upper_bound(S.begin(), S.end(), Point(tx, ty))-S.begin();
        size_t y_lb=lower_bound(T.begin(), T.end(), Point(sy, sx))-T.begin();
        size_t y_ub=upper_bound(T.begin(), T.end(), Point(ty, tx))-T.begin();

        ptrdiff_t x_diff=x_ub-x_lb, y_diff=y_ub-y_lb;
        if (x_diff < y_diff) {
            for (size_t i=x_lb; i<x_ub; ++i) {
                int y=S[i].second;
                if (sy<=y && y<=ty)
                    q.push(S[i].index);
            }
        } else {
            for (size_t i=y_lb; i<y_ub; ++i) {
                int x=T[i].second;
                if (sx<=x && x<=tx)
                    q.push(T[i].index);
            }
        }

        while (!q.empty()) {
            printf("%zd\n", q.top());
            q.pop();
        }
        printf("\n");
    }

    return 0;
}

