#define compare(d, p, q) (d ? real(p.point) < real(q.point) : imag(p.point) < imag(q.point))
using namespace std;

const int INF = INT_MAX/3;

typedef complex<double> Point;

struct P{
    Point point;
    int id;
    P (const Point &point, int id)
        : point(point), id(id) {}
    bool operator<(const P &p)const{
        return id < p.id;
    }
};


struct node{
    P p;
    node *l, *r;
    node (const P &p)
        : p(p), l(NULL), r(NULL) {}
};

struct kDTree{
    node *root;
    kDTree() :root(NULL){}

    void insert(const P &p){
        root = insert(root, 0, p);
    }

    node *insert(node *t, int d, const P &p){
        if(t==NULL) return new node(p);
        if(compare(d, p, t->p)) t->l = insert(t->l, !d, p);
        else t->r = insert(t->r, !d, p);
        return t;
    }

    void find(const P &ld, const P &ru, vector<P> &out){
        find(root, 0, ld, ru, out);
    }

    void find(node *t, int d, const P &ld, const P &ru, vector<P> &out){
        if(t==NULL) return;
        const P &p = t->p;
        if(real(ld.point) <= real(p.point) && real(p.point) <= real(ru.point) && imag(ld.point) <= imag(p.point) && imag(p.point) <= imag(ru.point)){
            out.push_back(p);
        }
        if(!compare(d, p, ld)) find(t->l, !d, ld, ru, out);
        if(!compare(d, ru, p)) find(t->r, !d, ld, ru, out);
    }
};

int main(){
    random_device rnd;
    mt19937 mt(rnd());
    uniform_real_distribution<> ran(-0.1, 0.1);
    int n,q,x,y,sx, tx, sy, ty;
    cin >> n;
    kDTree k;
    for (int i=0;i<n;i++){
        cin >> x >> y;
        Point point(x + ran(mt), y + ran(mt));
        P p(point, i);
        k.insert(p);
    }

    cin >> q;
    for (int i=0;i<q;i++){
        cin >> sx >> tx >> sy >> ty ;
        vector<P> result;
        Point ldPoint(sx-0.5, sy-0.5);
        P ld(ldPoint, INF);
        Point ruPoint(tx+0.5, ty+0.5);
        P ru(ruPoint, INF);
        k.find(ld, ru, result);
        sort(result.begin(), result.end());
        for (int j=0;j<result.size();j++){
            cout << result[j].id <<endl;
        }
        cout << endl;
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct point {
    int id, x, y;
    point() : id(-1), x(0), y(0) {}
    point(int id, int x, int y) : id(id), x(x), y(y) {}
    point(int id, pair<int,int> xy) : id(id), x(xy.first), y(xy.second) {}
    bool operator < (const point &p) const {
        return id < p.id;
    }
};
class kdtree {
private:
    struct node {
        int p;
        int location;
        int l,r;
        node():l(NIL),r(NIL) {}
    };

    static bool lessX(const point &a, const point &b) { return a.x < b.x; }
    static bool lessY(const point &a, const point &b) { return a.y < b.y; }
    static const int NIL=-1;

    int root;
    int np;
    int N;
    vector<node> T;
    vector<point> &P;

    int make_kd_tree(int l, int r, int depth) {
        if (!(l < r)) return -1;
        int mid = (l + r) / 2;
        int t = np++;

        if (depth) sort(begin(P) + l, begin(P) + r, lessY);
        else       sort(begin(P) + l, begin(P) + r, lessX);

        T[t].location = mid;
        T[t].l = make_kd_tree(l, mid, !depth);
        T[t].r = make_kd_tree(mid+1, r, !depth);

        return t;
    }
    void find(int v, int sx, int sy, int tx, int ty, int depth, vector<point> &ans) {
        int x = P[T[v].location].x;
        int y = P[T[v].location].y;

        if (sx <= x && x <= tx && sy <= y && y <= ty) {
            ans.push_back(P[T[v].location]);
        }

        if (depth) {
            if(T[v].l != NIL && sy <= y) find(T[v].l, sx, sy, tx, ty, !depth, ans);
            if(T[v].r != NIL && y <= ty) find(T[v].r, sx, sy, tx, ty, !depth, ans);
        } else {
            if(T[v].l != NIL && sx <= x) find(T[v].l, sx, sy, tx, ty, !depth, ans);
            if(T[v].r != NIL && x <= tx) find(T[v].r, sx, sy, tx, ty, !depth, ans);
        }
    }

public:
    kdtree(vector<point> &p) : P(p) {
        np = 0;
        N = p.size();
        T.resize(N);
        root = make_kd_tree(0, N, 0);
    }
    void query(int sx,int sy,int tx,int ty, vector<point> &p) {
        find(root, sx, sy, tx, ty, 0, p);
    }
};

int main() {
    int n;
    cin >> n;
    vector<point> p(n);
    for (int i = 0; i < n; i++) {
        p[i].id = i;
        cin >> p[i].x >> p[i].y;
    }
    kdtree tree(p);
    int q;
    cin >> q;
    while (q--) {
        int sx, tx, sy, ty;
        cin >> sx >> tx >> sy >> ty;

        vector<point> ans;
        tree.query(sx, sy, tx, ty, ans);

        sort(begin(ans), end(ans));
        for (int i = 0; i < (int)ans.size(); i++) {
            cout << ans[i].id << endl;
        }
        cout << endl;
    }
    return 0;
}

