    x=(x-1)/2;
  }
}

void find(int ax,int ay,int bx,int by,vector<int> &v,int k=0,int l=0,int r=(1<<19)){

  if(bx<=l || r<=ax)return;

  if(ax<=l&&r<=bx){
    set<point> :: iterator it = t[k].lower_bound((point){ax,ay,0});
