struct Vertex {
    int label;
    int x, y;
    Vertex(int label, int x, int y) :label(label), x(x), y(y) {}
};

class KDTree {
public:
    KDTree(std::vector<Vertex> list) :root_(build(list, 0, list.size(), EVEN)) {}
    void search(const Vertex& initial, const Vertex& terminal) const {search(root_, initial, terminal, EVEN);}
private:
    static const bool EVEN = false, ODD = true;
    struct Node {
        Vertex vertex;
        std::unique_ptr<Node> left_child, right_child;
        Node(const Vertex& v) :vertex(v), left_child(nullptr), right_child(nullptr) {}
    };
    class Compare {
    public:
        Compare(const bool odd) :odd_(odd) {}
        bool operator()(const Vertex& lhs, const Vertex& rhs) const {return odd_ ? lhs.y < rhs.y : lhs.x < rhs.x;}
    private:
        bool odd_;
    };
    std::unique_ptr<Node> build(std::vector<Vertex>& list, const int left, const int right, const bool odd) const {
        if(right <= left) return nullptr;
        int mid = (left + right) >> 1;
        std::nth_element(list.begin() + left, list.begin() + mid, list.begin() + right, Compare(odd));
        std::unique_ptr<Node> node(new Node(list[mid]));
        node->left_child = build(list, left, mid, !odd);
        node->right_child = build(list, mid + 1, right, !odd);
        return std::move(node);
    }
    void search(const std::unique_ptr<Node>& node, const Vertex& initial, const Vertex& terminal, const bool odd) const {
        if(!node) return;
        if(initial.x <= node->vertex.x && node->vertex.x <= terminal.x && initial.y <= node->vertex.y && node->vertex.y <= terminal.y) {
            answer.push_back(node->vertex.label);
        }
        if(!Compare(odd)(node->vertex, initial)) search(node->left_child, initial, terminal, !odd);
        if(!Compare(odd)(terminal, node->vertex)) search(node->right_child, initial, terminal, !odd);
    }
    std::unique_ptr<Node> root_;
};

int main() {
    int n, q;
    cin >> n;

    vector<Vertex> vertex;
    for(int i = 0; i < n; ++i) {
        double x, y;
        cin >> x >> y;
        vertex.push_back(Vertex(i, x, y));
    }
    KDTree kdt(vertex);

    for(cin >> q; q > 0; --q) {
        double sx, tx, sy, ty;
        cin >> sx >> tx >> sy >> ty;
        answer.clear();
        kdt.search(Vertex(0, sx, sy), Vertex(0, tx, ty));
        sort(answer.begin(), answer.end());
        for(auto i: answer) cout << i << endl;
        cout << endl;
    }
}

