const int INF = 1e9 + 10;
using dat_t = tuple<int, int>;

const int MAX_N = 500010;

vector<const dat_t*> seg[MAX_N*2];
int x_min[MAX_N*2], x_max[MAX_N*2];
int size[MAX_N*2];

bool comp_x(const dat_t *a, const dat_t *b){
    return get<0>(*a) < get<0>(*b);    
}

bool comp_y(const dat_t *a, const dat_t *b){
    return get<1>(*a) < get<1>(*b);    
}

void make_tree(const dat_t **left, const dat_t **right, int n){
    int sz = right - left;
    x_min[n] = get<0>(**left);
    x_max[n] = get<0>(**(right - 1));
    auto &par = seg[n];
    std::copy(left, right, std::back_inserter(par));
    sort(par.begin(), par.end(), comp_y);
    if(sz > 1){
        make_tree(left, left + sz/2, n*2);
        make_tree(left + sz/2, right, n*2 + 1);
    }
}

void make_tree(const dat_t *left, const dat_t *right){
    static const dat_t *ptr[500010];
    int sz = right - left;
    for(auto i = left; i != right; ++i) ptr[i - left] = i;
    sort(ptr, ptr + sz, comp_x);
    make_tree(ptr, ptr + sz, 1);
}

void y_query(int y1, int y2, vector<const dat_t*> &ans, int n){
    auto t = make_tuple(-INF, y1);
    auto u = make_tuple(-INF, y2);
    auto l = lower_bound(seg[n].begin(), seg[n].end(), &t, comp_y);
    auto r = upper_bound(seg[n].begin(), seg[n].end(), &u, comp_y);
    std::copy(l, r, std::back_inserter(ans));
}

void range_query(int x1, int x2, int y1, int y2, vector<const dat_t*> &ans, int n){
    if(x_max[n] < x1 || x2 < x_min[n]){
        ;
    } else if(x1 <= x_min[n] && x_max[n] <= x2){
        y_query(y1, y2, ans, n);
    } else {
        range_query(x1, x2, y1, y2, ans, n*2);
        range_query(x1, x2, y1, y2, ans, n*2 + 1);
    }
}

void range_query(int x1, int x2, int y1, int y2, vector<const dat_t*> &ans){
    range_query(x1, x2, y1, y2, ans, 1);
}

