	int m;

	if (X[r].Value < s) {
		*index1 = *index2 = -1;
		return;
	}

	if (t < X[f].Value) {
		*index1 = *index2 = -1;
		return;
	}

	while (f <= r) {
		m = (f + r) / 2;
		if (s <= X[m].Value) {
			if (m == 0 || X[m - 1].Value < s) {
				*index1 = m;
				break;
			}
			else {
				r = m - 1;
				continue;
			}
		}
		else {
			f = m + 1;
			continue;
		}
	}
	if (r < f) {
