		if (X[m].Value <=t) {
			if (m == N - 1 || t < X[m + 1].Value) {
				*index2 = m;
				break;
			}
			else {
				f = m + 1;
				continue;
			}
		}
		else {
			r = m - 1;
			continue;
		}
	}
	if (r < f) {
		//not found
