bool binarySearch(int index1forX, int index2forX, int ID) {
	int f = index1forX;
	int r = index2forX;
	int m;

	while (f <= r) {
		m = (f + r) / 2;
		if (X[m].ID == ID) {
			return true;
		}
		else if (ID < X[m].ID) {
			r = m - 1;
		}
		else {
			f = m + 1;
		}
	}
	return false;
}

