void indicesInTheRangeForX(int s, int t, int *index1, int *index2) {
	int f = 0;
	int r = N-1;
	int m;

	if (X[r].Value < s) {
		*index1 = *index2 = -1;
		return;
	}

	if (t < X[f].Value) {
		*index1 = *index2 = -1;
		return;
	}

	while (f <= r) {
		m = (f + r) / 2;
		if (s <= X[m].Value) {
			if (m == 0 || X[m - 1].Value < s) {
				*index1 = m;
				break;
			}
			else {
				r = m - 1;
				continue;
			}
		}
		else {
			f = m + 1;
			continue;
		}
	}
	if (r < f) {
		//not found
		//impossible case
		printf("Something wrong\n");
	}

	f = m;
	r = N - 1;
	while (f <= r) {
		m = (f + r) / 2;
		if (X[m].Value <=t) {
			if (m == N - 1 || t < X[m + 1].Value) {
				*index2 = m;
				break;
			}
			else {
				f = m + 1;
				continue;
			}
		}
		else {
			r = m - 1;
			continue;
		}
	}
	if (r < f) {
		//not found
		//impossible case
		printf("Something wrong\n");
	}
}

