#include<stdio.h>
#include<vector>
#include<algorithm>
using namespace std;

struct Point {
	long long x, y;
	int i;
};

struct Node {
	Point p;
	int left;
	int right;
};

bool cmp_x(const Point& p1, const Point& p2) {
	return p1.x < p2.x;
}

bool cmp_y(const Point& p1, const Point& p2) {
	return p1.y < p2.y;
}

int makeTree(Node kDTree[],int& i, vector<Point>& points, int begin, int end,int depth) {
	if (begin >= end)return -1;
	if (depth & 1)sort(points.begin() + begin, points.begin() + end, cmp_x);
	else sort(points.begin() + begin, points.begin() + end, cmp_y);

	depth++;

	int mid = (begin + end) / 2;
	int j = i; i++;

	kDTree[j].p = points[mid];

	kDTree[j].left = makeTree(kDTree, i, points, begin, mid, depth);
	kDTree[j].right = makeTree(kDTree, i, points, mid + 1, end, depth);

	return j;
}

void searchTree(Node kDTree[], int i, Point p1, Point p2, int depth,vector<int>& ans) {
	Point p = kDTree[i].p;
	if (p.x >= p1.x && p.x <= p2.x && p.y >= p1.y && p.y <= p2.y) {
		ans.push_back(p.i);
	}

	if (depth & 1) {
		if (kDTree[i].left != -1 && p.x >= p1.x) {
			searchTree(kDTree, kDTree[i].left, p1, p2, depth + 1, ans);
		}
		if (kDTree[i].right != -1 && p.x <= p2.x) {
			searchTree(kDTree, kDTree[i].right, p1, p2, depth + 1, ans);
		}
	}
	else {
		if (kDTree[i].left != -1 && p.y >= p1.y) {
			searchTree(kDTree, kDTree[i].left, p1, p2, depth + 1, ans);
		}
		if (kDTree[i].right != -1 && p.y <= p2.y) {
			searchTree(kDTree, kDTree[i].right, p1, p2, depth + 1, ans);
		}
	}
}

const int MAX = 500000;

int main() {
	int n, q;
	vector<Point> points;
	Node kDTree[MAX];

	kDTree = new Node[MAX];

	scanf("%d", &n);
	for (int i = 0; i < n; i++) {
		Point p;
		scanf("%d%d", &p.x, &p.y);
		p.i = i;
		points.push_back(p);
	}

	int index = 0;
	makeTree(kDTree,index, points, 0, n, 0);

	scanf("%d", &q);
	for (int i = 0; i < q; i++) {
		Point p1, p2;
		vector<int> ans;

		scanf("%d%d%d%d", &p1.x, &p2.x, &p1.y, &p2.y);
		searchTree(kDTree, 0, p1, p2, 0, ans);
		sort(ans.begin(), ans.end());

		for (int i = 0; i < ans.size(); i++) {
			printf("%d\n", ans[i]);
		}
		printf("\n");
	}

	return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long

struct point{
  int id,x,y;
  bool operator<(const point &u)const{
    return id < u.id;
  }
};

struct KDtree{
  struct node{
    int location;
    int p,l,r;
  };

  vector<point> P;
  vector<node> T;
  int n,np = 0;

  void init(int n){
    P.resize(n+1);
    T.resize(n+1);
  }

  static bool cmpX(const point &a,const point &b){ return a.x < b.x; }
  static bool cmpY(const point &a,const point &b){ return a.y < b.y; }

  int maketree(int l,int r,int depth){
    if(!(l < r)) return -1;
    int mid = (l+r) / 2;
    int t = np++;
    if(depth%2 == 0) sort(P.begin()+l,P.begin()+r,cmpX);
    else sort(P.begin()+l,P.begin()+r,cmpY);
    T[t].location = mid;
    T[t].l = maketree(l,mid,depth+1);
    T[t].r = maketree(mid+1,r,depth+1);
    return t;
  }

  void find(int v,int sx,int tx,int sy,int ty,int depth,vector<point> &ans){
    int x = P[T[v].location].x;
    int y = P[T[v].location].y;
    if(sx <= x && x <= tx && sy <= y && y <= ty){
      ans.push_back(P[T[v].location]);
    }

    if(depth%2 == 0){
      if(T[v].l != -1){
        if(sx <= x) find(T[v].l,sx,tx,sy,ty,depth+1,ans);
      }
      if(T[v].r != -1){
        if(x <= tx) find(T[v].r,sx,tx,sy,ty,depth+1,ans);
      }
    }
    else {
      if(T[v].l != -1){
        if(sy <= y) find(T[v].l,sx,tx,sy,ty,depth+1,ans);
      }
      if(T[v].r != -1){
        if(y <= ty) find(T[v].r,sx,tx,sy,ty,depth+1,ans);
      }
    }
  }
}kd;

signed main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n; cin >> n;
  kd.init(n);
  for(int i = 0; i < n; i++){
    int x,y; cin >> x >> y;
    kd.P[i] = {i,x,y};
    kd.T[i].l = kd.T[i].r = kd.T[i].p = -1;
  }
  int root = kd.maketree(0,n,0);

  int q; cin >> q;
  vector<point> ans;
  for(int i = 0; i < q; i++){
    int sx,tx,sy,ty; cin >> sx >> tx >> sy >> ty;
    ans.clear();
    kd.find(root,sx,tx,sy,ty,0,ans);
    sort(ans.begin(),ans.end());
    for(auto p : ans){
      cout << p.id << '\n';
    }
    cout << '\n';
  }

  return 0;
}

