struct kdtree {
	struct node {
		P p;
		node *l, *r;
		node(const P &p)
			: p(p), l(NULL), r(NULL) { }
	} *root;
	kdtree() : root(NULL) { }

#define compare(d, p, q) (d ? real(p) < real(q) : imag(p) < imag(q))
	void insert(const P &p) {
		root = insert(root, 0, p);
	}
	node *insert(node *t, int d, const P &p) {
		if (t == NULL) return new node(p);
		if (compare(d, p, t->p)) t->l = insert(t->l, !d, p);
		else                   t->r = insert(t->r, !d, p);
		return t;
	}
	void search(const P &ld, const P &ru, vector<P> &out) {
		search(root, 0, ld, ru, out);
	}
	void search(node *t, int d, const P &ld, const P &ru, vector<P> &out) {
		if (t == NULL) return;
		const P &p = t->p;
		if (real(ld) <= real(p) && real(p) <= real(ru) &&
			imag(ld) <= imag(p) && imag(p) <= imag(ru)) out.push_back(p);
		if (!compare(d, p, ld)) search(t->l, !d, ld, ru, out);
		if (!compare(d, ru, p)) search(t->r, !d, ld, ru, out);
	}
};

