int main() {
    int n, q;
    cin >> n;

    vector<Vertex> vertex;
    for(int i = 0; i < n; ++i) {
        double x, y;
        cin >> x >> y;
        vertex.push_back(Vertex(i, x, y));
    }
    KDTree kdt(vertex);

    for(cin >> q; q > 0; --q) {
        double sx, tx, sy, ty;
        cin >> sx >> tx >> sy >> ty;
        answer.clear();
        kdt.search(Vertex(0, sx, sy), Vertex(0, tx, ty));
        for(auto i: answer) cout << i << endl;
        cout << endl;
    }
    kdt.print();
}

