{
	READ(int, n);

	KDTree<int, 2> tree;
	REP(i, n)
	{
		READ(int, x, y);
		tree.add({ x, y });
	}
	tree.build();
	READ(int, q);
	REP(i, q)
	{
		READ(int, sx, tx, sy, ty);
		auto v = tree.range({ sx,sy }, { tx,ty });
		sort(allof(v));
		for (auto val : v) { WRITE(val); }
		WRITE("");
	}
}

