bool lessX(const Point &p1,const Point &p2){return p1.x<p2.x;}
bool lessY(const Point &p1,const Point &p2){return p1.y<p2.y;}

int makeKDTree(int l,int r, int d){
  if(!(l<r))return NIL;
  int mid=(l+r)>>1;
  int t=np++;
  nth_element(p+l,p+mid,p+r,(d&1 ? lessY : lessX));
  T[t].location=mid;
  T[t].l=makeKDTree(l,mid,d+1);
  T[t].r=makeKDTree(mid+1,r,d+1);
  return t;
}

void find(int v,int sx,int tx,int sy,int ty,int d,vector<Point> &ans){
  if( sx <= P[T[v].location].x && P[T[v].location].x <= tx && sy <= P[T[v].location].y && P[T[v].location].y <= ty )return T[v].location;
  int res=-1;
  if(d%2==0){
    if(T[v].l!=NIL&&sx<=x)res=find(T[v].l,sx,tx,sy,ty,d+1,ans);
    if(res!=-1)return res;
    if(T[v].r!=NIL&&x<=tx)res=find(T[v].r,sx,tx,sy,ty,d+1,ans);
  }
  else{
    if(T[v].l!=NIL&&sy<=y)res=find(T[v].l,sx,tx,sy,ty,d+1,ans);
    if(res!=-1)return res;
    if(T[v].r!=NIL&&y<=ty)res=find(T[v].r,sx,tx,sy,ty,d+1,ans);
  }
  return res;
}

bool exist(int v,int sx,int tx,int sy,int ty,int d,vector<Point> &ans){
  if( sx <= P[T[v].location].x && P[T[v].location].x <= tx && sy <= P[T[v].location].y && P[T[v].location].y <= ty )return 1;
  if(d%2==0){
