  }
  auto sx = v;
  auto sy = v;
  sort(sx.begin(), sx.end());
  sort(sy.begin(), sy.end(), CompareY);
  auto root = Build(sx, sy, 0);

  //  Print(root, 0);

  cin >> q;
  for (int x1, y1, x2, y2; cin >> x1 >> x2 >> y1 >> y2;) {
    set<int> res;
    Query(root, 0, {x1, y1, 0}, {x2, y2, 0}, res);
    for (auto id : res)
      cout << id << endl;
    cout << endl;
  }
}

