int make2DTree( int l, int r, int depth )
{
	if( l >= r ) return NIL;
	int mid = ( l + r ) / 2;
	int t = np++;
	int dmod = depth % 2;
	sort( v.begin() + l, v.begin() + r,
		[&]( vert a, vert b ) { return a.xy[dmod] < b.xy[dmod]; } );
	node[t].loc = mid;
	node[t].left = make2DTree( l, mid, depth + 1 );
	node[t].right = make2DTree( mid + 1, r, depth + 1 );
	return t;
}

