{
	int x = v[node[n].loc].xy[0];
	int y = v[node[n].loc].xy[1];
	if( sx <= x && x <= tx && sy <= y && y <= ty ) ans.push_back( v[node[n].loc].idx );
	if( depth % 2 == 0 ) {
		if( node[n].left != NIL && sx <= x ) find( node[n].left, sx, tx, sy, ty, depth + 1, ans );
		if( node[n].right != NIL && x <= tx ) find( node[n].right, sx, tx, sy, ty, depth + 1, ans );
	}
	else {
		if( node[n].left != NIL && sy <= y ) find( node[n].left, sx, tx, sy, ty, depth + 1, ans );
		if( node[n].right != NIL && y <= ty ) find( node[n].right, sx, tx, sy, ty, depth + 1, ans );
