{
    return p1.y < p2.y;
}

int makeKDTree(int l, int r, int depth)
{
    if(l==r) return NIL;
    int mid = (l+r)/2;
    int t = np++;
    if(depth%2==0)
        sort(P+l, P+r, lessX);
    else
        sort(P+l, P+r, lessY);
    T[t].location = mid;
    T[t].l = makeKDTree(l, mid, depth+1);
    T[t].r = makeKDTree(mid+1, r, depth+1);

    return t;
}

