    if(depth%2==0)
    {
        if(T[v].l!=NIL && sx<=x)
        {
            find(T[v].l, sx, tx, sy, ty, depth+1, ans);
        }
        if(T[v].r!=NIL && tx>=x)
        {
            find(T[v].r, sx, tx, sy, ty, depth+1, ans);
        }
    }
    else
    {
        if(T[v].l!=NIL && sy<=y)
        {
            find(T[v].l, sx, tx, sy, ty, depth+1, ans);
        }
        if(T[v].r!=NIL && ty>=y)
        {
            find(T[v].r, sx, tx, sy, ty, depth+1, ans);
        }
    }
}
