template <class U>
class TwoDimTree{
    struct node{int location, l, r;};
private:
    int n, idx = 0, NIL = -1;
    vector<Point<U>> &P;
    vector<node> tdt;
    function<bool(Point<U>, Point<U>)> cmp_odd = [](Point<U> p1, Point<U> p2){
        if(p1.x==p2.x) return p1.y < p2.y;
        else return p1.x < p2.x;
    };
    function<bool(Point<U>, Point<U>)> cmp_even = [](Point<U> p1, Point<U> p2){
        if(p1.y==p2.y) return p1.x < p2.x;
        else return p1.y < p2.y;
    };

    int make2DTree(int l, int r, int depth){
        if(r<=l) return -1;
        int mid = (l+r) / 2;
        int t = idx++;
        if(depth%2){
            sort(P.begin()+l, P.begin()+r, cmp_even);
        } else {
            sort(P.begin()+l, P.begin()+r, cmp_odd);
        }
        tdt[t] = {mid, NIL, NIL};
        tdt[t].l = make2DTree(l, mid, depth+1);
        tdt[t].r = make2DTree(mid+1, r, depth+1);
        return t;
    }

    // [sx, tx], [sy, ty]
    void find(int v, U sx, U tx, U sy, U ty, int depth, vector<Point<U>> &res){
        U x = P[tdt[v].location].x, y = P[tdt[v].location].y;
        if(sx<=x and x<=tx and sy<=y and y<=ty) res.push_back(P[tdt[v].location]);

        if(depth%2){
            if(tdt[v].l!=NIL and sy<=y){
                find(tdt[v].l, sx, tx, sy, ty, depth+1, res);
            }
            if(tdt[v].r!=NIL and y<=ty){
                find(tdt[v].r, sx, tx, sy, ty, depth+1, res);
            }
        } else {
            if(tdt[v].l!=NIL and sx<=x){
                find(tdt[v].l, sx, tx, sy, ty, depth+1, res);
            }
            if(tdt[v].r!=NIL and x<=tx){
                find(tdt[v].r, sx, tx, sy, ty, depth+1, res);
            }
        }
    }

public:
    TwoDimTree(size_t _n, vector<Point<U>> &_P) : n(_n), P(_P){
        tdt = vector<node>(n);
        make2DTree(0, n, 0);
    }

    void _find(U sx, U tx, U sy, U ty, vector<Point<U>> &res){
        find(0, sx, tx, sy, ty, 0, res);
    }
};

int main(){
    ios::sync_with_stdio(false), cin.tie(nullptr);
    int N;
