        }
    }
}

#include<iostream>
#include<set>
using namespace std;

enum Collision {
	INSIDE,
	OUTSIDE,
	CROSS
};

struct Point {
	Point():x(-1),y(-1) {};
	Point(long long x, long long y) :x(x), y(y) {};
	bool operator == (const Point& p)const {
		return x == p.x && y == p.y;
	}
	long long x;
	long long y;
};

struct Rect {
	Rect() :t(0), l(0), b(0), r(0) {};
	Rect(long long t, long long l, long long b, long long r) :t(t), l(l), b(b), r(r) {};
	long long t;
	long long l;
	long long b;
	long long r;
};

class Block {
public:
	Block(Rect rect) {
		this->rect = rect;
		pointIndex = -1;
		for (int i = 0; i < 4; i++) {
			child[i] = NULL;
		}
	}

	void insert(Point p, int index) {
		if (child[0] != NULL) {
			for (int i = 0; i < 4; i++) {
				if (child[i]->insidePoint(p)) {
					child[i]->insert(p,index);
					return;
				}
			}
		}
		else {
			if (pointIndex == -1) {
				point = p;
				pointIndex = index;
			}
			else {
				long long wid = (rect.b - rect.t) / 2;
				Point pos[4] = {
					{rect.l,rect.t},
					{rect.l + wid,rect.t},
					{rect.l,rect.t + wid},
					{rect.l + wid,rect.t + wid}
				};

				for (int i = 0; i < 4; i++) {
					Rect r(pos[i].y, pos[i].x, pos[i].y + wid, pos[i].x + wid);
					child[i] = new Block(r);
				}
				this->insert(this->point,this->pointIndex);
				this->pointIndex = -1;
				this->insert(p,index);
			}
		}
	}

	void pointCheck(const Rect& r, set<int>& s) {
		switch (collision(r)) {

		case INSIDE:
			check(s);
			break;

		case OUTSIDE:
			break;

		case CROSS:
			if (child[0] != NULL) {
				for (int i = 0; i < 4; i++) {
					child[i]->pointCheck(r,s);
				}
			}
			else {
				if (pointIndex != -1) {
					if (insideRect(r, point)) {
						s.insert(pointIndex);
					}
				}
			}
			break;
		}
	}

	void check(set<int>& s) {
		if (child[0] == NULL) {
			if (pointIndex != -1) {
				s.insert(pointIndex);
			}
		}
		else {
			for (int i = 0; i < 4; i++) {
				child[i]->check(s);
			}
		}
	}

	bool insideRect(const Rect& r, const Point& p) {
		if (r.t <= p.y && r.b >= p.y && r.l <= p.x && r.r >= p.x) {
			return true;
		}
		return false;
	}

	bool insidePoint(const Point& p) {
		if (rect.t <= p.y && rect.b > p.y && rect.l <= p.x && rect.r > p.x) {
			return true;
		}
		return false;
	}

	Collision collision(const Rect& r) {
		if (rect.t >= r.t && rect.b <= r.b && rect.l >= r.l && rect.r <= r.r) {
			return INSIDE;
		}
		else if (rect.t <= r.b && rect.b >= r.t && rect.l <= r.r && rect.r >= r.l) {
			return CROSS;
		}
		else {
			return OUTSIDE;
		}
	}

private:
	Point point;
	int pointIndex;
	Block* child[4];
	Rect rect;
};

const long long MAX = 2147483648;
const long long HALF = MAX / 2;

int main() {
	int n, q;
	Rect rect(0, 0, MAX, MAX);
	Block block(rect);
	set<int> s;

	cin >> n;
	for (int i = 0; i < n; i++) {
		Point p;
		cin >> p.x >> p.y;
		p.x += HALF;
		p.y += HALF;
