#define N 500003

vector<P> data[N];
class kdTree {
  private:
    int n;

    void init(int k, int l, int r, P *d) {
      if(r-l == 1) {
        data[k].push_back(d[l]);
      } else {
        int lch = 2*k+1, rch = 2*k+2;
        init(lch, l, (l+r)/2, d);
        init(rch, (l+r)/2, r, d);
        data[k].resize(r-l);

        merge(
            data[lch].begin(), data[lch].end(),
            data[rch].begin(), data[rch].end(),
            data[k].begin()
            );
      }
    }
    int r_query(int a, int b, int x, int k, int l, int r, set<int> *result) {
      if(b <= l || r <= a) {
        return 0;
      } else if(a <= l && r <= b) {
        vector<P>::iterator it = upper_bound(data[k].begin(), data[k].end(), P(x, -1));
        int sz = it - data[k].begin();
        vector<int> res(sz);
        rep(i, sz) (*result).insert(data[k][i].second);
        return sz;
      } else {
        int lc = r_query(a, b, x, 2*k+1, l, (l+r)/2, result);
        int rc = r_query(a, b, x, 2*k+2, (l+r)/2, r, result);

        return lc + rc;
      }
    }
  public:
    kdTree(int n, P *d) {
      this->n = n;
      init(0, 0, n, d);
    }
    int query(int a, int b, int x, set<int> *result) {
      return r_query(a, b, x, 0, 0, n, result);
    }
};

