class PrioritySearchTree{
	struct P{
		int idx,x,y;
		P(int idx,int x,int y):idx(idx),x(x),y(y){}
		bool operator<(const P& p)const{return x<p.x;}
	};
	struct Node{
		int idx,x,y;
		Node *l,*r;
		Node(const P &p):idx(p.idx),x(p.x),y(p.y){}
		~Node(){
			if(l)delete l;
			if(r)delete r;
		}
		void search(int x1,int y1,int x2,int y2,std::vector<int> &result)const{
			if(!this||y2<y)return;
			if(x1<=x){
				l->search(x1,y1,x2,y2,result);
				if(x<=x2){
					r->search(x1,y1,x2,y2,result);
					if(y1<=y)result.push_back(idx);
				}
			}else if(x<=x2){
				r->search(x1,y1,x2,y2,result);
			}
		}
	} *root;
	Node* build(std::vector<P> &ps,int n){
		if(n<=0)return NULL;
		int miny=ps[0].y;
		int mini=0;
		for(int i=1;i<n;i++){
			if(ps[i].y < miny){
				miny=ps[i].y;
				mini=i;
			}
		}
		Node *res=new Node(ps[mini]);
		ps.erase(ps.begin()+mini);
		int m=(n-1)/2;
		res->l=build(ps,m);
		res->r=build(ps,n-1-m);
		return res;
	}
public:
	PrioritySearchTree(const std::vector<std::pair<int,int> > &xy){
		std::vector<P> ps;
		for(int i=0;i<(int)xy.size();i++)ps.push_back(P(i,xy[i].first,xy[i].second));
		std::sort(ps.begin(),ps.end());
		root=build(ps,ps.size());
	}
	PrioritySearchTree(){delete root;}
	std::vector<int> search(int x1,int y1,int x2,int y2)const{
		std::vector<int> result;
		root->search(x1,y1,x2,y2,result);
		std::sort(result.begin(),result.end());
		return result;
	}
};

