class Point {
public:
    Point(){};
    Point(int i, int x, int y) : id {i}, x {x}, y {y} {};
    int id;
    int x;
    int y;
};

class TwoDTree {
public:
    TwoDTree(){};
    TwoDTree(Point* p, TwoDTree* l, TwoDTree* r) : root {p}, left {l}, right {r} {};
    TwoDTree(vector<Point>& ps) {
        auto tree = const2DTree(ps.begin(), ps.end(), 0);
        root = tree->root;
        left = tree->left;
        right = tree->right;
    };
    using pIter = vector<Point>::iterator;
    TwoDTree* const2DTree(pIter a, pIter b, int d){
        if(a >= b){
            return nullptr;
        }
        if(d%2){
            sort(a, b, [](Point p, Point q){ return p.y < q.y; });
        } else {
            sort(a, b, [](Point p, Point q){ return p.x < q.x; });
        }
        pIter mid = a + (b-a)/2;
        auto l = const2DTree(a, mid, d+1);
        auto r = const2DTree(mid+1, b, d+1);
        return new TwoDTree(&(*mid), l, r);
    };
    vector<Point> find(int x1, int x2, int y1, int y2){
        auto ps = new vector<Point>();
        find(x1, x2, y1, y2, *ps);
        return *ps;
    };
    void print(){
        if(root){
            cout << root->id << ", " << root->x << ", " << root->y << endl;
            if(left){
                left->print();
            }
            if(right){
                right->print();
            }
        }
    };
    Point* root;
    TwoDTree* left;
    TwoDTree* right;
private:
    void find(int x1, int x2, int y1, int y2, vector<Point>& vec){
        if(!root){
            return;
        }
        int rx = root->x;
        int ry = root->y;
        if(x1 <= rx && rx <= x2 && y1 <= ry && ry <= y2){
            vec.push_back(*root);
        }

        if(left){
            Point* lr = left->root;
            if(lr && (lr->x >= x1 || lr->y >= y1)){
                left->find(x1, x2, y1, y2, vec);
            }
        }
        if(right){
            Point* rr = right->root;
            if(rr && (rr->x <= x2 || rr->y <= y2)){
                right->find(x1, x2, y1, y2, vec);
            }
        }
    }
};

int main(){
    ios_base::sync_with_stdio(false);
    int n;
    cin >> n;
