struct kDTree {
    int id;
    int d[k];
    kDTree *l, *r;

    bool isInRange(int range_start[k], int range_end[k]) { // [start, end)
        bool ans = 1;
        rep(i,0,k) {
            if(d[i] < range_start[i] or range_end[i] <= d[i]) {ans = 0; break;}
        }
        return ans;
    }
} *root;


