}





void add(int i, int data[k]) {

#ifdef debug
    dout << "----- add( i = " << setw(3) << i << " : ( " << setw(3) << data[0] << ", " << setw(3) << data[1] << " )\n";
#endif

    int axis = 0; // 0 = check x-axis, 1 = check y-axis
    kDTree** p = &root;

    while( (*p)!=NULL ) {
#ifdef debug
        disp(axis);
        disp((*p)->id);
#endif

        if( data[axis] < (*p)->d[axis] ) p = &((*p)->l);
        else p = &((*p)->r);

        (++axis)%=k;
    }

    kDTree* newNode = new kDTree();
    newNode->id = i;
    rep(j,0,k) newNode->d[j] = data[j];

    (*p) = newNode;

}





void sub_rangeSearch(kDTree *p, int range_start[k], int range_end[k], int axis, int target_start[k], int target_end[k]) {
#ifdef debug
    dout << "\n--- sub_rangeSearch( " << (p==NULL? NONE: p->id) << " )\n";
    dout << "range : " << range_start[0] << " <= x < " << range_end[0] << ", " << range_start[1] << " <= y < " << range_end[1] << " ) (fixed)\n";
    dout << "axis = " << (axis ? "y":"x") << " : "; disp(axis);
    dout << "target: " << target_start[0] << " <= x < " << target_end[0] << ", " << target_start[1] << " <= y < " << target_end[1] << " )\n";
#endif

    if(p==NULL) {
#ifdef debug
        dout << "p == NULL\n";
#endif
        return;
    }

//    assert(range_start[axis] < range_end[axis]);
//    assert(target_start[axis] < target_end[axis]);

    if( target_end[axis] <= range_start[axis] or range_end[axis] <= target_start[axis] ) { //has no intersection
#ifdef debug
        dout << "no intersection\n";
#endif
        return;
    }

    //    if( range_start[axis] <= target_start[axis] and target_end[axis] <= range_end[axis] ) { //completely including
    //
    //        if(1) {//leaf
    //        int i = 0;
    //        for(; i<ans.size() and ans[i] < p->id; i++);
    //        ans.insert(ans.begin()+i, p->id); //ans keeps sorted
    //        }
    //        else { //not leaf
    //            sub_rangeSearch(p, range_start, range_end, (axis+1)%k, target_start, target_end);
    //        }
    //    }

    //other case
    if( p->isInRange(range_start, range_end ) ) {
#ifdef debug
        dout << "p is in range\n";
        disp(p->id);
#endif
        ans.insert(p->id);
    }


    int tmp_target_start[k], tmp_target_end[k];

    memcpy(tmp_target_start, target_start, sizeof(tmp_target_start));
    memcpy(tmp_target_end, target_end, sizeof(tmp_target_end));

    tmp_target_end[axis] = p->d[axis];
#ifdef debug
    dout << "\n# " << p->id << " called sub " << (p->l==NULL?NONE:p->l->id) << " ( axis=" <<axis << ", " << tmp_target_start[0] << " <= x < " << tmp_target_end[0] << ", " << tmp_target_start[1] << " <= y < " << tmp_target_end[1] << " )\n";
#endif
    sub_rangeSearch(p->l, range_start, range_end, (axis+1)%k, tmp_target_start, tmp_target_end);


    memcpy(tmp_target_start, target_start, sizeof(tmp_target_start));
    memcpy(tmp_target_end, target_end, sizeof(tmp_target_end));

    tmp_target_start[axis] = p->d[axis];
#ifdef debug
    dout << "\n# " << p->id << " called sub " << (p->r==NULL?NONE:p->r->id) << " ( axis=" <<axis << ", " << tmp_target_start[0] << " <= x < " << tmp_target_end[0] << ", " << tmp_target_start[1] << " <= y < " << tmp_target_end[1] << " )\n";
#endif
    sub_rangeSearch(p->r, range_start, range_end, (axis+1)%k, tmp_target_start, tmp_target_end);

}


void rangeSearch(int range_start[k], int range_end[k]) { //[start, end)

#ifdef debug
    dout << "---------------- rangeSearch( " << range_start[0] << " <= x < " << range_end[0] << ", " << range_start[1] << " <= y < " << range_end[1] << " )\n";
#endif

    int target_start[k], target_end[k];
    rep(i,0,k) {
        target_start[i] = -INF;
        target_end[i] = INF;
    }

    sub_rangeSearch(root, range_start, range_end, 0, target_start, target_end);

}



