const int INF = (1<<19);

struct QuadTree{
private:
  struct node_t{
    vector<int>vals;
    node_t *tl,*tr,*bl,*br;

    node_t(){
      tl=tr=bl=br=NULL;
    }
  };

  node_t *root;

  node_t *insert(node_t *node,int ax,int ay,int bx,int by,int x,int y,int val){
    if(ax>x || x>bx || ay>y || y>by)return node;
    if(!node)node=new node_t();

    node->vals.push_back(val);

    if(ax==bx && ay==by)return node;

    int mx=(ax+bx)>>1,my=(ay+by)>>1;

    node->bl=insert(node->bl,ax,ay,mx,my,x,y,val);
    node->tl=insert(node->tl,ax,my+1,mx,by,x,y,val);
    node->br=insert(node->br,mx+1,ay,bx,my,x,y,val);
    node->tr=insert(node->tr,mx+1,my+1,bx,by,x,y,val);

    return node;
  }

  void getList(node_t *node,int ax,int ay,int bx,int by,
		      int x1,int y1,int x2,int y2,vector<int> &res) {
    if(!node || ax>x2 || x1>bx || ay>y2 || y1>by)return;
    if(x1<=ax && bx<=x2 && y1<=ay && by<=y2){
      res.insert(res.end(),all(node->vals));
      return;
    }
    int mx=(ax+bx)>>1,my=(ay+by)>>1;
    getList(node->bl,ax,ay,mx,my,x1,y1,x2,y2,res);
    getList(node->tl,ax,my+1,mx,by,x1,y1,x2,y2,res);
    getList(node->br,mx+1,ay,bx,my,x1,y1,x2,y2,res);
    getList(node->tr,mx+1,my+1,bx,by,x1,y1,x2,y2,res);
  }

public:

  QuadTree(){
    root=NULL;
  }

  void insert(int x,int y,int val){
    root=insert(root,0,0,INF-1,INF-1,x,y,val);
  }

  vector<int> getList(int x1,int y1,int x2,int y2) {
    vector<int>res;
    getList(root,0,0,INF-1,INF-1,x1,y1,x2,y2,res);
    sort(all(res));
    res.erase(unique(all(res)),res.end());
    return res;
  }
};

