int num = 0;
priority_queue<int, vector<int>, greater<int> > ans;

bool lessX(Point& p1, Point& p2) { return p1.x < p2.x; }
bool lessY(Point& p1, Point& p2) { return p1.y < p2.y; }

void setPoint(int n)
{
	int x, y;

	rep(i, n) {
		scanf("%d %d", &x, &y);
		P[i].id = i;
		P[i].x = x;
		P[i].y = y;
	}
}

void init_kDTree(int n)
{
	rep(i, n) {
		T[i].pid = NIL;
		T[i].ppos = NIL;
		T[i].left = NIL;
		T[i].right = NIL;
	}
}

int make_kDTree(int left, int right, int depth)
{
	int mid, index;

	if (left >= right) return NIL;

	if (depth % 2 == 0) sort(P + left, P + right, lessX);
	else sort(P + left, P + right, lessY);

	mid = (left + right) / 2;
	index = num++;

	T[index].pid = P[mid].id;
	T[index].ppos = mid;
	T[index].left = make_kDTree(left, mid, depth + 1);
	T[index].right = make_kDTree(mid + 1, right, depth + 1);

	return index;
}

void search_kDTree(int index, int depth, Point* sp, Point* tp)
{
	int Pid, Ppos, Px, Py, Tleft, Tright;

	Pid = T[index].pid;
	Ppos = T[index].ppos;
	Tleft = T[index].left;
	Tright = T[index].right;

	Px = P[Ppos].x;
	Py = P[Ppos].y;

	if (((sp->x) <= Px && Px <= (tp->x))
		&& ((sp->y) <= Py && Py <= (tp->y))) {
		ans.push(Pid);
	}

	if (depth % 2 == 0) {
		if ((sp->x) <= Px && Tleft != NIL) search_kDTree(Tleft, depth + 1, sp, tp);
		if ((tp->x) >= Px && Tright != NIL) search_kDTree(Tright, depth + 1, sp, tp);
	}
	else {
		if ((sp->y) <= Py && Tleft != NIL) search_kDTree(Tleft, depth + 1, sp, tp);
		if ((tp->y) >= Py && Tright != NIL) search_kDTree(Tright, depth + 1, sp, tp);
	}
}

int main()
{
	int n, q, sx, tx, sy, ty;
	Point sp, tp;

	scanf("%d", &n);

	setPoint(n);
	init_kDTree(n);
	make_kDTree(0, n, 0);

	scanf("%d", &q);
	rep(i, q) {
		scanf("%d %d %d %d", &sx, &tx, &sy, &ty);
		sp.x = sx;
		sp.y = sy;
		tp.x = tx;
		tp.y = ty;

		search_kDTree(0, 0, &sp, &tp);

		while (!ans.empty()) {
			printf("%d\n", ans.top());
			ans.pop();
		}
		putchar('\n');
	}

	return 0;
}

