int upper(vector<pair<int,int> > list,int l,int r,int t){
    int med = (l + r)/2;
    if (r-l == 1) {
        return l;
    }
    if(list[med].first <= t){
        return upper(list,med,r,t);
    }else{
        return upper(list,l,med,t);
    }
}

int downer(vector<pair<int,int> > list,int l,int r,int s){
    int med = (l + r)/2;
    if (r-l == 1){
        if (list[l].first == s){
            return l;
        }else{
            return r;
        }
    }
    if(list[med].first >= s){
        return downer(list,l,med,s);
    }else{
        return downer(list,med,r,s);
    }
}

void rec(int n,vector<pair<int,int> > listx,vector<pair<int,int> > listy,int xs,int xt,int ys,int yt){
    BR;
    int xis = downer(listx,0,n,xs);
    int xit = upper(listx,0,n,xt);
    int yis = downer(listy,0,n,ys);
    int yit = upper(listy,0,n,yt);

    priority_queue<int> ans;
    bool tbit[100000] = {};
    REP2(i,xis,xit) tbit[listx[i].second] = 1;
    REP2(i,yis,yit) {
        if(tbit[listy[i].second]){
            ans.push(-listy[i].second);
        }
    }
    while (!ans.empty()) {
        printf("%d\n",-ans.top());
        ans.pop();
    }
}

