vector<int> val[1048588], id[1048588], ret; int d;
void query(int a, int b, int vl, int vr, int k, int l, int r) {
	if(a <= l && r <= b) {
		int ptl = lower_bound(val[k].begin(), val[k].end(), vl) - val[k].begin();
		int ptr = lower_bound(val[k].begin(), val[k].end(), vr) - val[k].begin();
		for(int i = ptl; i < ptr; i++) ret.push_back(id[k][i]);
		return;
	}
	if(r <= a || b <= l) return;
	query(a, b, vl, vr, k * 2, l, (l + r) >> 1);
	query(a, b, vl, vr, k * 2 + 1, (l + r) >> 1, r);
}
