	sort(p, p + n, compare);
	vector<int> xs(n), ys(n);
	for(int i = 0; i < n; i++) tmp[i] = x[p[i]];
	for(int i = 0; i < n; i++) x[i] = tmp[i];
	for(int i = 0; i < n; i++) tmp[i] = y[p[i]];
	for(int i = 0; i < n; i++) y[i] = tmp[i];
	for(int i = 0; i < n; i++) {
		val[(1 << d) + i] = vector<int>({ y[i] });
		id[(1 << d) + i] = vector<int>({ p[i] });
	}
	for(int i = (1 << d) - 1; i >= 1; i--) {
		int pl = val[i * 2].size(), pr = val[i * 2 + 1].size();
		val[i].resize(pl + pr);
		id[i].resize(pl + pr);
		int lc = 0, rc = 0;
		while(lc + rc < pl + pr) {
			bool left = true;
			if(lc == pl) left = false;
			else if(rc != pr && val[i * 2][lc] > val[i * 2 + 1][rc]) left = false;
			if(left) {
				val[i][lc + rc] = val[i * 2][lc];
				id[i][lc + rc] = id[i * 2][lc];
				lc++;
			}
			else {
				val[i][lc + rc] = val[i * 2 + 1][rc];
				id[i][lc + rc] = id[i * 2 + 1][rc];
				rc++;
			}
		}
	}
	scanf("%d", &q);
	while(q--) {
		scanf("%d%d%d%d", &xa, &xb, &ya, &yb);
		int ptl = lower_bound(x, x + n, xa) - x;
