      depth = _depth;
      int axis = depth % k;
      if(axis == 0){
        sort(all(v),sortx);
      }
      else{
        sort(all(v),sorty);
      }
      auto med = v[v.size()/2];
      auto node = make_shared<kDTree>(kDTree(k));
      node->location = med;
      node->left = (constructTree(vector<datas>(v.begin(),v.begin()+v.size()/2),depth+1));
      node->right = (constructTree(vector<datas>(v.begin()+v.size()/2+1,v.end()),depth+1));
      return node;
    }
    void find(int x,int y,int x2,int y2){
      int axis = depth % k;
      if(axis == 0){
        if(x <= location.x && location.x <= x2){
          ans.push_back(location.i);
          if(left != nullptr)
            left->find(x,y,x2,y2);
          if(right != nullptr)
            right->find(x,y,x2,y2);
        }
        else if(location.x <= x){
          if(right != nullptr)
            right->find(x,y,x2,y2);
        }
        else if(location.x >= x2){
          if(left != nullptr)
            left->find(x,y,x2,y2);
        }
        else
          return ;
      }
      else{
        if(y <= location.y && location.y <= y2){
          ans.push_back(location.i);
          if(left != nullptr)
            left->find(x,y,x2,y2);
          if(right != nullptr)
            right->find(x,y,x2,y2);
        }
        else if(location.y <= y){
          if(right != nullptr)
            right->find(x,y,x2,y2);
        }
        else if(location.y >= y2){
          if(left != nullptr)
            left->find(x,y,x2,y2);
        }
        else{
          return ;
        }
      }
    }
    void insert(int x,int y,int i){
      int axis = depth % k;
      if(axis == 0){
        if(location.x < x){
          if(right == nullptr){
            auto node = make_shared<kDTree>(kDTree(k));
            node->depth = depth+1;
            node->location = {x,y,i};
            right = node;
          }
          else
            right->insert(x,y,i);
        }
        else{
          if(left == nullptr){
            auto node = make_shared<kDTree>(kDTree(k));
            node->depth = depth+1;
            node->location = {x,y,i};
            left = node;
          }
          else
            left->insert(x,y,i);
        }
      }
      else{
        if(location.y < y){
          if(right == nullptr){
