bool lessX(const Point &p1,const Point &p2){return p1.x<p2.x;}
bool lessY(const Point &p1,const Point &p2){return p1.y<p2.y;}

int maketree(int l,int r,int depth){
if(l>=r)return NIL;
int mid = (l+r)/2;
int t = np++;
if(depth%2==0)
sort(P+1,P+r,lessX);
else sort(P+1,P+r,lessY);
T[t].location = mid;
T[t].l = maketree(l,mid,depth+1);
T[t].r = maketree(mid+1,r,depth+1);
return t;
}

