int KDTree::build(std::vector<Vertex>& vertex, int low, int high, int depth) {
  if(!(low < high)) return NIL;
  std::sort(begin(vertex) + low, begin(vertex) + high, Compare(depth));
  int middle = (low + high) / 2;
  node_[middle].vertex = vertex[middle];
  node_[middle].left_child = build(vertex, low, middle, depth ^ 1);
  node_[middle].right_child = build(vertex, middle + 1, high, depth ^ 1);
  return middle;
}
