int node_index = 0;

int make2DTree(int l, int r, int depth)
{
  if (!(l < r))
  {
    return NIL;
  }
  int mid = (l + r) / 2;
  int t = node_index;
  node_index++;
  if (depth % 2 == 0)
  {
    // x軸を基準にソート
    sort(P.begin() + l, P.begin() + r, less_x);
  }
  else
  {
    // y軸を基準にソート
    sort(P.begin() + l, P.begin() + r, less_y);
  }
  T.at(t).location = mid;
  T.at(t).l = make2DTree(l, mid, depth + 1);
  T.at(t).r = make2DTree(mid + 1, r, depth + 1);

  return t;
}

void find(int v, int sx, int tx, int sy, int ty, int depth, vector<int> &ans)
{
  int x = P.at(T.at(v).location).x;
  int y = P.at(T.at(v).location).y;
  if (sx <= x && x <= tx && sy <= y && y <= ty)
  {
    ans.push_back(P.at(T.at(v).location).id);
  }

  if (depth % 2 == 0)
  {
    // x軸が基準のとき
    if (T.at(v).l != NIL && sx <= x)
    {
      find(T.at(v).l, sx, tx, sy, ty, depth + 1, ans);
    }
    if (T.at(v).r != NIL && x <= tx)
    {
      find(T.at(v).r, sx, tx, sy, ty, depth + 1, ans);
    }
  }
  else
  {
    // y軸が基準のとき
    if (T.at(v).l != NIL && sy <= y)
    {
      find(T.at(v).l, sx, tx, sy, ty, depth + 1, ans);
    }
    if (T.at(v).r != NIL && y <= ty)
    {
      find(T.at(v).r, sx, tx, sy, ty, depth + 1, ans);
    }
  }
}

