using namespace std;

class Node
{
    public:
        int location;  // 要素全体の位置 ( 昇順に並べた時 )
        int p, l, r;
        // コンストラクタ
        Node() {}
};

class Point
{
    public:
        int id, x, y;

        Point() {}
        // メンバ変数の初期化
        Point(int id, int x, int y): id(id), x(x), y(y) {}

        // 演算子のオーバーロード ( constメンバ関数 : メンバ変数の変更を禁止する)
        // main() 内の sort() で使用する
