    cin >> q;
    for(lli i = 0;i < q;i++){
        cin >> s[0] >> t[0] >> s[1] >> t[1];
        ans = vll();
        search(s,t,min_p,max_p,0,k.begin(),k.end());
        sort(ans.begin(),ans.end());
        for(lli i = 0;i < ans.size();i++) cout << ans[i] << endl;
        cout << endl;

    }
    return 0;
}

