int makeDTree(int l,int r,int depth){
	if(l>=r)	return NIL;
	int mid=(l+r)/2;
	int t=np++;
	if(depth%2==0)	sort(P+l,P+r,lessx);
	else 			sort(P+l,P+r,lessy);
