void sub_rangeSearch(kDTree *p, int range_start[k], int range_end[k], int axis, int target_start[k], int target_end[k]) {

    if(p==NULL) return;

    assert(range_start[axis] < range_end[axis]);
    assert(target_start[axis] < target_end[axis]);

    if( target_end[axis] <= range_start[axis] or range_end[axis] <= target_start[axis] ) //has no intersection
        return;

    //    if( range_start[axis] <= target_start[axis] and target_end[axis] <= range_end[axis] ) { //completely including
    //
    //        if(1) {//leaf
    //        int i = 0;
    //        for(; i<ans.size() and ans[i] < p->id; i++);
