    //        }
    //        else { //not leaf
    //            sub_rangeSearch(p, range_start, range_end, (axis+1)%k, target_start, target_end);
    //        }
    //    }

    //other case
    if( p->isInRange(range_start, range_end ) ) {
        ans.insert(p->id);
    }

    int tmp = target_end[axis];
    target_end[axis] = p->d[axis];
    sub_rangeSearch(p->l, range_start, range_end, (axis+1)%k, target_start, target_end);

    target_end[axis] = tmp;
    target_start[axis] = p->d[axis];
    sub_rangeSearch(p->r, range_start, range_end, (axis+1)%k, target_start, target_end);

}


void rangeSearch(int range_start[k], int range_end[k]) { //[start, end)

