struct Vertex {
    int label;
    double x, y;
    Vertex(int label = -1, double x = 0.0, double y = 0.0) :label(label), x(x), y(y) {}
};

class KDTree {
public:
    KDTree() :root_(std::unique_ptr<Node>(new Node())) {}
    void insert(const Vertex& v) {insert(root_, v, false);}
    void search(const Vertex& initial, const Vertex& terminal) const {search(root_, initial, terminal, false);}
private:
    struct Node {
        Vertex vertex;
        std::unique_ptr<Node> left_child;
        std::unique_ptr<Node> right_child;
        Node(const Vertex& vertex = Vertex()) :vertex(vertex), left_child(nullptr), right_child(nullptr) {}
    };
    bool compare(const Vertex& v1, const Vertex& v2, bool y_first) const {
        return y_first ? v1.y < v2.y : v1.x < v2.x;
    }
    void insert(std::unique_ptr<Node>& node, const Vertex& vertex, bool parity) {
        auto& next_node = compare(node->vertex, vertex, parity) ? node->left_child : node->right_child;
        if(next_node)   insert(next_node, vertex, !parity);
        else            next_node = std::unique_ptr<Node>(new Node(vertex));
    }
    void search(const std::unique_ptr<Node>& node, const Vertex& initial, const Vertex& terminal, bool parity) const {
        if(!node) return;
        if(initial.x <= node->vertex.x && node->vertex.x <= terminal.x && initial.y <= node->vertex.y && node->vertex.y <= terminal.y) {
            if(node->vertex.label != -1) answer.insert(node->vertex.label);
        }
        if(!compare(node->vertex, initial, parity)) search(node->right_child, initial, terminal, !parity);
        if(!compare(terminal, node->vertex, parity)) search(node->left_child, initial, terminal, !parity);
    }
    std::unique_ptr<Node> root_;
};

