		scanf ("%d %d", &x, &y );
		p[i].x = x, p[i].y = y; p[i].id = i-1;
	} // end rep
	sort (p+1, p+n+1, cmp );
	swap (p[1], p[n/2] );

	preprocess (n );

	scanf ("%d", &q );
	for (i = 0; i < q; i++ ){
		ans.clear();
		scanf ("%d %d %d %d", &sx0, &tx0, &sy0, &ty0 );
		struct rect r; r.x1 = sx0, r.y1 = sy0, r.x2 = tx0, r.y2 = ty0;
		tree2drange (head, r, 0 );
		set<int>::iterator it = ans.begin();
		for (; it != ans.end(); it++ ){
			int res = (*it);
			printf ("%d\n", res );
		} // end for
		printf ("\n" );
	} // end rep

	return 0;
}

