vector<int> ans;

class kDTree{
    shared_ptr<kDTree> left,right;
  public:
    int k;
    int depth;
    datas location;
    kDTree(){};
    kDTree(int _k){
      k = _k;
      left = nullptr;
      right =nullptr;
    }
    shared_ptr<kDTree> constructTree(vector<datas> v,int _depth){
      if(v.empty()) return nullptr;
      int axis = _depth % k;
      if(axis == 0){
        sort(all(v),sortx);
      }
      else{
        sort(all(v),sorty);
      }
      auto med = v[v.size()/2];
      auto node = make_shared<kDTree>(kDTree(k));
      node->location = med;
      node->left = (constructTree(vector<datas>(v.begin(),v.begin()+v.size()/2),_depth+1));
      node->right = (constructTree(vector<datas>(v.begin()+v.size()/2+1,v.end()),_depth+1));
      return node;
    }
    void find(int x,int y,int x2,int y2,int d){
      int axis = d % k;
      /* cout << location.i << ' ' << axis << endl; */
      if(x <= location.x && location.x <= x2 && y <= location.y && location.y <= y2){
        ans.push_back(location.i);
      }
      if(axis == 0){
        if(x <= location.x && location.x <= x2){
          if(left != nullptr)
            left->find(x,y,x2,y2,d+1);
          if(right != nullptr)
            right->find(x,y,x2,y2,d+1);
        }
        else if(location.x <= x){
          if(right != nullptr)
            right->find(x,y,x2,y2,d+1);
        }
        else if(location.x >= x2){
          if(left != nullptr)
            left->find(x,y,x2,y2,d+1);
        }
        else
          return ;
      }
      else{
        if(y <= location.y && location.y <= y2){
          if(left != nullptr)
            left->find(x,y,x2,y2,d+1);
          if(right != nullptr)
            right->find(x,y,x2,y2,d+1);
        }
        else if(location.y <= y){
          if(right != nullptr)
            right->find(x,y,x2,y2,d+1);
        }
        else if(location.y >= y2){
          if(left != nullptr)
            left->find(x,y,x2,y2,d+1);
        }
        else{
          return ;
        }
      }
    }
    void insert(int x,int y,int i){
      int axis = depth % k;
      if(axis == 0){
        if(location.x < x){
          if(right == nullptr){
            auto node = make_shared<kDTree>(kDTree(k));
            node->depth = depth+1;
            node->location = {x,y,i};
            right = node;
          }
          else
            right->insert(x,y,i);
        }
        else{
          if(left == nullptr){
            auto node = make_shared<kDTree>(kDTree(k));
            node->depth = depth+1;
            node->location = {x,y,i};
            left = node;
          }
          else
            left->insert(x,y,i);
        }
      }
      else{
        if(location.y < y){
          if(right == nullptr){
            auto node = make_shared<kDTree>(kDTree(k));
            node->depth = depth+1;
            node->location = {x,y,i};
            right = node;
          }
          else
            right->insert(x,y,i);
        }
        else{
          if(left == nullptr){
            auto node = make_shared<kDTree>(kDTree(k));
            node->depth = depth+1;
            node->location = {x,y,i};
            left = node;
          }
          else
            left->insert(x,y,i);
        }
      }
    }
    void show(int k){
      rep(i,k){
        cout << "  ";
      }
      cout << location.x << ' ' << location.y << ' ' << location.i << endl;
      if(left != nullptr){
        left->show(k+1);
      }
      if(right != nullptr){
        right->show(k+1);
      }
    }
};

