        ans.push_back(nd->mid.id);
        if(nd->left != NULL) rangeSearch(nd->left, depth+1);
        if(nd->right != NULL) rangeSearch(nd->right, depth+1);
    }else if(depth%2==0){
        if(nd->mid.x < sx){
            if(nd->right != NULL) rangeSearch(nd->right, depth+1);
        }else if(tx < nd->mid.x){
            if(nd->left != NULL) rangeSearch(nd->left, depth+1);
        }else{
            if(nd->left != NULL) rangeSearch(nd->left, depth+1);
            if(nd->right != NULL) rangeSearch(nd->right, depth+1);
        }
    }else if(depth%2==1){
        if(nd->mid.y < sy){
            if(nd->right != NULL) rangeSearch(nd->right, depth+1);
        }else if(ty < nd->mid.y){
            if(nd->left != NULL) rangeSearch(nd->left, depth+1);
        }else{
            if(nd->left != NULL) rangeSearch(nd->left, depth+1);
            if(nd->right != NULL) rangeSearch(nd->right, depth+1);
        }
    }

    // printf("x=%d, y=%d, dpth=%d\n", nd->mid.x, nd->mid.y, depth);
}

