  }
  int root = Build(0, n - 1, 0);
  set<int> res;
  cin >> q;
  while (cin >> x1 >> x2 >> y1 >> y2) {
    res.clear();
    Find(root, 0, x1, x2, y1, y2, res);
    for (int x : res)
      cout << x << endl;
    cout << endl;
  }
}

