  for(int i = 0; i < q; ++i) {
    double sx, tx, sy, ty;
    cin >> sx >> tx >> sy >> ty;
    answer.clear();
    t.search({sx, sy}, {tx, ty});
    sort(begin(answer), end(answer));
    for(auto a: answer) cout << a << endl;
    cout << endl;
  }
}

