void build(int d , int b , int e )
{
    if (b == e) {
        st[d][b] = x[b].second;
        return;
    }
    int m = (b + e) >> 1;
    build(d + 1, b, m);
    build(d + 1, m + 1, e);
    int l = b, r = m + 1;
    for (int pt = b; pt <= e; ++pt) // p = point ha
        if (r == e + 1 || y[st[d + 1][l]] < y[st[d + 1][r]])
            st[d][pt] = st[d + 1][l++];
        else
            st[d][pt] = st[d + 1][r++];
}
