    cin >> sx >> tx >> sy >> ty;

    vector<int>res=t.getList(sx+mxy,sy+mxy,tx+mxy,ty+mxy);
    for(int j=0;j<res.size();j++)
      cout << res[j] << endl;

    printf("\n");
  }

  return 0;
}

