template<typename T>
class KdTree {
public:

  struct Data{
    int id = -1;
    std::vector<T> v;
    Data(std::initializer_list<T> list, int _id = -1): v(list), id(_id) {}

    Data()                             = default;
    Data(const Data &other)            = default;
    Data& operator=(const Data &other) = default;
    Data(Data &&other)                 = default;
    Data& operator=(Data &&other)      = default;

