      for(int i = 0; i < v.size(); ++i) {
        if(!(v[i] < rhs.v[i])) return false;
      }
      return true;
    }
    bool operator>(const Data &rhs) const {
      for(int i = 0; i < v.size(); ++i) {
        if(!(v[i] > rhs.v[i])) return false;
      }
      return true;
    }
    bool operator<=(const Data &rhs) const {
      for (int i = 0; i < v.size(); ++i)
      {
        if(!(v[i] <= rhs.v[i])) return false;
      }
      return true;
    }
    bool operator>=(const Data &rhs) const {
      for (int i = 0; i < v.size(); ++i)
      {
        if(!(v[i] >= rhs.v[i])) return false;
      }
      return true;
    }

    std::string to_string() const{
      std::stringstream ss;
      std::string str_id = id == -1 ? std::string("-") : std::to_string(id);
      ss << "Data{" << str_id << ": ";
      for(auto&& i : v) {
        ss << i << " ";
      }
      ss << "}";
      return ss.str();
    }
  };

private:

  struct Node{
    int axis;
    Data data;
    Node *left, *right;
    Node(int a, Data d):
      axis(a), data(d), left(nullptr), right(nullptr) {}
    ~Node(){
      delete left;
      delete right;
    }
    std::string to_string() const{
      std::stringstream ss;
      ss << "Node at " << this << " {\n";
      ss << "\taxis: " << axis << "\n";
      ss << "\tdata: " << data.to_string() << "\n";
      ss << "\tleft: " << left << "\n";
      ss << "\tright: " << right << "\n}";
      return ss.str();
    }
  };

  int k_; // number of axes
  int n_; // number of points
  std::vector<Data> points_;
  Node *root;
  Data lower_limit_, upper_limit_;

  class AxisSorter{
    int k_;
  public:
    AxisSorter(int k): k_(k){}
    inline bool operator()(const Data& lhs, const Data& rhs){
      return lhs.v[k_] < rhs.v[k_];
    }
  };

  void _BuildTree(Node **t, int depth, size_t left, size_t right) noexcept;
  void _Find(std::vector<Data> &out, Node *node,
             const Data &s, const Data &t,
             const Data &lower_limit, const Data &upper_limit) noexcept;

public:

  KdTree() = delete;
  KdTree(KdTree<T> &other) = delete;
  KdTree(KdTree<T> &&other) = default;
  KdTree(std::vector<Data> &&vec, Data min, Data max);
  ~KdTree(){
    delete root;
  }
  std::vector<Data> Find(Data s, Data t);
  void BuildTree(){
    _BuildTree(&root, 0, 0, n_);
  }
  void Dump() noexcept;
};

template<typename T>
KdTree<T>::KdTree(std::vector<Data> &&vec, Data min, Data max)
  : lower_limit_(min), upper_limit_(max), points_(vec)
{
  // assert(!vec.empty());
  // assert(!vec[0].v.empty());
  n_ = vec.size();
  k_ = vec[0].v.size();

  BuildTree();
}

template<typename T>
void KdTree<T>::_BuildTree(Node **t, int depth, size_t left, size_t right) noexcept {
  // printf("depth: %d, left: %zu, right: %zu\n", depth, left, right);
  // assert(left <= right);
  int axis = depth % k_;
  int size = right - left;
  if(size < 1) return;
  else if(size < 2) {
    *t = new Node{axis, points_[left]};
    return;
  }
  std::sort(points_.begin() + left, points_.begin() + right, AxisSorter(axis));
  int mid = left + (size >> 1);
  *t = new Node{axis, points_[mid]};
  _BuildTree(&(*t)->left, depth + 1, left, mid);
  _BuildTree(&(*t)->right, depth + 1, mid + 1, right);
}

template<typename T>
void KdTree<T>::Dump() noexcept {
  // std::cout << "KdTree<" << typeid(T).name() << ">::Dump()\n";
  std::queue<Node*> que;
  que.push(root);
  int pre = -1;
  while(!que.empty()) {
      Node *p = que.front();
      que.pop();
      if(p == nullptr) continue;
      if(pre < 0 || pre != p->axis){
        // std::cout << std::endl << "axis " << p->axis << ":\n\t";
        pre = p->axis;
      }
      if(p->data.v.empty()) continue;
      // std::cout << "(";
      for(int i = 0; i < p->data.v.size() - 1; ++i)
        // std::cout << p->data.v[i] << ", ";
      // std::cout << p->data.v.back() << ") ";
      que.push(p->left);
      que.push(p->right);
  }
  // std::cout << std::endl;
  // std::cout << "KdTree<" << typeid(T).name() << ">::Dump() end\n";
}

template<typename T>
void KdTree<T>::_Find(
  std::vector<Data> &out, Node *node,
  const Data &s, const Data &t,
  const Data &lower_limit, const Data &upper_limit) noexcept
{
  if(!node) return;
  // DUMP
  // std::cout << "\n-----_Find() DUMP:--------\n";
  // std::cout << "node: " << node->to_string() << "\n";
  // std::cout << "s: " << s.to_string() << "\n";
  // std::cout << "t: " << t.to_string() << "\n";
  // std::cout << "lower_limit: " << lower_limit.to_string() << "\n";
  // std::cout << "upper_limit: " << upper_limit.to_string() << "\n";
  // std::cout << "-----_Find() DUMP end-----\n\n";
  // DUMP end
  // assert(s <= t);
  if(s <= lower_limit && upper_limit <= t) {
    // std::cout << "all insertion\n";
    std::queue<Node*> que;
    que.push(node);
    while(!que.empty()) {
        Node* p = que.front();
        que.pop();
        if(!p) continue;
        out.push_back(p->data);
      // std::cout << "\tout.push_back(" << p->data.to_string() << ")\n";
        que.push(p->left);
        que.push(p->right);
    }
    return;
  }
  if(upper_limit < s || t < lower_limit) {
    // std::cout << "no overlap\n";
    return;
  }

  if(lower_limit <= node->data && node->data <= upper_limit)
    // std::cout << "out.push_back(" << node->data.to_string() << ")\n";
    out.push_back(node->data);

  auto ll = lower_limit, uu = upper_limit;
  ll.v[node->axis] = std::max<T>(ll.v[node->axis], node->data.v[node->axis]);
  uu.v[node->axis] = std::min<T>(uu.v[node->axis], node->data.v[node->axis]);

  T criterion = node->data.v[node->axis];
  if(t.v[node->axis] <= criterion) {
    // std::cout << "left only recursion\n";
    _Find(out, node->left, s, t, lower_limit, uu);
  }
  else if(criterion <= s.v[node->axis]){
    // std::cout << "right only recursion\n";
    _Find(out, node->right, s, t, ll, upper_limit);
  }
  else{
    // std::cout << "both side recursion\n";
    _Find(out, node->left, s, t, lower_limit, uu);
    _Find(out, node->right, s, t, ll, upper_limit);
  }
}

template<typename T>
std::vector<typename KdTree<T>::Data> KdTree<T>::Find(
  Data s, Data t)
{
  for(int i = 0; i < s.v.size(); ++i)
    if(s.v[i] > t.v[i]) std::swap(s.v[i], t.v[i]);
  if(s <= lower_limit_) s = lower_limit_;
  if(t >= upper_limit_) t = upper_limit_;
  std::vector<KdTree<T>::Data> ret;
  _Find(ret, root, s, t, lower_limit_, upper_limit_);
  return ret;
}


