using namespace std;

const int NIL = -1;

struct Node {
    int location = 0;
    int l, r;

    Node(int l = NIL, int r = NIL) : l(l), r(r) {
    }
};

struct Point {
    int id;
    int x;
    int y;

    Point(int id = 0, int x = 0, int y = 0) : id(id), x(x), y(y) {
    }

    bool operator<(const Point& other) const {
        return id < other.id;
    }
};

bool cmpX(const Point& a, const Point& b) {
    return a.x < b.x;
}

bool cmpY(const Point& a, const Point& b) {
    return a.y < b.y;
}

struct KD {
    int n;
    vector<Point> points;
    vector<Node> heap;
    int np = 0;
    int root = 0;

    KD(const vector<Point>& p) : points(p) {
        n = p.size();
        heap.assign(4 * n, Node());
        root = makeTree(0, n, 0);
    }

    //[l, r)
    int makeTree(int l, int r, int depth) {
        if (l >= r) {
            return NIL;
        }
        int m = l + (r - l) / 2;
        int t = np++;

        if (depth % 2 == 0) {
            sort(points.begin() + l, points.begin() + r, cmpX);
        } else {
            sort(points.begin() + l, points.begin() + r, cmpY);
        }

        heap[t].location = m;
        heap[t].l = makeTree(l, m, depth + 1);
        heap[t].r = makeTree(m + 1, r, depth + 1);

        return t;
    }

      void find(int sx, int tx, int sy, int ty, vector<Point>& ans) {
          find(root, sx, tx, sy, ty, 0, ans);
      }

    void find(int v, int lx, int hx, int ly, int hy, int depth, vector<Point>& ans) {

        int x = points[heap[v].location].x;
        int y = points[heap[v].location].y;

        if (lx <= x && x <= hx && ly <= y && y <= hy) {
            ans.push_back(points[heap[v].location]);
            //cout << p[heap[v].locaion].id << " " << p[heap[v].locaion].x << endl;
        }

        if (depth % 2 == 0) {
            if (heap[v].l != NIL && lx <= x) {
                find(heap[v].l, lx, hx, ly, hy, depth + 1, ans);
            }
            if (heap[v].r != NIL && x <= hx) {
                find(heap[v].r, lx, hx, ly, hy, depth + 1, ans);
            }
        }

        else {
            if (heap[v].l != NIL && ly <= y) {
                find(heap[v].l, lx, hx, ly, hy, depth + 1, ans);
            }
            if (heap[v].r != NIL && y <= hy) {
                find(heap[v].r, lx, hx, ly, hy, depth + 1, ans);
            }
        }
    }

    void printStats() {
        for (int i = 0; i < np; i++) {
            Node& node = heap[i];
            cout << i << " Loc: " << node.location << " Id: " << points[node.location].id 
                    << " L: " << node.l << " R: " << node.r 
                    << " (" << points[node.location].x << ","<< points[node.location].y << ")"
                    << endl;
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<Point> points;
    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        points.push_back(Point(i, x, y));
    }

    KD kd(points);

    //kd.printStats();

    int q;
    cin >> q;
    int lx, hx, ly, hy;
    vector<Point> ans;
    for (int i = 0; i < q; i++) {
        cin >> lx >> hx >> ly >> hy;
        ans.clear();
        kd.find(lx, hx, ly, hy, ans);
        sort(ans.begin(), ans.end());
        for (int j = 0; j < ans.size(); j++) {
            cout << ans[j].id << endl;
        }
        cout << endl;

    }
    return 0;
}

