const int K = 2;
class kDTree{
  public:
    int depth;
    ll n;
    vector<datas> nodes,tree;
    kDTree(){};
    kDTree(vector<datas> &v): n(v.size()),nodes(n),tree(n){
      rep(i,n){
        nodes[i] = v[i];
      }
      build(0,n,0);
    }
    void build(int l,int r,int _depth){
      if(l >= r) return ;
      int m = (l+r)/2;
      int axis = _depth % K;
      auto first = nodes.begin() + l, nth = nodes.begin() + m, last = nodes.begin() + r;
      if (axis == 0)
            nth_element(first, nth, last, sortx);
        else
            nth_element(first, nth, last, sorty);
      tree[m] = *nth;
      build(l,m,_depth+1);
      build(m+1,r,_depth+1);
    }
