struct po {
	int index;
	vector<int>coors;
	po(int _d) : coors(_d) {}
	po() {}
};
template<class T>
class axisSorter {
	int k;
public:
	axisSorter(int _k) : k(_k) {}
	bool operator()(const T &a, const T &b) {
		return a.coors[k] < b.coors[k];
	}
};
template<class T,int Dim = 2>
struct kdtree {
public:
	T val;
	kdtree<T> *ltree, *rtree;
	int depth;
	kdtree(const T &p_) :val(p_), ltree(nullptr), rtree(nullptr){

	}

	kdtree(vector<T>&ps_,const int l,const int r,const int depth_=0): ltree(nullptr), rtree(nullptr),depth(depth_) {
		init(ps_,l,r);
	}
	vector<T>query(const T & amin, const T&amax) {
		vector<T>ans;
		bool aok = true;
		for (int i = 0; i < Dim; ++i) {
			if (amin.coors[i] <= val.coors[i] && val.coors[i] <= amax.coors[i]) {

			}
			else {
				aok = false;
				break;
			}
		}
		if (aok) {
			ans.emplace_back(val);
		}
		const int axis = depth%Dim;
		axisSorter<T> as(axis);
		if (as(val, amax)||val.coors[axis]==amax.coors[axis]) {
			if (rtree != nullptr) {
				vector<T>tans(rtree->query(amin, amax));
				ans.insert(ans.end(), tans.begin(), tans.end());
			}
		}
		if (as(amin, val) || val.coors[axis] == amax.coors[axis]) {
			if (ltree != nullptr) {
				vector<T>tans(ltree->query(amin, amax));
				ans.insert(ans.end(), tans.begin(), tans.end());
			}
		}
		return ans;
	}
private :
	void init(vector<T>&ps,const int l,const int r) {
		if (l >= r) {
			return;
		}
		sort(ps.begin()+l, ps.begin()+r, axisSorter<T>(depth%Dim));
		const int mid = (l + r) / 2;
		val = ps[mid];
		ltree = make_kdtree(ps, l, mid, depth + 1);
		rtree = make_kdtree(ps,mid+1,r, depth + 1);
	}

};
template<class T>
kdtree<T> *make_kdtree(vector<T>&ps_, const int l, const int r, const int depth = 0) {
	if (l >= r)return nullptr;
	else {
		return new kdtree<T>(ps_, l, r, depth);
	}
}
