static const int NIL = -1;
static const int MAX =1000010;
int N;
Point P[MAX];
Node T[MAX];
int np;

bool lessX(const Point &p1,const Point &p2){return p1.x<p2.x;}//结点按照x排序
bool lessY(const Point &p1,const Point &p2){return p1.y<p2.y;}//结点按照y排序

int maketree(int l,int r,int depth){//递归构造二叉树
if(l>=r)return NIL;
int mid = (l+r)/2;
int t = np++;

if(depth%2==0)//按层给x和y交替排序构成二叉树
sort(P+l,P+r,lessX);//按照x排序
else sort(P+l,P+r,lessY);//按照y排序

T[t].location = mid;
T[t].l = maketree(l,mid,depth+1);
T[t].r = maketree(mid+1,r,depth+1);

return t;
}

void find(int v,int sx,int tx,int sy,int ty,int depth,vector<Point> &ans){//寻找范围内的点
int x = P[T[v].location].x;
int y = P[T[v].location].y;

if(sx<=x&&x<=tx&&sy<=y&&y<=ty)
ans.push_back(P[T[v].location]);

if(depth%2==0){//按x和y分层的构造方式,采取对应的分层查找方法
if(T[v].l!=NIL&&x>=sx)
find(T[v].l,sx,tx,sy,ty,depth+1,ans);
if(T[v].r!=NIL&&x<=tx)
find(T[v].r,sx,tx,sy,ty,depth+1,ans);
}
else{
if(T[v].l!=NIL&&y>=sy)
find(T[v].l,sx,tx,sy,ty,depth+1,ans);
if(T[v].r!=NIL&&y<=ty)
find(T[v].r,sx,tx,sy,ty,depth+1,ans);
}
}

