template<class T>
struct RangeTree{
    int size;
    vector<vector<T>> seg;
    RangeTree(int N){
        size=1;
        while(size<N) size<<=1;
        seg.assign(2*size,vector<T>());
    }
    void set(int k,T x){
        seg[k+size].push_back(x);
    }
    void build(){
        for(int k=2*size-1;k>=size;k--){
            sort(seg[k].begin(),seg[k].end());
        }
        for(int k=size-1;k>0;k--){
            int x=seg[2*k].size()+seg[2*k+1].size();
            merge(seg[2*k].begin(),seg[2*k].end(),seg[2*k+1].begin(),seg[2*k+1].end(),back_inserter(seg[k]));
        }
    }
    //seg[k]のx以上y以下をpush
    inline void push(int k,T &x,T &y,vector<T> &ret){
        int itr1=lower_bound(seg[k].begin(),seg[k].end(),x)-seg[k].begin();
        int itr2=upper_bound(seg[k].begin(),seg[k].end(),y)-seg[k].begin();
        copy(seg[k].begin()+itr1,seg[k].begin()+itr2,back_inserter(ret));
    }

    //[a:b)のx以上y以下を全列挙
    vector<T> query(int a,int b,T x,T y){
        vector<T> ret;
        for(a+=size,b+=size;a<b;a>>=1,b>>=1){
            if(a&1) push(a,x,y,ret),a++;
            if(b&1) push(b-1,x,y,ret),b--;
        }
        return ret;
    }
};

template<class T>
struct Compress{
    vector<T> cv; //順番にして重複を消したもの
    bool flag;
    Compress():flag(false){};

    Compress(const vector<T> &v):flag(false){
        add(v);
    }
    //vectorを追加
    void add(const vector<T> &v){
        flag=false;
        copy(v.begin(),v.end(),back_inserter(cv));
    }
    //Tを追加
    void add(const T x){
        flag=false;
        cv.emplace_back(x);
    }
    //テーブルを作る O(NlogN)
    void build(){
        flag=true;
        sort(cv.begin(),cv.end());
        cv.erase(unique(cv.begin(),cv.end()),cv.end());
    }
    //vectorの要素を座標圧縮したものを返す O(NlogN)
    vector<int> get(const vector<T> &v) const{
        assert(flag);
        vector<int> ret(v.size());
        for(int i=0;i<v.size();i++) ret[i]=lower_bound(cv.begin(),cv.end(),v[i])-cv.begin();
        return ret;
    }
    //xを座標圧縮したものを返す O(logN)
    int get(const T x)const{
        return lower_bound(cv.begin(),cv.end(),x)-cv.begin();
    }
    //座標圧縮後のkが示す実際の値 O(1)
    T &operator[](int k){
        return cv[k];
    }
};
