    const point &p = t->p;
    if (real(ld) <= real(p) && real(p) <= real(ru) &&
        imag(ld) <= imag(p) && imag(p) <= imag(ru)) out.push_back(t->id);
    if (!compare(d,p,ld)) search(t->l, !d, ld, ru, out);
    if (!compare(d,ru,p)) search(t->r, !d, ld, ru, out);
  }
};

