}

Node * Tree::make2DTree(int l, int r, int depth) {
    if(l >= r) return nullptr;
    int mid = (l + r) / 2;
    if(depth % 2 == 0) sort(P + l, P + r, lessX);
    else sort(P + l, P + r, lessY);

    auto node = new Node;
    node -> location = mid;
    node -> l = make2DTree(l, mid, depth + 1);
    node -> r = make2DTree(mid + 1, r, depth + 1);
