        if(node -> l != nullptr && sx <= P[node -> location].x) find(node -> l, sx,tx, sy, ty, depth + 1, ans);
        if(node -> r != nullptr && P[node -> location].x <= tx) find(node -> r, sx,tx, sy, ty, depth + 1, ans);
