Point flip(const Point &p) { return {p.y, p.x, 0}; }

bool operator<(const Point &p1, const Point &p2) {
  return p1.x < p2.x or (p1.x == p2.x and p1.y < p2.y);
}
bool operator==(const Point &p1, const Point &p2) {
  return !(p1 < p2) and !(p2 < p1);
}
bool operator<=(const Point &p1, const Point &p2) {
  return (p1 < p2) or (p1 == p2);
}

