template<typename T> class segtree
{
public:
    using ptt = pair<T,T>;
    vector<ptt> org,sorg;
    vector<vector<int> > id;
    vector<vector<T> > apl;
    //各座標が値(val)を持っているとき
    // vector<T> val;
    int n,sz;
    segtree(vector<ptt>& vec){
        sz = (int)vec.size();
        n = 1;
        while(n < sz){
            n *= 2;
        }
        org = vec, sorg = org;
        sort(all(sorg));
        id.resize(2*n-1), apl.resize(2*n-1);
        vector<int> index(sz);
        iota(all(index),0);
        sort(all(index),[&](int a, int b){
            return org[a] < org[b];
        });
        rep(i,sz){
            id[i+n-1].push_back(index[i]);
            apl[i+n-1].push_back(org[index[i]].second);
        }
        for(int i = n-2; i >= 0; i--){
            id[i].resize((int)id[2*i+1].size()+id[2*i+2].size());
            merge(all(id[2*i+1]),all(id[2*i+2]),id[i].begin(),[&](int a, int b){
                return org[a].second < org[b].second;
            });
            apl[i].resize((int)id[i].size());
            rep(j,(int)id[i].size()){
                apl[i][j] = org[id[i][j]].second;
            }
        }
    }
    vector<int> query(int a,int b,const T infy,const T supy,int k=0,int l=0,int r=-1)
    {
        if(r < 0) r = n;
        if(r <= a || b <= l){
            return vector<int>();
        }
        if(a <= l && r <= b){
            int lid = lower_bound(all(apl[k]),infy) - apl[k].begin();
            int rid = upper_bound(all(apl[k]),supy) - apl[k].begin();
            vector<int> ans(rid-lid);
            for(int i = lid; i < rid; i++){
                ans[i-lid] = id[k][i];
            }
            sort(all(ans));
            return ans;
        }else{
            vector<int> vl = query(a,b,infy,supy,2*k+1,l,(l+r)/2);
            vector<int> vr = query(a,b,infy,supy,2*k+2,(l+r)/2,r);
            vector<int> res((int)vl.size()+(int)vr.size());
            merge(all(vl),all(vr),res.begin());
            return res;
        }
    }
    //左下がl,右上がrの長方形領域に含まれる点の個数
    void query(const ptt l, const ptt r)
    {
        int lid = lower_bound(all(sorg),l) - sorg.begin();
        int rid = upper_bound(all(sorg),r) - sorg.begin();
        vector<int> ans = query(lid,rid,l.second,r.second);
        rep(i,len(ans)){
            cout << ans[i] << "\n";
        }
    }
};

