bool lessX(const Point &p1, const Point &p2) {
	return (p1.x == p2.x) ? (p1.y < p2.y) : (p1.x < p2.x);
}
bool lessY(const Point &p1, const Point &p2) {
	return (p1.y == p2.y) ? (p1.x < p2.x) : (p1.y < p2.y);
}
struct KDTree {
	struct Node {
		int index, l, r;
		Node() {}
		Node(int index, int l, int r) :index(index), l(l), r(r) {}
	};
	vector<Node>nodes; vector<Point>points, ret;
	int n, root, nn;
	KDTree(const vector<Point>&p) :points(p), n(p.size()), nn(0) {
		nodes.resize(n);
		root = makeKDTree(0, n, true);
	}
	int makeKDTree(int l, int r, bool is_x_base) {
		if (!(l < r))return NIL;
		int mid = (l + r) / 2, t = nn++;
		vector<Point>::iterator first = points.begin() + l,
			nth = points.begin() + mid, last = points.begin() + r;
		if (is_x_base)nth_element(first, nth, last, lessX);
		else nth_element(first, nth, last, lessY);
		nodes[t] = Node(mid, makeKDTree(l, mid, !is_x_base), makeKDTree(mid + 1, r, !is_x_base));
		return t;
	}
	bool inrange(const Point&z, const Point&p1, const Point&p2) {
		return p1.x <= z.x&&z.x <= p2.x&&p1.y <= z.y&&z.y <= p2.y;
	}
	vector<Point> find(Point&s, Point&t) {
		ret.clear();
		return find(root, true, s, t);
	}
	vector<Point> find(int v, bool is_x_base, const Point&s, const Point&t) {
		Point u = points[nodes[v].index];
		Node node = nodes[v];
		if (inrange(u, s, t))ret.emplace_back(u);
		if (is_x_base) {
			if (node.l != NIL && s.x <= u.x)find(node.l, !is_x_base, s, t);
			if (node.r != NIL && u.x <= t.x)find(node.r, !is_x_base, s, t);
		}
		else {
			if (node.l != NIL && s.y <= u.y)find(node.l, !is_x_base, s, t);
			if (node.r != NIL && u.y <= t.y)find(node.r, !is_x_base, s, t);
		}
		return ret;
	}
};
