KDTree::KDTree(const std::vector<Vertex>& vertex) {
  for(int i = 0; i < vertex.size(); ++i) vertex_[i] = vertex[i];
  root_ = build(0, vertex.size(), 0);
}
// ?§????
int KDTree::build(int low, int high, int depth) {
  if(!(low < high)) return NIL;
  std::sort(vertex_ + low, vertex_ + high, Compare(depth));
  int middle = (low + high) / 2;
  node_[middle].index = middle;
  node_[middle].left_child = build(low, middle, depth ^ 1);
  node_[middle].right_child = build(middle + 1, high, depth ^ 1);
  return middle;
}
