class kD_tree{
  public:
    struct Node{
      ll pos;
      ll par, lef, rig;
      Node() {}
    };
    struct Point{
      ll id;
      ll x, y;
      bool operator < (const Point &p){
        return id < p.id;
      }
    };

  private:
    ll N;
    ll np = 0;
    const ll NIL = -1;

  public:
    vector<Node> T;
    vector<Point> P;

    static bool lessX(const Point &p1, const Point &p2) {return p1.x < p2.x;}
    static bool lessY(const Point &p1, const Point &p2) {return p1.y < p2.y;}

    kD_tree(ll n){
      N = n;
      T.resize(N); P.resize(N);
    }

    ll make_tree(ll l, ll r,ll depth){
      if(l >= r) return NIL;

      ll mid = (l + r) / 2;
      ll t = np++;
      if(depth%2 == 0) sort(P.begin()+l,P.begin()+r,lessX);
      else sort(P.begin()+l,P.begin()+r,lessY);

      T[t].pos = mid;
      T[t].lef = make_tree(l,mid,depth+1);
      T[t].rig = make_tree(mid+1,r,depth+1);

      return t;
    }

    void find(ll v, ll sx, ll tx, ll sy, ll ty, ll depth, vector<Point> &ans){
      ll x = P[T[v].pos].x;
      ll y = P[T[v].pos].y;
      if(sx <= x && x <= tx && sy <= y && y <= ty){
        ans.push_back(P[T[v].pos]);
      }

      if(depth % 2 == 0){
        if(T[v].lef != NIL && sx <= x){
          find(T[v].lef, sx, tx, sy, ty, depth+1, ans);
        }
        if(T[v].rig != NIL && x <= tx){
          find(T[v].rig, sx, tx, sy, ty, depth+1, ans);
        }
      }
      else{
        if(T[v].lef != NIL && sy <= y){
          find(T[v].lef, sx, tx, sy, ty, depth+1, ans);
        }
        if(T[v].rig != NIL && y <= ty){
          find(T[v].rig, sx, tx, sy, ty, depth+1, ans);
        }
      }
    }
};
