struct point {
	int index;
	int x, y;

	point() {
		x=INT_MIN;y=INT_MIN;
		index = -1;
	}

	point(int in_index, int in_x, int in_y) {
		index = in_index;
		x = in_x;
		y = in_y;
	}
};

struct node {
	point p;
	node* left, * right;

	node() {
		p= point();
		left = NULL;
		right = NULL;
	}
};

bool compareX(const point& p1,const point& p2)
{
	return p1.x < p2.x;
}

bool compareY(const point& p1,const point& p2)
{
	return p1.y < p2.y;
}

point* sortX(point* p_start, point* p_end) {
	sort(p_start, p_end, compareX);
	return p_start+(p_end-p_start)/2;
}

point* sortY(point* p_start, point* p_end) {
	sort(p_start, p_end, compareY);
	return p_start+(p_end-p_start)/2;
}

void build(node* n_node, point* p_start, point* p_end, int index) {
	point* mid = index % 2 ? sortY(p_start, p_end) : sortX(p_start, p_end);
	if(p_start>=p_end)
		return;
	n_node->p = *mid;
	n_node->left = new node();
	n_node->right = new node();
	build(n_node->left, p_start, mid, index+1);
	build(n_node->right, mid + 1, p_end, index+1);
}

void search(int sx, int tx, int sy, int ty, node* now, int index, vector<int> &ans) {
	if(now == NULL) {
		return;
	}
	if(index %2) {
		if(now->p.y >= sy && now->p.y <= ty) {
			if(now->p.x >= sx && now->p.x <= tx) {
				ans.push_back(now->p.index);
			}
			search(sx, tx, sy, ty, now->left, index + 1, ans);
			search(sx, tx, sy, ty, now->right, index + 1, ans);
		}
		else if(now->p.y < sy) {
			search(sx, tx, sy, ty, now->right, index + 1, ans);
		}
		else if(now->p.y > ty) {
			search(sx, tx, sy, ty, now->left, index + 1, ans);
		}
	}
	else {
		if(now->p.x >= sx && now->p.x <= tx) {
			if(now->p.y >= sy && now->p.y <= ty) {
				ans.push_back(now->p.index);
			}
			search(sx, tx, sy, ty, now->left, index + 1, ans);
			search(sx, tx, sy, ty, now->right, index + 1, ans);
		}
		else if(now->p.x < sx) {
			search(sx, tx, sy, ty, now->right, index + 1, ans);
		}
		else if(now->p.x > tx) {
			search(sx, tx, sy, ty, now->left, index + 1, ans);
		}
	}
}

