std::set<int> answer;

class KDTree {
private:
    typedef std::vector<double> Vertex;
    class Node {
    public:
        Node(int n, const Vertex& vertex) :name(n), label(vertex), left_child(nullptr), right_child(nullptr) {}
        Vertex label;
        int name;
        std::unique_ptr<Node> left_child;
        std::unique_ptr<Node> right_child;
    };

public:
    KDTree(int n) :dimension_(n), root_(-1, Vertex(n, 0)) {}
    void insert(int n, const Vertex& vertex) {
        insert(root_, 0, n, vertex);
    }
    void search(const Vertex& initial, const Vertex& terminal) const {
        search(root_, 0, initial, terminal);
    }

private:
    void insert(Node& current_node, int d, int n, const Vertex& vertex) {
        if(vertex[d] < current_node.label[d]) {
            if(current_node.left_child) insert(*(current_node.left_child), (d + 1) % dimension_, n, vertex);
            else current_node.left_child = std::unique_ptr<Node>(new Node(n, vertex));
        } else {
            if(current_node.right_child) insert(*(current_node.right_child), (d + 1) % dimension_, n, vertex);
            else current_node.right_child = std::unique_ptr<Node>(new Node(n, vertex));
        }
    }
    bool in_range(const Node& node, const Vertex& initial, const Vertex& terminal) const {
        for(int i = 0; i < dimension_; ++i) if(node.label[i] < initial[i] || terminal[i] < node.label[i]) return false;
        return true;
    }
    void search(const Node& node, int d, const Vertex& initial, const Vertex& terminal) const {
        if(node.name != -1 && in_range(node, initial, terminal)) answer.insert(node.name);
        if(terminal[d] >= node.label[d] && node.right_child) search(*(node.right_child), (d + 1) % dimension_, initial, terminal);
        if(initial[d] <= node.label[d] && node.left_child) search(*(node.left_child), (d + 1) % dimension_, initial, terminal);
    }

    int dimension_;
    Node root_;
};

