using namespace std;

enum {POINT, NAME};
typedef tuple<vector<double>, int> Vertex;

bool comp(const Vertex& v1, const Vertex& v2) {
    return get<POINT>(v1)[1]!=get<POINT>(v2)[1] ? get<POINT>(v1)[1] < get<POINT>(v2)[1] : get<POINT>(v1)[0] < get<POINT>(v2)[0];
}

int main() {
    int n, q;
    KDTree kdt(2);
    cin >> n;
    vector<Vertex> v;
    for(int i = 0; i < n; ++i) {
        double x, y;
        cin >> x >> y;
        vector<double> t = {x, y};
        v.push_back(Vertex(t, i));
    }
    for(int i = 0; i < n; ++i) {
        if(i&1) sort(v.begin(), v.end());
        else    sort(v.begin(), v.end(), comp);
        auto it = v.begin();
        for(int j = 0;j < v.size() / 2; ++j)++it;
        kdt.insert(get<NAME>(*it), get<POINT>(*it));
        v.erase(it);
    }
    cin >> q;
    for(int i = 0; i < q; ++i) {
        double sx, tx, sy, ty;
        cin >> sx >> tx >> sy >> ty;
        answer.clear();
        kdt.search({sx, sy}, {tx, ty});
        for(auto it = answer.begin(); it != answer.end(); ++it) {
            cout << *it << endl;
        }
        cout << endl;
    }
}

