  Point() {}
  Point(int id, int x, int y): id(id), x(x), y(y) {}
  bool operator < (const Point &p)
  {
    return id < p.id;
  }
//  void print()
//  {
//    printf("%d\n", id);
//  }
};
Point P[500005];
bool compar_x(const Point &X, const Point &Y)
{
  return X.x < Y.x;
}
bool compar_y(const Point &X, const Point &Y)
{
  return X.y < Y.y;
}
int make2DTree(int l, int r, int depth)
{
  if(!(l<r)) return NIL; //NIL signs NULL node.
  int mid = (l + r) / 2;
  if(depth % 2 == 0 )
  {
    sort(P+l, P+r, compar_x);
  }
  else  sort(P+l, P+r, compar_y);
  int root = np++;
  T[root].location = mid;// root , left , right, create tree in preorder.
  T[root].l = make2DTree(l, mid, depth+1);
  T[root].r = make2DTree(mid+1, r, depth+1);
  return root;
}
void findp(int r, int sx, int tx, int sy, int ty, int depth, vector<int> &ans)
{
  int x, y;
  x = P[T[r].location].x; y = P[T[r].location].y;
  if(x >= sx && x <= tx && y >= sy && y <= ty) ans.push_back(P[T[r].location].id);
  if(depth % 2 == 0)
  {
    if(x >= sx && T[r].l != NIL)
      findp(T[r].l, sx, tx, sy, ty, depth+1, ans);
    if(x <= tx && T[r].r != NIL)
      findp(T[r].r, sx, tx, sy, ty, depth+1, ans);
  }
  else
  {
    if(y >= sy && T[r].l != NIL)
      findp(T[r].l, sx, tx, sy, ty, depth+1, ans);
    if(y <= ty && T[r].r != NIL)
      findp(T[r].r, sx, tx, sy, ty, depth+1, ans);
  }
}
