  for(int i=0; i<n; i++)
  {
    scanf("%d%d", &x, &y);
    P[i] = Point(i, x, y);
    T[i].l = T[i].r = T[i].location = NIL;
  }
  make2DTree(0, n, 0);
  scanf("%d", &q);
  int sx, tx, sy, ty; vector<int> ans;
  for(int i=0; i<q; i++)
  {
    scanf("%d%d%d%d", &sx, &tx, &sy, &ty);
    findp(0, sx, tx, sy, ty, 0, ans);
    sort(ans.begin(), ans.end());
    for(int j=0; j<ans.size(); j++)
      printf("%d\n", ans[j]);
    ans.clear();
    printf("\n");
  }

  return 0;
}

