bool lessY(Point &p1,Point &p2){return p1.y<p2.y;}
int makeKDTree(int l,int r, int d){
  if(!(l<r))return NIL;
  int mid=(l+r)>>1;
  int t=np++;
  nth_element(P+l,P+mid,P+r,(d&1 ? lessY : lessX));
  T[t].location=mid;
  T[t].l=makeKDTree(l,mid,d+1);
  T[t].r=makeKDTree(mid+1,r,d+1);
  return t;
}
void find(int v,int sx,int tx,int sy,int ty,int d,vector<Point> &ans){
  int x=P[T[v].location].x;
  int y=P[T[v].location].y;
  if(sx<=x&&x<=tx&&sy<=y&&y<=ty)ans.push_back(P[T[v].location]);
  if(d%2==0){
    if(T[v].l!=NIL&&sx<=x)find(T[v].l,sx,tx,sy,ty,d+1,ans);
    if(T[v].r!=NIL&&x<=tx)find(T[v].r,sx,tx,sy,ty,d+1,ans);
  }
  else{
    if(T[v].l!=NIL&&sy<=y)find(T[v].l,sx,tx,sy,ty,d+1,ans);
    if(T[v].r!=NIL&&y<=ty)find(T[v].r,sx,tx,sy,ty,d+1,ans);
  }
}

bool ex(int v,int sx,int tx,int sy,int ty,int d,vector<Point> &ans){
  int x=P[T[v].location].x;
  int y=P[T[v].location].y;
  if(sx<=x&&x<=tx&&sy<=y&&y<=ty)return 1;
  if(d%2==0){
    if(T[v].l!=NIL&&sx<=x)if(ex(T[v].l,sx,tx,sy,ty,d+1,ans))return 1;
    if(T[v].r!=NIL&&x<=tx)if(ex(T[v].r,sx,tx,sy,ty,d+1,ans))return 1;
  }
  else{
    if(T[v].l!=NIL&&sy<=y)if(ex(T[v].l,sx,tx,sy,ty,d+1,ans))return 1;
    if(T[v].r!=NIL&&y<=ty)if(ex(T[v].r,sx,tx,sy,ty,d+1,ans))return 1;
  }
}
int main(){
  int x,y;
  cin>>n;
  rep(i,n){
    scanf("%d %d",&x,&y);
    P[i]=Point(i,x,y);
    T[i].l=T[i].r=T[i].p=NIL;
