struct OwnNode
{
	int x, y;
	int index;
	OwnNode* right;
	OwnNode* left;

	OwnNode(int x, int y,int index) :x(x), y(y),index(index), right(nullptr), left(nullptr) {}

	void insert(int x, int y, int d, int index)
	{
		if (d % 2 == 0)
		{
			if (this->x < x)
			{
				if (right == nullptr)
				{
					right = new OwnNode(x, y, index);
				}
				else
				{
					right->insert(x, y, d + 1, index);
				}
			}
			else
			{
				if (left == nullptr)
				{
					left = new OwnNode(x, y, index);
				}
				else
				{
					left->insert(x, y, d + 1, index);
				}
			}
		}
		else
		{
			if (this->y < y)
			{
				if (right == nullptr)
				{
					right = new OwnNode(x, y, index);
				}
				else
				{
					right->insert(x, y, d + 1, index);
				}
			}
			else
			{
				if (left == nullptr)
				{
					left = new OwnNode(x, y, index);
				}
				else
				{
					left->insert(x, y, d + 1, index);
				}
			}
		}
	}

	void find(OwnNode& ld, OwnNode& ru, int d, vector<int>& v)
	{
		if (ld.x <= x&&x <= ru.x&&ld.y <= y&&y <= ru.y)
		{
			v.push_back(index);
		}

		if (d % 2 == 0)
		{
			if (ld.x <= x)
			{
				if (left != nullptr)
				{
					left->find(ld, ru, d + 1, v);
				}
			}
			if(x<=ru.x)
			{
				if (right != nullptr)
				{
					right->find(ld, ru, d + 1, v);
				}
			}
		}
		else
		{
			if (ld.y <= y)
			{
				if (left != nullptr)
				{
					left->find(ld, ru, d + 1, v);
				}
			}
			if (y <= ru.y)
			{
				if (right != nullptr)
				{
					right->find(ld, ru, d + 1, v);
				}
			}
		}
	}
};

int main()
{
	OwnNode* top = nullptr;
	int n, q;
	cin >> n;

	for (int i = 0; i < n; i++)
	{
		int x, y;
		cin >> x >> y;
		if (top == nullptr)
		{
			top = new OwnNode(x, y, i);
		}
		else
		{
			top->insert(x, y, 0, i);
		}
