#define MAX_N  500005

typedef struct { int id; int p[2], child[2], min[2], max[2]; } NODE;
NODE kdTree[MAX_N];

int root;       // root of kd tree
int ans[102], len;
int s[2], t[2];

/* see quickselect method */

int find_median(int start, int end, int k)
{
    int i, mid, pivot, store;
	NODE t;

	if (start == end) return start;
	mid = (start+end)>>1;
    while (1) {
        pivot = kdTree[mid].p[k];

		t = kdTree[mid], kdTree[mid] = kdTree[end], kdTree[end] = t;

		store = start;
        for (i = start; i <= end; i++) {
            if (kdTree[i].p[k] < pivot) {
                if (i != store) {
					t = kdTree[i], kdTree[i] = kdTree[store], kdTree[store] = t;
				}
                store++;
            }
        }
		t = kdTree[store], kdTree[store] = kdTree[end], kdTree[end] = t;

        /* median has duplicate values */
        if (kdTree[store].p[k] == kdTree[mid].p[k]) break;

        if (store > mid) end = store-1;
        else start = store;
    }
	return mid;
}

int mkKdTree(int l, int r, int k)
{
	int i, j, c;
	int m;

	m = find_median(l, r, k);
	kdTree[m].child[0] = (l == m)? 0: mkKdTree(l, m-1, !k);
	kdTree[m].child[1] = (r == m)? 0: mkKdTree(m+1, r, !k);

	for (i = 0; i < 2; i++) {
		kdTree[m].min[i] = kdTree[m].max[i] = kdTree[m].p[i];
		for (j = 0; j < 2; j++) if (c = kdTree[m].child[j]) {
			if (kdTree[m].min[i] > kdTree[c].min[i]) kdTree[m].min[i] = kdTree[c].min[i];
			if (kdTree[m].max[i] < kdTree[c].max[i]) kdTree[m].max[i] = kdTree[c].max[i];
		}
	}
	return m;
