/* see quickselect method */

int find_median(int start, int end, int k)
{
    int i, mid, pivot, store;
	NODE t;

	if (start >= end) return start;
	if (start == end+1) return start;
	mid = (start+end)>>1;
    while (1) {
        pivot = kdTree[mid].p[k];

		t = kdTree[mid], kdTree[mid] = kdTree[end-1], kdTree[end-1] = t;

		store = start;
        for (i = start; i < end; i++) {
            if (kdTree[i].p[k] < pivot) {
                if (i != store) {
					t = kdTree[i], kdTree[i] = kdTree[store], kdTree[store] = t;
				}
                store++;
            }
        }
		t = kdTree[store], kdTree[store] = kdTree[end-1], kdTree[end-1] = t;

        /* median has duplicate values */
        if (kdTree[store].p[k] == kdTree[mid].p[k]) break;

        if (store > mid) end = store;
        else start = store;
    }
	return mid;
}

