	m = find_median(l, r, k);
	kdTree[m].child[0] = (l == m)? 0: mkKdTree(l, m, !k);
	kdTree[m].child[1] = (m+1 == r)? 0: mkKdTree(m+1, r, !k);

	for (i = 0; i < 2; i++) {
		kdTree[m].min[i] = kdTree[m].max[i] = kdTree[m].p[i];
