struct KdNode { int id; int Data[2]; KdTree Left, Right; };

struct KdNode buf[MAX_N]; int sz;
KdTree T;

int ans[102], len;

KdTree recIns(int id, int *Item, KdTree T, int Level)
{
	if (T == NULL) {
		T = buf+sz++;
		T->Left = T->Right = NULL;
		T->id = id, T->Data[0] = Item[0], T->Data[1] = Item[1];
	} else if (Item[Level] < T->Data[Level])
		T->Left  = recIns(id, Item, T->Left , !Level);
	else
		T->Right = recIns(id, Item, T->Right, !Level);
	return T;
}

KdTree insert(int id, int *Item, KdTree T)
{
	return recIns(id, Item, T, 0);
}

// Print items satisfying
// Low[ 0 ] <= Item[ 0 ] <= High[ 0 ] and
// Low[ 1 ] <= Item[ 1 ] <= High[ 1 ]

void recPrintRange(int *Low, int *High, KdTree T, int Level)
{
	if (T != NULL) {
		if (Low[0] <= T->Data[0] &&	T->Data[0] <= High[0] &&
			Low[1] <= T->Data[1] &&	T->Data[1] <= High[1]) {
			ans[len++] = T->id;
		}

		if (Low[Level] <= T->Data[Level])
			recPrintRange(Low, High, T->Left, !Level);
		if (High[ Level ] >= T->Data[Level])
			recPrintRange(Low, High, T->Right, !Level);
	}
}

void PrintRange(int *Low, int *High, KdTree T)
{
	recPrintRange(Low, High, T, 0);
}

