#include<iostream>
#include<vector>
#include<algorithm>
#include<cmath>

#define all(c) (c).begin(),(c).end()
#define MAX_N 500000

using namespace std;

struct point{
  int x,y;
  point(){}
  point(int x,int y):x(x),y(y){}

  bool operator < (const point &p) const {
    if(p.x != x)return p.x<x;
    return p.y < y;
  }

  bool operator > (const point &p) const {
    if(p.y != y)return p.y<y;
    return p.x < x;
  }
};

struct tree_node{
  int id;
  point location;
  tree_node(){}
};

typedef pair<point,int>ppi;

int N,K; //点の数、次元数
ppi pointList[MAX_N];
tree_node *tree[MAX_N*2];

//点のリスト、リストのサイズ、現在の深さ,medianのid
void kdtree(ppi *pList,int n,int depth,int i){
  //深さに応じて軸を選択し、軸が順次選択されるようにする
  int axis = depth % K;
  int mid = n/2;

  if(n<=0)return;
  if(axis==0)sort(pList,pList+n);
  if(axis==1)sort(pList,pList+n,greater<ppi>());

  tree[i]=new tree_node;
  tree[i]->id=pList[mid].second;
  tree[i]->location=pList[mid].first;
  //cout << pList[mid].first.x << " " << pList[mid].first.y << endl;
  if(n==1)return;

  kdtree(pList,mid,depth+1,i*2+1);
  kdtree(pList+mid+1,n-mid-1,depth+1,i*2+2);
}

/*
左下、右上、現在のノード、深さ
長方形領域に含まれる点のidを列挙する
*/
void kdtree_search(int x1,int y1,int x2,int y2,int i,int depth,vector<int> &res){

  if(!tree[i])return;

  int axis = depth % K;

  bool fgleft=false,fgright=false;

  if(axis==0){
    if(tree[i]->location.x<=x2)fgleft=true;
    if(tree[i]->location.x>=x1)fgright=true;
  }
  else {
    if(tree[i]->location.y<=y2)fgleft=true;
    if(tree[i]->location.y>=y1)fgright=true; 
  }

  if(fgleft)kdtree_search(x1,y1,x2,y2,i*2+1,depth+1,res);
  if(fgright)kdtree_search(x1,y1,x2,y2,i*2+2,depth+1,res);
  //  cout << tree[i]->location.x << " " << tree[i]->location.y << endl;
  if(tree[i]->location.x<x1 || x2<tree[i]->location.x)return;
  if(tree[i]->location.y<y1 || y2<tree[i]->location.y)return;
  res.push_back(tree[i]->id);

}


int main(void){

  fill(tree,tree+MAX_N,(tree_node *)0);

  K=2;
  cin >> N;
  for(int i=0;i<N;i++){
    cin >> pointList[i].first.x >> pointList[i].first.y;
    pointList[i].second=i;
  }

  sort(pointList,pointList+N);
  sort(pointList,pointList+N,greater<ppi>());

  kdtree(pointList,N,0,0);
  int q;
  cin >> q;
  for(int i=0;i<q;i++){
    int x1,y1,x2,y2;
    cin >> x1 >> x2 >> y1 >> y2;
    vector<int>res;
    kdtree_search(x1,y1,x2,y2,0,0,res);
    sort(all(res));
    for(int j=0;j<res.size();j++){
      cout << res[j] << endl;
    }
    cout << endl;
  }

  return 0;
}

#include <stdio.h>          // printf(), scanf()
#include <stdlib.h>         // qsort()

#define MAX_N 1000000
static const int nil = -1;

typedef struct point_tbl
{
	int id;
	int x, y;
} point;

typedef struct node_tbl
{
	int location;
	int l, r;
} node;

point p[MAX_N];
node t[MAX_N];
int pid[MAX_N];
int n;
int np;
int n_pid;

int
cmpx_func(const void *l_, const void *r_)
{
	const point* l = (const point*) l_;
	const point* r = (const point*) r_;

	if (l->x < r->x)
		return -1;

	if (l->x > r->x)
		return 1;

	return 0;
}

int
cmpy_func(const void *l_, const void *r_)
{
	const point* l = (const point*) l_;
	const point* r = (const point*) r_;

	if (l->y < r->y)
		return -1;

	if (l->y > r->y)
		return 1;

	return 0;
}

int
makeKDTree(int l, int r, int depth)
{
	if (l >= r)
		return nil;

	if (r - l >= 2)
	{
		if (depth % 2 == 0)
			qsort(&p[l], r - l, sizeof(point), cmpx_func);
		else
			qsort(&p[l], r - l, sizeof(point), cmpy_func);
	}

	int mid = (l + r) / 2;
	int s = np++;
	t[s].location = mid;
	t[s].l = makeKDTree(l, mid, depth + 1);
	t[s].r = makeKDTree(mid + 1, r, depth + 1);
	return s;
}

void
find(int v, int sx, int tx, int sy, int ty, int depth)
{
	int x = p[t[v].location].x;
	int y = p[t[v].location].y;

	if (sx <= x && x <= tx && sy <= y && y <= ty)
		pid[n_pid++] = p[t[v].location].id;

	if (depth % 2 == 0)
	{
		if (t[v].l != nil)
		{
			if (sx <= x)
				find(t[v].l, sx, tx, sy, ty, depth + 1);
		}

		if (t[v].r != nil)
		{
			if (x <= tx)
				find(t[v].r, sx, tx, sy, ty, depth + 1);
		}
	}
	else
	{
		if (t[v].l != nil)
		{
			if (sy <= y)
				find(t[v].l, sx, tx, sy, ty, depth + 1);
		}

		if (t[v].r != nil)
		{
			if (y <= ty)
				find(t[v].r, sx, tx, sy, ty, depth + 1);
		}
	}
}

int
cmpi_func(const void *l_, const void *r_)
{
	const int* l = (const int*) l_;
	const int* r = (const int*) r_;

	if (*l < *r)
		return -1;

	if (*l > *r)
