class MySearch{
    static<T> int lower_bound(T[] a, T key, Comparator<T> c) {
        int l = 0, r = a.length;
        while (l < r) {
            int m = l + (r - l) / 2;
            if(c.compare(key, a[m]) <= 0) r = m;
            else l = m + 1;
        }
        return l;
    }

    static<T> int upper_bound(T[] a, T key, Comparator<T> c) {
        int l = 0, r = a.length;
        while (l < r) {
            int m = l + (r - l) / 2;
            if(c.compare(key, a[m]) >= 0) l = m + 1;
            else r = m;
        }
        return l;
    }
}

