	Node head;
	Node t;
	Node z;

	public TwoDTree(Point[] parray, int n){
//		int i;
		//Point pzero = new Point(0, 0);
		Point pzero = new Point(-1000000001, -1000000001);
		pzero.info = 0;
		z = new Node(pzero);
		head = new Node(null);
		head.right = z;
		head.point = pzero;
		for(int i = 0; i < n; i++){
			insert(parray[i]);
		}
	}

	void insert (Point p){
//		if(p.x == 0 && p.y == 0){
