class KDTree {
	boolean debug;

	class Pt {
		int id;
		int x, y;
		boolean xJudge;
		int leftC, rightC;

		public Pt(int id, int x, int y) {
			this.id = id;
			this.x = x;
			this.y = y;
		}

		public int key(boolean xjudge) {
			if (xjudge)
				return this.x;
			else
				return this.y;
		}
	}

	Pt[] pt;
	int root;

	public KDTree(int n, boolean b) {
		pt = new Pt[n];
		debug = b;
	}

	public void add(int id, int x, int y) {
		pt[id] = new Pt(id, x, y);
	}

	public void build() {
		root = buildTree(0, pt.length, true, false);
	}

	class compPt implements Comparator<Pt> {

		@Override
		public int compare(Pt o1, Pt o2) {
			if (o1.key(sortbyX) > o2.key(sortbyX))
				return 1;
			else if (o1.key(sortbyX) == o2.key(sortbyX)) {
				sorteq++;
				return 0;
			} else
				return -1;
		}

	}

	boolean sortbyX;
	long sorteq;

	private int buildTree(int st, int len, boolean xjudge, boolean contig) {
		if (len == 0)
			return Integer.MAX_VALUE;

		if (len == 1) {
			pt[st].xJudge = xjudge;
			pt[st].leftC = Integer.MAX_VALUE;
			pt[st].rightC = Integer.MAX_VALUE;
			return st;
		}

		if (!contig) {
			sortbyX = xjudge;
			sorteq = 0;
			Arrays.sort(pt, st, st+len, new compPt());
		}

		if (len > 3 && sorteq < len)
			contig = true;
		else
			contig = false;

		int med = st + len / 2;
		pt[med].xJudge = xjudge;
		pt[med].leftC = buildTree(st, len / 2, !(xjudge ^ contig), contig);
		pt[med].rightC = buildTree(med + 1, len - len / 2 - 1, !(xjudge ^ contig), contig);
		return med;
	}

	List<Integer> inPt = new ArrayList<Integer>();

	public void judge(StringBuilder ans, int sx, int tx, int sy, int ty) {
		inPt.clear();
		countIn(root, sx, tx, sy, ty);
		inPt.sort(null);
		for (int i = 0; i < inPt.size(); i++)
			ans.append(inPt.get(i) + "\n");
		ans.append("\n");
	}

	private int countIn(int p, int sx, int tx, int sy, int ty) {
		if (p == Integer.MAX_VALUE)
			return 0;
		int r = 0;
		if (pt[p].x >= sx && pt[p].x <= tx && pt[p].y >= sy && pt[p].y <= ty) {
			inPt.add(pt[p].id);
			r++;
		}
		if (pt[p].xJudge) {
			if (pt[p].x >= sx)
				r += countIn(pt[p].leftC, sx, tx, sy, ty);
			if (pt[p].x <= tx)
				r += countIn(pt[p].rightC, sx, tx, sy, ty);
		} else {
			if (pt[p].y >= sy)
				r += countIn(pt[p].leftC, sx, tx, sy, ty);
			if (pt[p].y <= ty)
				r += countIn(pt[p].rightC, sx, tx, sy, ty);
		}
		return r;
	}
}

