		System.out.println("id " + pt[p].id + "\tlevel " + v + "\t" + pt[p].x + "," + pt[p].y + "\tXdim " + pt[p].xJudge
				+ "\tleft " + pt[p].leftC + " rignt " + pt[p].rightC);
		printKd(pt[p].leftC, v + 1);
		//printKd(pt[p].rightC, v + 1);
