class FastScanner {
	private final InputStream in = System.in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;

	private boolean hasNext() throws IOException {
		skipCtlSpace();
		if (ptr < buflen)
			return true;
		ptr = 0;
		buflen = in.read(buffer);
		if (buflen <= 0)
			return false;
		return hasNext();
	}

	private void skipCtlSpace() {
		for (; ptr < buflen; ptr++)
			if (!isCtlSpace(buffer[ptr]))
				break;
	}

	private boolean isCtlSpace(byte b) {
		if (b <= ' ' || b > '~')
			return true;
		else
			return false;
	}

	public void close() throws IOException {
		in.close();
	}

	public String next() throws IOException  {
		if (!hasNext())
			return null;
		StringBuilder sb = new StringBuilder();
		while (ptr < buflen && !isCtlSpace(buffer[ptr])) {
			sb.appendCodePoint(buffer[ptr++]);
		}
		return sb.toString();
	}

	public Integer nextInt() throws IOException {
		if (!hasNext())
			return null;
		int n = 0;
		boolean minus = false;
		if (buffer[ptr] == '-') {
			minus = true;
			ptr++;
		}
		while (ptr < buflen && !isCtlSpace(buffer[ptr])) {
			n *= 10;
			n += (buffer[ptr++] - '0');
		}
		if (minus)
			return n * -1;
		else
			return n;
	}
}

