	static class Node2DTree {
		int id;
		int left = -1;
		int right = -1;
		int parent = -1;
		int x;
		int y;

		Node2DTree(int id, int x, int y) {
			this.id = id;
			this.x = x;
			this.y = y;
		}

		//??§?¨????????????´????????????????????????????????????
		void addNode(int id_target, int depth) {
			if(id_target == 0) {
				return;
			}
			if(depth % 2 == 0) {
				if(V[id_target].x <= x) {
					if(left != -1) {
						V[left].addNode(id_target, depth + 1);
					} else {
						left = id_target;
						V[id_target].parent = id_target;
					}
				} else {
					if(right != -1) {
						V[right].addNode(id_target, depth + 1);
					} else {
						right = id_target;
						V[id_target].parent = id_target;
					}
				}
			} else {
				if(V[id_target].y <= y) {
					if(left != -1) {
						V[left].addNode(id_target, depth + 1);
					} else {
						left = id_target;
						V[id_target].parent = id_target;
					}
				} else {
					if(right != -1) {
						V[right].addNode(id_target, depth + 1);
					} else {
						right = id_target;
						V[id_target].parent = id_target;
					}
				}
			}
		}

		void searchNode(int sx, int tx, int sy, int ty, int depth) {
//			System.out.println(id);
			if(depth % 2 == 0) {
				if(tx < x) {
					if(left != -1) {
						V[left].searchNode(sx, tx, sy, ty, depth + 1);
					}
				} else if(sx > x){
					if(right != -1) {
						V[right].searchNode(sx, tx, sy, ty, depth + 1);
					}
				} else {
					if(left != -1) {
						V[left].searchNode(sx, tx, sy, ty, depth + 1);
					}
					if(right != -1) {
						V[right].searchNode(sx, tx, sy, ty, depth + 1);
					}
					if(sy <= y && y <= ty) {
						set.add(id);
					}
				}
			} else {
				if(ty < y) {
					if(left != -1) {
						V[left].searchNode(sx, tx, sy, ty, depth + 1);
					}
				} else if(sy > y){
					if(right != -1) {
						V[right].searchNode(sx, tx, sy, ty, depth + 1);
					}
				} else {
					if(left != -1) {
						V[left].searchNode(sx, tx, sy, ty, depth + 1);
					}
					if(right != -1) {
						V[right].searchNode(sx, tx, sy, ty, depth + 1);
					}
					if(sx <= x && x <= tx) {
						set.add(id);
					}
				}
			}
		}
	}

