class Pair{
    private static final Map<String,Pair> map = new HashMap<>();

    public static Pair valueOf(int k,int v){
        return map.computeIfAbsent(k + ":" + v,key->new Pair(k,v));
    }

    private int id;
    private int key;
    private int value;

    private Pair(int key,int value) {
        this.id = map.size();
        this.key = key;
        this.value = value;
    }

    public int getId(){
        return id;
    }

    public int getKey() {
        return key;
    }

    public int getValue() {
        return value;
    }

    public void compute(Pair p, Consumer<Pair> f){
        if(key <= p.key && value <= p.value){
            for(int i = key,l = p.key;i <= l;i++){
                for(int j = value,m = p.value;j <= m;j++) f.accept(valueOf(i,j));
            }
        }
    }

    @Override
    public String toString() {
        return key + "=" + value;
    }

    @Override
    public int hashCode() {
        return key * 13 + value;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o instanceof Pair) {
            Pair pair = (Pair) o;
            if (key != pair.key || value != pair.value) return false;
            return true;
        }
        return false;
    }
}

