namespace ConsoleApplication1
{
    class Node
    {
        internal int id, x, y;
        internal Node left, right;

        public Node(int id, int x, int y)
        {
            this.id = id;
            this.x = x;
            this.y = y;
        }
    }

    class ComparerX : IComparer<Node>
    {
        public int Compare(Node a, Node b)
        {
            return a.x - b.x;
        }
    }

    class ComparerY : IComparer<Node>
    {
        public int Compare(Node a, Node b)
        {
            return a.y - b.y;
        }
    }

    class Program
    {
        static List<int> ans = new List<int>();

        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());

            List<Node> nodeList = new List<Node>();

            for (int i = 0; i < n; i++)
            {
                int[] temp = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);

                nodeList.Add(new Node(i, temp[0], temp[1]));
            }

            Node root = MakeKDTree(nodeList, 0, n, 0);

            StringBuilder sb = new StringBuilder();
            int q = int.Parse(Console.ReadLine());

            for (int i = q; i > 0; i--)
            {
                int[] temp = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);

                ans.Clear();
                Find(root, temp[0], temp[1], temp[2], temp[3], 0);
                ans.Sort();

                foreach (int id in ans)
                {
                    sb.AppendLine(id.ToString());
                }
                sb.AppendLine();
            }
            Console.Write(sb);
        }

        static ComparerX compX = new ComparerX();
        static ComparerY compY = new ComparerY();

        static Node MakeKDTree(List<Node> nodeList, int left, int right, int depth)
        {
            if (left >= right) return null;

            int mid = (left + right) / 2;

            if (depth % 2 == 0) nodeList.Sort(left, right - left, compX);
            else nodeList.Sort(left, right - left, compY);

            Node node = nodeList[mid];
            node.left = MakeKDTree(nodeList, left, mid, depth + 1);
            node.right = MakeKDTree(nodeList, mid + 1, right, depth + 1);

            return node;
        }

        static void Find(Node node, int sx, int tx, int sy, int ty, int depth)
        {
            int x = node.x;
            int y = node.y;

            if (sx <= x && x <= tx && sy <= y && y <= ty)
                ans.Add(node.id);

            if (depth % 2 == 0)
            {
                if (node.left != null)
                    if (sx <= x) Find(node.left, sx, tx, sy, ty, depth + 1);
                if (node.right != null)
                    if (x <= tx) Find(node.right, sx, tx, sy, ty, depth + 1);
            }
            else
            {
                if (node.left != null)
                    if (sy <= y) Find(node.left, sx, tx, sy, ty, depth + 1);
                if (node.right != null)
                    if (y <= ty) Find(node.right, sx, tx, sy, ty, depth + 1);
            }
        }
    }
