class kDTree
{
    public struct Point
    {
        public int id, x, y;
        public Point(int id, int x, int y)
        {
            this.id = id;
            this.x = x;
            this.y = y;
        }

    }
    public struct Node
    {
        public int l, r;
        public Node(int l, int r)
        {
            this.l = l;
            this.r = r; 
        }
    }

    internal int n;
    Node[] T;
    public Point[] P;
    public int root;
    public List<int> A;

    public kDTree(int n)
    {
        this.n = n;
        T = new Node[n];
        P = new Point[n];
    }

    public int MakekDTree(int l, int r, int depth)
    {
        if (l >= r) return -1;

        int mid = (l + r) / 2;

        if (depth % 2 == 0) Array.Sort(P, l, r - l, new Comparer_X());
        else Array.Sort(P, l, r - l, new Comparer_Y());

        T[mid].l = MakekDTree(l, mid, depth + 1);
        T[mid].r = MakekDTree(mid + 1, r, depth + 1);

        return mid;
    }
    class Comparer_X : IComparer<Point>
    {
        public int Compare(Point a, Point b)
        {
            return a.x - b.x;
        }
    }

    class Comparer_Y : IComparer<Point>
    {
        public int Compare(Point a, Point b)
        {
            return a.y - b.y;
        }
    }
    public void Find(int v, int sx, int tx, int sy, int ty, int depth)
    {
        int x = P[v].x, y = P[v].y;
        if (sx <= x && x <= tx && sy <= y && y <= ty) A.Add(P[v].id);

        if (depth % 2 == 0)
        {
            if (T[v].l != -1 && sx <= x) Find(T[v].l, sx, tx, sy, ty, depth + 1);
            if (T[v].r != -1 && x <= tx) Find(T[v].r, sx, tx, sy, ty, depth + 1);
        }
        else
        {
            if (T[v].l != -1 && sy <= y) Find(T[v].l, sx, tx, sy, ty, depth + 1);
            if (T[v].r != -1 && y <= ty) Find(T[v].r, sx, tx, sy, ty, depth + 1);
        }
    }



}
class Program
{
    static void Main()
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        new Program().solve();
        Console.Out.Flush();
    }
    Scanner cin = new Scanner();

    int n, q;
    void solve()
    {
        n = cin.nextint;
        kDTree K = new kDTree(n);
        for (int i = 0; i < n; i++)
        {
            K.P[i]= new kDTree.Point(i, cin.nextint, cin.nextint); 
        }
        K.root = K.MakekDTree(0, n, 0);
        q = cin.nextint;

        for (int i = 0; i < q; i++)
        {
            K.A = new List<int>();
            K.Find(K.root, cin.nextint, cin.nextint, cin.nextint, cin.nextint, 0);
            K.A.Sort();
            foreach (var id in K.A)
            {
                Console.WriteLine(id);
            }
            Console.WriteLine();
        }

    }

}

class Scanner
{
    string[] s; int i;
    char[] cs = new char[] { ' ' };
    public Scanner() { s = new string[0]; i = 0; }
    public string[] scan { get { return Console.ReadLine().Split(); } }
    public int[] scanint { get { return Array.ConvertAll(scan, int.Parse); } }
    public long[] scanlong { get { return Array.ConvertAll(scan, long.Parse); } }
    public double[] scandouble { get { return Array.ConvertAll(scan, double.Parse); } }
    public string next
    {
        get
        {
            if (i < s.Length) return s[i++];
            string st = Console.ReadLine();
            while (st == "") st = Console.ReadLine();
            s = st.Split(cs, StringSplitOptions.RemoveEmptyEntries);
            i = 0;
            return next;
        }
    }
    public int nextint { get { return int.Parse(next); } }
    public long nextlong { get { return long.Parse(next); } }
    public double nextdouble { get { return double.Parse(next); } }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

namespace ConsoleApplication1
{
    class KDTree
    {
        readonly int n;

        Node[] nodes;
        Point[] points;
        List<int> idList;
        int root;

        public KDTree(int n)
        {
            this.n = n;

            nodes = new Node[n];
            points = new Point[n];
        }

        public void AddPoint(int id, int x, int y)
        {
            points[id].id = id;
            points[id].x = x;
            points[id].y = y;
        }

        public void MakeKDTree()
        {
            root = MakeKDTree(0, n, 0);
        }

        private int MakeKDTree(int l, int r, int depth)
        {
            if (l >= r) return -1;

            int mid = (l + r) / 2;

            if (depth % 2 == 0) Array.Sort(points, l, r - l, new ComparerX());
            else Array.Sort(points, l, r - l, new ComparerY());

            nodes[mid].l = MakeKDTree(l, mid, depth + 1);
            nodes[mid].r = MakeKDTree(mid + 1, r, depth + 1);

            return mid;
        }

        public List<int> FindPoints(int sx, int tx, int sy, int ty)
        {
            idList = new List<int>();

            Find(root, sx, tx, sy, ty, 0);

            return idList;
        }

        private void Find(int v, int sx, int tx, int sy, int ty, int depth)
        {
            Node cur = nodes[v];
            Point p = points[v];
            int x = p.x;
            int y = p.y;

            if (sx <= x && x <= tx && sy <= y && y <= ty) idList.Add(p.id);

            if (depth % 2 == 0)
            {
                if (cur.l != -1 && sx <= x) Find(cur.l, sx, tx, sy, ty, depth + 1);
                if (cur.r != -1 && x <= tx) Find(cur.r, sx, tx, sy, ty, depth + 1);
            }
            else
            {
                if (cur.l != -1 && sy <= y) Find(cur.l, sx, tx, sy, ty, depth + 1);
                if (cur.r != -1 && y <= ty) Find(cur.r, sx, tx, sy, ty, depth + 1);
            }
        }
    }

    struct Node
    {
        internal int l, r;
    }

    struct Point
    {
        internal int id, x, y;
    }

    class ComparerX : IComparer<Point>
    {
        public int Compare(Point a, Point b)
        {
            return a.x - b.x;
        }
    }

    class ComparerY : IComparer<Point>
    {
        public int Compare(Point a, Point b)
        {
            return a.y - b.y;
        }
    }

    class Program
    {
        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            KDTree T = new KDTree(n);

            for (int i = 0; i < n; i++)
            {
                int[] temp = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);

                T.AddPoint(i, temp[0], temp[1]);
            }

            T.MakeKDTree();

            int q = int.Parse(Console.ReadLine());

            StringBuilder sb = new StringBuilder();

            for (int i = q; i > 0; i--)
            {
                int[] temp = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);

                List<int> ans = T.FindPoints(temp[0], temp[1], temp[2], temp[3]);
                ans.Sort();

                foreach (var id in ans)
                {
                    sb.AppendLine(id.ToString());
                }
                sb.AppendLine();
            }
            Console.Write(sb);
        }
    }
}

