class Solver
{
    public void Solve(Scanner sc)
    {
        var N = sc.Int;
        var XY = new int[N][];var P = new List<int>();
        for (int i = 0; i < N; i++)
        {
            int x, y;
            sc.Make(out x, out y);
            XY[i] = new[] { x, y };P.Add(x);
        }
        var Q = sc.Int;
        var qry = new int[Q][];
        for (int i = 0; i < Q; i++)
        {
            int sx, tx, sy, ty;
            sc.Make(out sx, out tx, out sy, out ty);
            tx++;ty++;
            qry[i] = new[] { sx, tx, sy, ty };
            P.Add(sx);P.Add(tx);
        }
        var d = Compression(P);
        var g = Create(d.Count, () => new List<Tuple<int, int>>());
        for (int i = 0; i < N; i++)
        {
            g[d[XY[i][0]]].Add(new Tuple<int, int>(XY[i][1], i));
        }
        var seg = new SegmentTreeFractionalCascading(g);
        foreach (var q in qry)
        {
            seg.Query(d[q[0]], d[q[1]], q[2], q[3]);
        }
    }
    public static Dictionary<T, int> Compression<T>(IList<T> A, int d = 0, Comparison<T> cmp = null)
    {
        cmp = cmp ?? Comparer<T>.Default.Compare;
        var dic = new Dictionary<T, int>();
        var cp = A.ToArray();
        Array.Sort(cp, (a, b) => cmp(a, b));
        for (var i = 0; i < cp.Length; i++)
            if (!dic.ContainsKey(cp[i]))
                dic[cp[i]] = d++;
        return dic;
    }
}

class SegmentTreeFractionalCascading
{
    Tuple<int, int>[][] seg;
    int[][] L, R;
    int sz;
    public SegmentTreeFractionalCascading(List<Tuple<int, int>>[] A)
    {
        sz = 1;
        while (sz < A.Length) sz <<= 1;
        seg = new Tuple<int, int>[2 * sz - 1][];
        L = new int[2 * sz - 1][];
        R = new int[2 * sz - 1][];
        for (int i = 0; i < sz; i++)
        {
            if (i < A.Length)
            {
                seg[i + sz - 1] = A[i].ToArray();
                Array.Sort(seg[i + sz - 1], (a, b) => a.Item1 - b.Item1);
            }
            else
            {
                seg[i + sz - 1] = new Tuple<int, int>[0];
            }
        }
        for (int k = sz - 2; k >= 0; k--)
        {
            seg[k] = new Tuple<int, int>[seg[2 * k + 1].Length + seg[2 * k + 2].Length];
            L[k] = new int[seg[k].Length + 1];
            R[k] = new int[seg[k].Length + 1];
            int t1 = 0, t2 = 0;
            for (int i = 0; i < seg[k].Length; i++)
            {
                L[k][i] = t1;
                R[k][i] = t2;
                if (t1 == seg[2 * k + 1].Length)
                {
                    seg[k][i] = seg[2 * k + 2][t2++];
                }
                else if (t2 == seg[2 * k + 2].Length)
                {
                    seg[k][i] = seg[2 * k + 1][t1++];
                }
                else
                {
                    if (seg[2 * k + 1][t1].Item1 < seg[2 * k + 2][t2].Item1)
                        seg[k][i] = seg[2 * k + 1][t1++];
                    else
                        seg[k][i] = seg[2 * k + 2][t2++];
                }
            }
            L[k][seg[k].Length] = seg[2 * k + 1].Length;
            R[k][seg[k].Length] = seg[2 * k + 2].Length;
        }
    }
    List<int> res=new List<int>();
    public void Query(int l, int r, int d, int u)
    {
        d = LowerBound(seg[0], new Tuple<int, int>(d, -1), (a, b) => a.Item1.CompareTo(b.Item1));
        u = LowerBound(seg[0], new Tuple<int, int>(u, -1), (a, b) => a.Item1.CompareTo(b.Item1));
        res.Clear();
        Query(l, r, d, u, 0, 0, sz);
        res.Sort();
        for (int i = 0; i < res.Count; i++)
        {
            Console.WriteLine(res[i]);
        }
        Console.WriteLine();
    }
    void Query(int l, int r, int lw, int up, int k, int lft, int rgt)
    {
        if (rgt <= l || r <= lft) return;
        if (l <= lft && rgt <= r)
        {
            for (int i = lw; i < up; i++)
                res.Add(seg[k][i].Item2);
            return;
        }
        Query(l, r, L[k][lw], L[k][up], 2 * k + 1, lft, (lft + rgt) >> 1); Query(l, r, R[k][lw], R[k][up], 2 * k + 2, (lft + rgt) >> 1, rgt);
    }
    #region UpperBound/LowerBound
    public static int UpperBound<T>(IList<T> array, T value, Comparison<T> cmp = null)
    {
        cmp = cmp ?? Comparer<T>.Default.Compare;
        var low = -1;
        var high = array.Count;
        while (high - low > 1)
        {
            var mid = (high + low) / 2;
            if (cmp(array[mid], value) == 1) high = mid;
            else low = mid;
        }
        return high;
    }

    public static int LowerBound<T>(IList<T> array, T value, Comparison<T> cmp = null)
    {
        cmp = cmp ?? Comparer<T>.Default.Compare;
        var low = -1;
        var high = array.Count;
        while (high - low > 1)
        {
            var mid = (high + low) / 2;
            if (cmp(array[mid], value) != -1) high = mid;
            else low = mid;
        }
        return high;
    }
    #endregion
}

