namespace algo
{
    class MainClass
    {
        static List<Point> Points = new List<Point>();
        static List<Point> InitialPoints = new List<Point>();

        static List<Query> Queries = new List<Query>();

        static Node[] Nodes = new Node[6];
        static int Np = 0;

        static IComparer<Point> XComparer = new PointXComparer();
        static IComparer<Point> YComparer = new PointYComparer();

        public static void Main(string[] args)
        {
            // input points
            var n = int.Parse(Console.ReadLine());
            for (var i = 0; i < n; i++)
            {
                var pointArray = Console.ReadLine().Split(' ').Select(d => int.Parse(d)).ToArray();
                Points.Add(new Point(pointArray[0], pointArray[1]));
            }
            var arr = new Point[n];
            Points.CopyTo(arr);
            InitialPoints = new List<Point>(arr);

            // input queries
            var q = int.Parse(Console.ReadLine());
            for (var i = 0; i < q; i++)
            {
                var queryArray = Console.ReadLine().Split(' ').Select(d => int.Parse(d)).ToArray();
                Queries.Add(new Query(queryArray[0], queryArray[1], queryArray[2], queryArray[3]));
            }

            // Make Kd Tree
            var root = MakeKDTree(0, n, 0);

            foreach (var query in Queries)
            {
                var result = new List<int>();
                Find(query, root, 0, result);
                result.Sort();
                foreach (var i in result)
                {
                    Console.WriteLine("{0}", i);
                }
                Console.WriteLine();
            }
        }

        static int MakeKDTree(int l, int r, int depth)
        {
            if (!(l < r))
                return -1;

            var mid = (l + r) / 2;
            var t = Np++;
            if (depth % 2 == 0)
            {
                Points.Sort(l, r - l, XComparer);
            }
            else
            {
                Points.Sort(l, r - l, YComparer);
            }

            Nodes[t].Location = InitialPoints.IndexOf(Points[mid]);
            Nodes[t].L = MakeKDTree(l, mid, depth + 1);
            Nodes[t].R = MakeKDTree(mid + 1, r, depth + 1);

            return t;
        }

        static void Find(Query query, int nid, int depth, List<int> result)
        {
            var node = Nodes[nid];
            var p = InitialPoints[node.Location];
            if (query.CheckInner(p))
            {
                result.Add(node.Location);
            }

            if (depth % 2 == 0)
            {
                if (node.L != -1 && p.X >= query.X1)
                    Find(query, node.L, depth + 1, result);

                if (node.R != -1 && p.X <= query.X2)
                    Find(query, node.R, depth + 1, result);
            }
            else
            {
                if (node.L != -1 && p.Y >= query.Y1)
                    Find(query, node.L, depth + 1, result);

                if (node.R != -1 && p.Y <= query.Y2)
                    Find(query, node.R, depth + 1, result);
            }
        }
    }

