    class KDTree
    {
        readonly int n;

        Node[] nodeList;
        int root;

        public KDTree(int n)
        {
            this.n = n;

            nodeList = new Node[n];
        }

        public void AddPoint(int id, int x, int y)
        {
            nodeList[id] = new Node(id, x, y);
        }

        public void MakeKDTree()
        {
            root = MakeKDTree(0, n, 0);
        }

        private int MakeKDTree(int l, int r, int depth)
        {
            if (l >= r) return -1;

            int mid = (l + r) / 2;

            if (depth % 2 == 0) Array.Sort(nodeList, l, r - l, new ComparerX());
            else Array.Sort(nodeList, l, r - l, new ComparerY());

            nodeList[mid].l = MakeKDTree(l, mid, depth + 1);
            nodeList[mid].r = MakeKDTree(mid + 1, r, depth + 1);

            return mid;
        }

        public List<int> FindPoints(int sx, int tx, int sy, int ty)
        {
            List<int> idList = new List<int>();

            Find(root, sx, tx, sy, ty, 0, idList);

            return idList;
        }

        private void Find(int v, int sx, int tx, int sy, int ty, int depth, List<int> idList)
        {
            Node cur = nodeList[v];
            int x = cur.point.x;
            int y = cur.point.y;

            if (sx <= x && x <= tx && sy <= y && y <= ty) idList.Add(cur.id);

            if (depth % 2 == 0)
            {
                if (cur.l != -1 && sx <= x) Find(cur.l, sx, tx, sy, ty, depth + 1, idList);
                if (cur.r != -1 && x <= tx) Find(cur.r, sx, tx, sy, ty, depth + 1, idList);
            }
            else
            {
                if (cur.l != -1 && sy <= y) Find(cur.l, sx, tx, sy, ty, depth + 1, idList);
                if (cur.r != -1 && y <= ty) Find(cur.r, sx, tx, sy, ty, depth + 1, idList);
            }
        }
    }

