class KDTree {
    public class Node {
        public Point p;
        public Node l, r;
        public Node(Point p) {
            this.p = p;
        }
    }

    private Node _root;

    public void make(Point[] ps) {
        _root = make(ps, 0, ps.Length, 0);
    }

    Node make(Point[] ps, int lo, int hi, int d) {
        if (lo >= hi) return null;

        if (d == 0)
            Array.Sort(ps, lo, hi - lo, new CmpX());
        else
            Array.Sort(ps, lo, hi - lo, new CmpY());

        int mid = (lo + hi) / 2;
        var node = new Node(ps[mid]);
        node.l = make(ps, lo, mid, d ^ 1);
        node.r = make(ps, mid + 1, hi, d ^ 1);
        return node;
    }

    public int[] search(Point ld, Point ru) {
        var acc = new List<int>();
        search(_root, 0, ld, ru, acc);
        return acc.ToArray();
    }

    bool cmp(int d, Point a, Point b) {
        return d != 0 ? a.x < b.x : a.y < b.y;
    }

    public void search(Node t, int d, Point ld, Point ru, List<int> acc) {
        if (t == null) return;

        var p = t.p;
        if (ld.x <= p.x && p.x <= ru.x && ld.y <= p.y && p.y <= ru.y) {
            acc.Add(p.index);
        }
#if false
        if (!cmp(d, p, ld))
            search(t.l, d ^ 1, ld, ru, acc);
        if (!cmp(d, ru, p))
            search(t.r, d ^ 1, ld, ru, acc);
#else
        if (d == 0) {
            if (ld.x <= p.x) search(t.l, d ^ 1, ld, ru, acc);
            if (p.x <= ru.x) search(t.r, d ^ 1, ld, ru, acc);
        }
        else {
            if (ld.y <= p.y) search(t.l, d ^ 1, ld, ru, acc);
            if (p.y <= ru.y) search(t.r, d ^ 1, ld, ru, acc);
        }
#endif
    }
}

