            var t = Np++;
            if (depth % 2 == 0)
            {
                Points.Sort(l, r - l, XComparer);
            }
            else
            {
                Points.Sort(l, r - l, YComparer);
            }

            Nodes[t].Location = InitialPoints.IndexOf(Points[mid]);
            Nodes[t].L = MakeKDTree(l, mid, depth + 1);
            Nodes[t].R = MakeKDTree(mid + 1, r, depth + 1);

            return t;
        }

        static void Find(Query query, int nid, int depth, List<int> result)
        {
            var node = Nodes[nid];
            var p = InitialPoints[node.Location];
            if (query.CheckInner(p))
            {
                result.Add(node.Location);
            }

            if (depth % 2 == 0)
            {
                if (node.L != -1 && p.X >= query.X1)
                    Find(query, node.L, depth + 1, result);

                if (node.R != -1 && p.X <= query.X2)
                    Find(query, node.R, depth + 1, result);
            }
            else
            {
                if (node.L != -1 && p.Y >= query.Y1)
                    Find(query, node.L, depth + 1, result);

                if (node.R != -1 && p.Y <= query.Y2)
                    Find(query, node.R, depth + 1, result);
            }
        }
    }

    struct Node
    {
        public int Location;
        public int L, R;
    }

    struct Point
    {
        public readonly int X;
        public readonly int Y;

        public Point(int x, int y)
        {
            X = x;
            Y = y;
        }

        public override string ToString()
        {
            return string.Format("{0}, {1}", X, Y);
        }
    }

    class PointXComparer : IComparer<Point>
    {
        public int Compare(Point p1, Point p2)
        {
            return (p1.X < p2.X) ? -1 : 1;
        }
    }

    class PointYComparer : IComparer<Point>
    {
        public int Compare(Point p1, Point p2)
        {
            return (p1.Y < p2.Y) ? -1 : 1;
        }
    }

    struct Query
    {
        public readonly int X1;
        public readonly int X2;
        public readonly int Y1;
        public readonly int Y2;

        public Query(int x1, int x2, int y1, int y2)
        {
            X1 = x1;
            X2 = x2;
            Y1 = y1;
            Y2 = y2;
        }

        public bool CheckInner(Point p)
        {
            return p.X >= X1 && p.X <= X2 && p.Y >= Y1 && p.Y <= Y2;
        }
    }
}

