    }

    Node make(Point[] ps, int lo, int hi, int d) {
        if (lo >= hi) return null;

        if (d == 0)
            Array.Sort(ps, lo, hi - lo, new CmpX());
        else
            Array.Sort(ps, lo, hi - lo, new CmpY());

        int mid = (lo + hi) / 2;
        var node = new Node(ps[mid]);
        node.l = make(ps, lo, mid, d ^ 1);
        node.r = make(ps, mid + 1, hi, d ^ 1);
        return node;
    }

