            if (p.x <= ru.x) search(t.r, d ^ 1, ld, ru, acc);
        }
        else {
            if (ld.y <= p.y) search(t.l, d ^ 1, ld, ru, acc);
            if (p.y <= ru.y) search(t.r, d ^ 1, ld, ru, acc);
        }
#endif
    }
