    class Node
    {
        public int location;
        public Node left, right;

        public Node(int value)
        {
            location = value;
        }
    }

    class KDTree
    {
        public Node root;
        int dimension;

        public KDTree(int[][] points, int dimension)
        {
            int[][] pointsForBuild = points;

            this.dimension = dimension;

            root = Build(pointsForBuild, 0, 0, points.Length - 1);
        }

        public Node Build(int[][] points, int depth, int startIndex, int endIndex)
        {
            int length = endIndex - startIndex;
            int mid = startIndex + length / 2;

            if (length < 0) return null;

            Node result;
            result = new Node(GetMedianIndex(points, startIndex, endIndex, depth % dimension));
            result.left = Build(points, ++depth, startIndex, mid - 1);
            result.right = Build(points, depth, mid + 1, endIndex);

            return result;
        }

        private int GetMedianIndex(int[][] points, int startIndex, int endIndex, int axis)
        {
            Quicksort(points, startIndex, endIndex, axis);

            return startIndex + (endIndex - startIndex) / 2;
        }

        private void Quicksort(int[][] points, int startIndex, int endIndex, int axis)
        {
            int length = endIndex - startIndex;

            if (length <= 0)
            {
                return;
            }
            else if (length == 1)
            {
                if (points[endIndex][axis] < points[startIndex][axis])
                {
                    KDTree.Swap(points, startIndex, endIndex);
                }
            }
            else
            {
                int middleIndex = startIndex;

                for (int i = startIndex; i < endIndex; i++)
                {
                    if (points[i][axis] < points[endIndex][axis])
                    {
                        KDTree.Swap(points, i, middleIndex++);
                    }
                }

                if (middleIndex != endIndex)
                {
                    KDTree.Swap(points, middleIndex, endIndex);
                }

                Quicksort(points, startIndex, middleIndex - 1, axis);
                Quicksort(points, middleIndex + 1, endIndex, axis);
            }
        }

        private static void Swap<T>(T[] array, int index1, int index2)
        {
            T temp = array[index1];

            array[index1] = array[index2];
            array[index2] = temp;
        }
    }
}

