    {
        this.n = n;
        T = new Node[n];
        P = new Point[n];
    }

    public int MakekDTree(int l, int r, int depth)
    {
        if (l >= r) return -1;

        int mid = (l + r) / 2;

        if (depth % 2 == 0) Array.Sort(P, l, r - l, new Comparer_X());
        else Array.Sort(P, l, r - l, new Comparer_Y());

        T[mid].l = MakekDTree(l, mid, depth + 1);
        T[mid].r = MakekDTree(mid + 1, r, depth + 1);

        return mid;
    }
    class Comparer_X : IComparer<Point>
    {
        public int Compare(Point a, Point b)
        {
            return a.x - b.x;
        }
    }

