    class Point
    {
        internal int id, x, y;

        public Point(int id, int x, int y)
        {
            this.id = id;
            this.x = x;
            this.y = y;
        }
    }

    class ComparerX : IComparer<Point>
    {
        public int Compare(Point a, Point b)
        {
            return a.x - b.x;
        }
    }

    class ComparerY : IComparer<Point>
    {
        public int Compare(Point a, Point b)
        {
            return a.y - b.y;
        }
    }

    class Program
    {
        static Point[] P;
        static Node[] T;
        static SortedSet<int> ans = new SortedSet<int>();

        static void Main(string[] args)
        {
            int n = int.Parse(Console.ReadLine());
            P = new Point[n];
            T = new Node[n];

            for (int i = 0; i < n; i++)
            {
                string[] temp = Console.ReadLine().Split(' ');

                P[i] = new Point(i, int.Parse(temp[0]), int.Parse(temp[1]));
                T[i] = new Node(i);
            }

            int root = MakeKDTree(0, n, 0);

            int q = int.Parse(Console.ReadLine());

            StringBuilder sb = new StringBuilder();

            for (int i = q; i > 0; i--)
            {
                string[] temp = Console.ReadLine().Split(' ');

                ans.Clear();
                Find(root, int.Parse(temp[0]), int.Parse(temp[1]), int.Parse(temp[2]), int.Parse(temp[3]), 0);

                foreach (var id in ans)
                {
                    sb.AppendLine(id.ToString());
                }
                sb.AppendLine();
            }
            Console.Write(sb);
        }

        static ComparerX compX = new ComparerX();
        static ComparerY compY = new ComparerY();

        static int MakeKDTree(int l, int r, int depth)
        {
            if (l >= r) return -1;

            int mid = (l + r) / 2;

            if (depth % 2 == 0) Array.Sort(P, l, r - l, compX);
            else Array.Sort(P, l, r - l, compY);

            T[mid].l = MakeKDTree(l, mid, depth + 1);
            T[mid].r = MakeKDTree(mid + 1, r, depth + 1);

            return mid;
        }

        static void Find(int v, int sx, int tx, int sy, int ty, int depth)
        {
            int index = T[v].location;
            int x = P[index].x;
            int y = P[index].y;

            if (sx <= x && x <= tx && sy <= y && y <= ty) ans.Add(P[index].id);

            if (depth % 2 == 0)
            {
                if (T[v].l != -1 && sx <= x) Find(T[v].l, sx, tx, sy, ty, depth + 1);
                if (T[v].r != -1 && x <= tx) Find(T[v].r, sx, tx, sy, ty, depth + 1);
            }
            else
            {
                if (T[v].l != -1 && sy <= y) Find(T[v].l, sx, tx, sy, ty, depth + 1);
                if (T[v].r != -1 && y <= ty) Find(T[v].r, sx, tx, sy, ty, depth + 1);
            }
        }
    }
