  {
    public int Compare(Point p1, Point p2)
    {
//      Point p1 = (Point) o1;
//      Point p2 = (Point) o2;
//      return p1.x.CompareTo(p2.x);
	    return p1.x - p2.x;
    }
  }

  public class MyComparatorY : IComparer<Point>
  {
    public int Compare(Point p1, Point p2)
    {
//      Point p2 = (Point) o2;
//      Point p1 = (Point) o1;
//      return p1.y.CompareTo(p2.y);
		return p1.y - p2.y;
    }
  }

  static readonly int MAX = 500000;
  static readonly int NIL = -1;

  static int N;
  static Point[] P = new Point[MAX];
  static Node[] T = new Node[MAX];
  static int np;
  static List<Point> answer = new List<Point>();

//  static int lessX(Point p1, Point p2) { return p1.x - p2.x; }
//  static int lessY(Point p1, Point p2) { return p1.y - p2.y; }

  static int makeKDTree(int left, int right, int depth)
  {
    if(!(left < right)) { return NIL; }
    int mid = (left + right) / 2;
    int t = np++;
    if(depth%2 == 0)
    {
	  Array.Sort(P, left, right-left, new MyComparatorX());
    } else {
	  Array.Sort(P, left, right-left, new MyComparatorY() );
    }

    T[t].location = mid;
    T[t].left = makeKDTree(left, mid, depth+1);
    T[t].right = makeKDTree(mid+1, right, depth+1);

    return t;
  }

  static void find(int v, int sx, int tx, int sy, int ty, int depth)
  {
    int x = P[T[v].location].x;
    int y = P[T[v].location].y;

    if(sx <= x && x <=tx && sy <= y && y <= ty)
    {
      answer.Add(P[T[v].location]);
    }

    if(depth%2 == 0)
    {
      if(T[v].left != NIL)
      {
	if(sx<=x) { find(T[v].left, sx, tx, sy, ty, depth+1); }
      }
      if(T[v].right != NIL)
      {
	if(x<=tx) { find(T[v].right, sx, tx, sy, ty, depth+1); }
      }
    } else {
      if(T[v].left != NIL)
      {
	if(sy<=y) { find(T[v].left, sx, tx, sy, ty, depth+1); }
      }
      if(T[v].right != NIL)
      {
	if(y<=ty) { find(T[v].right, sx, tx, sy, ty, depth+1); }
      }
    }
  }

