//      Console.Write("T[i].left={0}, T[i].right{1}=, T[i].point={2}, Point.x={3}, Point.y={4}, Point.id={5}\n", T[i].left, T[i].right, T[i].point, P[i].x, P[i].y, P[i].id);
    }

