class TDTree
  def initialize
    @points = []
    @nodes = []
  end

  def add_point(point)
    @points << point
  end

  def build(left = 0, right = @points.length, depth = 0)
    return if left >= right
    middle = (left + right) / 2

    method = depth.even? ? :x : :y
    @points[left...right] = @points[left...right].sort_by(&method)

    Node.new(
      @points[middle],
      build(left, middle, depth + 1),
      build(middle + 1, right, depth + 1)
    ).tap { |n| @nodes << n }
  end

  def search(range, node = root, depth = 0, results = [])
    point = node.point
    if range.member?(point)
      results << point
    end

    if depth.even?
      if node.left && range.sx <= point.x
        search(range, node.left, depth + 1, results)
      end
      if node.right && point.x <= range.tx
        search(range, node.right, depth + 1, results)
      end
    else
      if node.left && range.sy <= point.y
        search(range, node.left, depth + 1, results)
      end
      if node.right && point.y <= range.ty
        search(range, node.right, depth + 1, results)
      end
    end

    results.tap { |r| r.sort_by!(&:id) if depth = 0 }
  end

  def root
    @nodes.last
  end
end

