var np int
var P []*Point
var T []Node

const None = -1

type Node struct {
	location, p, l, r int
}

type Point struct {
	X, Y int
	id   int
}

type PointSliceX []*Point

func (s PointSliceX) Len() int           { return len(s) }
func (s PointSliceX) Less(i, j int) bool { return s[i].X < s[j].X }
func (s PointSliceX) Swap(i, j int)      { s[i], s[j] = s[j], s[i] }

type PointSliceY []*Point

func (s PointSliceY) Len() int           { return len(s) }
func (s PointSliceY) Less(i, j int) bool { return s[i].Y < s[j].Y }
func (s PointSliceY) Swap(i, j int)      { s[i], s[j] = s[j], s[i] }

func MakeKDTree(l, r, depth int) int {
	if !(l < r) {
		return None
	}
	mid := (l + r) / 2
	t := np
	np++
	if depth%2 == 0 {
		// sort.Slice(P[l:r], func(i, j int) bool { return P[l+i].X < P[l+j].X })
		Select(PointSliceX(P), mid, l, r-1)
	} else {
		// sort.Slice(P[l:r], func(i, j int) bool { return P[l+i].Y < P[l+j].Y })
		Select(PointSliceY(P), mid, l, r-1)
	}
	T[t].location = mid
	T[t].l = MakeKDTree(l, mid, depth+1)
	T[t].r = MakeKDTree(mid+1, r, depth+1)
	return t
}

func Find(v, sx, tx, sy, ty, depth int, ans *[]*Point) {
	x := P[T[v].location].X
	y := P[T[v].location].Y
	if sx <= x && x <= tx && sy <= y && y <= ty {
		*ans = append(*ans, P[T[v].location])
	}
	if depth%2 == 0 {
		if T[v].l != None {
			if sx <= x {
				Find(T[v].l, sx, tx, sy, ty, depth+1, ans)
			}
		}
		if T[v].r != None {
			if x <= tx {
				Find(T[v].r, sx, tx, sy, ty, depth+1, ans)
			}
		}
	} else {
		if T[v].l != None {
			if sy <= y {
				Find(T[v].l, sx, tx, sy, ty, depth+1, ans)
			}
		}
		if T[v].r != None {
			if y <= ty {
				Find(T[v].r, sx, tx, sy, ty, depth+1, ans)
			}
		}
	}
}

