func main() {
	fp := os.Stdin
	wfp := os.Stdout

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	n := getNextInt(scanner)
	xx := make(Ranks, n+40000, n+40000)
	yy := make([]int, n+40000, n+40000)
	rx := map[int]int{}
	ry := map[int]int{}
	pp := make(Points, n)

	for i := 0; i < n; i++ {
		pp[i].x = getNextInt(scanner)
		pp[i].y = getNextInt(scanner)
		pp[i].i = i
		xx[i].v = pp[i].x
		xx[i].q = 1
		yy[i] = pp[i].y
	}
	q := getNextInt(scanner)
	qq := make([]Query, q)
	xyi := n
	for i := 0; i < q; i++ {
		qq[i].sx = getNextInt(scanner)
		qq[i].tx = getNextInt(scanner) + 1
		xx[xyi].v = qq[i].sx
		xx[xyi].q = 0
		xx[xyi+1].v = qq[i].tx
		xx[xyi+1].q = 0
		qq[i].sy = getNextInt(scanner)
		qq[i].ty = getNextInt(scanner)
		yy[xyi] = qq[i].sy
		yy[xyi+1] = qq[i].ty
		xyi += 2
	}
	rcnt := q*2 + n
	sort.Sort(xx[0:rcnt])
	sort.Ints(yy[0:rcnt])
	rankx := 0
	ranky := 0
	if xx[0].q == 1 {
		rankx++
	} else {
		rx[xx[0].v] = rankx
	}

	for i := 1; i < rcnt; i++ {
		if yy[i] != yy[i-1] {
			ranky++
		}
		if xx[i].q == 1 {
			rankx++
		} else {
			rx[xx[i].v] = rankx
		}
		ry[yy[i]] = ranky
	}

	sort.Sort(pp)
	raw := make([]int, n, n)
	prev := make([]int, rcnt, rcnt)
	for i := 0; i < n; i++ {
		raw[i] = ry[pp[i].y]
		pp[i].prev = prev[raw[i]]
		prev[raw[i]] = i
	}
	wl := WaveletKeanuReeves{}
	wl.init(raw)

	ans := make([]int, 100, 100)

	for i := 0; i < q; i++ {
		sx := rx[qq[i].sx]
		tx := rx[qq[i].tx]

		ai := 0

		more := wl.rangerankmore(sx, tx, ry[qq[i].ty])
		for {
			c := wl.quantile(sx, tx, more+1)
			if c < ry[qq[i].sy] {
				break
			}
			l, r := wl.getbottomrange(sx, tx, c)
			cnt := r - l
			ti := wl.gettopindex(r - 1)
			for iii := 0; iii < cnt; iii++ {
				ans[ai] = pp[ti].i
				ti = pp[ti].prev
				ai++
			}
			more += cnt
		}

		sort.Ints(ans[0:ai])
		for ii := 0; ii < ai; ii++ {
			fmt.Fprintln(writer, ans[ii])
		}
		fmt.Fprintln(writer, "")
	}
	writer.Flush()
}

