func (a Ranks) Swap(i, j int) { a[i], a[j] = a[j], a[i] }
func (a Ranks) Less(i, j int) bool {
	if a[i].v == a[j].v {
		return a[i].q < a[j].q
	}
	return a[i].v < a[j].v
}

