let generate_g n =
  let rec doit i g acc =
    if g > n then acc
    else doit (i + 1) (int_of_float (4.**(float_of_int i) +. 3.*.2.**(float_of_int (i - 1)) +. 1.)) (g :: acc) in
  doit 1 1 []

let insertion_sort first last g cmp =
  let rec insert j v =
    if j < first || cmp p.(j) v <= 0 then p.(j+g) <- v
    else begin
      p.(j+g) <- p.(j);
      insert (j - g) v
    end in
  let rec doit i =
    if i < last then begin
      insert (i - g) p.(i);
      doit (i + 1)
    end in
  doit (g + first)

let shell_sort first last cmp =
  let g = generate_g (last - first) in
  let rec doit = function
    | [] -> ()
    | hd :: tl -> insertion_sort first last hd cmp; doit tl in
  doit g

