class KDTree {
    class Node {
        Point p;
        Node l, r;
        this(Point p) {
            this.p = p;
        }
    }

    private Node root;

    void make(Point[] ps) {
        root = make(ps, 0, cast(int) ps.length, 0);
    }

    Node make(ref Point[] ps, int lo, int hi, int d) {
        if (lo >= hi)
            return null;

        if (d) {
            sort!((a, b) => a.x < b.x)(ps[lo .. hi]);
        }
        else {
            sort!((a, b) => a.y < b.y)(ps[lo .. hi]);
        }
        //        ps.sort!((a, b) => d ? a.x < b.x : a.y < b.y);
        // auto median = ps.length / 2;
        auto mid = (lo + hi) / 2;

        auto node = new Node(ps[mid]);
        node.l = make(ps, lo, mid, !d);
        node.r = make(ps, mid + 1, hi, !d);
        return node;
    }

    void insert(Point p) {
        root = insert(root, 0, p);
    }

    bool cmp(int d, Point a, Point b) {
        return d ? a.x < b.x : a.y < b.y;
    }

    Node insert(Node t, int d, Point p) {
        if (t is null) {
            return new Node(p);
        }

        if (cmp(d, p, t.p))
            t.l = insert(t.l, !d, p);
        else
            t.r = insert(t.r, !d, p);
        return t;
    }

    int[] search(Point ld, Point ru) {
        int[] acc;
        search(root, 0, ld, ru, acc);
        return acc;
    }

    void search(Node t, int d, Point ld, Point ru, ref int[] acc) {
        if (t is null)
            return;
        auto p = t.p;
        if (ld.x <= p.x && p.x <= ru.x && ld.y <= p.y && p.y <= ru.y) {
            acc ~= p.index;
        }
        if (!cmp(d, p, ld))
            search(t.l, !d, ld, ru, acc);
        if (!cmp(d, ru, p))
            search(t.r, !d, ld, ru, acc);
    }
}

