  Node make_kd_tree(size_t l, size_t r, int depth) {
    if (!(l < r)) return null;
    size_t mid = (l + r) / 2;

    if (depth) P[l..r].sort!"a.y<b.y";
    else       P[l..r].sort!"a.x<b.x";

    Node t = new Node();
    t.p = mid;
    t.left = make_kd_tree(l, mid, !depth);
    t.right = make_kd_tree(mid+1, r, !depth);
