    int y = P[v.p].y;

    if (sx <= x && x <= tx && sy <= y && y <= ty) {
      ans ~= P[v.p];
    }

    if (depth ? sy <= y : sx <= x) find(v.left, sx, sy, tx, ty, !depth, ans);
    if (depth ? y <= ty : x <= tx) find(v.right, sx, sy, tx, ty, !depth, ans);
  }

  this (Point[] p) {
    this.P = p;
    this.N = p.length;
    this.root = make_kd_tree(0, N, 0);
  }

