def find(z,s,t,d,nums):
    if(s[0]<=z.key[0]<=t[0])and(s[1]<=z.key[1]<=t[1]):
        nums.append(z.num)

    if (z.left != None)and(z.key[d%2]>=s[d%2]):
        find(z.left,s,t,d+1,nums)
    if (z.right != None)and(z.key[d%2]<=t[d%2]):
        find(z.right,s,t,d+1,nums)

class Tree():
    def __init__(self):
        self.root = None

    def add_Node(self,k,n):
        y = None
        x = self.root
        d = 0
        while(x != None):
            y = x
            if x.key[d%2] > k[d%2]:
                x = x.left
            else:
                x = x.right
            d += 1

        z = Node(k,n)
        z.parent = y
        z.depth  = d

        if y == None:
            self.root = z
        elif y.key[d%2] > k[d%2]:
            y.left = z
        else:
            y.right = z

    def recursive_add_Node(self,keys,depth):
        keys.sort(key=lambda x:x[depth%2])
        id_mean = len(keys)/2
        self.add_Node(keys[id_mean][:2],keys[id_mean][2])

        keys_l = keys[:id_mean]
        keys_r = keys[id_mean+1:]

        if keys_l:
            self.recursive_add_Node(keys_l,depth+1)
        if keys_r:
            self.recursive_add_Node(keys_r,depth+1)

class Node():
    def __init__(self,k,n):
        self.key    = k
        self.num    = n
        self.depth  = None
        self.parent = None
        self.left   = None
        self.right  = None



