import sys
from collections import deque
from functools import lru_cache
from math import floor, log2, sqrt


def sort3(i, j, k):
    if i > j:
        if j > k:
            return (0, 1, 2)
        elif i > k:
            return (0, 2, 1)
        else:
            return (2, 0, 1)
    else:
        if i > k:
            return (1, 0, 2)
        elif j > k:
            return (1, 2, 0)
        else:
            return (2, 1, 0)


def partition(ps, lo, hi, dim):
    mid = (lo+hi)//2
    ns = (lo, mid, hi)
    n0, n1, n2 = sort3(ps[lo][dim], ps[mid][dim], ps[hi][dim])
    ps[lo], ps[mid], ps[hi] = ps[ns[n1]], ps[ns[n2]], ps[ns[n0]]
    i, j = lo, hi
    v = ps[lo][dim]
    while True:
        i, j = i+1, j-1
        while ps[i][dim] < v:
            i += 1
        while ps[j][dim] > v:
            j -= 1
        if i >= j:
            break
        ps[i], ps[j] = ps[j], ps[i]
    ps[j], ps[lo] = ps[lo], ps[j]
    return j


def sort(ps, lo, hi, dim):
    i = lo
    for p in sorted(ps[lo:hi+1], key=lambda p: p[dim]):
        ps[i] = p
        i += 1


def halve(ps, s, t, dim):
    def _halve(lo, hi):
        if hi - lo < 10:
            sort(ps, lo, hi, dim)
            return mid
        i = partition(ps, lo, hi, dim)
        if i > mid:
            return _halve(lo, i-1)
        elif i < mid:
            return _halve(i+1, hi)
        else:
            return mid

    mid = (s+t) // 2
    return _halve(s, t)


def build(ps):
    n = len(ps)
    _dim = dimension(ps)
    q = deque([(0, n-1, 0)])
    while len(q) > 0:
        s, t, lv = q.popleft()
        mid = halve(ps, s, t, _dim(lv))
        if mid-1 > s:
            q.append((s, mid-1, lv+1))
        if t > mid+1:
            q.append((mid+1, t, lv+1))

    return ps, _dim


def search(ps, _dim, s, t):
    n = len(ps)
    stack = [(0, n-1, 0)]
    rev = (1, 0)
    while len(stack) > 0:
        i, j, lv = stack.pop()
        dim = _dim(lv)
        if i > j:
            continue
        mid = (i+j) // 2
        if t[dim] < ps[mid][dim]:
            stack.append((i, mid-1, lv+1))
        elif s[dim] > ps[mid][dim]:
            stack.append((mid+1, j, lv+1))
        else:
            rd = rev[dim]
            if s[rd] <= ps[mid][rd] <= t[rd]:
                yield ps[mid][2]
            stack.append((i, mid-1, lv+1))
            stack.append((mid+1, j, lv+1))


def dimension(ps):
    @lru_cache(maxsize=len(ps))
    def _dimension(lv):
        return pat[lv % len(pat)]

    xs = [p[0] for p in ps]
    ys = [p[1] for p in ps]

    cx = len(set(xs))
    cy = len(set(ys))
    depth = floor(log2(sqrt(len(ps))))

    if cx < cy:
        m, s = 1, 0
        ratio = min(cy // cx, depth)
    else:
        m, s = 0, 1
        ratio = min(cx // cy, depth)

    pat = []
    for i in range(ratio):
        pat.append(m)
    pat.append(s)

    return _dimension


def run():
    n = int(input())
    ps = []
    i = 0
    for line in sys.stdin:
        if i < n:
            x, y = [int(v) for v in line.split()]
            ps.append((x, y, i))
            i += 1
        else:
            break

    dim = dimension(ps)
    base = dim(0)
    trees = []
    size = n//floor(sqrt(n))
    ps.sort(key=lambda p: p[base])
    for i in range((n-1)//size+1):
        min_ = ps[i*size][base]
        max_ = ps[min((i+1)*size-1, n-1)][base]
        tree, dim = build(ps[i*size:(i+1)*size])
        trees.append((tree, dim, min_, max_))

    # q = int(line)
    for line in sys.stdin:
        sx, tx, sy, ty = [int(v) for v in line.split()]
        s, t = (sx, sy)[base], (tx, ty)[base]
        ids = []
        for tree, dim, min_, max_ in trees:
            if max_ < s:
                continue
            elif min_ > t:
                break
            else:
                ids.extend(list(search(tree, dim, (sx, sy), (tx, ty))))

        for v in sorted(ids):
            print(v)
        print()


if __name__ == '__main__':
    run()

