class Place(object):
    def __init__(self, id=-1, y=0, x=0):
        self.id = id
        self.y = y
        self.x = x

class KdTree(object):
    class node:
        def __init__(self):
            self.p = 0
            self.left = None
            self.right = None

    def __init__(self, p):
        self.P = p
        self.N = len(p)
        self.root = self.makeKdTree(0, self.N, False)

    def makeKdTree(self, l, r, depth):
        if not (l < r):
            return None

        mid = (l + r) / 2;
        if depth:
            self.P[l:r] = sorted(self.P[l:r], key=lambda p: p.y)
        else:
            self.P[l:r] = sorted(self.P[l:r], key=lambda p: p.x)

        t = self.node()
        t.p = mid
        t.left = self.makeKdTree(l, mid, not depth)
        t.right = self.makeKdTree(mid + 1, r, not depth)
        return t

    def search(self, v, sy, sx, ty, tx, depth, ans):
        if v is None:
            return

        x = self.P[v.p].x
        y = self.P[v.p].y

        if sy <= y and y <= ty and sx <= x and x <= tx:
            ans.append(self.P[v.p])
        if (depth and sy <= y) or ((not depth) and sx <= x):
            self.search(v.left, sy, sx, ty, tx, not depth, ans)
        if (depth and y <= ty) or ((not depth) and x <= tx):
            self.search(v.right, sy, sx, ty, tx, not depth, ans)

    def query(self, sy, sx, ty, tx, ans):
        self.search(self.root, sy, sx, ty, tx, False, ans)


