def partition(A, l, r, key):
    x = A[r][key]
    i = l - 1
    for j in range(l, r):
        if A[j][key] <= x:
            i += 1
            A[i], A[j] = A[j], A[i]
    A[i + 1], A[r] = A[r], A[i + 1]
    return i + 1

def make2DTree(l, r, depth):
    if l == r:
        return None

    if depth % 2 == 0:
        separator = partition(T, l, r - 1, 1)
    else:
        separator = partition(T, l, r - 1, 2)

    T[separator][3] = make2DTree(l, separator, depth + 1)
    T[separator][4] = make2DTree(separator + 1, r, depth + 1)

    return T[separator]


