# DSL_2_C: Range Search(kD Tree)

from bisect import bisect_left, bisect_right
from math import floor, sqrt
import sys


def run():
    n = int(input())
    ps = []
    i = 0
    for line in sys.stdin:
        if i >= n:
            break
        x, y = [int(v) for v in line.split()]
        ps.append((i, x, y))
        i += 1

    xs, ys, xids, yids = [], [], [], []
    for i, x in sorted(((i, x) for i, x, y in ps), key=lambda p: p[1]):
        xids.append(i)
        xs.append(x)

    for i, y in sorted(((i, y) for i, x, y in ps), key=lambda p: p[1]):
        yids.append(i)
        ys.append(y)

    sz = n//max(1, floor(sqrt(n)))
    idmap = [[None] * (n//sz+1) for _ in range(n//sz+1)]
    xidmap = [frozenset(xids[i*sz:(i+1)*sz]) for i in range(n//sz+1)]
    yidmap = [frozenset(yids[j*sz:(j+1)*sz]) for j in range(n//sz+1)]
    for line in sys.stdin:
        sx, tx, sy, ty = [int(v) for v in line.split()]
        xmin = bisect_left(xs, sx)
        xmax = bisect_right(xs, tx)
        ymin = bisect_left(ys, sy)
        ymax = bisect_right(ys, ty)

        ids = set()
        for i in range(xmin//sz, (xmax-1)//sz+1):
            xpart = xmin > i*sz or xmax < (i+1)*sz
            for j in range(ymin//sz, (ymax-1)//sz+1):
                if idmap[i][j] is None:
                    idmap[i][j] = xidmap[i] & yidmap[j]
                ypart = ymin > j*sz or ymax < (j+1)*sz
                if xpart or ypart:
                    ids |= {p for p in idmap[i][j] if (sx <= ps[p][1] <= tx and
