class Node:
    def __init__(self, points, horizontal):
        len_p = len(points)
        if len_p < LIMIT_POINTS_IN_NODE:
            self.center = None
            self.points = set(points)
            return

        self.points = set(p[0] for p in points)
        self.horizontal = horizontal

        xy_idx = 2 if horizontal else 1
        center_idx = len_p // 2
        sorted_points = sorted(points, key=lambda p: p[xy_idx])
        self.center = sorted_points[center_idx]
        left, right = sorted_points[:center_idx], sorted_points[center_idx + 1:]

        self.left = Node(left, not horizontal) if left else None
        self.right = Node(right, not horizontal) if right else None

    def search(self, bound, intersection):
        if not self.center:
            return set(p[0] for p in self.points if bound.contains(p))

        if all(intersection):
            return self.points

        result = {self.center[0]} if bound.contains(self.center) else set()
        lis, ris = bound.update_intersection(intersection, self)
        if lis:
            result |= self.left.search(bound, lis)
        if ris:
            result |= self.right.search(bound, ris)
        return result

    def get_div(self):
        return self.center[2 if self.horizontal else 1]


