class Node:
    __slots__ = ('x', 'y', 'left', 'right', 'value')

    def __init__(self, x, y, value):
        self.x = x
        self.y = y
        self.value = value
        self.left = None
        self.right = None

    def __str__(self):
        return "({} [{},{}:{}] {})".format(self.left, self.x, self.y,
                                           self.value, self.right)


class KdTree:

    def __init__(self):
        self.root = None

    def add(self, x, y, v=None):
        if self.root is None:
            self.root = Node(x, y, v)
            return

        node = self.root
        level = 0
        while True:
            if level % 2 == 0:
                if node.x > x:
                    if node.left is None:
                        node.left = Node(x, y, v)
                        break
                    else:
                        node = node.left
                else:
                    if node.right is None:
                        node.right = Node(x, y, v)
                        break
                    else:
                        node = node.right
            else:
                if node.y > y:
                    if node.left is None:
                        node.left = Node(x, y, v)
                        break
                    else:
                        node = node.left
                else:
                    if node.right is None:
                        node.right = Node(x, y, v)
                        break
                    else:
                        node = node.right
            level += 1
        return node

    def range(self, x1, x2, y1, y2):
        def _range(node, level):
            if node is None:
                return
            if level % 2 == 0:
                if x2 < node.x:
                    yield from _range(node.left, level+1)
                elif x1 > node.x:
                    yield from _range(node.right, level+1)
                else:
                    if y1 <= node.y <= y2:
                        yield (node.x, node.y, node.value)
                    yield from _range(node.left, level+1)
                    yield from _range(node.right, level+1)
            else:
                if y2 < node.y:
                    yield from _range(node.left, level+1)
                elif y1 > node.y:
                    yield from _range(node.right, level+1)
                else:
                    if x1 <= node.x <= x2:
                        yield (node.x, node.y, node.value)
                    yield from _range(node.left, level+1)
                    yield from _range(node.right, level+1)

        yield from _range(self.root, 0)


