class Bound:
    def __init__(self, sx, tx, sy, ty):
        self.sx = sx
        self.tx = tx
        self.sy = sy
        self.ty = ty

    def is_contained(self, bound):
        return bound.sx <= self.sx and self.tx <= bound.tx and \
               bound.sy <= self.sy and self.ty <= bound.ty

    def is_intersected(self, bound):
        if bound.tx < self.sx or self.tx < bound.sx or bound.ty < self.sy or self.ty < self.sy:
            return False
        return True

    def contains(self, point):
        return self.sx <= point[1] <= self.tx and self.sy <= point[2] <= self.ty

    def divide(self, point, horizontal):
        if horizontal:
            dy = point[2]
            return Bound(self.sx, self.tx, self.sy, dy), Bound(self.sx, self.tx, dy, self.ty)
        else:
            dx = point[1]
            return Bound(self.sx, dx, self.sy, self.ty), Bound(dx, self.tx, self.sy, self.ty)


class Node:
    def __init__(self, points, bound, horizontal):
        self.points = points
        self.bound = bound

        xy_idx = 2 if horizontal else 1
        center_idx = len(points) // 2
        sorted_points = sorted(points, key=lambda p: p[xy_idx])
        self.center = sorted_points[center_idx]
        left, right = sorted_points[:center_idx], sorted_points[center_idx + 1:]

        lb, rb = self.bound.divide(self.center, horizontal)
        self.left = Node(left, lb, not horizontal) if left else None
        self.right = Node(right, rb, not horizontal) if right else None

    def search(self, bound):
        if self.bound.is_contained(bound):
            return set(self.points)
        if self.bound.is_intersected(bound):
            result = {self.center} if bound.contains(self.center) else set()
            if self.left:
                result |= self.left.search(bound)
            if self.right:
                result |= self.right.search(bound)
            return result
        return set()


