def binary_search(array, p, min_or_max):
    end = len(array)
    i = end // 2

    while array[i]!=p or i==0 or i==end-1:
        if array[i] > p:
            if i==0:
                break
            if array[i-1] < p:
                if min_or_max==0:
                    return([i-1])
                else:
                    return([i])
            i = i // 2
            continue
        if array[i] < p:
            if i==end-1:
                break
            if array[i+1] > p:
                if min_or_max==0:
                    return([i])
                else:
                    return([i+1])
            i += (end-i) // 2
            continue

    if array[i]!=p:
        if i==0:
            return([0])
        if i==end-1:
            return([end-1])

    min_,max_ = i,i

    while array[min_-1]==p:
        min_ -= 1
    while array[max_+1]==p:
        max_ += 1

    if min_==max_:
        return([i])
    else:
        return(np.arange(min_,max_+1))

