class Tree():
    def __init__(self):
        self.tree = {}
        self.ans = []
        self.n_node = 0
    # Tree構造が出来上がる。

    def kdTree(self, pointList, depth):
        if not pointList:
            return None

        # 深さに応じて軸を選択し、軸が順次選択されるようにする
        k = len(pointList[0].p)
        axis = depth % k

        # 点のリストをsortし、中央値の点を選択する
        pointList.sort(key=lambda x: x.p[axis])
        mid = len(pointList)//2

        node = Node()
        node.location = pointList[mid]
        node.leftChild = self.kdTree(pointList[0:mid], depth+1)
        node.rightChild = self.kdTree(pointList[mid+1:], depth+1)
        self.add_node(node)
        return node

    def add_node(self, node):
        self.tree[self.n_node] = node
        self.n_node += 1

    def find(self, node, s, t, depth):
        p = node.location.p

        flag = True
        for i in range(len(p)):
            if not(s[i] <= p[i] and p[i] <= t[i]):
                flag = False
                break
        if flag:
            self.ans.append(node.location.id)

        axis = depth % len(node.location.p)

        if node.leftChild is not None and s[axis] <= p[axis]:
            self.find(node.leftChild, s, t, depth+1)

        if node.rightChild is not None and p[axis] <= t[axis]:
            self.find(node.rightChild, s, t, depth+1)

