n = int(i_f.readline())

T = []
for i in range(n):
    x, y = map(int, i_f.readline().split())
    # [3] is left and [4] is right node.
    T.append([i, x, y, None, None])

def make2DTree(l, r, depth):
    if l >= r:
        return None

    mid = (l + r) // 2

    if depth % 2 == 0:
        t_lr = T[l:r]
        t_lr.sort(key=lambda n: n[1])
        T[l:r] = t_lr
    else:
        t_lr = T[l:r]
        t_lr.sort(key=lambda n: n[2])
        T[l:r] = t_lr

    T[mid][3] = make2DTree(l, mid, depth + 1)
    T[mid][4] = make2DTree(mid + 1, r, depth + 1)

    return T[mid]


make2DTree(0, n, 0)

root_node = T[n // 2]

Ans = []

def range_search(sx, tx, sy, yx):
    ans = []

    def _find(node, sx, tx, sy, ty, depth):
        x = node[1]
        y = node[2]

        if sx <= x <= tx and sy <= y <= ty:
            ans.append(node[0])

        if depth % 2 == 0:
            if node[3] and sx <= x:
                _find(node[3], sx, tx, sy, ty, depth + 1)
            if node[4] and x <= tx:
                _find(node[4], sx, tx, sy, ty, depth + 1)
        else:
            if node[3] and sy <= y:
                _find(node[3], sx, tx, sy, ty, depth + 1)
            if node[4] and y <= ty:
                _find(node[4], sx, tx, sy, ty, depth + 1)

    _find(root_node, sx, tx, sy, ty, 0)

    if ans:
        ans.sort()
        Ans.extend(ans)
    Ans.append('')


q = int(i_f.readline())


for l in i_f:
    sx, tx, sy, ty = map(int, l.split())
    range_search(sx, tx, sy, ty)

print('\n'.join(map(str, Ans)))

