        if i > j:
            if j > k:
                return (0, 1, 2)
            elif i > k:
                return (0, 2, 1)
            else:
                return (2, 0, 1)
        else:
            if i > k:
                return (1, 0, 2)
            elif j > k:
                return (1, 2, 0)
            else:
                return (2, 1, 0)

    def move_max(lo, hi, lv):
        j, v = hi, ps[hi][lv]
        for i in range(lo, hi):
            if ps[i][lv] > v:
                j, v = i, ps[i][lv]
        if j < hi:
            ps[j], ps[hi] = ps[hi], ps[j]
        return hi

    def move_min(lo, hi, lv):
        j, v = lo, ps[lo][lv]
        for i in range(hi, lo, -1):
            if ps[i][lv] < v:
                j, v = i, ps[i][lv]
        if j > lo:
            ps[j], ps[lo] = ps[lo], ps[j]
        return lo

    def sort(lo, hi, lv):
        for i in range(lo+1, hi+1):
            for j in range(i, lo, -1):
                if ps[j-1][lv] > ps[j][lv]:
                    ps[j-1], ps[j] = ps[j], ps[j-1]
                else:
                    break

    def partition(lo, hi, lv):
        mid = (lo+hi)//2
        ns = (lo, mid, hi)
        n0, n1, n2 = sort3(ps[lo][lv], ps[mid][lv], ps[hi][lv])
        v = ps[ns[n1]][lv]
        ps[lo], ps[mid], ps[hi] = ps[ns[n1]], ps[ns[n2]], ps[ns[n0]]
        i, j = lo, hi
        while True:
            i, j = i+1, j-1
            while ps[i][lv] < v:
                i += 1
            while ps[j][lv] > v:
                j -= 1
            if i >= j:
                break
            ps[i], ps[j] = ps[j], ps[i]
        ps[j], ps[lo] = ps[lo], ps[j]
        """
        assert all(ps[j][lv] >= ps[n][lv] for n in range(lo, j)), \
            [(n, ps[n][lv]) for n in range(lo, j+1) if ps[n][lv] > ps[j][lv]]
        assert all(ps[j][lv] <= ps[n][lv] for n in range(j, hi+1)), \
            [(n, ps[n][lv]) for n in range(j, hi+1) if ps[n][lv] < ps[j][lv]]
        """
        return j

    def halve(s, t, lv):
        def _halve(mid, lo, hi):
            if mid == lo:
                return move_min(lo, hi, lv)
            elif mid == hi:
                return move_max(lo, hi, lv)
            elif hi-lo < 7:
                sort(lo, hi, lv)
                return mid
            i = partition(lo, hi, lv)
            if i == mid:
                return i
            elif i > mid:
                return _halve(mid, lo, i-1)
            else:
                return _halve(mid, i+1, hi)

        k = _halve((s+t)//2, s, t)
        assert k == (s+t)//2, (k, s, t, (s+t)//2)
        return k

    def build():
        rev = (1, 0)
        q = deque([(0, len(ps)-1, 0)])
        while len(q) > 0:
            s, t, lv = q.popleft()
            mid = halve(s, t, lv)
            if mid-1 > s:
                q.append((s, mid-1, rev[lv]))
            if t > mid+1:
                q.append((mid+1, t, rev[lv]))

    def search(s, t):
