        rev = (1, 0)
        ret = []
        while len(stack) > 0:
            i, j, dim = stack.pop()
            if i > j:
                continue
            mid = (i+j) // 2
            if t[dim] < ps[mid][dim]:
                stack.append((i, mid-1, rev[dim]))
            elif s[dim] > ps[mid][dim]:
                stack.append((mid+1, j, rev[dim]))
            else:
                rd = rev[dim]
                if s[rd] <= ps[mid][rd] <= t[rd]:
                    ret.append(ps[mid][2])
                stack.append((i, mid-1, rd))
                stack.append((mid+1, j, rd))
        return sorted(ret)

    n = int(input())
