def add_Node(root,kx,ky,n):
    y = None
    x = root
    d = 0
    xy = 0
    while(x != None):
        d += 1
        xy = d%2
        y = x
        if xy == 0:
            if x.key_x > kx:
                x = x.left
            else:
                x = x.right
        else:
            if x.key_y > ky:
                x = x.left
            else:
                x = x.right

    z = Node(kx,ky,n)

    if xy == 0:
        if y.key_x > kx:
            y.left = z
        else:
            y.right = z
    else:
        if y.key_y > ky:
            y.left = z
        else:
            y.right = z

def recursive_add_Node(root,k,d):
    k.sort(key=itemgetter(d%2))
    len_k = len(k)
    id_m = len_k/2
    add_Node(root,k[id_m][0],k[id_m][1],k[id_m][2])
    if id_m != 0:
        recursive_add_Node(root,k[:id_m],d+1)
    if id_m+1 != len_k:
        recursive_add_Node(root,k[id_m+1:],d+1)

