struct Point {
    orig_index: usize,
    x: i32,
    y: i32,
}

#[derive(Debug)]
struct Node {
    point_index: usize,
    left: Option<usize>,
    right: Option<usize>,
}

fn make_tree(
    depth: usize,
    nodes: &mut Vec<Node>,
    points: &mut Vec<Point>,
    l: usize,
    r: usize,
) -> Option<usize> {
    if !(l < r) {
        return None;
    }

    if depth % 2 == 0 {
        points[l..r].sort_by_key(|p| p.x);
    } else {
        points[l..r].sort_by_key(|p| p.y);
    }

    let node_index = nodes.len();
    let mid = (l+r)/2;
    nodes.push(Node { point_index: mid, left: None, right: None }); 
    nodes[node_index].left = make_tree(depth+1, nodes, points, l, mid);
    nodes[node_index].right = make_tree(depth+1, nodes, points, mid+1, r);
    Some(node_index)
}

fn find(
    depth: usize,
    node_index: usize,
    points: &[Point],
    nodes: &[Node],
    sx: i32,
    tx: i32,
    sy: i32,
    ty: i32,
    out: &mut Vec<usize>
) {
    let node = &nodes[node_index];
    let p = &points[node.point_index];

    if sx <= p.x && p.x <= tx && sy <= p.y && p.y <= ty {
        out.push(p.orig_index);
    }
    // println!("{:?}", node);
    if depth % 2 == 0 {
        if node.left.is_some() && sx <= p.x {
            find(depth+1, node.left.unwrap(), points, nodes, sx, tx, sy, ty, out);
        }
        if node.right.is_some() && p.x <= tx {
            find(depth+1, node.right.unwrap(), points, nodes, sx, tx, sy, ty, out);
        }
    } else {
        if node.left.is_some() && sy <= p.y {
            find(depth+1, node.left.unwrap(), points, nodes, sx, tx, sy, ty, out);
        }
        if node.right.is_some() && p.y <= ty {
            find(depth+1, node.right.unwrap(), points, nodes, sx, tx, sy, ty, out);
        }
    }
}

fn solve() {
    input! {
        n: usize,
        points: [(i32,i32); n],
        q: usize,
        queries: [(i32,i32,i32,i32); q],
    }
    let out = stdout();
    let mut out = BufWriter::new(out.lock());
    let mut points = points.into_iter()
        .enumerate()
        .map(|(i, (x,y))| Point {
            orig_index: i,
            x: x,
            y: y,
        }).collect();
    let mut nodes = vec![];
    make_tree(0, &mut nodes, &mut points, 0, n);
    assert_eq!(nodes.len(), n);

    for &qu in &queries {
        let (sx, tx, sy, ty) = qu;
        let mut v = vec![];
        find(0, 0, &points, &nodes, sx, tx, sy, ty, &mut v);

        v.sort();
        for &x in &v {
            writeln!(out, "{}", x).unwrap();
        }
        writeln!(out, "").unwrap();
    }
}

